INSERT INTO public.ano_biblico_textos (livro_abrev, capitulo, idioma, versiculos, fonte)
VALUES
  ('Mc', 6, 'pt', '[{"numero": 1, "texto": "[Jesus] partiu-se dali, veio à sua terra, e seus discípulos o seguiram."}, {"numero": 2, "texto": "E chegando o sábado, começou a ensinar na sinagoga; e muitos, quando o ouviram, espantavam-se, dizendo: De onde lhe [vem] estas coisas? E que sabedoria é esta que lhe foi dada? E tais maravilhas feitas por suas mãos?"}, {"numero": 3, "texto": "Não é este o carpinteiro, filho de Maria, e irmão de Tiago, de José, de Judas, e de Simão? E não estão aqui as suas irmãs conosco? E ofenderam-se nele."}, {"numero": 4, "texto": "E Jesus lhes dizia: Todo profeta tem honra, menos em sua terra, entre os parentes, e em sua própria casa."}, {"numero": 5, "texto": "Ele não pôde ali fazer milagre algum, a não ser somente para uns poucos enfermos, sobre os quais pôs as mãos e os curou."}, {"numero": 6, "texto": "E ficou admirado da incredulidade deles. Ele percorreu as aldeias do redor, ensinando."}, {"numero": 7, "texto": "E chamou a si os doze, e começou a enviar de dois em dois; e deu-lhes poder sobre os espíritos imundos."}, {"numero": 8, "texto": "E mandou-lhes que não tomassem nada para o caminho, a não ser somente um bordão; nem bolsa, nem pão, nem dinheiro no cinto;"}, {"numero": 9, "texto": "mas que calçassem sandálias, e não se vestissem de duas túnicas."}, {"numero": 10, "texto": "E dizia-lhes: Onde quer que entrardes em alguma casa, ficai ali até que dali saiais."}, {"numero": 11, "texto": "E todos os que não vos receberem, nem vos ouvirem, quando sairdes dali, sacudi o pó que estiver debaixo de vossos pés, em testemunho contra eles Em verdade vos digo, que mais tolerável será a [os de] Sodoma ou Gomorra no dia do juízo, do que a [os d] aquela cidade."}, {"numero": 12, "texto": "Eles, então, se foram, e pregaram que [as pessoas] se arrependessem."}, {"numero": 13, "texto": "Eles expulsaram muitos demônios, e a muitos enfermos ungiram com azeite, e os curaram."}, {"numero": 14, "texto": "O rei Herodes ouviu falar disso (porque o nome de [Jesus] já era notório). E dizia: João Batista ressuscitou dos mortos, e por isso estas maravilhas operam nele."}, {"numero": 15, "texto": "Outros diziam: É Elias; e outros diziam: É profeta, ou como algum dos profetas."}, {"numero": 16, "texto": "Quando, porém, Herodes ouviu falar disso, falou: Ele é João, de quem cortei a cabeça. Ele ressuscitou dos mortos."}, {"numero": 17, "texto": "Pois o próprio Herodes havia mandado prender João, e acorrentá-lo na prisão, por causa de Herodias, mulher do seu irmão Filipe, porque havia se casado com ela."}, {"numero": 18, "texto": "Pois João dizia a Herodes: Não te é lícito possuir a mulher do teu irmão."}, {"numero": 19, "texto": "Assim Herodias o odiava, e queria matá-lo, mas não podia,"}, {"numero": 20, "texto": "pois Herodes temia João, sabendo que era um homem justo e santo, e o estimava. E quando o ouvia, fazia muitas coisas, o ouvia de boa vontade."}, {"numero": 21, "texto": "Mas veio um dia oportuno, em que Herodes, no dia do seu aniversário, dava uma ceia aos grandes de sua corte, aos comandantes militares, e aos principais da Galileia."}, {"numero": 22, "texto": "Então a filha dessa Herodias entrou dançando, e agradou a Herodes e aos que estavam sentados com ele. O rei disse à garota: Pede-me quanto quiseres, que eu darei a ti."}, {"numero": 23, "texto": "E jurou a ela: Tudo o que me pedirdes te darei, até a metade do meu reino."}, {"numero": 24, "texto": "Então ela saiu, e perguntou à sua mãe: Que pedirei? E ela respondeu: A cabeça de João Batista."}, {"numero": 25, "texto": "E entrando ela logo apressadamente ao rei, pediu, dizendo: Quero que imediatamente me dês num prato a cabeça de João Batista."}, {"numero": 26, "texto": "E o rei entristeceu-se muito; [mas] , por causa dos juramentos, e dos que estavam juntamente à mesa, não quis recusar a ela."}, {"numero": 27, "texto": "Então logo o rei enviou o executor com a ordem de trazer ali sua cabeça. Ele, foi, e o decapitou na prisão."}, {"numero": 28, "texto": "Em seguida, trouxe a sua cabeça num prato, e o deu à garota; e a garota a deu à sua mãe."}, {"numero": 29, "texto": "Quando os discípulos dele ouviram isso, vieram, pegaram o seu cadáver, e o puseram num sepulcro."}, {"numero": 30, "texto": "Os apóstolos juntaram-se [de volta] a Jesus, e contaram-lhe tudo, tanto o que haviam feito, como o que haviam ensinado."}, {"numero": 31, "texto": "E ele lhes disse: Vinde vós à parte a um lugar deserto, e descansai um pouco; pois havia muitos que iam e vinham, e não tinham tempo para comer."}, {"numero": 32, "texto": "E foram-se num barco a um lugar deserto à parte."}, {"numero": 33, "texto": "Mas as multidões os viram ir, e muitos o reconheceram. Então correram para lá a pé de todas as cidades, chegaram antes deles, e vieram para perto dele."}, {"numero": 34, "texto": "Quando Jesus saiu [do barco] , viu uma grande multidão, e teve compaixão deles porque eram como ovelhas que não têm pastor. Assim, começou a lhes ensinar muitas coisas."}, {"numero": 35, "texto": "E quando já era tarde, os seus discípulos vieram a ele, e disseram: O lugar é deserto, e a hora já é tarde."}, {"numero": 36, "texto": "Despede-os, para eles irem aos campos e aldeias circunvizinhos, e comprarem pão para si; pois não têm o que comer."}, {"numero": 37, "texto": "Mas ele respondeu: Dai-lhes vós mesmos de comer. E eles lhe responderam: Iremos, e compraremos duzentos denários de pão, para lhes darmos de comer?"}, {"numero": 38, "texto": "E ele lhes disse: Quantos pães tendes? Ide ver. Quando souberam, disseram: Cinco, e dois peixes."}, {"numero": 39, "texto": "E mandou-lhes que fizessem sentar a todos em grupos sobre a grama verde."}, {"numero": 40, "texto": "E sentaram-se repartidos de cem em cem, e de cinquenta em cinquenta."}, {"numero": 41, "texto": "Ele tomou os cinco pães e os dois peixes, levantou os olhos ao céu, abençoou, e partiu os pães, e os deu aos seus discípulos, para que os pusessem diante deles. E os dois peixes repartiu com todos."}, {"numero": 42, "texto": "Todos comeram e se saciaram."}, {"numero": 43, "texto": "E dos pedaços de pão e dos peixes levantaram doze cestos cheios."}, {"numero": 44, "texto": "Os que comeram os pães eram quase cinco mil homens."}, {"numero": 45, "texto": "Logo depois, ordenou seus discípulos a subirem no barco, e ir adiante para o outro lado, em Betsaida, enquanto ele despedia a multidão."}, {"numero": 46, "texto": "E, depois de os despedir, foi ao monte para orar."}, {"numero": 47, "texto": "Ao anoitecer, o barco estava no meio do mar, e [Jesus] sozinho em terra."}, {"numero": 48, "texto": "E viu que se cansavam muito remando, porque o vento lhes era contrário. Então, perto da quarta vigília da noite, veio a eles andando sobre o mar, e queria passar por eles."}, {"numero": 49, "texto": "Mas quando eles o viram andando sobre o mar, pensaram que era uma fantasma, e gritaram,"}, {"numero": 50, "texto": "pois todos o viam, e ficaram perturbados. Então logo falou com eles, dizendo: Tende coragem! Sou eu, não tenhais medo."}, {"numero": 51, "texto": "E subiu a eles no barco, e o vento se aquietou. Eles ficaram muito espantados e maravilhados entre si,"}, {"numero": 52, "texto": "pois não haviam entendido o que tinha acontecido com os pães, porque o coração deles estava endurecido."}, {"numero": 53, "texto": "Eles terminaram de atravessar o mar, chegaram à terra de Genesaré, e ali aportaram."}, {"numero": 54, "texto": "Quando eles saíram do barco, logo [as pessoas] o reconheceram."}, {"numero": 55, "texto": "Então gente de toda a região em redor veio correndo, e começaram a trazer em camas os doentes, aonde quer que ouviam que ele estava."}, {"numero": 56, "texto": "E aonde quer que ele entrava, em povoados, cidades, ou aldeias, colocavam os enfermos nas praças, e rogavam-lhe que ao menos tocassem a borda de sua roupa; e todos os que o tocavam ficavam sarados."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 6, 'en', '[{"numero": 1, "texto": "And he went out from thence, and came into his own country; and his disciples follow him."}, {"numero": 2, "texto": "And when the sabbath day was come, he began to teach in the synagogue: and many hearing him were astonished, saying, From whence hath this man these things? and what wisdom is this which is given unto him, that even such mighty works are wrought by his hands?"}, {"numero": 3, "texto": "Is not this the carpenter, the son of Mary, the brother of James, and Joses, and of Juda, and Simon? and are not his sisters here with us? And they were offended at him."}, {"numero": 4, "texto": "But Jesus, said unto them, A prophet is not without honour, but in his own country, and among his own kin, and in his own house."}, {"numero": 5, "texto": "And he could there do no mighty work, save that he laid his hands upon a few sick folk, and healed them."}, {"numero": 6, "texto": "And he marvelled because of their unbelief. And he went round about the villages, teaching."}, {"numero": 7, "texto": "And he called unto him the twelve, and began to send them forth by two and two; and gave them power over unclean spirits;"}, {"numero": 8, "texto": "And commanded them that they should take nothing for their journey, save a staff only; no scrip, no bread, no money in their purse:"}, {"numero": 9, "texto": "But be shod with sandals; and not put on two coats."}, {"numero": 10, "texto": "And he said unto them, In what place soever ye enter into an house, there abide till ye depart from that place."}, {"numero": 11, "texto": "And whosoever shall not receive you, nor hear you, when ye depart thence, shake off the dust under your feet for a testimony against them. Verily I say unto you, It shall be more tolerable for Sodom and Gomorrha in the day of judgment, than for that city."}, {"numero": 12, "texto": "And they went out, and preached that men should repent."}, {"numero": 13, "texto": "And they cast out many devils, and anointed with oil many that were sick, and healed them."}, {"numero": 14, "texto": "And king Herod heard of him; (for his name was spread abroad:) and he said, That John the Baptist was risen from the dead, and therefore mighty works do shew forth themselves in him."}, {"numero": 15, "texto": "Others said, That it is Elias. And others said, That it is a prophet, or as one of the prophets."}, {"numero": 16, "texto": "But when Herod heard thereof, he said, It is John, whom I beheaded: he is risen from the dead."}, {"numero": 17, "texto": "For Herod himself had sent forth and laid hold upon John, and bound him in prison for Herodias'' sake, his brother Philip''s wife: for he had married her."}, {"numero": 18, "texto": "For John had said unto Herod, It is not lawful for thee to have thy brother''s wife."}, {"numero": 19, "texto": "Therefore Herodias had a quarrel against him, and would have killed him; but she could not:"}, {"numero": 20, "texto": "For Herod feared John, knowing that he was a just man and an holy, and observed him; and when he heard him, he did many things, and heard him gladly."}, {"numero": 21, "texto": "And when a convenient day was come, that Herod on his birthday made a supper to his lords, high captains, and chief estates of Galilee;"}, {"numero": 22, "texto": "And when the daughter of the said Herodias came in, and danced, and pleased Herod and them that sat with him, the king said unto the damsel, Ask of me whatsoever thou wilt, and I will give it thee."}, {"numero": 23, "texto": "And he sware unto her, Whatsoever thou shalt ask of me, I will give it thee, unto the half of my kingdom."}, {"numero": 24, "texto": "And she went forth, and said unto her mother, What shall I ask? And she said, The head of John the Baptist."}, {"numero": 25, "texto": "And she came in straightway with haste unto the king, and asked, saying, I will that thou give me by and by in a charger the head of John the Baptist."}, {"numero": 26, "texto": "And the king was exceeding sorry; yet for his oath''s sake, and for their sakes which sat with him, he would not reject her."}, {"numero": 27, "texto": "And immediately the king sent an executioner, and commanded his head to be brought: and he went and beheaded him in the prison,"}, {"numero": 28, "texto": "And brought his head in a charger, and gave it to the damsel: and the damsel gave it to her mother."}, {"numero": 29, "texto": "And when his disciples heard of it, they came and took up his corpse, and laid it in a tomb."}, {"numero": 30, "texto": "And the apostles gathered themselves together unto Jesus, and told him all things, both what they had done, and what they had taught."}, {"numero": 31, "texto": "And he said unto them, Come ye yourselves apart into a desert place, and rest a while: for there were many coming and going, and they had no leisure so much as to eat."}, {"numero": 32, "texto": "And they departed into a desert place by ship privately."}, {"numero": 33, "texto": "And the people saw them departing, and many knew him, and ran afoot thither out of all cities, and outwent them, and came together unto him."}, {"numero": 34, "texto": "And Jesus, when he came out, saw much people, and was moved with compassion toward them, because they were as sheep not having a shepherd: and he began to teach them many things."}, {"numero": 35, "texto": "And when the day was now far spent, his disciples came unto him, and said, This is a desert place, and now the time is far passed:"}, {"numero": 36, "texto": "Send them away, that they may go into the country round about, and into the villages, and buy themselves bread: for they have nothing to eat."}, {"numero": 37, "texto": "He answered and said unto them, Give ye them to eat. And they say unto him, Shall we go and buy two hundred pennyworth of bread, and give them to eat?"}, {"numero": 38, "texto": "He saith unto them, How many loaves have ye? go and see. And when they knew, they say, Five, and two fishes."}, {"numero": 39, "texto": "And he commanded them to make all sit down by companies upon the green grass."}, {"numero": 40, "texto": "And they sat down in ranks, by hundreds, and by fifties."}, {"numero": 41, "texto": "And when he had taken the five loaves and the two fishes, he looked up to heaven, and blessed, and brake the loaves, and gave them to his disciples to set before them; and the two fishes divided he among them all."}, {"numero": 42, "texto": "And they did all eat, and were filled."}, {"numero": 43, "texto": "And they took up twelve baskets full of the fragments, and of the fishes."}, {"numero": 44, "texto": "And they that did eat of the loaves were about five thousand men."}, {"numero": 45, "texto": "And straightway he constrained his disciples to get into the ship, and to go to the other side before unto Bethsaida, while he sent away the people."}, {"numero": 46, "texto": "And when he had sent them away, he departed into a mountain to pray."}, {"numero": 47, "texto": "And when even was come, the ship was in the midst of the sea, and he alone on the land."}, {"numero": 48, "texto": "And he saw them toiling in rowing; for the wind was contrary unto them: and about the fourth watch of the night he cometh unto them, walking upon the sea, and would have passed by them."}, {"numero": 49, "texto": "But when they saw him walking upon the sea, they supposed it had been a spirit, and cried out:"}, {"numero": 50, "texto": "For they all saw him, and were troubled. And immediately he talked with them, and saith unto them, Be of good cheer: it is I; be not afraid."}, {"numero": 51, "texto": "And he went up unto them into the ship; and the wind ceased: and they were sore amazed in themselves beyond measure, and wondered."}, {"numero": 52, "texto": "For they considered not the miracle of the loaves: for their heart was hardened."}, {"numero": 53, "texto": "And when they had passed over, they came into the land of Gennesaret, and drew to the shore."}, {"numero": 54, "texto": "And when they were come out of the ship, straightway they knew him,"}, {"numero": 55, "texto": "And ran through that whole region round about, and began to carry about in beds those that were sick, where they heard he was."}, {"numero": 56, "texto": "And whithersoever he entered, into villages, or cities, or country, they laid the sick in the streets, and besought him that they might touch if it were but the border of his garment: and as many as touched him were made whole."}]'::jsonb, 'King James Version'),
  ('Mc', 6, 'fr', '[{"numero": 1, "texto": "Jésus partit de là, et se rendit dans sa patrie. Ses disciples le suivirent."}, {"numero": 2, "texto": "Quand le sabbat fut venu, il se mit à enseigner dans la synagogue. Beaucoup de gens qui l''''entendirent étaient étonnés et disaient: D''''où lui viennent ces choses? Quelle est cette sagesse qui lui a été donnée, et comment de tels miracles se font-ils par ses mains?"}, {"numero": 3, "texto": "N''''est-ce pas le charpentier, le fils de Marie, le frère de Jacques, de Joses, de Jude et de Simon? et ses soeurs ne sont-elles pas ici parmi nous? Et il était pour eux une occasion de chute."}, {"numero": 4, "texto": "Mais Jésus leur dit: Un prophète n''''est méprisé que dans sa patrie, parmi ses parents, et dans sa maison."}, {"numero": 5, "texto": "Il ne put faire là aucun miracle, si ce n''''est qu''''il imposa les mains à quelques malades et les guérit."}, {"numero": 6, "texto": "Et il s''''étonnait de leur incrédulité. Jésus parcourait les villages d''''alentour, en enseignant."}, {"numero": 7, "texto": "Alors il appela les douze, et il commença à les envoyer deux à deux, en leur donnant pouvoir sur les esprits impurs."}, {"numero": 8, "texto": "Il leur prescrivit de ne rien prendre pour le voyage, si ce n''''est un bâton; de n''''avoir ni pain, ni sac, ni monnaie dans la ceinture;"}, {"numero": 9, "texto": "de chausser des sandales, et de ne pas revêtir deux tuniques."}, {"numero": 10, "texto": "Puis il leur dit: Dans quelque maison que vous entriez, restez-y jusqu''''à ce que vous partiez de ce lieu."}, {"numero": 11, "texto": "Et, s''''il y a quelque part des gens qui ne vous reçoivent ni ne vous écoutent, retirez-vous de là, et secouez la poussière de vos pieds, afin que cela leur serve de témoignage."}, {"numero": 12, "texto": "Ils partirent, et ils prêchèrent la repentance."}, {"numero": 13, "texto": "Ils chassaient beaucoup de démons, et ils oignaient d''''huile beaucoup de malades et les guérissaient."}, {"numero": 14, "texto": "Le roi Hérode entendit parler de Jésus, dont le nom était devenu célèbre, et il dit: Jean Baptiste est ressuscité des morts, et c''''est pour cela qu''''il se fait par lui des miracles."}, {"numero": 15, "texto": "D''''autres disaient: C''''est Elie. Et d''''autres disaient: C''''est un prophète comme l''''un des prophètes."}, {"numero": 16, "texto": "Mais Hérode, en apprenant cela, disait: Ce Jean que j''''ai fait décapiter, c''''est lui qui est ressuscité."}, {"numero": 17, "texto": "Car Hérode lui-même avait fait arrêter Jean, et l''''avait fait lier en prison, à cause d''''Hérodias, femme de Philippe, son frère, parce qu''''il l''''avait épousée,"}, {"numero": 18, "texto": "et que Jean lui disait: Il ne t''''est pas permis d''''avoir la femme de ton frère."}, {"numero": 19, "texto": "Hérodias était irritée contre Jean, et voulait le faire mourir. Mais elle ne le pouvait;"}, {"numero": 20, "texto": "car Hérode craignait Jean, le connaissant pour un homme juste et saint; il le protégeait, et, après l''''avoir entendu, il était souvent perplexe, et l''''écoutait avec plaisir."}, {"numero": 21, "texto": "Cependant, un jour propice arriva, lorsque Hérode, à l''''anniversaire de sa naissance, donna un festin à ses grands, aux chefs militaires et aux principaux de la Galilée."}, {"numero": 22, "texto": "La fille d''''Hérodias entra dans la salle; elle dansa, et plut à Hérode et à ses convives. Le roi dit à la jeune fille: Demande-moi ce que tu voudras, et je te le donnerai."}, {"numero": 23, "texto": "Il ajouta avec serment: Ce que tu me demanderas, je te le donnerai, fût-ce la moitié de mon royaume."}, {"numero": 24, "texto": "Etant sortie, elle dit à sa mère: Que demanderai-je? Et sa mère répondit: La tête de Jean Baptiste."}, {"numero": 25, "texto": "Elle s''''empressa de rentrer aussitôt vers le roi, et lui fit cette demande: Je veux que tu me donnes à l''''instant, sur un plat, la tête de Jean Baptiste."}, {"numero": 26, "texto": "Le roi fut attristé; mais, à cause de ses serments et des convives, il ne voulut pas lui faire un refus."}, {"numero": 27, "texto": "Il envoya sur-le-champ un garde, avec ordre d''''apporter la tête de Jean Baptiste. Le garde alla décapiter Jean dans la prison,"}, {"numero": 28, "texto": "et apporta la tête sur un plat. Il la donna à la jeune fille, et la jeune fille la donna à sa mère."}, {"numero": 29, "texto": "Les disciples de Jean, ayant appris cela, vinrent prendre son corps, et le mirent dans un sépulcre."}, {"numero": 30, "texto": "Les apôtres, s''''étant rassemblés auprès de Jésus, lui racontèrent tout ce qu''''ils avaient fait et tout ce qu''''ils avaient enseigné."}, {"numero": 31, "texto": "Jésus leur dit: Venez à l''''écart dans un lieu désert, et reposez-vous un peu. Car il y avait beaucoup d''''allants et de venants, et ils n''''avaient même pas le temps de manger."}, {"numero": 32, "texto": "Ils partirent donc dans une barque, pour aller à l''''écart dans un lieu désert."}, {"numero": 33, "texto": "Beaucoup de gens les virent s''''en aller et les reconnurent, et de toutes les villes on accourut à pied et on les devança au lieu où ils se rendaient."}, {"numero": 34, "texto": "Quand il sortit de la barque, Jésus vit une grande foule, et fut ému de compassion pour eux, parce qu''''ils étaient comme des brebis qui n''''ont point de berger; et il se mit à leur enseigner beaucoup de choses."}, {"numero": 35, "texto": "Comme l''''heure était déjà avancée, ses disciples s''''approchèrent de lui, et dirent: Ce lieu est désert, et l''''heure est déjà avancée;"}, {"numero": 36, "texto": "renvoie-les, afin qu''''ils aillent dans les campagnes et dans les villages des environs, pour s''''acheter de quoi manger."}, {"numero": 37, "texto": "Jésus leur répondit: Donnez-leur vous-mêmes à manger. Mais ils lui dirent: Irions-nous acheter des pains pour deux cents deniers, et leur donnerions-nous à manger?"}, {"numero": 38, "texto": "Et il leur dit: Combien avez-vous de pains? Allez voir. Ils s''''en assurèrent, et répondirent: Cinq, et deux poissons."}, {"numero": 39, "texto": "Alors il leur commanda de les faire tous asseoir par groupes sur l''''herbe verte,"}, {"numero": 40, "texto": "et ils s''''assirent par rangées de cent et de cinquante."}, {"numero": 41, "texto": "Il prit les cinq pains et les deux poissons et, levant les yeux vers le ciel, il rendit grâces. Puis, il rompit les pains, et les donna aux disciples, afin qu''''ils les distribuassent à la foule. Il partagea aussi les deux poissons entre tous."}, {"numero": 42, "texto": "Tous mangèrent et furent rassasiés,"}, {"numero": 43, "texto": "et l''''on emporta douze paniers pleins de morceaux de pain et de ce qui restait des poissons."}, {"numero": 44, "texto": "Ceux qui avaient mangé les pains étaient cinq mille hommes."}, {"numero": 45, "texto": "Aussitôt après, il obligea ses disciples à monter dans la barque et à passer avant lui de l''''autre côté, vers Bethsaïda, pendant que lui-même renverrait la foule."}, {"numero": 46, "texto": "Quand il l''''eut renvoyée, il s''''en alla sur la montagne, pour prier."}, {"numero": 47, "texto": "Le soir étant venu, la barque était au milieu de la mer, et Jésus était seul à terre."}, {"numero": 48, "texto": "Il vit qu''''ils avaient beaucoup de peine à ramer; car le vent leur était contraire. A la quatrième veille de la nuit environ, il alla vers eux, marchant sur la mer, et il voulait les dépasser."}, {"numero": 49, "texto": "Quand ils le virent marcher sur la mer, ils crurent que c''''était un fantôme, et ils poussèrent des cris;"}, {"numero": 50, "texto": "car ils le voyaient tous, et ils étaient troublés. Aussitôt Jésus leur parla, et leur dit: Rassurez-vous, c''''est moi, n''''ayez pas peur!"}, {"numero": 51, "texto": "Puis il monta vers eux dans la barque, et le vent cessa. Ils furent en eux-mêmes tout stupéfaits et remplis d''''étonnement;"}, {"numero": 52, "texto": "car ils n''''avaient pas compris le miracle des pains, parce que leur coeur était endurci."}, {"numero": 53, "texto": "Après avoir traversé la mer, ils vinrent dans le pays de Génésareth, et ils abordèrent."}, {"numero": 54, "texto": "Quand ils furent sortis de la barque, les gens, ayant aussitôt reconnu Jésus,"}, {"numero": 55, "texto": "parcoururent tous les environs, et l''''on se mit à apporter les malades sur des lits, partout où l''''on apprenait qu''''il était."}, {"numero": 56, "texto": "En quelque lieu qu''''il arrivât, dans les villages, dans les villes ou dans les campagnes, on mettait les malades sur les places publiques, et on le priait de leur permettre seulement de toucher le bord de son vêtement. Et tous ceux qui le touchaient étaient guéris."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 6, 'es', '[{"numero": 1, "texto": "Y SALIÓ de allí, y vino á su tierra, y le siguieron sus discípulos."}, {"numero": 2, "texto": "Y llegado el sábado, comenzó á enseñar en la sinagoga; y muchos oyéndole, estaban atónitos, diciendo: ¿De dónde tiene éste estas cosas? ¿Y qué sabiduría es ésta que le es dada, y tales maravillas que por sus manos son hechas?"}, {"numero": 3, "texto": "¿No es éste el carpintero, hijo de María, hermano de Jacobo, y de José, y de Judas, y de Simón? ¿No están también aquí con nosotros, sus hermanas? Y se escandalizaban en él."}, {"numero": 4, "texto": "Mas Jesús les decía: No hay profeta deshonrado sino en su tierra, y entre sus parientes, y en su casa."}, {"numero": 5, "texto": "Y no pudo hacer allí alguna maravilla; solamente sanó unos pocos enfermos, poniendo sobre ellos las manos."}, {"numero": 6, "texto": "Y estaba maravillado de la incredulidad de ellos. Y rodeaba las aldeas de alrededor, enseñando."}, {"numero": 7, "texto": "Y llamó á los doce, y comenzó á enviarlos de dos en dos: y les dió potestad sobre los espíritus inmundos."}, {"numero": 8, "texto": "Y les mandó que no llevasen nada para el camino, sino solamente báculo; no alforja, ni pan, ni dinero en la bolsa;"}, {"numero": 9, "texto": "Mas que calzasen sandalias, y no vistiesen dos túnicas."}, {"numero": 10, "texto": "Y les decía: Donde quiera que entréis en una casa, posad en ella hasta que salgáis de allí."}, {"numero": 11, "texto": "Y todos aquellos que no os recibieren ni os oyeren, saliendo de allí, sacudid el polvo que está debajo de vuestros pies, en testimonio á ellos. De cierto os digo que más tolerable será el castigo de los de Sodoma y Gomorra el día del juicio, que el de aquella ciudad."}, {"numero": 12, "texto": "Y saliendo, predicaban que los hombres se arrepintiesen."}, {"numero": 13, "texto": "Y echaban fuera muchos demonios, y ungían con aceite á muchos enfermos, y sanaban."}, {"numero": 14, "texto": "Y oyó el rey Herodes la fama de Jesús, porque su nombre se había hecho notorio; y dijo: Juan el que bautizaba, ha resucitado de los muertos, y por tanto, virtudes obran en él."}, {"numero": 15, "texto": "Otros decían: Elías es. Y otros decían: Profeta es, ó alguno de los profetas."}, {"numero": 16, "texto": "Y oyéndolo Herodes, dijo: Este es Juan el que yo degollé: él ha resucitado de los muertos."}, {"numero": 17, "texto": "Porque el mismo Herodes había enviado, y prendido á Juan, y le había aprisionado en la cárcel á causa de Herodías, mujer de Felipe su hermano; pues la había tomado por mujer."}, {"numero": 18, "texto": "Porque Juan decía á Herodes: No te es lícito tener la mujer de tu hermano."}, {"numero": 19, "texto": "Mas Herodías le acechaba, y deseaba matarle, y no podía:"}, {"numero": 20, "texto": "Porque Herodes temía á Juan, sabiendo que era varón justo y santo, y le tenía respeto: y oyéndole, hacía muchas cosas; y le oía de buena gana."}, {"numero": 21, "texto": "Y venido un día oportuno, en que Herodes, en la fiesta de su nacimiento, daba una cena á sus príncipes y tribunos, y á los principales de Galilea;"}, {"numero": 22, "texto": "Y entrando la hija de Herodías, y danzando, y agradando á Herodes y á los que estaban con él á la mesa, el rey dijo á la muchacha: Pídeme lo que quisieres, que yo te lo daré."}, {"numero": 23, "texto": "Y le juró: Todo lo que me pidieres te daré, hasta la mitad de mi reino."}, {"numero": 24, "texto": "Y saliendo ella, dijo á su madre: ¿Qué pediré? Y ella dijo: La cabeza de Juan Bautista."}, {"numero": 25, "texto": "Entonces ella entró prestamente al rey, y pidió, diciendo: Quiero que ahora mismo me des en un plato la cabeza de Juan Bautista."}, {"numero": 26, "texto": "Y el rey se entristeció mucho; mas á causa del juramento, y de los que estaban con él á la mesa, no quiso desecharla."}, {"numero": 27, "texto": "Y luego el rey, enviando uno de la guardia, mandó que fuese traída su cabeza;"}, {"numero": 28, "texto": "El cual fué, y le degolló en la cárcel, y trajo su cabeza en un plato, y la dió á la muchacha, y la muchacha la dió á su madre."}, {"numero": 29, "texto": "Y oyéndolo sus discípulos, vinieron y tomaron su cuerpo, y le pusieron en un sepulcro."}, {"numero": 30, "texto": "Y los apóstoles se juntaron con Jesús, y le contaron todo lo que habían hecho, y lo que habían enseñado."}, {"numero": 31, "texto": "Y él les dijo: Venid vosotros aparte al lugar desierto, y reposad un poco. Porque eran muchos los que iban y venían, que ni aun tenían lugar de comer."}, {"numero": 32, "texto": "Y se fueron en un barco al lugar desierto aparte."}, {"numero": 33, "texto": "Y los vieron ir muchos, y le conocieron; y concurrieron allá muchos á pie de las ciudades, y llegaron antes que ellos, y se juntaron á él."}, {"numero": 34, "texto": "Y saliendo Jesús vió grande multitud, y tuvo compasión de ellos, porque eran como ovejas que no tenían pastor; y les comenzó á enseñar muchas cosas."}, {"numero": 35, "texto": "Y como ya fuese el día muy entrado, sus discípulos llegaron á él, diciendo: El lugar es desierto, y el día ya muy entrado;"}, {"numero": 36, "texto": "Envíalos para que vayan á los cortijos y aldeas de alrededor, y compren para sí pan; porque no tienen qué comer."}, {"numero": 37, "texto": "Y respondiendo él, les dijo: Dadles de comer vosotros. Y le dijeron: ¿Que vayamos y compremos pan por doscientos denarios, y les demos de comer?"}, {"numero": 38, "texto": "Y él les dice: ¿Cuántos panes tenéis? Id, y vedlo. Y sabiéndolo, dijeron: Cinco, y dos peces."}, {"numero": 39, "texto": "Y les mandó que hiciesen recostar á todos por partidas sobre la hierba verde."}, {"numero": 40, "texto": "Y se recostaron por partidas, de ciento en ciento, y de cincuenta en cincuenta."}, {"numero": 41, "texto": "Y tomados los cinco panes y los dos peces, mirando al cielo, bendijo, y partió los panes, y dió á sus discípulos para que los pusiesen delante: y repartió á todos los dos peces."}, {"numero": 42, "texto": "Y comieron todos, y se hartaron."}, {"numero": 43, "texto": "Y alzaron de los pedazos doce cofines llenos, y de los peces."}, {"numero": 44, "texto": "Y los que comieron eran cinco mil hombres."}, {"numero": 45, "texto": "Y luego dió priesa á sus discípulos á subir en el barco, é ir delante de él á Bethsaida de la otra parte, entre tanto que él despedía la multitud."}, {"numero": 46, "texto": "Y después que los hubo despedido, se fué al monte á orar."}, {"numero": 47, "texto": "Y como fué la tarde, el barco estaba en medio de la mar, y él solo en tierra."}, {"numero": 48, "texto": "Y los vió fatigados bogando, porque el viento les era contrario: y cerca de la cuarta vigilia de la noche, vino á ellos andando sobre la mar, y quería precederlos."}, {"numero": 49, "texto": "Y viéndole ellos, que andaba sobre la mar, pensaron que era fantasma, y dieron voces;"}, {"numero": 50, "texto": "Porque todos le veían, y se turbaron. Mas luego habló con ellos, y les dijo: Alentaos; yo soy, no temáis."}, {"numero": 51, "texto": "Y subió á ellos en el barco, y calmó el viento: y ellos en gran manera estaban fuera de sí, y se maravillaban:"}, {"numero": 52, "texto": "Porque aun no habían considerado lo de los panes, por cuanto estaban ofuscados sus corazones."}, {"numero": 53, "texto": "Y cuando estuvieron de la otra parte, vinieron á tierra de Genezaret, y tomaron puerto."}, {"numero": 54, "texto": "Y saliendo ellos del barco, luego le conocieron."}, {"numero": 55, "texto": "Y recorriendo toda la tierra de alrededor, comenzaron á traer de todas partes enfermos en lechos, á donde oían que estaba."}, {"numero": 56, "texto": "Y donde quiera que entraba, en aldeas, ó ciudades, ó heredades, ponían en las calles á los que estaban enfermos, y le rogaban que tocasen siquiera el borde de su vestido; y todos los que le tocaban quedaban sanos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 7, 'pt', '[{"numero": 1, "texto": "Os fariseus, e alguns dos escribas, que tinham vindo de Jerusalém, reuniram-se com ele."}, {"numero": 2, "texto": "E, quando viram que alguns dos discípulos dele comiam pão com mãos impuras, isto é, sem lavar, repreendiam-lhes."}, {"numero": 3, "texto": "(Pois os fariseus, e todos os judeus, mantendo a tradição dos antigos, se não lavarem bastante as mãos, não comem."}, {"numero": 4, "texto": "E, quando voltam da rua, se não se lavarem, não comem; e há muitas outras coisas que se encarregam de guardar, [como] lavar os copos, as vasilhas, os utensílios de metal, e os leitos)."}, {"numero": 5, "texto": "Depois os fariseus e os escribas lhe perguntaram: Por que os teus discípulos não andam conforme a tradição dos antigos, em vez de comerem pão com as mãos sem lavar?"}, {"numero": 6, "texto": "E ele lhes respondeu: Bem profetizou Isaías acerca de vós, hipócritas! Como está escrito: Este povo me honra com os lábios, mas o seu coração está longe de mim."}, {"numero": 7, "texto": "Eles, porém, me honram em vão, ensinando como doutrinas mandamentos humanos."}, {"numero": 8, "texto": "Pois vós deixais o mandamento de Deus, e mantendes a tradição humana, [como] lavar as vasilhas e os copos; e fazeis muitas outras coisas semelhantes a estas."}, {"numero": 9, "texto": "E dizia-lhes: Vós dispensais o mandamento de Deus para guardardes a vossa tradição;"}, {"numero": 10, "texto": "porque Moisés disse: Honra o teu pai e a tua mãe. E quem maldisser ao pai ou à mãe terá de morrer."}, {"numero": 11, "texto": "Mas vós dizeis: Se o homem disser ao pai ou à mãe: Tudo o que te puder aproveitar de mim é corbã (isto é, oferta),"}, {"numero": 12, "texto": "então não lhe deixais mais nada fazer por seu pai ou por sua mãe."}, {"numero": 13, "texto": "Assim invalidaias a palavra de Deus por vossa tradição, que ordenastes; e [fazeis] muitas coisas semelhantes a estas."}, {"numero": 14, "texto": "E chamando para si toda a multidão, disse-lhes: Ouvi-me todos, e entendei:"}, {"numero": 15, "texto": "Nada há fora do ser humano que nele entre que o possa contaminar; mas o que dele sai, isso é o que contamina o ser humano."}, {"numero": 16, "texto": "Se alguém tem ouvidos para ouvir, ouça."}, {"numero": 17, "texto": "Quando [Jesus] deixou a multidão e entrou em casa, seus discípulos lhe perguntaram sobre a parábola."}, {"numero": 18, "texto": "E ele lhes disse: Também vós estais assim sem entendimento? Não entendeis que tudo o que de fora entra no ser humano não o pode contaminar?"}, {"numero": 19, "texto": "Pois não entra no seu coração, mas, sim, no ventre, e sai para a privada. (Assim, ele declarou como limpas todas as comidas)."}, {"numero": 20, "texto": "E dizia: O que sai do ser humano, isso contamina o ser humano."}, {"numero": 21, "texto": "Pois é de dentro do coração humano que vêm os maus pensamentos, os adultérios, os pecados sexuais, os homicídios,"}, {"numero": 22, "texto": "os roubos, as ganâncias, as maldades, o engano, a depravação, o olho malicioso, a blasfêmia, a soberba, a insensatez."}, {"numero": 23, "texto": "Todos estes males procedem de dentro, e contaminam o ser humano."}, {"numero": 24, "texto": "[Jesus] levantou-se dali e foi para a região de Tiro e de Sidom. Ele entrou numa casa, e não queria que ninguém soubesse disso, mas não pôde se esconder."}, {"numero": 25, "texto": "Pois uma mulher, cuja filhinha tinha um espírito imundo, assim que ouviu falar dele, veio, e prostrou-se a seus pés."}, {"numero": 26, "texto": "Esta mulher era grega, de nacionalidade sirofenícia; e rogava-lhe que expulsasse o demônio de sua filha."}, {"numero": 27, "texto": "Mas Jesus lhe disse: Deixa primeiro que os filhos se fartem; porque não é bom tomar o pão dos filhos, e lançá-lo aos cachorrinhos."}, {"numero": 28, "texto": "Porém ela lhe respondeu: Sim Senhor; mas também os cachorrinhos comem debaixo da mesa, das migalhas que os filhos deixam."}, {"numero": 29, "texto": "Então ele lhe disse: Por esta palavra, vai, o demônio já saiu da tua filha."}, {"numero": 30, "texto": "Quando ela chegou à sua casa, encontrou que o demônio já havia saído, e a filha estava deitada sobre a cama."}, {"numero": 31, "texto": "Então [Jesus] voltou a sair da região de Tiro e de Sidom, e veio para o mar da Galilea, por meio da região de Decápolis."}, {"numero": 32, "texto": "E trouxeram-lhe um surdo que dificilmente falava, e rogaram-lhe que pusesse a mão sobre ele."}, {"numero": 33, "texto": "E tomando-o em separado da multidão, pôs os seus dedos nos ouvidos dele, cuspiu, e tocou-lhe a língua."}, {"numero": 34, "texto": "Depois, levantando os olhos ao céu, suspirou, e disse: Efatá, (isto é, abre-te)."}, {"numero": 35, "texto": "Imediatamente os ouvidos dele se abriram, e o que prendia sua língua se soltou, e passou a falar bem."}, {"numero": 36, "texto": "[Jesus] lhes mandou que a ninguém dissessem; porém, quanto mais lhes mandava, mais divulgavam."}, {"numero": 37, "texto": "E ficavam muito admirados, dizendo: Ele faz tudo bem! Aos surdos faz ouvir, e aos mudos falar."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 7, 'en', '[{"numero": 1, "texto": "Then came together unto him the Pharisees, and certain of the scribes, which came from Jerusalem."}, {"numero": 2, "texto": "And when they saw some of his disciples eat bread with defiled, that is to say, with unwashen, hands, they found fault."}, {"numero": 3, "texto": "For the Pharisees, and all the Jews, except they wash their hands oft, eat not, holding the tradition of the elders."}, {"numero": 4, "texto": "And when they come from the market, except they wash, they eat not. And many other things there be, which they have received to hold, as the washing of cups, and pots, brasen vessels, and of tables."}, {"numero": 5, "texto": "Then the Pharisees and scribes asked him, Why walk not thy disciples according to the tradition of the elders, but eat bread with unwashen hands?"}, {"numero": 6, "texto": "He answered and said unto them, Well hath Esaias prophesied of you hypocrites, as it is written, This people honoureth me with their lips, but their heart is far from me."}, {"numero": 7, "texto": "Howbeit in vain do they worship me, teaching for doctrines the commandments of men."}, {"numero": 8, "texto": "For laying aside the commandment of God, ye hold the tradition of men, as the washing of pots and cups: and many other such like things ye do."}, {"numero": 9, "texto": "And he said unto them, Full well ye reject the commandment of God, that ye may keep your own tradition."}, {"numero": 10, "texto": "For Moses said, Honour thy father and thy mother; and, Whoso curseth father or mother, let him die the death:"}, {"numero": 11, "texto": "But ye say, If a man shall say to his father or mother, It is Corban, that is to say, a gift, by whatsoever thou mightest be profited by me; he shall be free."}, {"numero": 12, "texto": "And ye suffer him no more to do ought for his father or his mother;"}, {"numero": 13, "texto": "Making the word of God of none effect through your tradition, which ye have delivered: and many such like things do ye."}, {"numero": 14, "texto": "And when he had called all the people unto him, he said unto them, Hearken unto me every one of you, and understand:"}, {"numero": 15, "texto": "There is nothing from without a man, that entering into him can defile him: but the things which come out of him, those are they that defile the man."}, {"numero": 16, "texto": "If any man have ears to hear, let him hear."}, {"numero": 17, "texto": "And when he was entered into the house from the people, his disciples asked him concerning the parable."}, {"numero": 18, "texto": "And he saith unto them, Are ye so without understanding also? Do ye not perceive, that whatsoever thing from without entereth into the man, it cannot defile him;"}, {"numero": 19, "texto": "Because it entereth not into his heart, but into the belly, and goeth out into the draught, purging all meats?"}, {"numero": 20, "texto": "And he said, That which cometh out of the man, that defileth the man."}, {"numero": 21, "texto": "For from within, out of the heart of men, proceed evil thoughts, adulteries, fornications, murders,"}, {"numero": 22, "texto": "Thefts, covetousness, wickedness, deceit, lasciviousness, an evil eye, blasphemy, pride, foolishness:"}, {"numero": 23, "texto": "All these evil things come from within, and defile the man."}, {"numero": 24, "texto": "And from thence he arose, and went into the borders of Tyre and Sidon, and entered into an house, and would have no man know it: but he could not be hid."}, {"numero": 25, "texto": "For a certain woman, whose young daughter had an unclean spirit, heard of him, and came and fell at his feet:"}, {"numero": 26, "texto": "The woman was a Greek, a Syrophenician by nation; and she besought him that he would cast forth the devil out of her daughter."}, {"numero": 27, "texto": "But Jesus said unto her, Let the children first be filled: for it is not meet to take the children''s bread, and to cast it unto the dogs."}, {"numero": 28, "texto": "And she answered and said unto him, Yes, Lord: yet the dogs under the table eat of the children''s crumbs."}, {"numero": 29, "texto": "And he said unto her, For this saying go thy way; the devil is gone out of thy daughter."}, {"numero": 30, "texto": "And when she was come to her house, she found the devil gone out, and her daughter laid upon the bed."}, {"numero": 31, "texto": "And again, departing from the coasts of Tyre and Sidon, he came unto the sea of Galilee, through the midst of the coasts of Decapolis."}, {"numero": 32, "texto": "And they bring unto him one that was deaf, and had an impediment in his speech; and they beseech him to put his hand upon him."}, {"numero": 33, "texto": "And he took him aside from the multitude, and put his fingers into his ears, and he spit, and touched his tongue;"}, {"numero": 34, "texto": "And looking up to heaven, he sighed, and saith unto him, Ephphatha, that is, Be opened."}, {"numero": 35, "texto": "And straightway his ears were opened, and the string of his tongue was loosed, and he spake plain."}, {"numero": 36, "texto": "And he charged them that they should tell no man: but the more he charged them, so much the more a great deal they published it;"}, {"numero": 37, "texto": "And were beyond measure astonished, saying, He hath done all things well: he maketh both the deaf to hear, and the dumb to speak."}]'::jsonb, 'King James Version'),
  ('Mc', 7, 'fr', '[{"numero": 1, "texto": "Les pharisiens et quelques scribes, venus de Jérusalem, s''''assemblèrent auprès de Jésus."}, {"numero": 2, "texto": "Ils virent quelques-uns de ses disciples prendre leurs repas avec des mains impures, c''''est-à-dire, non lavées."}, {"numero": 3, "texto": "Or, les pharisiens et tous les Juifs ne mangent pas sans s''''être lavé soigneusement les mains, conformément à la tradition des anciens;"}, {"numero": 4, "texto": "et, quand ils reviennent de la place publique, ils ne mangent qu''''après s''''être purifiés. Ils ont encore beaucoup d''''autres observances traditionnelles, comme le lavage des coupes, des cruches et des vases d''''airain."}, {"numero": 5, "texto": "Et les pharisiens et les scribes lui demandèrent: Pourquoi tes disciples ne suivent-ils pas la tradition des anciens, mais prennent-ils leurs repas avec des mains impures?"}, {"numero": 6, "texto": "Jésus leur répondit: Hypocrites, Esaïe a bien prophétisé sur vous, ainsi qu''''il est écrit: Ce peuple m''''honore des lèvres, Mais son coeur est éloigné de moi."}, {"numero": 7, "texto": "C''''est en vain qu''''ils m''''honorent, En donnant des préceptes qui sont des commandements d''''hommes."}, {"numero": 8, "texto": "Vous abandonnez le commandement de Dieu, et vous observez la tradition des hommes."}, {"numero": 9, "texto": "Il leur dit encore: Vous anéantissez fort bien le commandement de Dieu, pour garder votre tradition."}, {"numero": 10, "texto": "Car Moïse a dit: Honore ton père et ta mère; et: Celui qui maudira son père ou sa mère sera puni de mort."}, {"numero": 11, "texto": "Mais vous, vous dites: Si un homme dit à son père ou à sa mère: Ce dont j''''aurais pu t''''assister est corban, c''''est-à-dire, une offrande à Dieu,"}, {"numero": 12, "texto": "vous ne le laissez plus rien faire pour son père ou pour sa mère,"}, {"numero": 13, "texto": "annulant ainsi la parole de Dieu par votre tradition, que vous avez établie. Et vous faites beaucoup d''''autres choses semblables."}, {"numero": 14, "texto": "Ensuite, ayant de nouveau appelé la foule à lui, il lui dit: Ecoutez-moi tous, et comprenez."}, {"numero": 15, "texto": "Il n''''est hors de l''''homme rien qui, entrant en lui, puisse le souiller; mais ce qui sort de l''''homme, c''''est ce qui le souille."}, {"numero": 16, "texto": "Si quelqu''''un a des oreilles pour entendre, qu''''il entende."}, {"numero": 17, "texto": "Lorsqu''''il fut entré dans la maison, loin de la foule, ses disciples l''''interrogèrent sur cette parabole."}, {"numero": 18, "texto": "Il leur dit: Vous aussi, êtes-vous donc sans intelligence? Ne comprenez-vous pas que rien de ce qui du dehors entre dans l''''homme ne peut le souiller?"}, {"numero": 19, "texto": "Car cela n''''entre pas dans son coeur, mais dans son ventre, puis s''''en va dans les lieux secrets, qui purifient tous les aliments."}, {"numero": 20, "texto": "Il dit encore: Ce qui sort de l''''homme, c''''est ce qui souille l''''homme."}, {"numero": 21, "texto": "Car c''''est du dedans, c''''est du coeur des hommes, que sortent les mauvaises pensées, les adultères, les impudicités, les meurtres,"}, {"numero": 22, "texto": "les vols, les cupidités, les méchancetés, la fraude, le dérèglement, le regard envieux, la calomnie, l''''orgueil, la folie."}, {"numero": 23, "texto": "Toutes ces choses mauvaises sortent du dedans, et souillent l''''homme."}, {"numero": 24, "texto": "Jésus, étant parti de là, s''''en alla dans le territoire de Tyr et de Sidon. Il entra dans une maison, désirant que personne ne le sût; mais il ne put rester caché."}, {"numero": 25, "texto": "Car une femme, dont la fille était possédée d''''un esprit impur, entendit parler de lui, et vint se jeter à ses pieds."}, {"numero": 26, "texto": "Cette femme était grecque, syro-phénicienne d''''origine. Elle le pria de chasser le démon hors de sa fille."}, {"numero": 27, "texto": "Jésus lui dit: Laisse d''''abord les enfants se rassasier; car il n''''est pas bien de prendre le pain des enfants, et de le jeter aux petits chiens."}, {"numero": 28, "texto": "Oui, Seigneur, lui répondit-elle, mais les petits chiens, sous la table, mangent les miettes des enfants."}, {"numero": 29, "texto": "Alors il lui dit: à cause de cette parole, va, le démon est sorti de ta fille."}, {"numero": 30, "texto": "Et, quand elle rentra dans sa maison, elle trouva l''''enfant couchée sur le lit, le démon étant sorti."}, {"numero": 31, "texto": "Jésus quitta le territoire de Tyr, et revint par Sidon vers la mer de Galilée, en traversant le pays de la Décapole."}, {"numero": 32, "texto": "On lui amena un sourd, qui avait de la difficulté à parler, et on le pria de lui imposer les mains."}, {"numero": 33, "texto": "Il le prit à part loin de la foule, lui mit les doigts dans les oreilles, et lui toucha la langue avec sa propre salive;"}, {"numero": 34, "texto": "puis, levant les yeux au ciel, il soupira, et dit: Ephphatha, c''''est-à-dire, ouvre-toi."}, {"numero": 35, "texto": "Aussitôt ses oreilles s''''ouvrirent, sa langue se délia, et il parla très bien."}, {"numero": 36, "texto": "Jésus leur recommanda de n''''en parler à personne; mais plus il le leur recommanda, plus ils le publièrent."}, {"numero": 37, "texto": "Ils étaient dans le plus grand étonnement, et disaient: Il fait tout à merveille; même il fait entendre les sourds, et parler les muets."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 7, 'es', '[{"numero": 1, "texto": "Y SE juntaron á él los Fariseos, y algunos de los escribas, que habían venido de Jerusalem;"}, {"numero": 2, "texto": "Los cuales, viendo á algunos de sus discípulos comer pan con manos comunes, es á saber, no lavadas, los condenaban."}, {"numero": 3, "texto": "(Porque los Fariseos y todos los Judíos, teniendo la tradición de los ancianos, si muchas veces no se lavan las manos, no comen."}, {"numero": 4, "texto": "Y volviendo de la plaza, si no se lavaren, no comen. Y otras muchas cosas hay, que tomaron para guardar, como las lavaduras de los vasos de beber, y de los jarros, y de los vasos de metal, y de los lechos.)"}, {"numero": 5, "texto": "Y le preguntaron los Fariseos y los escribas: ¿Por qué tus discípulos no andan conforme á la tradición de los ancianos, sino que comen pan con manos comunes?"}, {"numero": 6, "texto": "Y respondiendo él, les dijo: Hipócritas, bien profetizó de vosotros Isaías, como está escrito: Este pueblo con los labios me honra, mas su corazón lejos está de mí."}, {"numero": 7, "texto": "Y en vano me honran, enseñando como doctrinas mandamientos de hombres."}, {"numero": 8, "texto": "Porque dejando el mandamiento de Dios, tenéis la tradición de los hombres; las lavaduras de los jarros y de los vasos de beber: y hacéis otras muchas cosas semejantes."}, {"numero": 9, "texto": "Les decía también: Bien invalidáis el mandamiento de Dios para guardar vuestra tradición."}, {"numero": 10, "texto": "Porque Moisés dijo: Honra á tu padre y á tu madre, y: El que maldijere al padre ó á la madre, morirá de muerte."}, {"numero": 11, "texto": "Y vosotros decís: Basta si dijere un hombre al padre ó la madre: Es Corbán (quiere decir, don mío á Dios) todo aquello con que pudiera valerte;"}, {"numero": 12, "texto": "Y no le dejáis hacer más por su padre ó por su madre,"}, {"numero": 13, "texto": "Invalidando la palabra de Dios con vuestra tradición que disteis: y muchas cosas hacéis semejantes á éstas."}, {"numero": 14, "texto": "Y llamando á toda la multitud, les dijo: Oidme todos, y entended:"}, {"numero": 15, "texto": "Nada hay fuera del hombre que entre en él, que le pueda contaminar: mas lo que sale de él, aquello es lo que contamina al hombre."}, {"numero": 16, "texto": "Si alguno tiene oídos para oir, oiga."}, {"numero": 17, "texto": "Y apartado de la multitud, habiendo entrado en casa, le preguntaron sus discípulos sobre la parábola."}, {"numero": 18, "texto": "Y díjoles: ¿También vosotros estáis así sin entendimiento? ¿No entendéis que todo lo de fuera que entra en el hombre, no le puede contaminar;"}, {"numero": 19, "texto": "Porque no entra en su corazón, sino en el vientre, y sale á la secreta? Esto decía, haciendo limpias todas las viandas."}, {"numero": 20, "texto": "Mas decía, que lo que del hombre sale, aquello contamina al hombre."}, {"numero": 21, "texto": "Porque de dentro, del corazón de los hombres, salen los malos pensamientos, los adulterios, las fornicaciones, los homicidios,"}, {"numero": 22, "texto": "Los hurtos, las avaricias, las maldades, el engaño, las desvergüenzas, el ojo maligno, las injurias, la soberbia, la insensatez."}, {"numero": 23, "texto": "Todas estas maldades de dentro salen, y contaminan al hombre."}, {"numero": 24, "texto": "Y levantándose de allí, se fué á los términos de Tiro y de Sidón; y entrando en casa, quiso que nadie lo supiese; mas no pudo esconderse."}, {"numero": 25, "texto": "Porque una mujer, cuya hija tenía un espíritu inmundo, luego que oyó de él, vino y se echó á sus pies."}, {"numero": 26, "texto": "Y la mujer era Griega, Sirofenisa de nación; y le rogaba que echase fuera de su hija al demonio."}, {"numero": 27, "texto": "Mas Jesús le dijo: Deja primero hartarse los hijos, porque no es bien tomar el pan de los hijos y echarlo á los perrillos."}, {"numero": 28, "texto": "Y respondió ella, y le dijo: Sí, Señor; pero aun los perrillos debajo de la mesa, comen de las migajas de los hijos."}, {"numero": 29, "texto": "Entonces le dice: Por esta palabra, ve; el demonio ha salido de tu hija."}, {"numero": 30, "texto": "Y como fué á su casa, halló que el demonio había salido, y á la hija echada sobre la cama."}, {"numero": 31, "texto": "Y volviendo á salir de los términos de Tiro, vino por Sidón á la mar de Galilea, por mitad de los términos de Decápolis."}, {"numero": 32, "texto": "Y le traen un sordo y tartamudo, y le ruegan que le ponga la mano encima."}, {"numero": 33, "texto": "Y tomándole aparte de la gente, metió sus dedos en las orejas de él, y escupiendo, tocó su lengua;"}, {"numero": 34, "texto": "Y mirando al cielo, gimió, y le dijo: Ephphatha: que es decir: Sé abierto."}, {"numero": 35, "texto": "Y luego fueron abiertos sus oídos, y fué desatada la ligadura de su lengua, y hablaba bien."}, {"numero": 36, "texto": "Y les mandó que no lo dijesen á nadie; pero cuanto más les mandaba, tanto más y más lo divulgaban."}, {"numero": 37, "texto": "Y en gran manera se maravillaban, diciendo: Bien lo ha hecho todo: hace á los sordos oir, y á los mudos hablar."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 8, 'pt', '[{"numero": 1, "texto": "Naqueles dias, quando havia uma multidão muito grande, e não tinham o que comer, Jesus chamou os seus discípulos a si, e disse-lhes:"}, {"numero": 2, "texto": "Tenho compaixão da multidão, porque já há três dias que estão comigo, e não têm o que comer."}, {"numero": 3, "texto": "E se eu os deixar ir sem comer para suas casas desmaiarão no caminho; porque alguns deles vieram de longe."}, {"numero": 4, "texto": "Os seus discípulos lhe responderam: De onde poderá alguém saciar estes de pão aqui no deserto?"}, {"numero": 5, "texto": "[Jesus] lhes perguntou: Quantos pães tendes? E eles disseram: Sete."}, {"numero": 6, "texto": "Então mandou à multidão que se sentassem no chão. Em seguida, tomou os sete pães, e tendo dado graças, partiu-os, e os deu a seus discípulos, para que os pusessem diante deles. E eles os puseram diante da multidão."}, {"numero": 7, "texto": "E tinham uns poucos peixinhos, e havendo dado graças, disse que também os pusessem diante deles."}, {"numero": 8, "texto": "Eles comeram, e se saciaram; e levantaram, do que sobrou dos pedaços, sete cestos."}, {"numero": 9, "texto": "Os que comeram eram quase quatro mil. Depois os despediu."}, {"numero": 10, "texto": "E logo entrou no barco com os seus discípulos, e veio para a região de Dalmanuta."}, {"numero": 11, "texto": "Os fariseus vieram, e começaram a disputar com ele, pedindo-lhe sinal do céu, para o testar."}, {"numero": 12, "texto": "E ele, suspirando profundamente em seu espírito, disse: Por que esta geração pede um sinal? Em verdade vos digo, que não se dará sinal a esta geração."}, {"numero": 13, "texto": "Então os deixou, voltou a entrar no barco , e foi para a outro lado [do mar] ."}, {"numero": 14, "texto": "E [os seus discípulos] haviam se esquecido de tomar pão, e nada tinham, a não ser um pão com eles no barco."}, {"numero": 15, "texto": "E [Jesus] lhes deu a seguinte ordem: Prestai atenção: tende cuidado com o fermento dos fariseus e o fermento de Herodes."}, {"numero": 16, "texto": "E indagavam-se com os outros , dizendo: É porque não temos pão."}, {"numero": 17, "texto": "Jesus soube e lhes disse: Por que indagais que não tendes pão? Não percebeis ainda, nem entendeis? Ainda tendes o vosso coração endurecido?"}, {"numero": 18, "texto": "Tendes olhos, e não vedes? Tendes ouvidos, e não ouvis?"}, {"numero": 19, "texto": "E não vos lembrais de, quando parti os cinco pães entre os cinco mil, quantos cestos cheios de pedaços levantastes?Responderam-lhe: Doze."}, {"numero": 20, "texto": "E quando [parti] os sete entre os quatro mil, quantas cestas cheias de pedaços levantastes? Eles disseram: Sete."}, {"numero": 21, "texto": "Ele lhes perguntou: Como não entendeis?"}, {"numero": 22, "texto": "Então veio a Betsaida. E trouxeram-lhe um cego, e rogaram-lhe que o tocasse."}, {"numero": 23, "texto": "Ele tomou o cego pela mão e o tirou para fora da aldeia. Depois cuspiu nos olhos dele e, pondo as mãos encima dele, perguntou-lhe se via alguma coisa."}, {"numero": 24, "texto": "Ele levantou os olhos e disse: Vejo as pessoas; pois vejo como árvores que andam."}, {"numero": 25, "texto": "Então [Jesus] pôs de novo as mãos sobre os seus olhos, e o fez olhar para cima . Assim ele ficou restabelecido, e passou a ver todos claramente."}, {"numero": 26, "texto": "Então o mandou para sua casa, dizendo: Não entres na aldeia, nem contes a ninguém da aldeia."}, {"numero": 27, "texto": "Jesus saiu com os seus discípulos para as aldeias de Cesareia de Filipe; e no caminho perguntou a seus discípulos: Quem as pessoas dizem que eu sou?"}, {"numero": 28, "texto": "Eles responderam: João Batista, e outros, Elias; e outros, algum dos profetas."}, {"numero": 29, "texto": "E ele lhes perguntou: E vós, quem dizeis que eu sou? Pedro lhe respondeu: Tu és o Cristo."}, {"numero": 30, "texto": "E lhes ordenou que a ninguém dissessem aquilo dele."}, {"numero": 31, "texto": "E começou a lhes ensinar que era necessário que o Filho do homem sofresse muito, e fosse rejeitado pelos anciãos e pelos chefes dos sacerdotes e escribas, e que fosse morto, e depois de três dias ressuscitasse."}, {"numero": 32, "texto": "Ele dizia essa palavra abertamente. Então Pedro o tomou à parte, e começou a repreendê-lo."}, {"numero": 33, "texto": "Mas [Jesus] virou-se e, olhando para os seus discípulos, repreendeu Pedro, dizendo: Sai de diante de mim, satanás! Pois tu não compreendes as coisas de Deus, mas sim as humanas."}, {"numero": 34, "texto": "Então chamou a si a multidão com os seus discípulos, e disse-lhes: Quem quiser vir após mim, negue a si mesmo, tome a sua cruz, e siga-me;"}, {"numero": 35, "texto": "pois quem quiser salvar a sua vida, a perderá; mas quem perder a sua vida por causa de mim e do Evangelho, esse a salvará."}, {"numero": 36, "texto": "Pois que proveito teria alguém, se ganhasse o mundo todo, e perdesse a sua alma?"}, {"numero": 37, "texto": "Ou que daria alguém em resgate de sua alma?"}, {"numero": 38, "texto": "Porque todo aquele que se envergonhar de mim e de minhas palavras nesta geração adúltera e pecadora, também o Filho do homem, quando vier na glória de seu Pai com os santos anjos, envergonhar-se-á dele."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 8, 'en', '[{"numero": 1, "texto": "In those days the multitude being very great, and having nothing to eat, Jesus called his disciples unto him, and saith unto them,"}, {"numero": 2, "texto": "I have compassion on the multitude, because they have now been with me three days, and have nothing to eat:"}, {"numero": 3, "texto": "And if I send them away fasting to their own houses, they will faint by the way: for divers of them came from far."}, {"numero": 4, "texto": "And his disciples answered him, From whence can a man satisfy these men with bread here in the wilderness?"}, {"numero": 5, "texto": "And he asked them, How many loaves have ye? And they said, Seven."}, {"numero": 6, "texto": "And he commanded the people to sit down on the ground: and he took the seven loaves, and gave thanks, and brake, and gave to his disciples to set before them; and they did set them before the people."}, {"numero": 7, "texto": "And they had a few small fishes: and he blessed, and commanded to set them also before them."}, {"numero": 8, "texto": "So they did eat, and were filled: and they took up of the broken meat that was left seven baskets."}, {"numero": 9, "texto": "And they that had eaten were about four thousand: and he sent them away."}, {"numero": 10, "texto": "And straightway he entered into a ship with his disciples, and came into the parts of Dalmanutha."}, {"numero": 11, "texto": "And the Pharisees came forth, and began to question with him, seeking of him a sign from heaven, tempting him."}, {"numero": 12, "texto": "And he sighed deeply in his spirit, and saith, Why doth this generation seek after a sign? verily I say unto you, There shall no sign be given unto this generation."}, {"numero": 13, "texto": "And he left them, and entering into the ship again departed to the other side."}, {"numero": 14, "texto": "Now the disciples had forgotten to take bread, neither had they in the ship with them more than one loaf."}, {"numero": 15, "texto": "And he charged them, saying, Take heed, beware of the leaven of the Pharisees, and of the leaven of Herod."}, {"numero": 16, "texto": "And they reasoned among themselves, saying, It is because we have no bread."}, {"numero": 17, "texto": "And when Jesus knew it, he saith unto them, Why reason ye, because ye have no bread? perceive ye not yet, neither understand? have ye your heart yet hardened?"}, {"numero": 18, "texto": "Having eyes, see ye not? and having ears, hear ye not? and do ye not remember?"}, {"numero": 19, "texto": "When I brake the five loaves among five thousand, how many baskets full of fragments took ye up? They say unto him, Twelve."}, {"numero": 20, "texto": "And when the seven among four thousand, how many baskets full of fragments took ye up? And they said, Seven."}, {"numero": 21, "texto": "And he said unto them, How is it that ye do not understand?"}, {"numero": 22, "texto": "And he cometh to Bethsaida; and they bring a blind man unto him, and besought him to touch him."}, {"numero": 23, "texto": "And he took the blind man by the hand, and led him out of the town; and when he had spit on his eyes, and put his hands upon him, he asked him if he saw ought."}, {"numero": 24, "texto": "And he looked up, and said, I see men as trees, walking."}, {"numero": 25, "texto": "After that he put his hands again upon his eyes, and made him look up: and he was restored, and saw every man clearly."}, {"numero": 26, "texto": "And he sent him away to his house, saying, Neither go into the town, nor tell it to any in the town."}, {"numero": 27, "texto": "And Jesus went out, and his disciples, into the towns of Caesarea Philippi: and by the way he asked his disciples, saying unto them, Whom do men say that I am?"}, {"numero": 28, "texto": "And they answered, John the Baptist; but some say, Elias; and others, One of the prophets."}, {"numero": 29, "texto": "And he saith unto them, But whom say ye that I am? And Peter answereth and saith unto him, Thou art the Christ."}, {"numero": 30, "texto": "And he charged them that they should tell no man of him."}, {"numero": 31, "texto": "And he began to teach them, that the Son of man must suffer many things, and be rejected of the elders, and of the chief priests, and scribes, and be killed, and after three days rise again."}, {"numero": 32, "texto": "And he spake that saying openly. And Peter took him, and began to rebuke him."}, {"numero": 33, "texto": "But when he had turned about and looked on his disciples, he rebuked Peter, saying, Get thee behind me, Satan: for thou savourest not the things that be of God, but the things that be of men."}, {"numero": 34, "texto": "And when he had called the people unto him with his disciples also, he said unto them, Whosoever will come after me, let him deny himself, and take up his cross, and follow me."}, {"numero": 35, "texto": "For whosoever will save his life shall lose it; but whosoever shall lose his life for my sake and the gospel''s, the same shall save it."}, {"numero": 36, "texto": "For what shall it profit a man, if he shall gain the whole world, and lose his own soul?"}, {"numero": 37, "texto": "Or what shall a man give in exchange for his soul?"}, {"numero": 38, "texto": "Whosoever therefore shall be ashamed of me and of my words in this adulterous and sinful generation; of him also shall the Son of man be ashamed, when he cometh in the glory of his Father with the holy angels."}]'::jsonb, 'King James Version'),
  ('Mc', 8, 'fr', '[{"numero": 1, "texto": "En ces jours-là, une foule nombreuse s''''étant de nouveau réunie et n''''ayant pas de quoi manger, Jésus appela les disciples, et leur dit:"}, {"numero": 2, "texto": "Je suis ému de compassion pour cette foule; car voilà trois jours qu''''ils sont près de moi, et ils n''''ont rien à manger."}, {"numero": 3, "texto": "Si je les renvoie chez eux à jeun, les forces leur manqueront en chemin; car quelques-uns d''''entre eux sont venus de loin."}, {"numero": 4, "texto": "Ses disciples lui répondirent: Comment pourrait-on les rassasier de pains, ici, dans un lieu désert?"}, {"numero": 5, "texto": "Jésus leur demanda: Combien avez-vous de pains? Sept, répondirent-ils."}, {"numero": 6, "texto": "Alors il fit asseoir la foule par terre, prit les sept pains, et, après avoir rendu grâces, il les rompit, et les donna à ses disciples pour les distribuer; et ils les distribuèrent à la foule."}, {"numero": 7, "texto": "Ils avaient encore quelques petits poissons, et Jésus, ayant rendu grâces, les fit aussi distribuer."}, {"numero": 8, "texto": "Ils mangèrent et furent rassasiés, et l''''on emporta sept corbeilles pleines des morceaux qui restaient."}, {"numero": 9, "texto": "Ils étaient environ quatre mille. Ensuite Jésus les renvoya."}, {"numero": 10, "texto": "Aussitôt il monta dans la barque avec ses disciples, et se rendit dans la contrée de Dalmanutha."}, {"numero": 11, "texto": "Les pharisiens survinrent, se mirent à discuter avec Jésus, et, pour l''''éprouver, lui demandèrent un signe venant du ciel."}, {"numero": 12, "texto": "Jésus, soupirant profondément en son esprit, dit: Pourquoi cette génération demande-t-elle un signe? Je vous le dis en vérité, il ne sera point donné de signe à cette génération."}, {"numero": 13, "texto": "Puis il les quitta, et remonta dans la barque, pour passer sur l''''autre bord."}, {"numero": 14, "texto": "Les disciples avaient oublié de prendre des pains; ils n''''en avaient qu''''un seul avec eux dans la barque."}, {"numero": 15, "texto": "Jésus leur fit cette recommandation: Gardez-vous avec soin du levain des pharisiens et du levain d''''Hérode."}, {"numero": 16, "texto": "Les disciples raisonnaient entre eux, et disaient: C''''est parce que nous n''''avons pas de pains."}, {"numero": 17, "texto": "Jésus, l''''ayant connu, leur dit: Pourquoi raisonnez-vous sur ce que vous n''''avez pas de pains? Etes-vous encore sans intelligence, et ne comprenez-vous pas? Avez-vous le coeur endurci?"}, {"numero": 18, "texto": "Ayant des yeux, ne voyez-vous pas? Ayant des oreilles, n''''entendez-vous pas? Et n''''avez-vous point de mémoire?"}, {"numero": 19, "texto": "Quand j''''ai rompu les cinq pains pour les cinq mille hommes, combien de paniers pleins de morceaux avez-vous emportés? Douze, lui répondirent-ils."}, {"numero": 20, "texto": "Et quand j''''ai rompu les sept pains pour les quatre mille hommes, combien de corbeilles pleines de morceaux avez-vous emportées? Sept, répondirent-ils."}, {"numero": 21, "texto": "Et il leur dit: Ne comprenez-vous pas encore?"}, {"numero": 22, "texto": "Ils se rendirent à Bethsaïda; et on amena vers Jésus un aveugle, qu''''on le pria de toucher."}, {"numero": 23, "texto": "Il prit l''''aveugle par la main, et le conduisit hors du village; puis il lui mit de la salive sur les yeux, lui imposa les mains, et lui demanda s''''il voyait quelque chose."}, {"numero": 24, "texto": "Il regarda, et dit: J''''aperçois les hommes, mais j''''en vois comme des arbres, et qui marchent."}, {"numero": 25, "texto": "Jésus lui mit de nouveau les mains sur les yeux; et, quand l''''aveugle regarda fixement, il fut guéri, et vit tout distinctement."}, {"numero": 26, "texto": "Alors Jésus le renvoya dans sa maison, en disant: N''''entre pas au village."}, {"numero": 27, "texto": "Jésus s''''en alla, avec ses disciples, dans les villages de Césarée de Philippe, et il leur posa en chemin cette question: Qui dit-on que je suis?"}, {"numero": 28, "texto": "Ils répondirent: Jean Baptiste; les autres, Elie, les autres, l''''un des prophètes."}, {"numero": 29, "texto": "Et vous, leur demanda-t-il, qui dites-vous que je suis? Pierre lui répondit: Tu es le Christ."}, {"numero": 30, "texto": "Jésus leur recommanda sévèrement de ne dire cela de lui à personne."}, {"numero": 31, "texto": "Alors il commença à leur apprendre qu''''il fallait que le Fils de l''''homme souffrît beaucoup, qu''''il fût rejeté par les anciens, par les principaux sacrificateurs et par les scribes, qu''''il fût mis à mort, et qu''''il ressuscitât trois jours après."}, {"numero": 32, "texto": "Il leur disait ces choses ouvertement. Et Pierre, l''''ayant pris à part, se mit à le reprendre."}, {"numero": 33, "texto": "Mais Jésus, se retournant et regardant ses disciples, réprimanda Pierre, et dit: Arrière de moi, Satan! car tu ne conçois pas les choses de Dieu, tu n''''as que des pensées humaines."}, {"numero": 34, "texto": "Puis, ayant appelé la foule avec ses disciples, il leur dit: Si quelqu''''un veut venir après moi, qu''''il renonce à lui-même, qu''''il se charge de sa croix, et qu''''il me suive."}, {"numero": 35, "texto": "Car celui qui voudra sauver sa vie la perdra, mais celui qui perdra sa vie à cause de moi et de la bonne nouvelle la sauvera."}, {"numero": 36, "texto": "Et que sert-il à un homme de gagner tout le monde, s''''il perd son âme?"}, {"numero": 37, "texto": "Que donnerait un homme en échange de son âme?"}, {"numero": 38, "texto": "Car quiconque aura honte de moi et de mes paroles au milieu de cette génération adultère et pécheresse, le Fils de l''''homme aura aussi honte de lui, quand il viendra dans la gloire de son Père, avec les saints anges."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 8, 'es', '[{"numero": 1, "texto": "EN aquellos días, como hubo gran gentío, y no tenían qué comer, Jesús llamó á sus discípulos, y les dijo:"}, {"numero": 2, "texto": "Tengo compasión de la multitud, porque ya hace tres días que están conmigo, y no tienen qué comer:"}, {"numero": 3, "texto": "Y si los enviare en ayunas á sus casas, desmayarán en el camino; porque algunos de ellos han venido de lejos."}, {"numero": 4, "texto": "Y sus discípulos le respondieron: ¿De dónde podrá alguien hartar á estos de pan aquí en el desierto?"}, {"numero": 5, "texto": "Y les preguntó: ¿Cuántos panes tenéis? Y ellos dijeron: Siete."}, {"numero": 6, "texto": "Entonces mandó á la multitud que se recostase en tierra; y tomando los siete panes, habiendo dado gracias, partió, y dió á sus discípulos que los pusiesen delante: y los pusieron delante á la multitud."}, {"numero": 7, "texto": "Tenían también unos pocos pececillos: y los bendijo, y mandó que también los pusiesen delante."}, {"numero": 8, "texto": "Y comieron, y se hartaron: y levantaron de los pedazos que habían sobrado, siete espuertas."}, {"numero": 9, "texto": "Y eran los que comieron, como cuatro mil: y los despidió."}, {"numero": 10, "texto": "Y luego entrando en el barco con sus discípulos, vino á las partes de Dalmanutha."}, {"numero": 11, "texto": "Y vinieron los Fariseos, y comenzaron á altercar con él, pidiéndole señal del cielo, tentándole."}, {"numero": 12, "texto": "Y gimiendo en su espíritu, dice: ¿Por qué pide señal esta generación? De cierto os digo que no se dará señal á esta generación."}, {"numero": 13, "texto": "Y dejándolos, volvió á entrar en el barco, y se fué de la otra parte."}, {"numero": 14, "texto": "Y se habían olvidado de tomar pan, y no tenían sino un pan consigo en el barco."}, {"numero": 15, "texto": "Y les mandó, diciendo: Mirad, guardaos de la levadura de los Fariseos, y de la levadura de Herodes."}, {"numero": 16, "texto": "Y altercaban los unos con los otros diciendo: Pan no tenemos."}, {"numero": 17, "texto": "Y como Jesús lo entendió, les dice: ¿Qué altercáis, porque no tenéis pan? ¿no consideráis ni entendéis? ¿aun tenéis endurecido vuestro corazón?"}, {"numero": 18, "texto": "¿Teniendo ojos no veis, y teniendo oídos no oís? ¿y no os acordáis?"}, {"numero": 19, "texto": "Cuando partí los cinco panes entre cinco mil, ¿cuántas espuertas llenas de los pedazos alzasteis? Y ellos dijeron: Doce."}, {"numero": 20, "texto": "Y cuando los siete panes entre cuatro mil, ¿cuántas espuertas llenas de los pedazos alzasteis? Y ellos dijeron: Siete."}, {"numero": 21, "texto": "Y les dijo: ¿Cómo aun no entendéis?"}, {"numero": 22, "texto": "Y vino á Bethsaida; y le traen un ciego, y le ruegan que le tocase."}, {"numero": 23, "texto": "Entonces, tomando la mano del ciego, le sacó fuera de la aldea; y escupiendo en sus ojos, y poniéndole las manos encima, le preguntó si veía algo."}, {"numero": 24, "texto": "Y él mirando, dijo: Veo los hombres, pues veo que andan como árboles."}, {"numero": 25, "texto": "Luego le puso otra vez las manos sobre sus ojos, y le hizo que mirase; y fué restablecido, y vió de lejos y claramente á todos."}, {"numero": 26, "texto": "Y envióle á su casa, diciendo: No entres en la aldea, ni lo digas á nadie en la aldea."}, {"numero": 27, "texto": "Y salió Jesús y sus discípulos por las aldeas de Cesarea de Filipo. Y en el camino preguntó á sus discípulos, diciéndoles: ¿Quién dicen los hombres que soy yo?"}, {"numero": 28, "texto": "Y ellos respondieron: Juan Bautista; y otros, Elías; y otros, Alguno de los profetas."}, {"numero": 29, "texto": "Entonces él les dice: Y vosotros, ¿quién decís que soy yo? Y respondiendo Pedro, le dice: Tú eres el Cristo."}, {"numero": 30, "texto": "Y les apercibió que no hablasen de él á ninguno."}, {"numero": 31, "texto": "Y comenzó á enseñarles, que convenía que el Hijo del hombre padeciese mucho, y ser reprobado de los ancianos, y de los príncipes de los sacerdotes, y de los escribas, y ser muerto, y resucitar después de tres días."}, {"numero": 32, "texto": "Y claramente decía esta palabra. Entonces Pedro le tomó, y le comenzó á reprender."}, {"numero": 33, "texto": "Y él, volviéndose y mirando á sus discípulos, riñó á Pedro, diciendo: Apártate de mí, Satanás; porque no sabes las cosas que son de Dios, sino las que son de los hombres."}, {"numero": 34, "texto": "Y llamando á la gente con sus discípulos, les dijo: Cualquiera que quisiere venir en pos de mí, niéguese á sí mismo, y tome su cruz, y sígame."}, {"numero": 35, "texto": "Porque el que quisiere salvar su vida, la perderá; y el que perdiere su vida por causa de mí y del evangelio, la salvará."}, {"numero": 36, "texto": "Porque ¿qué aprovechará al hombre, si granjeare todo el mundo, y pierde su alma?"}, {"numero": 37, "texto": "¿O qué recompensa dará el hombre por su alma?"}, {"numero": 38, "texto": "Porque el que se avergonzare de mí y de mis palabras en esta generación adulterina y pecadora, el Hijo del hombre se avergonzará también de él, cuando vendrá en la gloria de su Padre con los santos ángeles."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 9, 'pt', '[{"numero": 1, "texto": "E disse-lhes também: Em verdade vos digo, que há alguns dos que aqui estão, que não experimentarão a morte, até que vejam o reino de Deus vindo com poder."}, {"numero": 2, "texto": "Seis dias depois, Jesus tomou consigo Pedro, Tiago, e João, e os levou à parte, sozinhos, para um alto monte ; e transfigurou-se diante deles."}, {"numero": 3, "texto": "E suas roupas ficaram resplandescentes, muito brancas como a neve , como nenhum lavadeiro na terra seria capaz de branquear."}, {"numero": 4, "texto": "E apareceu-lhes Elias com Moisés, e falavam com Jesus."}, {"numero": 5, "texto": "Então Pedro disse a Jesus: Mestre, é bom para nós estarmos aqui; façamos três tendas: uma para ti, uma para Moisés, e uma para Elias."}, {"numero": 6, "texto": "Pois ele não sabia o que dizia, pois estavam assombrados."}, {"numero": 7, "texto": "Então desceu uma nuvem, que os cobriu com a sua sombra, e veio uma voz da nuvem, que dizia: Este é meu Filho amado; a ele ouvi."}, {"numero": 8, "texto": "De repente, quando olharam em redor, não viram mais ninguém, a não ser só Jesus com eles."}, {"numero": 9, "texto": "Enquanto desciam do monte, [Jesus] lhes mandou que a ninguém contassem o que haviam visto, até que o Filho do homem ressuscitasse dos mortos."}, {"numero": 10, "texto": "E eles guardaram o caso entre si, perguntando uns aos outros o que seria aquilo de “ressuscitar dos mortos”."}, {"numero": 11, "texto": "Então lhe perguntaram: Por que os escribas dizem que Elias tem que vir primeiro?"}, {"numero": 12, "texto": "E ele lhes respondeu: De fato Elias vem primeiro, e restaura todas as coisas. Então, como está escrito sobre o Filho do homem tem que sofrer muito, e ser desprezado?"}, {"numero": 13, "texto": "Porém eu vos digo que Elias já veio, e fizeram-lhe tudo o que quiseram, como está escrito sobre ele."}, {"numero": 14, "texto": "E quando veio aos discípulos, ele viu uma grande multidão ao redor deles; e uns escribas estavam discutindo com eles."}, {"numero": 15, "texto": "Logo que toda a multidão o viu, ficou admirada. Então correram a ele, e o cumprimentaram."}, {"numero": 16, "texto": "[Jesus] perguntou aos escribas: O que estais discutindo com eles?"}, {"numero": 17, "texto": "E um da multidão respondeu: Mestre, trouxe a ti o meu filho, que tem um espírito mudo."}, {"numero": 18, "texto": "E onde quer que o toma, faz-lhe ter convulsões, solta espuma, range os dentes, e vai ficando rígido. Eu disse aos teus discípulos que o expulsassem, mas não conseguiram."}, {"numero": 19, "texto": "[Jesus] lhe respondeu: Ó geração incrédula! Até quando estarei ainda convosco? Até quando vos suportarei? Trazei-o a mim."}, {"numero": 20, "texto": "Então trouxeram-no a ele. E quando o viu, logo o espírito o fez ter uma convulsão e, caindo em terra, rolava, e espumava."}, {"numero": 21, "texto": "E perguntou ao seu pai: Quanto tempo há que isto lhe sobreveio? E ele lhe disse: Desde a infância."}, {"numero": 22, "texto": "E muitas vezes o lançou também no fogo e na água para o destruir. Mas, se podes algo, tem compaixão de nós, e ajuda-nos."}, {"numero": 23, "texto": "E Jesus lhe disse: Se podes crer, tudo é possível ao que crê."}, {"numero": 24, "texto": "Logo o pai do menino, clamando, com lágrimas, disse: Creio, Senhor! Ajuda-me na minha incredulidade."}, {"numero": 25, "texto": "Quando Jesus viu que a multidão corria e se ajuntava, repreendeu o espírito imundo, dizendo-lhe: Espírito mudo e surdo, eu te ordeno, sai dele, e nunca mais entres nele!"}, {"numero": 26, "texto": "Então [o espírito] , gritando, e fazendo-o ter muita convulsão, saiu. E [o menino] ficou como morto, de maneira que muitos diziam que estava morto."}, {"numero": 27, "texto": "Então Jesus o tomou pela mão, e o ergueu; e ele se levantou."}, {"numero": 28, "texto": "E quando entrou em casa, seus discípulos lhe perguntaram à parte: Por que nós não conseguimos o expulsar?"}, {"numero": 29, "texto": "E lhes respondeu: Este tipo não pode sair por coisa alguma, a não ser com oração e jejum."}, {"numero": 30, "texto": "Depois partiram dali, e caminharam pela Galileia. Mas [Jesus] não queria que ninguém soubesse,"}, {"numero": 31, "texto": "Porque ensinava a seus discípulos, e lhes dizia: O Filho do homem será entregue em mãos de homens, e o matarão; e [estando] ele morto, ressuscitará ao terceiro dia."}, {"numero": 32, "texto": "Mas eles não entendiam esta palavra, e temiam lhe perguntar."}, {"numero": 33, "texto": "E veio a Cafarnaum, e entrando em casa, perguntou-lhes: Que indagais entre vós pelo caminho?"}, {"numero": 34, "texto": "Mas eles se calaram; porque eles haviam discutido uns com os outros pelo caminho, qual [deles seria] o maior."}, {"numero": 35, "texto": "E sentando-se ele, chamou aos doze, e disse-lhes: Se alguém quiser ser o primeiro, seja o últimos de todos, e servo de todos."}, {"numero": 36, "texto": "E tomando um menino, ele o pôs no meio deles, e tomando-o entre seus braços, disse-lhes:"}, {"numero": 37, "texto": "Qualquer que em meu nome receber a um dos tais meninos, recebe a mim; e qualquer que me receber, não é a mim que recebe, mas, sim, àquele que me enviou."}, {"numero": 38, "texto": "E respondeu-lhe João, dizendo: Mestre, vimos um que em teu nome expulsava os demônios, e ele não nos segue. Então o proibimos, porque não nos segue."}, {"numero": 39, "texto": "Porém Jesus disse: Não o proibais; porque ninguém há que faça milagre em meu nome, e logo possa falar mal de mim."}, {"numero": 40, "texto": "Pois quem não é contra nós, é por nós."}, {"numero": 41, "texto": "Porque qualquer que vos der um copo d''água para beber em meu nome, porque sois de Cristo, em verdade vos digo, que não perderá sua recompensa."}, {"numero": 42, "texto": "E qualquer que conduzir ao pecado um destes pequenos que creem em mim, melhor lhe fora que lhe pusesse ao pescoço uma grande pedra de moinho, e que fosse lançado no mar."}, {"numero": 43, "texto": "E se a tua mão te faz pecar, corta-a; melhor te é entrar na vida mutilado, do que, tendo duas mãos, ir ao inferno, ao fogo que nunca se apaga."}, {"numero": 44, "texto": "Onde seu verme não morre, e o fogo nunca se apaga."}, {"numero": 45, "texto": "E se teu pé te faz pecar, corta-o; melhor te é entrar na vida manco, do que, tendo dois pés, ser lançado no inferno, no fogo que nunca se apaga."}, {"numero": 46, "texto": "Onde seu verme não morre, e o fogo nunca se apaga."}, {"numero": 47, "texto": "E se teu olho te faz pecar, lança-o fora; melhor te é entrar no Reino de Deus com um olho, do que, tendo dois olhos, ser lançado no fogo do inferno,"}, {"numero": 48, "texto": "onde seu verme não morre, e o fogo nunca se apaga."}, {"numero": 49, "texto": "Porque cada um será salgado com fogo, e cada sacrifício será salgado com sal."}, {"numero": 50, "texto": "O sal é bom; mas se o sal se tornar insípido, com que o temperareis? Tende sal em vós mesmos, e paz uns com os outros."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 9, 'en', '[{"numero": 1, "texto": "And he said unto them, Verily I say unto you, That there be some of them that stand here, which shall not taste of death, till they have seen the kingdom of God come with power."}, {"numero": 2, "texto": "And after six days Jesus taketh with him Peter, and James, and John, and leadeth them up into an high mountain apart by themselves: and he was transfigured before them."}, {"numero": 3, "texto": "And his raiment became shining, exceeding white as snow; so as no fuller on earth can white them."}, {"numero": 4, "texto": "And there appeared unto them Elias with Moses: and they were talking with Jesus."}, {"numero": 5, "texto": "And Peter answered and said to Jesus, Master, it is good for us to be here: and let us make three tabernacles; one for thee, and one for Moses, and one for Elias."}, {"numero": 6, "texto": "For he wist not what to say; for they were sore afraid."}, {"numero": 7, "texto": "And there was a cloud that overshadowed them: and a voice came out of the cloud, saying, This is my beloved Son: hear him."}, {"numero": 8, "texto": "And suddenly, when they had looked round about, they saw no man any more, save Jesus only with themselves."}, {"numero": 9, "texto": "And as they came down from the mountain, he charged them that they should tell no man what things they had seen, till the Son of man were risen from the dead."}, {"numero": 10, "texto": "And they kept that saying with themselves, questioning one with another what the rising from the dead should mean."}, {"numero": 11, "texto": "And they asked him, saying, Why say the scribes that Elias must first come?"}, {"numero": 12, "texto": "And he answered and told them, Elias verily cometh first, and restoreth all things; and how it is written of the Son of man, that he must suffer many things, and be set at nought."}, {"numero": 13, "texto": "But I say unto you, That Elias is indeed come, and they have done unto him whatsoever they listed, as it is written of him."}, {"numero": 14, "texto": "And when he came to his disciples, he saw a great multitude about them, and the scribes questioning with them."}, {"numero": 15, "texto": "And straightway all the people, when they beheld him, were greatly amazed, and running to him saluted him."}, {"numero": 16, "texto": "And he asked the scribes, What question ye with them?"}, {"numero": 17, "texto": "And one of the multitude answered and said, Master, I have brought unto thee my son, which hath a dumb spirit;"}, {"numero": 18, "texto": "And wheresoever he taketh him, he teareth him: and he foameth, and gnasheth with his teeth, and pineth away: and I spake to thy disciples that they should cast him out; and they could not."}, {"numero": 19, "texto": "He answereth him, and saith, O faithless generation, how long shall I be with you? how long shall I suffer you? bring him unto me."}, {"numero": 20, "texto": "And they brought him unto him: and when he saw him, straightway the spirit tare him; and he fell on the ground, and wallowed foaming."}, {"numero": 21, "texto": "And he asked his father, How long is it ago since this came unto him? And he said, Of a child."}, {"numero": 22, "texto": "And ofttimes it hath cast him into the fire, and into the waters, to destroy him: but if thou canst do any thing, have compassion on us, and help us."}, {"numero": 23, "texto": "Jesus said unto him, If thou canst believe, all things are possible to him that believeth."}, {"numero": 24, "texto": "And straightway the father of the child cried out, and said with tears, Lord, I believe; help thou mine unbelief."}, {"numero": 25, "texto": "When Jesus saw that the people came running together, he rebuked the foul spirit, saying unto him, Thou dumb and deaf spirit, I charge thee, come out of him, and enter no more into him."}, {"numero": 26, "texto": "And the spirit cried, and rent him sore, and came out of him: and he was as one dead; insomuch that many said, He is dead."}, {"numero": 27, "texto": "But Jesus took him by the hand, and lifted him up; and he arose."}, {"numero": 28, "texto": "And when he was come into the house, his disciples asked him privately, Why could not we cast him out?"}, {"numero": 29, "texto": "And he said unto them, This kind can come forth by nothing, but by prayer and fasting."}, {"numero": 30, "texto": "And they departed thence, and passed through Galilee; and he would not that any man should know it."}, {"numero": 31, "texto": "For he taught his disciples, and said unto them, The Son of man is delivered into the hands of men, and they shall kill him; and after that he is killed, he shall rise the third day."}, {"numero": 32, "texto": "But they understood not that saying, and were afraid to ask him."}, {"numero": 33, "texto": "And he came to Capernaum: and being in the house he asked them, What was it that ye disputed among yourselves by the way?"}, {"numero": 34, "texto": "But they held their peace: for by the way they had disputed among themselves, who should be the greatest."}, {"numero": 35, "texto": "And he sat down, and called the twelve, and saith unto them, If any man desire to be first, the same shall be last of all, and servant of all."}, {"numero": 36, "texto": "And he took a child, and set him in the midst of them: and when he had taken him in his arms, he said unto them,"}, {"numero": 37, "texto": "Whosoever shall receive one of such children in my name, receiveth me: and whosoever shall receive me, receiveth not me, but him that sent me."}, {"numero": 38, "texto": "And John answered him, saying, Master, we saw one casting out devils in thy name, and he followeth not us: and we forbad him, because he followeth not us."}, {"numero": 39, "texto": "But Jesus said, Forbid him not: for there is no man which shall do a miracle in my name, that can lightly speak evil of me."}, {"numero": 40, "texto": "For he that is not against us is on our part."}, {"numero": 41, "texto": "For whosoever shall give you a cup of water to drink in my name, because ye belong to Christ, verily I say unto you, he shall not lose his reward."}, {"numero": 42, "texto": "And whosoever shall offend one of these little ones that believe in me, it is better for him that a millstone were hanged about his neck, and he were cast into the sea."}, {"numero": 43, "texto": "And if thy hand offend thee, cut it off: it is better for thee to enter into life maimed, than having two hands to go into hell, into the fire that never shall be quenched:"}, {"numero": 44, "texto": "Where their worm dieth not, and the fire is not quenched."}, {"numero": 45, "texto": "And if thy foot offend thee, cut it off: it is better for thee to enter halt into life, than having two feet to be cast into hell, into the fire that never shall be quenched:"}, {"numero": 46, "texto": "Where their worm dieth not, and the fire is not quenched."}, {"numero": 47, "texto": "And if thine eye offend thee, pluck it out: it is better for thee to enter into the kingdom of God with one eye, than having two eyes to be cast into hell fire:"}, {"numero": 48, "texto": "Where their worm dieth not, and the fire is not quenched."}, {"numero": 49, "texto": "For every one shall be salted with fire, and every sacrifice shall be salted with salt."}, {"numero": 50, "texto": "Salt is good: but if the salt have lost his saltness, wherewith will ye season it? Have salt in yourselves, and have peace one with another."}]'::jsonb, 'King James Version'),
  ('Mc', 9, 'fr', '[{"numero": 1, "texto": "Il leur dit encore: Je vous le dis en vérité, quelques-uns de ceux qui sont ici ne mourront point, qu''''ils n''''aient vu le royaume de Dieu venir avec puissance."}, {"numero": 2, "texto": "Six jours après, Jésus prit avec lui Pierre, Jacques et Jean, et il les conduisit seuls à l''''écart sur une haute montagne. Il fut transfiguré devant eux;"}, {"numero": 3, "texto": "ses vêtements devinrent resplendissants, et d''''une telle blancheur qu''''il n''''est pas de foulon sur la terre qui puisse blanchir ainsi."}, {"numero": 4, "texto": "Elie et Moïse leur apparurent, s''''entretenant avec Jésus."}, {"numero": 5, "texto": "Pierre, prenant la parole, dit à Jésus: Rabbi, il est bon que nous soyons ici; dressons trois tentes, une pour toi, une pour Moïse, et une pour Elie."}, {"numero": 6, "texto": "Car il ne savait que dire, l''''effroi les ayant saisis."}, {"numero": 7, "texto": "Une nuée vint les couvrir, et de la nuée sortit une voix: Celui-ci est mon Fils bien-aimé: écoutez-le!"}, {"numero": 8, "texto": "Aussitôt les disciples regardèrent tout autour, et ils ne virent que Jésus seul avec eux."}, {"numero": 9, "texto": "Comme ils descendaient de la montagne, Jésus leur recommanda de ne dire à personne ce qu''''ils avaient vu, jusqu''''à ce que le Fils de l''''homme fût ressuscité des morts."}, {"numero": 10, "texto": "Ils retinrent cette parole, se demandant entre eux ce que c''''est que ressusciter des morts."}, {"numero": 11, "texto": "Les disciples lui firent cette question: Pourquoi les scribes disent-ils qu''''il faut qu''''Elie vienne premièrement?"}, {"numero": 12, "texto": "Il leur répondit: Elie viendra premièrement, et rétablira toutes choses. Et pourquoi est-il écrit du Fils de l''''homme qu''''il doit souffrir beaucoup et être méprisé?"}, {"numero": 13, "texto": "Mais je vous dis qu''''Elie est venu, et qu''''ils l''''ont traité comme ils ont voulu, selon qu''''il est écrit de lui."}, {"numero": 14, "texto": "Lorsqu''''ils furent arrivés près des disciples, ils virent autour d''''eux une grande foule, et des scribes qui discutaient avec eux."}, {"numero": 15, "texto": "Dès que la foule vit Jésus, elle fut surprise, et accourut pour le saluer."}, {"numero": 16, "texto": "Il leur demanda: Sur quoi discutez-vous avec eux?"}, {"numero": 17, "texto": "Et un homme de la foule lui répondit: Maître, j''''ai amené auprès de toi mon fils, qui est possédé d''''un esprit muet."}, {"numero": 18, "texto": "En quelque lieu qu''''il le saisisse, il le jette par terre; l''''enfant écume, grince des dents, et devient tout raide. J''''ai prié tes disciples de chasser l''''esprit, et ils n''''ont pas pu."}, {"numero": 19, "texto": "Race incrédule, leur dit Jésus, jusques à quand serai-je avec vous? jusques à quand vous supporterai-je? Amenez-le-moi."}, {"numero": 20, "texto": "On le lui amena. Et aussitôt que l''''enfant vit Jésus, l''''esprit l''''agita avec violence; il tomba par terre, et se roulait en écumant."}, {"numero": 21, "texto": "Jésus demanda au père: Combien y a-t-il de temps que cela lui arrive? Depuis son enfance, répondit-il."}, {"numero": 22, "texto": "Et souvent l''''esprit l''''a jeté dans le feu et dans l''''eau pour le faire périr. Mais, si tu peux quelque chose, viens à notre secours, aie compassion de nous."}, {"numero": 23, "texto": "Jésus lui dit: Si tu peux!... Tout est possible à celui qui croit."}, {"numero": 24, "texto": "Aussitôt le père de l''''enfant s''''écria: Je crois! viens au secours de mon incrédulité!"}, {"numero": 25, "texto": "Jésus, voyant accourir la foule, menaça l''''esprit impur, et lui dit: Esprit muet et sourd, je te l''''ordonne, sors de cet enfant, et n''''y rentre plus."}, {"numero": 26, "texto": "Et il sortit, en poussant des cris, et en l''''agitant avec une grande violence. L''''enfant devint comme mort, de sorte que plusieurs disaient qu''''il était mort."}, {"numero": 27, "texto": "Mais Jésus, l''''ayant pris par la main, le fit lever. Et il se tint debout."}, {"numero": 28, "texto": "Quand Jésus fut entré dans la maison, ses disciples lui demandèrent en particulier: Pourquoi n''''avons-nous pu chasser cet esprit?"}, {"numero": 29, "texto": "Il leur dit: Cette espèce-là ne peut sortir que par la prière."}, {"numero": 30, "texto": "Ils partirent de là, et traversèrent la Galilée. Jésus ne voulait pas qu''''on le sût."}, {"numero": 31, "texto": "Car il enseignait ses disciples, et il leur dit: Le Fils de l''''homme sera livré entre les mains des hommes; ils le feront mourir, et, trois jours après qu''''il aura été mis à mort, il ressuscitera."}, {"numero": 32, "texto": "Mais les disciples ne comprenaient pas cette parole, et ils craignaient de l''''interroger."}, {"numero": 33, "texto": "Ils arrivèrent à Capernaüm. Lorsqu''''il fut dans la maison, Jésus leur demanda: De quoi discutiez-vous en chemin?"}, {"numero": 34, "texto": "Mais ils gardèrent le silence, car en chemin ils avaient discuté entre eux pour savoir qui était le plus grand."}, {"numero": 35, "texto": "Alors il s''''assit, appela les douze, et leur dit: Si quelqu''''un veut être le premier, il sera le dernier de tous et le serviteur de tous."}, {"numero": 36, "texto": "Et il prit un petit enfant, le plaça au milieu d''''eux, et l''''ayant pris dans ses bras, il leur dit:"}, {"numero": 37, "texto": "Quiconque reçoit en mon nom un de ces petits enfants me reçoit moi-même; et quiconque me reçoit, reçoit non pas moi, mais celui qui m''''a envoyé."}, {"numero": 38, "texto": "Jean lui dit: Maître, nous avons vu un homme qui chasse des démons en ton nom; et nous l''''en avons empêché, parce qu''''il ne nous suit pas."}, {"numero": 39, "texto": "Ne l''''en empêchez pas, répondit Jésus, car il n''''est personne qui, faisant un miracle en mon nom, puisse aussitôt après parler mal de moi."}, {"numero": 40, "texto": "Qui n''''est pas contre nous est pour nous."}, {"numero": 41, "texto": "Et quiconque vous donnera à boire un verre d''''eau en mon nom, parce que vous appartenez à Christ, je vous le dis en vérité, il ne perdra point sa récompense."}, {"numero": 42, "texto": "Mais, si quelqu''''un scandalisait un de ces petits qui croient, il vaudrait mieux pour lui qu''''on lui mît au cou une grosse meule de moulin, et qu''''on le jetât dans la mer."}, {"numero": 43, "texto": "Si ta main est pour toi une occasion de chute, coupe-la; mieux vaut pour toi entrer manchot dans la vie,"}, {"numero": 44, "texto": "que d''''avoir les deux mains et d''''aller dans la géhenne, dans le feu qui ne s''''éteint point."}, {"numero": 45, "texto": "Si ton pied est pour toi une occasion de chute, coupe-le; mieux vaut pour toi entrer boiteux dans la vie,"}, {"numero": 46, "texto": "que d''''avoir les deux pieds et d''''être jeté dans la géhenne, dans le feu qui ne s''''éteint point."}, {"numero": 47, "texto": "Et si ton oeil est pour toi une occasion de chute, arrache-le; mieux vaut pour toi entrer dans le royaume de Dieu n''''ayant qu''''un oeil, que d''''avoir deux yeux et d''''être jeté dans la géhenne,"}, {"numero": 48, "texto": "où leur ver ne meurt point, et où le feu ne s''''éteint point."}, {"numero": 49, "texto": "Car tout homme sera salé de feu."}, {"numero": 50, "texto": "Le sel est une bonne chose; mais si le sel devient sans saveur, avec quoi l''''assaisonnerez-vous? Ayez du sel en vous-mêmes, et soyez en paix les uns avec les autres."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 9, 'es', '[{"numero": 1, "texto": "TAMBIÉN les dijo: De cierto os digo que hay algunos de los que están aquí, que no gustarán la muerte hasta que hayan visto el reino de Dios que viene con potencia."}, {"numero": 2, "texto": "Y seis días después tomó Jesús á Pedro, y á Jacobo, y á Juan, y los sacó aparte solos á un monte alto; y fué transfigurado delante de ellos."}, {"numero": 3, "texto": "Y sus vestidos se volvieron resplandecientes, muy blancos, como la nieve; tanto que ningún lavador en la tierra los puede hacer tan blancos."}, {"numero": 4, "texto": "Y les apareció Elías con Moisés, que hablaban con Jesús."}, {"numero": 5, "texto": "Entonces respondiendo Pedro, dice á Jesús: Maestro, bien será que nos quedemos aquí, y hagamos tres pabellones: para ti uno, y para Moisés otro, y para Elías otro;"}, {"numero": 6, "texto": "Porque no sabía lo que hablaba; que estaban espantados."}, {"numero": 7, "texto": "Y vino una nube que les hizo sombra, y una voz de la nube, que decía: Este es mi Hijo amado: á él oid."}, {"numero": 8, "texto": "Y luego, como miraron, no vieron más á nadie consigo, sino á Jesús solo."}, {"numero": 9, "texto": "Y descendiendo ellos del monte, les mandó que á nadie dijesen lo que habían visto, sino cuando el Hijo del hombre hubiese resucitado de los muertos."}, {"numero": 10, "texto": "Y retuvieron la palabra en sí, altercando qué sería aquéllo: Resucitar de los muertos."}, {"numero": 11, "texto": "Y le preguntaron, diciendo: ¿Qué es lo que los escribas dicen, que es necesario que Elías venga antes?"}, {"numero": 12, "texto": "Y respondiendo él, les dijo: Elías á la verdad, viniendo antes, restituirá todas las cosas: y como está escrito del Hijo del hombre, que padezca mucho y sea tenido en nada."}, {"numero": 13, "texto": "Empero os digo que Elías ya vino, y le hicieron todo lo que quisieron, como está escrito de él."}, {"numero": 14, "texto": "Y como vino á los discípulos, vió grande compañía alrededor de ellos, y escribas que disputaban con ellos."}, {"numero": 15, "texto": "Y luego toda la gente, viéndole, se espantó, y corriendo á él, le saludaron."}, {"numero": 16, "texto": "Y preguntóles: ¿Qué disputáis con ellos?"}, {"numero": 17, "texto": "Y respondiendo uno de la compañía, dijo: Maestro, traje á ti mi hijo, que tiene un espíritu mudo,"}, {"numero": 18, "texto": "El cual, donde quiera que le toma, le despedaza; y echa espumarajos, y cruje los dientes, y se va secando: y dije á tus discípulos que le echasen fuera, y no pudieron."}, {"numero": 19, "texto": "Y respondiendo él, les dijo: ¡Oh generación infiel! ¿hasta cuándo estaré con vosotros? ¿hasta cuándo os tengo de sufrir? Traédmele."}, {"numero": 20, "texto": "Y se le trajeron: y como le vió, luego el espíritu le desgarraba; y cayendo en tierra, se revolcaba, echando espumarajos."}, {"numero": 21, "texto": "Y Jesús preguntó á su padre: ¿Cuánto tiempo há que le aconteció esto? Y él dijo: Desde niño:"}, {"numero": 22, "texto": "Y muchas veces le echa en el fuego y en aguas, para matarle; mas, si puedes algo, ayúdanos, teniendo misericordia de nosotros."}, {"numero": 23, "texto": "Y Jesús le dijo: Si puedes creer, al que cree todo es posible."}, {"numero": 24, "texto": "Y luego el padre del muchacho dijo clamando: Creo, ayuda mi incredulidad."}, {"numero": 25, "texto": "Y como Jesús vió que la multitud se agolpaba, reprendió al espíritu inmundo, diciéndole: Espíritu mudo y sordo, yo te mando, sal de él, y no entres más en él."}, {"numero": 26, "texto": "Entonces el espíritu clamando y desgarrándole mucho, salió; y él quedó como muerto, de modo que muchos decían: Está muerto."}, {"numero": 27, "texto": "Mas Jesús tomándole de la mano, enderezóle; y se levantó."}, {"numero": 28, "texto": "Y como él entró en casa, sus discípulos le preguntaron aparte: ¿Por qué nosotros no pudimos echarle fuera?"}, {"numero": 29, "texto": "Y les dijo: Este género con nada puede salir, sino con oración y ayuno."}, {"numero": 30, "texto": "Y habiendo salido de allí, caminaron por Galilea; y no quería que nadie lo supiese."}, {"numero": 31, "texto": "Porque enseñaba á sus discípulos, y les decía: El Hijo del hombre será entregado en manos de hombres, y le matarán; mas muerto él, resucitará al tercer día."}, {"numero": 32, "texto": "Pero ellos no entendían esta palabra, y tenían miedo de preguntarle."}, {"numero": 33, "texto": "Y llegó á Capernaum; y así que estuvo en casa, les preguntó: ¿Qué disputabais entre vosotros en el camino?"}, {"numero": 34, "texto": "Mas ellos callaron; porque los unos con los otros habían disputado en el camino quién había de ser el mayor."}, {"numero": 35, "texto": "Entonces sentándose, llamó á los doce, y les dice: Si alguno quiere ser el primero, será el postrero de todos, y el servidor de todos."}, {"numero": 36, "texto": "Y tomando un niño, púsolo en medio de ellos; y tomándole en sus brazos, les dice:"}, {"numero": 37, "texto": "El que recibiere en mi nombre uno de los tales niños, á mí recibe; y el que á mí recibe, no recibe á mí, mas al que me envió."}, {"numero": 38, "texto": "Y respondióle Juan, diciendo: Maestro, hemos visto á uno que en tu nombre echaba fuera los demonios, el cual no nos sigue; y se lo prohibimos, porque no nos sigue."}, {"numero": 39, "texto": "Y Jesús dijo: No se lo prohibáis; porque ninguno hay que haga milagro en mi nombre que luego pueda decir mal de mí."}, {"numero": 40, "texto": "Porque el que no es contra nosotros, por nosotros es."}, {"numero": 41, "texto": "Y cualquiera que os diere un vaso de agua en mi nombre, porque sois de Cristo, de cierto os digo que no perderá su recompensa."}, {"numero": 42, "texto": "Y cualquiera que escandalizare á uno de estos pequeñitos que creen en mí, mejor le fuera si se le atase una piedra de molino al cuello, y fuera echado en la mar."}, {"numero": 43, "texto": "Y si tu mano te escandalizare, córtala: mejor te es entrar á la vida manco, que teniendo dos manos ir á la Gehenna, al fuego que no puede ser apagado;"}, {"numero": 44, "texto": "Donde su gusano no muere, y el fuego nunca se apaga."}, {"numero": 45, "texto": "Y si tu pie te fuere ocasión de caer, córtalo: mejor te es entrar á la vida cojo, que teniendo dos pies ser echado en la Gehenna, al fuego que no puede ser apagado;"}, {"numero": 46, "texto": "Donde el gusano de ellos no muere, y el fuego nunca se apaga."}, {"numero": 47, "texto": "Y si tu ojo te fuere ocasión de caer, sácalo: mejor te es entrar al reino de Dios con un ojo, que teniendo dos ojos ser echado á la Gehenna;"}, {"numero": 48, "texto": "Donde el gusano de ellos no muere, y el fuego nunca se apaga."}, {"numero": 49, "texto": "Porque todos serán salados con fuego, y todo sacrificio será salado con sal."}, {"numero": 50, "texto": "Buena es la sal; mas si la sal fuere desabrida, ¿con qué la adobaréis? Tened en vosotros mismos sal; y tened paz los unos con los otros."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 10, 'pt', '[{"numero": 1, "texto": "E levantando-se dali, [Jesus] se foi aos limites da Judeia, por dalém do Jordão; e as multidões voltaram a se juntar a ele, e voltou a lhes ensinar, como tinha costume."}, {"numero": 2, "texto": "E vindo a ele os fariseus, perguntaram-lhe se era lícito ao homem deixar a [sua] mulher, testando-o."}, {"numero": 3, "texto": "Mas ele lhes respondeu: O que Moisés vos mandou?"}, {"numero": 4, "texto": "E eles disseram: Moisés permitiu escrever carta de divórcio, e deixá-la."}, {"numero": 5, "texto": "E Jesus lhes respondeu: Foi pela dureza dos vossos corações que ele vos escreveu este mandamento."}, {"numero": 6, "texto": "Porém, desde o princípio da criação, macho e fêmea Deus os fez."}, {"numero": 7, "texto": "Por isso, deixará o homem a seu pai e a [sua] mãe, e se unirá à sua mulher."}, {"numero": 8, "texto": "E os dois serão uma [só] carne; assim, já não são dois, mas sim uma [só] carne."}, {"numero": 9, "texto": "Portanto, o que Deus juntou, não separe o homem."}, {"numero": 10, "texto": "E em casa seus discípulos voltaram a lhe perguntar sobre isto mesmo."}, {"numero": 11, "texto": "E disse-lhes: Qualquer um que deixar a sua mulher, e se casar com outra, adultera contra ela."}, {"numero": 12, "texto": "E se a mulher deixar o seu marido, e se casar com outro, adultera."}, {"numero": 13, "texto": "E lhe traziam crianças para que ele as tocasse, mas os discípulos repreendiam aos que [as] traziam."}, {"numero": 14, "texto": "Porém Jesus, vendo, indignou-se, e lhe disse: Deixai vir as crianças a mim, e não as impeçais; porque delas é o Reino de Deus."}, {"numero": 15, "texto": "Em verdade vos digo, que qualquer um que não receber o Reino de Deus como criança, em maneira nenhuma nele entrará."}, {"numero": 16, "texto": "Então, tomando-as entre seus braços, e pondo as mãos sobre elas, ele as abençoou."}, {"numero": 17, "texto": "E quando ele saiu para caminhar, um [homem] correu até ele; e pondo-se de joelhos diante dele, perguntou-lhe: Bom Mestre, que farei para herdar a vida eterna?"}, {"numero": 18, "texto": "E Jesus lhe disse: Por que me chamas bom? Ninguém é bom, a não ser um: Deus."}, {"numero": 19, "texto": "Sabes os mandamentos: Não adulterarás; não matarás; não furtarás; não darás falso testemunho; não serás enganador; honra o teu pai e a [tua] mãe."}, {"numero": 20, "texto": "Porém ele lhe respondeu: Mestre, tudo isto guardei desde a minha juventude."}, {"numero": 21, "texto": "E olhando Jesus para ele, amou-o, e disse-lhe: Uma coisa te falta: vai, vende tudo quanto tens, e dá aos pobres; e terás um tesouro no céu; e vem, segue-me, toma [tua] cruz."}, {"numero": 22, "texto": "Mas ele, pesaroso desta palavra, foi-se triste; porque tinha muitas propriedades."}, {"numero": 23, "texto": "Então Jesus olhando ao redor, disse a seus discípulos: Como é difícil aos que têm riquezas entrar no Reino de Deus!"}, {"numero": 24, "texto": "E os discípulos se espantaram destas suas palavras; mas Jesus, voltando a responder, disse-lhes: Filhos, como é difícil aos que confiam em riquezas entrar no Reino de Deus!"}, {"numero": 25, "texto": "Mais fácil é passar um camelo pelo olho de uma agulha, do que entrar um rico no Reino de Deus."}, {"numero": 26, "texto": "E eles se espantavam ainda mais, dizendo uns para os outros: Quem, pois, poderá se salvar?"}, {"numero": 27, "texto": "Porém, olhando Jesus para eles, disse: Para os seres humanos, é impossível; mas para Deus, não; porque para Deus tudo é possível."}, {"numero": 28, "texto": "E Pedro começou a lhe dizer: Eis que nós deixamos tudo, e te seguimos."}, {"numero": 29, "texto": "Jesus respondeu: Em verdade vos digo, que não há ninguém que tenha deixado casa, ou irmãos, ou irmãs, ou pai, ou mãe, ou esposa, ou filhos, ou campos, por amor de mim e do Evangelho,"}, {"numero": 30, "texto": "que não receba cem vezes tanto, agora neste tempo, casas, e irmãos, e irmãs, e mães, e filhos, e campos, com perseguições; e a vida eterna, no tempo que virá."}, {"numero": 31, "texto": "Porém muitos primeiros serão últimos, e últimos, primeiros."}, {"numero": 32, "texto": "E iam pelo caminho, subindo para Jerusalém; e Jesus ia diante deles, e espantavam-se, e seguiam-no atemorizados. E voltando a tomar consigo aos doze, começou-lhes a dizer as coisas que lhe viriam a acontecer:"}, {"numero": 33, "texto": "Eis que subimos a Jerusalém, e o Filho do homem será entregue aos chefes dos sacerdotes, e aos escribas; e o condenarão à morte, e o entregarão aos gentios."}, {"numero": 34, "texto": "E escarnecerão dele, e o açoitarão, e cuspirão nele, e o matarão; e ao terceiro dia ressuscitará."}, {"numero": 35, "texto": "E vieram a ele Tiago e João, filhos de Zebedeu, dizendo: Mestre, queríamos que nos fizesses o que pedirmos."}, {"numero": 36, "texto": "E ele lhes disse: O que quereis que eu vos faça?"}, {"numero": 37, "texto": "E eles lhe disseram: Concede-nos que em tua glória nos sentemos, um à tua direita, e outro à tua esquerda?"}, {"numero": 38, "texto": "Mas Jesus lhes disse: Não sabeis o que pedis; podeis vós beber o copo que eu bebo, e ser batizados com o batismo com que eu sou batizado?"}, {"numero": 39, "texto": "E eles lhe disseram: Podemos. Porém Jesus lhes disse: Em verdade, o copo que eu bebo, bebereis; e com o batismo com que eu sou batizado, sereis batizados."}, {"numero": 40, "texto": "Mas sentar-se à minha direita, e à minha esquerda, não é meu concedê-lo, mas sim, para aqueles a quem está preparado."}, {"numero": 41, "texto": "E quando os dez ouviram isto, começaram a se irritar contra Tiago e João."}, {"numero": 42, "texto": "Mas Jesus, chamando-os a si, disse-lhes: Já sabeis que os que são vistos como governadores dos gentios, agem como senhores deles; e os grandes usam de autoridade sobre eles."}, {"numero": 43, "texto": "Mas entre vós não será assim; antes qualquer que entre vós quiser ser grande, será vosso servidor."}, {"numero": 44, "texto": "E qualquer que de vós quiser ser o primeiro, será servo de todos."}, {"numero": 45, "texto": "Porque também não veio o Filho do homem para ser servido, mas para servir, e dar sua vida em resgate por muitos."}, {"numero": 46, "texto": "E vieram a Jericó. E saindo ele, e seus discípulos, e uma grande multidão de Jericó, estava Bartimeu, um cego, filho de Timeu, sentado junto ao caminho."}, {"numero": 47, "texto": "E ouvindo que era Jesus o nazareno, começou a clamar, e a dizer: Jesus, Filho de Davi! Tem misericórdia de mim!"}, {"numero": 48, "texto": "E muitos o repreendiam, para que se calasse; mas ele clamava ainda mais: Filho de Davi! Tem misericórdia de mim!"}, {"numero": 49, "texto": "Jesus parou, e disse que o chamassem. Então chamaram ao cego, dizendo-lhe: Tem bom ânimo, levanta-te, ele está te chamando."}, {"numero": 50, "texto": "Então ele lançou sua capa, levantou-se, e veio a Jesus."}, {"numero": 51, "texto": "Jesus, lhe perguntou: Que queres que eu te faça? E o cego lhe disse: Mestre, que eu veja."}, {"numero": 52, "texto": "Jesus lhe disse: Vai; a tua fé te salvou. E logo consegiu ver. Então seguiu Jesus pelo caminho."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 10, 'en', '[{"numero": 1, "texto": "And he arose from thence, and cometh into the coasts of Judaea by the farther side of Jordan: and the people resort unto him again; and, as he was wont, he taught them again."}, {"numero": 2, "texto": "And the Pharisees came to him, and asked him, Is it lawful for a man to put away his wife? tempting him."}, {"numero": 3, "texto": "And he answered and said unto them, What did Moses command you?"}, {"numero": 4, "texto": "And they said, Moses suffered to write a bill of divorcement, and to put her away."}, {"numero": 5, "texto": "And Jesus answered and said unto them, For the hardness of your heart he wrote you this precept."}, {"numero": 6, "texto": "But from the beginning of the creation God made them male and female."}, {"numero": 7, "texto": "For this cause shall a man leave his father and mother, and cleave to his wife;"}, {"numero": 8, "texto": "And they twain shall be one flesh: so then they are no more twain, but one flesh."}, {"numero": 9, "texto": "What therefore God hath joined together, let not man put asunder."}, {"numero": 10, "texto": "And in the house his disciples asked him again of the same matter."}, {"numero": 11, "texto": "And he saith unto them, Whosoever shall put away his wife, and marry another, committeth adultery against her."}, {"numero": 12, "texto": "And if a woman shall put away her husband, and be married to another, she committeth adultery."}, {"numero": 13, "texto": "And they brought young children to him, that he should touch them: and his disciples rebuked those that brought them."}, {"numero": 14, "texto": "But when Jesus saw it, he was much displeased, and said unto them, Suffer the little children to come unto me, and forbid them not: for of such is the kingdom of God."}, {"numero": 15, "texto": "Verily I say unto you, Whosoever shall not receive the kingdom of God as a little child, he shall not enter therein."}, {"numero": 16, "texto": "And he took them up in his arms, put his hands upon them, and blessed them."}, {"numero": 17, "texto": "And when he was gone forth into the way, there came one running, and kneeled to him, and asked him, Good Master, what shall I do that I may inherit eternal life?"}, {"numero": 18, "texto": "And Jesus said unto him, Why callest thou me good? there is none good but one, that is, God."}, {"numero": 19, "texto": "Thou knowest the commandments, Do not commit adultery, Do not kill, Do not steal, Do not bear false witness, Defraud not, Honour thy father and mother."}, {"numero": 20, "texto": "And he answered and said unto him, Master, all these have I observed from my youth."}, {"numero": 21, "texto": "Then Jesus beholding him loved him, and said unto him, One thing thou lackest: go thy way, sell whatsoever thou hast, and give to the poor, and thou shalt have treasure in heaven: and come, take up the cross, and follow me."}, {"numero": 22, "texto": "And he was sad at that saying, and went away grieved: for he had great possessions."}, {"numero": 23, "texto": "And Jesus looked round about, and saith unto his disciples, How hardly shall they that have riches enter into the kingdom of God!"}, {"numero": 24, "texto": "And the disciples were astonished at his words. But Jesus answereth again, and saith unto them, Children, how hard is it for them that trust in riches to enter into the kingdom of God!"}, {"numero": 25, "texto": "It is easier for a camel to go through the eye of a needle, than for a rich man to enter into the kingdom of God."}, {"numero": 26, "texto": "And they were astonished out of measure, saying among themselves, Who then can be saved?"}, {"numero": 27, "texto": "And Jesus looking upon them saith, With men it is impossible, but not with God: for with God all things are possible."}, {"numero": 28, "texto": "Then Peter began to say unto him, Lo, we have left all, and have followed thee."}, {"numero": 29, "texto": "And Jesus answered and said, Verily I say unto you, There is no man that hath left house, or brethren, or sisters, or father, or mother, or wife, or children, or lands, for my sake, and the gospel''s,"}, {"numero": 30, "texto": "But he shall receive an hundredfold now in this time, houses, and brethren, and sisters, and mothers, and children, and lands, with persecutions; and in the world to come eternal life."}, {"numero": 31, "texto": "But many that are first shall be last; and the last first."}, {"numero": 32, "texto": "And they were in the way going up to Jerusalem; and Jesus went before them: and they were amazed; and as they followed, they were afraid. And he took again the twelve, and began to tell them what things should happen unto him,"}, {"numero": 33, "texto": "Saying, Behold, we go up to Jerusalem; and the Son of man shall be delivered unto the chief priests, and unto the scribes; and they shall condemn him to death, and shall deliver him to the Gentiles:"}, {"numero": 34, "texto": "And they shall mock him, and shall scourge him, and shall spit upon him, and shall kill him: and the third day he shall rise again."}, {"numero": 35, "texto": "And James and John, the sons of Zebedee, come unto him, saying, Master, we would that thou shouldest do for us whatsoever we shall desire."}, {"numero": 36, "texto": "And he said unto them, What would ye that I should do for you?"}, {"numero": 37, "texto": "They said unto him, Grant unto us that we may sit, one on thy right hand, and the other on thy left hand, in thy glory."}, {"numero": 38, "texto": "But Jesus said unto them, Ye know not what ye ask: can ye drink of the cup that I drink of? and be baptized with the baptism that I am baptized with?"}, {"numero": 39, "texto": "And they said unto him, We can. And Jesus said unto them, Ye shall indeed drink of the cup that I drink of; and with the baptism that I am baptized withal shall ye be baptized:"}, {"numero": 40, "texto": "But to sit on my right hand and on my left hand is not mine to give; but it shall be given to them for whom it is prepared."}, {"numero": 41, "texto": "And when the ten heard it, they began to be much displeased with James and John."}, {"numero": 42, "texto": "But Jesus called them to him, and saith unto them, Ye know that they which are accounted to rule over the Gentiles exercise lordship over them; and their great ones exercise authority upon them."}, {"numero": 43, "texto": "But so shall it not be among you: but whosoever will be great among you, shall be your minister:"}, {"numero": 44, "texto": "And whosoever of you will be the chiefest, shall be servant of all."}, {"numero": 45, "texto": "For even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many."}, {"numero": 46, "texto": "And they came to Jericho: and as he went out of Jericho with his disciples and a great number of people, blind Bartimaeus, the son of Timaeus, sat by the highway side begging."}, {"numero": 47, "texto": "And when he heard that it was Jesus of Nazareth, he began to cry out, and say, Jesus, thou son of David, have mercy on me."}, {"numero": 48, "texto": "And many charged him that he should hold his peace: but he cried the more a great deal, Thou son of David, have mercy on me."}, {"numero": 49, "texto": "And Jesus stood still, and commanded him to be called. And they call the blind man, saying unto him, Be of good comfort, rise; he calleth thee."}, {"numero": 50, "texto": "And he, casting away his garment, rose, and came to Jesus."}, {"numero": 51, "texto": "And Jesus answered and said unto him, What wilt thou that I should do unto thee? The blind man said unto him, Lord, that I might receive my sight."}, {"numero": 52, "texto": "And Jesus said unto him, Go thy way; thy faith hath made thee whole. And immediately he received his sight, and followed Jesus in the way."}]'::jsonb, 'King James Version'),
  ('Mc', 10, 'fr', '[{"numero": 1, "texto": "Jésus, étant parti de là, se rendit dans le territoire de la Judée au delà du Jourdain. La foule s''''assembla de nouveau près de lui, et selon sa coutume, il se mit encore à l''''enseigner."}, {"numero": 2, "texto": "Les pharisiens l''''abordèrent; et, pour l''''éprouver, ils lui demandèrent s''''il est permis à un homme de répudier sa femme."}, {"numero": 3, "texto": "Il leur répondit: Que vous a prescrit Moïse?"}, {"numero": 4, "texto": "Moïse, dirent-ils, a permis d''''écrire une lettre de divorce et de répudier."}, {"numero": 5, "texto": "Et Jésus leur dit: C''''est à cause de la dureté de votre coeur que Moïse vous a donné ce précepte."}, {"numero": 6, "texto": "Mais au commencement de la création, Dieu fit l''''homme et la femme;"}, {"numero": 7, "texto": "c''''est pourquoi l''''homme quittera son père et sa mère, et s''''attachera à sa femme,"}, {"numero": 8, "texto": "et les deux deviendront une seule chair. Ainsi ils ne sont plus deux, mais ils sont une seule chair."}, {"numero": 9, "texto": "Que l''''homme donc ne sépare pas ce que Dieu a joint."}, {"numero": 10, "texto": "Lorsqu''''ils furent dans la maison, les disciples l''''interrogèrent encore là-dessus."}, {"numero": 11, "texto": "Il leur dit: Celui qui répudie sa femme et qui en épouse une autre, commet un adultère à son égard;"}, {"numero": 12, "texto": "et si une femme quitte son mari et en épouse un autre, elle commet un adultère."}, {"numero": 13, "texto": "On lui amena des petits enfants, afin qu''''il les touchât. Mais les disciples reprirent ceux qui les amenaient."}, {"numero": 14, "texto": "Jésus, voyant cela, fut indigné, et leur dit: Laissez venir à moi les petits enfants, et ne les en empêchez pas; car le royaume de Dieu est pour ceux qui leur ressemblent."}, {"numero": 15, "texto": "Je vous le dis en vérité, quiconque ne recevra pas le royaume de Dieu comme un petit enfant n''''y entrera point."}, {"numero": 16, "texto": "Puis il les prit dans ses bras, et les bénit, en leur imposant les mains."}, {"numero": 17, "texto": "Comme Jésus se mettait en chemin, un homme accourut, et se jetant à genoux devant lui: Bon maître, lui demanda-t-il, que dois-je faire pour hériter la vie éternelle?"}, {"numero": 18, "texto": "Jésus lui dit: Pourquoi m''''appelles-tu bon? Il n''''y a de bon que Dieu seul."}, {"numero": 19, "texto": "Tu connais les commandements: Tu ne commettras point d''''adultère; tu ne tueras point; tu ne déroberas point; tu ne diras point de faux témoignage; tu ne feras tort à personne; honore ton père et ta mère."}, {"numero": 20, "texto": "Il lui répondit: Maître, j''''ai observé toutes ces choses dès ma jeunesse."}, {"numero": 21, "texto": "Jésus, l''''ayant regardé, l''''aima, et lui dit: Il te manque une chose; va, vends tout ce que tu as, donne-le aux pauvres, et tu auras un trésor dans le ciel. Puis viens, et suis-moi."}, {"numero": 22, "texto": "Mais, affligé de cette parole, cet homme s''''en alla tout triste; car il avait de grands biens."}, {"numero": 23, "texto": "Jésus, regardant autour de lui, dit à ses disciples: Qu''''il sera difficile à ceux qui ont des richesses d''''entrer dans le royaume de Dieu!"}, {"numero": 24, "texto": "Les disciples furent étonnés de ce que Jésus parlait ainsi. Et, reprenant, il leur dit: Mes enfants, qu''''il est difficile à ceux qui se confient dans les richesses d''''entrer dans le royaume de Dieu!"}, {"numero": 25, "texto": "Il est plus facile à un chameau de passer par le trou d''''une aiguille qu''''à un riche d''''entrer dans le royaume de Dieu."}, {"numero": 26, "texto": "Les disciples furent encore plus étonnés, et ils se dirent les uns aux autres; Et qui peut être sauvé?"}, {"numero": 27, "texto": "Jésus les regarda, et dit: Cela est impossible aux hommes, mais non à Dieu: car tout est possible à Dieu."}, {"numero": 28, "texto": "Pierre se mit à lui dire; Voici, nous avons tout quitté, et nous t''''avons suivi."}, {"numero": 29, "texto": "Jésus répondit: Je vous le dis en vérité, il n''''est personne qui, ayant quitté, à cause de moi et à cause de la bonne nouvelle, sa maison, ou ses frères, ou ses soeurs, ou sa mère, ou son père, ou ses enfants, ou ses terres,"}, {"numero": 30, "texto": "ne reçoive au centuple, présentement dans ce siècle-ci, des maisons, des frères, des soeurs, des mères, des enfants, et des terres, avec des persécutions, et, dans le siècle à venir, la vie éternelle."}, {"numero": 31, "texto": "Plusieurs des premiers seront les derniers, et plusieurs des derniers seront les premiers."}, {"numero": 32, "texto": "Ils étaient en chemin pour monter à Jérusalem, et Jésus allait devant eux. Les disciples étaient troublés, et le suivaient avec crainte. Et Jésus prit de nouveau les douze auprès de lui, et commença à leur dire ce qui devait lui arriver:"}, {"numero": 33, "texto": "Voici, nous montons à Jérusalem, et le Fils de l''''homme sera livré aux principaux sacrificateurs et aux scribes. Ils le condamneront à mort, et ils le livreront aux païens,"}, {"numero": 34, "texto": "qui se moqueront de lui, cracheront sur lui, le battront de verges, et le feront mourir; et, trois jours après, il ressuscitera."}, {"numero": 35, "texto": "Les fils de Zébédée, Jacques et Jean, s''''approchèrent de Jésus, et lui dirent: Maître, nous voudrions que tu fisses pour nous ce que nous te demanderons."}, {"numero": 36, "texto": "Il leur dit: Que voulez-vous que je fasse pour vous?"}, {"numero": 37, "texto": "Accorde-nous, lui dirent-ils, d''''être assis l''''un à ta droite et l''''autre à ta gauche, quand tu seras dans ta gloire."}, {"numero": 38, "texto": "Jésus leur répondit: Vous ne savez ce que vous demandez. Pouvez-vous boire la coupe que je dois boire, ou être baptisés du baptême dont je dois être baptisé?"}, {"numero": 39, "texto": "Nous le pouvons, dirent-ils. Et Jésus leur répondit: Il est vrai que vous boirez la coupe que je dois boire, et que vous serez baptisés du baptême dont je dois être baptisé;"}, {"numero": 40, "texto": "mais pour ce qui est d''''être assis à ma droite ou à ma gauche, cela ne dépend pas de moi, et ne sera donné qu''''à ceux à qui cela est réservé."}, {"numero": 41, "texto": "Les dix, ayant entendu cela, commencèrent à s''''indigner contre Jacques et Jean."}, {"numero": 42, "texto": "Jésus les appela, et leur dit: Vous savez que ceux qu''''on regarde comme les chefs des nations les tyrannisent, et que les grands les dominent."}, {"numero": 43, "texto": "Il n''''en est pas de même au milieu de vous. Mais quiconque veut être grand parmi vous, qu''''il soit votre serviteur;"}, {"numero": 44, "texto": "et quiconque veut être le premier parmi vous, qu''''il soit l''''esclave de tous."}, {"numero": 45, "texto": "Car le Fils de l''''homme est venu, non pour être servi, mais pour servir et donner sa vie comme la rançon de plusieurs."}, {"numero": 46, "texto": "Ils arrivèrent à Jéricho. Et, lorsque Jésus en sortit, avec ses disciples et une assez grande foule, le fils de Timée, Bartimée, mendiant aveugle, était assis au bord du chemin."}, {"numero": 47, "texto": "Il entendit que c''''était Jésus de Nazareth, et il se mit à crier; Fils de David, Jésus aie pitié de moi!"}, {"numero": 48, "texto": "Plusieurs le reprenaient, pour le faire taire; mais il criait beaucoup plus fort; Fils de David, aie pitié de moi!"}, {"numero": 49, "texto": "Jésus s''''arrêta, et dit: Appelez-le. Ils appelèrent l''''aveugle, en lui disant: Prends courage, lève-toi, il t''''appelle."}, {"numero": 50, "texto": "L''''aveugle jeta son manteau, et, se levant d''''un bond, vint vers Jésus."}, {"numero": 51, "texto": "Jésus, prenant la parole, lui dit: Que veux-tu que je te fasse? Rabbouni, lui répondit l''''aveugle, que je recouvre la vue."}, {"numero": 52, "texto": "Et Jésus lui dit: Va, ta foi t''''a sauvé. Aussitôt il recouvra la vue, et suivit Jésus dans le chemin."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 10, 'es', '[{"numero": 1, "texto": "Y PARTIÉNDOSE de allí, vino á los términos de Judea y tras el Jordán: y volvió el pueblo á juntarse á él; y de nuevo les enseñaba como solía."}, {"numero": 2, "texto": "Y llegándose los Fariseos, le preguntaron, para tentarle, si era lícito al marido repudiar á su mujer."}, {"numero": 3, "texto": "Mas él respondiendo, les dijo: ¿Qué os mandó Moisés?"}, {"numero": 4, "texto": "Y ellos dijeron: Moisés permitió escribir carta de divorcio, y repudiar."}, {"numero": 5, "texto": "Y respondiendo Jesús, les dijo: Por la dureza de vuestro corazón os escribió este mandamiento;"}, {"numero": 6, "texto": "Pero al principio de la creación, varón y hembra los hizo Dios."}, {"numero": 7, "texto": "Por esto dejará el hombre á su padre y á su madre, y se juntará á su mujer."}, {"numero": 8, "texto": "Y los que eran dos, serán hechos una carne: así que no son más dos, sino una carne."}, {"numero": 9, "texto": "Pues lo que Dios juntó, no lo aparte el hombre."}, {"numero": 10, "texto": "Y en casa volvieron los discípulos á preguntarle de lo mismo."}, {"numero": 11, "texto": "Y les dice: Cualquiera que repudiare á su mujer, y se casare con otra, comete adulterio contra ella:"}, {"numero": 12, "texto": "Y si la mujer repudiare á su marido y se casare con otro, comete adulterio."}, {"numero": 13, "texto": "Y le presentaban niños para que los tocase; y los discípulos reñían á los que los presentaban."}, {"numero": 14, "texto": "Y viéndolo Jesús, se enojó, y les dijo: Dejad los niños venir, y no se lo estorbéis; porque de los tales es el reino de Dios."}, {"numero": 15, "texto": "De cierto os digo, que el que no recibiere el reino de Dios como un niño, no entrará en él."}, {"numero": 16, "texto": "Y tomándolos en los brazos, poniendo las manos sobre ellos, los bendecía."}, {"numero": 17, "texto": "Y saliendo él para ir su camino, vino uno corriendo, é hincando la rodilla delante de él, le preguntó: Maestro bueno, ¿qué haré para poseer la vida eterna?"}, {"numero": 18, "texto": "Y Jesús le dijo: ¿Por qué me dices bueno? Ninguno hay bueno, sino sólo uno, Dios."}, {"numero": 19, "texto": "Los mandamientos sabes: No adulteres: No mates: No hurtes: No digas falso testimonio: No defraudes: Honra á tu padre y á tu madre."}, {"numero": 20, "texto": "El entonces respondiendo, le dijo: Maestro, todo esto he guardado desde mi mocedad."}, {"numero": 21, "texto": "Entonces Jesús mirándole, amóle, y díjole: Una cosa te falta: ve, vende todo lo que tienes, y da á los pobres, y tendrás tesoro en el cielo; y ven, sígueme, tomando tu cruz."}, {"numero": 22, "texto": "Mas él, entristecido por esta palabra, se fué triste, porque tenía muchas posesiones."}, {"numero": 23, "texto": "Entonces Jesús, mirando alrededor, dice á sus discípulos: ¡Cuán difícilmente entrarán en el reino de Dios los que tienen riquezas!"}, {"numero": 24, "texto": "Y los discípulos se espantaron de sus palabras; mas Jesús respondiendo, les volvió á decir: ¡Hijos, cuán difícil es entrar en el reino de Dios, los que confían en las riquezas!"}, {"numero": 25, "texto": "Más fácil es pasar un camello por el ojo de una aguja, que el rico entrar en el reino de Dios."}, {"numero": 26, "texto": "Y ellos se espantaban más, diciendo dentro de sí: ¿Y quién podrá salvarse?"}, {"numero": 27, "texto": "Entonces Jesús mirándolos, dice: Para los hombres es imposible; mas para Dios, no; porque todas las cosas son posibles para Dios."}, {"numero": 28, "texto": "Entonces Pedro comenzó á decirle: He aquí, nosotros hemos dejado todas las cosas, y te hemos seguido."}, {"numero": 29, "texto": "Y respondiendo Jesús, dijo: De cierto os digo, que no hay ninguno que haya dejado casa, ó hermanos, ó hermanas, ó padre, ó madre, ó mujer, ó hijos, ó heredades, por causa de mí y del evangelio,"}, {"numero": 30, "texto": "Que no reciba cien tantos ahora en este tiempo, casas, y hermanos, y hermanas, y madres, é hijos, y heredades, con persecuciones; y en el siglo venidero la vida eterna."}, {"numero": 31, "texto": "Empero muchos primeros serán postreros, y postreros primeros."}, {"numero": 32, "texto": "Y estaban en el camino subiendo á Jerusalem; y Jesús iba delante de ellos, y se espantaban, y le seguían con miedo: entonces volviendo á tomar á los doce aparte, les comenzó á decir las cosas que le habían de acontecer:"}, {"numero": 33, "texto": "He aquí subimos á Jerusalem, y el Hijo del hombre será entregado á los príncipes de los sacerdotes, y á los escribas, y le condenarán á muerte, y le entregarán á los Gentiles:"}, {"numero": 34, "texto": "Y le escarnecerán, y le azotarán, y escupirán en él, y le matarán; mas al tercer día resucitará."}, {"numero": 35, "texto": "Entonces Jacobo y Juan, hijos de Zebedeo, se llegaron á él, diciendo: Maestro, querríamos que nos hagas lo que pidiéremos."}, {"numero": 36, "texto": "Y él les dijo: ¿Qué queréis que os haga?"}, {"numero": 37, "texto": "Y ellos le dijeron: Danos que en tu gloria nos sentemos el uno á tu diestra, y el otro á tu siniestra."}, {"numero": 38, "texto": "Entonces Jesús les dijo: No sabéis lo que pedís. ¿Podéis beber del vaso que yo bebo, ó ser bautizados del bautismo de que yo soy bautizado?"}, {"numero": 39, "texto": "Y ellos dijeron: Podemos. Y Jesús les dijo: A la verdad, del vaso que yo bebo, beberéis; y del bautismo de que yo soy bautizado, seréis bautizados."}, {"numero": 40, "texto": "Mas que os sentéis á mi diestra y á mi siniestra, no es mío darlo, sino á quienes está aparejado."}, {"numero": 41, "texto": "Y como lo oyeron los diez, comenzaron á enojarse de Jacobo y de Juan."}, {"numero": 42, "texto": "Mas Jesús, llamándolos, les dice: Sabéis que los que se ven ser príncipes entre las gentes, se enseñorean de ellas, y los que entre ellas son grandes, tienen sobre ellas potestad."}, {"numero": 43, "texto": "Mas no será así entre vosotros: antes cualquiera que quisiere hacerse grande entre vosotros, será vuestro servidor;"}, {"numero": 44, "texto": "Y cualquiera de vosotros que quisiere hacerse el primero, será siervo de todos."}, {"numero": 45, "texto": "Porque el Hijo del hombre tampoco vino para ser servido, mas para servir, y dar su vida en rescate por muchos."}, {"numero": 46, "texto": "Entonces vienen á Jericó: y saliendo él de Jericó y sus discípulos y una gran compañía, Bartimeo el ciego, hijo de Timeo, estaba sentado junto al camino mendigando."}, {"numero": 47, "texto": "Y oyendo que era Jesús el Nazareno, comenzó á dar voces y decir: Jesús, Hijo de David, ten misericordia de mí."}, {"numero": 48, "texto": "Y muchos le reñían, que callase: mas él daba mayores voces: Hijo de David, ten misericordia de mí."}, {"numero": 49, "texto": "Entonces Jesús parándose, mandó llamarle: y llaman al ciego, diciéndole: Ten confianza: levántate, te llama."}, {"numero": 50, "texto": "El entonces, echando su capa, se levantó, y vino á Jesús."}, {"numero": 51, "texto": "Y respondiendo Jesús, le dice: ¿Qué quieres que te haga? Y el ciego le dice: Maestro, que cobre la vista."}, {"numero": 52, "texto": "Y Jesús le dijo: Ve, tu fe te ha salvado. Y luego cobró la vista, y seguía á Jesús en el camino."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 11, 'pt', '[{"numero": 1, "texto": "E quando se aproximaram de Jerusalém, de Betfagé, e de Betânia, junto ao monte das Oliveiras, [Jesus] enviou dois de seus discípulos,"}, {"numero": 2, "texto": "dizendo-lhes: Ide ao vilarejo que está adiante de vós; e assim que nela entrardes, achareis um jumentinho amarrado, sobre o qual ninguém se sentou; soltai-o, e trazei-o."}, {"numero": 3, "texto": "E se alguém vos disser: Por que fazeis isso?, dizei: O Senhor precisa dele, e logo o devolverá para cá."}, {"numero": 4, "texto": "Eles foram, e acharam o jumentinho amarrado à porta, do lado de fora em uma esquina, e o soltaram."}, {"numero": 5, "texto": "E alguns dos que ali estavam lhes perguntaram: Que fazeis, soltando o jumentinho?"}, {"numero": 6, "texto": "Eles lhes disseram como Jesus [lhes] havia mandado, e os deixaram ir."}, {"numero": 7, "texto": "Então trouxeram o jumentinho a Jesus. Lançaram sobre ele suas roupas, e [Jesus] sentou-se sobre ele."}, {"numero": 8, "texto": "Muitos estendiam suas roupas pelo caminho, e outros cortavam ramos das árvores, e os espalhavam pelo caminho.."}, {"numero": 9, "texto": "E os que iam adiante, e os que seguiam, clamavam: Hosana, bendito o que vem no Nome do Senhor!"}, {"numero": 10, "texto": "Bendito o Reino que vem no Nome do Senhor, [o Reino] do nosso pai Davi! Hosana nas alturas!"}, {"numero": 11, "texto": "Jesus entrou em Jerusalém, e no Templo. E depois que ter visto tudo em redor, e sendo já tarde, ele saiu para Betânia com os doze."}, {"numero": 12, "texto": "E no dia seguinte, quando saíram de Betânia, ele teve fome."}, {"numero": 13, "texto": "E vendo de longe uma figueira que tinha folhas, [veio ver] se acharia alguma coisa nela; mas ao chegar perto dela, nada achou, a não ser folhas, pois não era o tempo de figos."}, {"numero": 14, "texto": "Então Jesus lhe disse: Nunca mais ninguém coma fruto de ti! E seus discípulos ouviram isso."}, {"numero": 15, "texto": "Depois vieram a Jerusalém. E entrando Jesus no Templo, começou a expulsar os que vendiam e compravam no Templo; e revirou as mesas dos cambiadores, e as cadeiras dos que vendiam pombas."}, {"numero": 16, "texto": "E não consentia que ninguém levasse vaso algum pelo Templo."}, {"numero": 17, "texto": "E ensinava, dizendo-lhes: Não está escrito: Minha casa será chamada casa de oração de todas as nações? Mas vós fizestes dela esconderijo de ladrões!"}, {"numero": 18, "texto": "Os escribas e os chefes dos sacerdotes ouviram isso, e buscavam uma maneira de o matar; pois o temiam, porque toda a multidão estava admirada do ensino dele."}, {"numero": 19, "texto": "E como já era tarde, [Jesus] saiu fora da cidade."}, {"numero": 20, "texto": "E passando pela manhã, viram que a figueira estava seca desde as raízes."}, {"numero": 21, "texto": "Pedro se lembrou disso, e disse-lhe: Mestre, eis que a figueira que amaldiçoaste, se secou."}, {"numero": 22, "texto": "E respondendo Jesus, disse-lhes: Tende fé em Deus."}, {"numero": 23, "texto": "Porque em verdade vos digo que qualquer um que disser a este monte: Levanta-te, e lança-te no mar; e não duvidar em seu coração, mas crer que se fará o que diz, tudo o que disser lhe será feito."}, {"numero": 24, "texto": "Portanto eu vos digo que tudo o que pedirdes orando, crede que recebereis, e vós [o] tereis."}, {"numero": 25, "texto": "E quando estiverdes orando, perdoai, se tendes algo contra alguém, para que o vosso Pai, que [está] nos céus, vos perdoe vossas ofensas."}, {"numero": 26, "texto": "Mas se vós não perdoardes, também o vosso Pai, que [está] nos céus, não vos perdoará vossas ofensas."}, {"numero": 27, "texto": "Depois voltaram a Jerusalém; e, enquanto ele andava pelo Templo, vieram a ele os chefes dos sacerdotes, os escribas, e os anciãos."}, {"numero": 28, "texto": "E disseram-lhe: Com que autoridade fazes estas coisas? E quem te deu esta autoridade, para fazerdes estas coisas?"}, {"numero": 29, "texto": "Jesus lhes respondeu: Também eu vos farei uma pergunta, e respondei-me; então vos direi com que autoridade faço estas coisas."}, {"numero": 30, "texto": "O batismo de João era do céu ou dos homens? Respondei-me."}, {"numero": 31, "texto": "E eles argumentavam entre si, dizendo: Se dissermos do céu, ele dirá: Por que, pois, não crestes nele?"}, {"numero": 32, "texto": "Porém, se dissermos dos homens, tememos ao povo, porque todos consideravam que João era verdadeiramente profeta."}, {"numero": 33, "texto": "Então responderam a Jesus: Não sabemos. E Jesus lhes replicou: Também eu não vos direi com que autoridade faço estas coisas."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 11, 'en', '[{"numero": 1, "texto": "And when they came nigh to Jerusalem, unto Bethphage and Bethany, at the mount of Olives, he sendeth forth two of his disciples,"}, {"numero": 2, "texto": "And saith unto them, Go your way into the village over against you: and as soon as ye be entered into it, ye shall find a colt tied, whereon never man sat; loose him, and bring him."}, {"numero": 3, "texto": "And if any man say unto you, Why do ye this? say ye that the Lord hath need of him; and straightway he will send him hither."}, {"numero": 4, "texto": "And they went their way, and found the colt tied by the door without in a place where two ways met; and they loose him."}, {"numero": 5, "texto": "And certain of them that stood there said unto them, What do ye, loosing the colt?"}, {"numero": 6, "texto": "And they said unto them even as Jesus had commanded: and they let them go."}, {"numero": 7, "texto": "And they brought the colt to Jesus, and cast their garments on him; and he sat upon him."}, {"numero": 8, "texto": "And many spread their garments in the way: and others cut down branches off the trees, and strawed them in the way."}, {"numero": 9, "texto": "And they that went before, and they that followed, cried, saying, Hosanna; Blessed is he that cometh in the name of the Lord:"}, {"numero": 10, "texto": "Blessed be the kingdom of our father David, that cometh in the name of the Lord: Hosanna in the highest."}, {"numero": 11, "texto": "And Jesus entered into Jerusalem, and into the temple: and when he had looked round about upon all things, and now the eventide was come, he went out unto Bethany with the twelve."}, {"numero": 12, "texto": "And on the morrow, when they were come from Bethany, he was hungry:"}, {"numero": 13, "texto": "And seeing a fig tree afar off having leaves, he came, if haply he might find any thing thereon: and when he came to it, he found nothing but leaves; for the time of figs was not yet."}, {"numero": 14, "texto": "And Jesus answered and said unto it, No man eat fruit of thee hereafter for ever. And his disciples heard it."}, {"numero": 15, "texto": "And they come to Jerusalem: and Jesus went into the temple, and began to cast out them that sold and bought in the temple, and overthrew the tables of the moneychangers, and the seats of them that sold doves;"}, {"numero": 16, "texto": "And would not suffer that any man should carry any vessel through the temple."}, {"numero": 17, "texto": "And he taught, saying unto them, Is it not written, My house shall be called of all nations the house of prayer? but ye have made it a den of thieves."}, {"numero": 18, "texto": "And the scribes and chief priests heard it, and sought how they might destroy him: for they feared him, because all the people was astonished at his doctrine."}, {"numero": 19, "texto": "And when even was come, he went out of the city."}, {"numero": 20, "texto": "And in the morning, as they passed by, they saw the fig tree dried up from the roots."}, {"numero": 21, "texto": "And Peter calling to remembrance saith unto him, Master, behold, the fig tree which thou cursedst is withered away."}, {"numero": 22, "texto": "And Jesus answering saith unto them, Have faith in God."}, {"numero": 23, "texto": "For verily I say unto you, That whosoever shall say unto this mountain, Be thou removed, and be thou cast into the sea; and shall not doubt in his heart, but shall believe that those things which he saith shall come to pass; he shall have whatsoever he saith."}, {"numero": 24, "texto": "Therefore I say unto you, What things soever ye desire, when ye pray, believe that ye receive them, and ye shall have them."}, {"numero": 25, "texto": "And when ye stand praying, forgive, if ye have ought against any: that your Father also which is in heaven may forgive you your trespasses."}, {"numero": 26, "texto": "But if ye do not forgive, neither will your Father which is in heaven forgive your trespasses."}, {"numero": 27, "texto": "And they come again to Jerusalem: and as he was walking in the temple, there come to him the chief priests, and the scribes, and the elders,"}, {"numero": 28, "texto": "And say unto him, By what authority doest thou these things? and who gave thee this authority to do these things?"}, {"numero": 29, "texto": "And Jesus answered and said unto them, I will also ask of you one question, and answer me, and I will tell you by what authority I do these things."}, {"numero": 30, "texto": "The baptism of John, was it from heaven, or of men? answer me."}, {"numero": 31, "texto": "And they reasoned with themselves, saying, If we shall say, From heaven; he will say, Why then did ye not believe him?"}, {"numero": 32, "texto": "But if we shall say, Of men; they feared the people: for all men counted John, that he was a prophet indeed."}, {"numero": 33, "texto": "And they answered and said unto Jesus, We cannot tell. And Jesus answering saith unto them, Neither do I tell you by what authority I do these things."}]'::jsonb, 'King James Version'),
  ('Mc', 11, 'fr', '[{"numero": 1, "texto": "Lorsqu''''ils approchèrent de Jérusalem, et qu''''ils furent près de Bethphagé et de Béthanie, vers la montagne des oliviers, Jésus envoya deux de ses disciples,"}, {"numero": 2, "texto": "en leur disant: Allez au village qui est devant vous; dès que vous y serez entrés, vous trouverez un ânon attaché, sur lequel aucun homme ne s''''est encore assis; détachez-le, et amenez-le."}, {"numero": 3, "texto": "Si quelqu''''un vous dit: Pourquoi faites-vous cela? répondez: Le Seigneur en a besoin. Et à l''''instant il le laissera venir ici."}, {"numero": 4, "texto": "les disciples, étant allés, trouvèrent l''''ânon attaché dehors près d''''une porte, au contour du chemin, et ils le détachèrent."}, {"numero": 5, "texto": "Quelques-uns de ceux qui étaient là leur dirent: Que faites-vous? pourquoi détachez-vous cet ânon?"}, {"numero": 6, "texto": "Ils répondirent comme Jésus l''''avait dit. Et on les laissa aller."}, {"numero": 7, "texto": "Ils amenèrent à Jésus l''''ânon, sur lequel ils jetèrent leurs vêtements, et Jésus s''''assit dessus."}, {"numero": 8, "texto": "Beaucoup de gens étendirent leurs vêtements sur le chemin, et d''''autres des branches qu''''ils coupèrent dans les champs."}, {"numero": 9, "texto": "Ceux qui précédaient et ceux qui suivaient Jésus criaient: Hosanna! Béni soit celui qui vient au nom du Seigneur!"}, {"numero": 10, "texto": "Béni soit le règne qui vient, le règne de David, notre père! Hosanna dans les lieux très hauts!"}, {"numero": 11, "texto": "Jésus entra à Jérusalem, dans le temple. Quand il eut tout considéré, comme il était déjà tard, il s''''en alla à Béthanie avec les douze."}, {"numero": 12, "texto": "Le lendemain, après qu''''ils furent sortis de Béthanie, Jésus eut faim."}, {"numero": 13, "texto": "Apercevant de loin un figuier qui avait des feuilles, il alla voir s''''il y trouverait quelque chose; et, s''''en étant approché, il ne trouva que des feuilles, car ce n''''était pas la saison des figues."}, {"numero": 14, "texto": "Prenant alors la parole, il lui dit: Que jamais personne ne mange de ton fruit! Et ses disciples l''''entendirent."}, {"numero": 15, "texto": "Ils arrivèrent à Jérusalem, et Jésus entra dans le temple. Il se mit à chasser ceux qui vendaient et qui achetaient dans le temple; il renversa les tables des changeurs, et les sièges des vendeurs de pigeons;"}, {"numero": 16, "texto": "et il ne laissait personne transporter aucun objet à travers le temple."}, {"numero": 17, "texto": "Et il enseignait et disait: N''''est-il pas écrit: Ma maison sera appelée une maison de prière pour toutes les nations? Mais vous, vous en avez fait une caverne de voleurs."}, {"numero": 18, "texto": "Les principaux sacrificateurs et les scribes, l''''ayant entendu, cherchèrent les moyens de le faire périr; car ils le craignaient, parce que toute la foule était frappée de sa doctrine."}, {"numero": 19, "texto": "Quand le soir fut venu, Jésus sortit de la ville."}, {"numero": 20, "texto": "Le matin, en passant, les disciples virent le figuier séché jusqu''''aux racines."}, {"numero": 21, "texto": "Pierre, se rappelant ce qui s''''était passé, dit à Jésus: Rabbi, regarde, le figuier que tu as maudit a séché."}, {"numero": 22, "texto": "Jésus prit la parole, et leur dit: Ayez foi en Dieu."}, {"numero": 23, "texto": "Je vous le dis en vérité, si quelqu''''un dit à cette montagne: Ote-toi de là et jette-toi dans la mer, et s''''il ne doute point en son coeur, mais croit que ce qu''''il dit arrive, il le verra s''''accomplir."}, {"numero": 24, "texto": "C''''est pourquoi je vous dis: Tout ce que vous demanderez en priant, croyez que vous l''''avez reçu, et vous le verrez s''''accomplir."}, {"numero": 25, "texto": "Et, lorsque vous êtes debout faisant votre prière, si vous avez quelque chose contre quelqu''''un, pardonnez, afin que votre Père qui est dans les cieux vous pardonne aussi vos offenses."}, {"numero": 26, "texto": "Mais si vous ne pardonnez pas, votre Père qui est dans les cieux ne vous pardonnera pas non plus vos offenses."}, {"numero": 27, "texto": "Ils se rendirent de nouveau à Jérusalem, et, pendant que Jésus se promenait dans le temple, les principaux sacrificateurs, les scribes et les anciens, vinrent à lui,"}, {"numero": 28, "texto": "et lui dirent: Par quelle autorité fais-tu ces choses, et qui t''''a donné l''''autorité de les faire?"}, {"numero": 29, "texto": "Jésus leur répondit: Je vous adresserai aussi une question; répondez-moi, et je vous dirai par quelle autorité je fais ces choses."}, {"numero": 30, "texto": "Le baptême de Jean venait-il du ciel, ou des hommes? Répondez-moi."}, {"numero": 31, "texto": "Mais ils raisonnèrent ainsi entre eux: Si nous répondons: Du ciel, il dira: Pourquoi donc n''''avez-vous pas cru en lui?"}, {"numero": 32, "texto": "Et si nous répondons: Des hommes... Ils craignaient le peuple, car tous tenaient réellement Jean pour un prophète."}, {"numero": 33, "texto": "Alors ils répondirent à Jésus: Nous ne savons. Et Jésus leur dit: Moi non plus, je ne vous dirai pas par quelle autorité je fais ces choses."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 11, 'es', '[{"numero": 1, "texto": "Y COMO fueron cerca de Jerusalem, de Bethphagé, y de Bethania, al monte de las Olivas, envía dos de sus discípulos,"}, {"numero": 2, "texto": "Y les dice: Id al lugar que está delante de vosotros, y luego entrados en él, hallaréis un pollino atado, sobre el cual ningún hombre ha subido; desatadlo y traedlo."}, {"numero": 3, "texto": "Y si alguien os dijere: ¿Por qué hacéis eso? decid que el Señor lo ha menester: y luego lo enviará acá."}, {"numero": 4, "texto": "Y fueron, y hallaron el pollino atado á la puerta fuera, entre dos caminos; y le desataron."}, {"numero": 5, "texto": "Y unos de los que estaban allí, les dijeron: ¿Qué hacéis desatando el pollino?"}, {"numero": 6, "texto": "Ellos entonces les dijeron como Jesús había mandado: y los dejaron."}, {"numero": 7, "texto": "Y trajeron el pollino á Jesús, y echaron sobre él sus vestidos, y se sentó sobre él."}, {"numero": 8, "texto": "Y muchos tendían sus vestidos por el camino, y otros cortaban hojas de los árboles, y las tendían por el camino."}, {"numero": 9, "texto": "Y los que iban delante, y los que iban detrás, daban voces diciendo: ¡Hosanna! Bendito el que viene en el nombre del Señor."}, {"numero": 10, "texto": "Bendito el reino de nuestro padre David que viene: ¡Hosanna en las alturas!"}, {"numero": 11, "texto": "Y entró Jesús en Jerusalem, y en el templo: y habiendo mirado alrededor todas las cosas, y siendo ya tarde, salióse á Bethania con los doce."}, {"numero": 12, "texto": "Y el día siguiente, como salieron de Bethania, tuvo hambre."}, {"numero": 13, "texto": "Y viendo de lejos una higuera que tenía hojas, se acercó, si quizá hallaría en ella algo: y como vino á ella, nada halló sino hojas; porque no era tiempo de higos."}, {"numero": 14, "texto": "Entonces Jesús respondiendo, dijo á la higuera: Nunca más coma nadie fruto de ti para siempre. Y lo oyeron sus discípulos."}, {"numero": 15, "texto": "Vienen, pues, á Jerusalem; y entrando Jesús en el templo, comenzó á echar fuera á los que vendían y compraban en el templo; y trastornó las mesas de los cambistas, y las sillas de los que vendían palomas;"}, {"numero": 16, "texto": "Y no consentía que alguien llevase vaso por el templo."}, {"numero": 17, "texto": "Y les enseñaba diciendo: ¿No está escrito que mi casa, casa de oración será llamada por todas las gentes? Mas vosotros la habéis hecho cueva de ladrones."}, {"numero": 18, "texto": "Y lo oyeron los escribas y los príncipes de los sacerdotes, y procuraban cómo le matarían; porque le tenían miedo, por cuanto todo el pueblo estaba maravillado de su doctrina."}, {"numero": 19, "texto": "Mas como fué tarde, Jesús salió de la ciudad."}, {"numero": 20, "texto": "Y pasando por la mañana, vieron que la higuera se había secado desde las raíces."}, {"numero": 21, "texto": "Entonces Pedro acordándose, le dice: Maestro, he aquí la higuera que maldijiste, se ha secado."}, {"numero": 22, "texto": "Y respondiendo Jesús, les dice: Tened fe en Dios."}, {"numero": 23, "texto": "Porque de cierto os digo que cualquiera que dijere á este monte: Quítate, y échate en la mar, y no dudare en su corazón, mas creyere que será hecho lo que dice, lo que dijere le será hecho."}, {"numero": 24, "texto": "Por tanto, os digo que todo lo que orando pidiereis, creed que lo recibiréis, y os vendrá."}, {"numero": 25, "texto": "Y cuando estuviereis orando, perdonad, si tenéis algo contra alguno, para que vuestro Padre que está en los cielos os perdone también á vosotros vuestras ofensas."}, {"numero": 26, "texto": "Porque si vosotros no perdonareis, tampoco vuestro Padre que está en los cielos os perdonará vuestras ofensas."}, {"numero": 27, "texto": "Y volvieron á Jerusalem; y andando él por el templo, vienen á él los príncipes de los sacerdotes, y los escribas, y los ancianos;"}, {"numero": 28, "texto": "Y le dicen: ¿Con qué facultad haces estas cosas? ¿y quién te ha dado esta facultad para hacer estas cosas?"}, {"numero": 29, "texto": "Y Jesús respondiendo entonces, les dice: Os preguntaré también yo una palabra; y respondedme, y os diré con qué facultad hago estas cosas:"}, {"numero": 30, "texto": "El bautismo de Juan, ¿era del cielo, ó de los hombres? Respondedme."}, {"numero": 31, "texto": "Entonces ellos pensaron dentro de sí, diciendo: Si dijéremos, del cielo, dirá: ¿Por qué, pues, no le creísteis?"}, {"numero": 32, "texto": "Y si dijéremos, de los hombres, tememos al pueblo: porque todos juzgaban de Juan, que verdaderamente era profeta."}, {"numero": 33, "texto": "Y respondiendo, dicen á Jesús: No sabemos. Entonces respondiendo Jesús, les dice: Tampoco yo os diré con qué facultad hago estas cosas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 12, 'pt', '[{"numero": 1, "texto": "Então [Jesus] começou a lhes dizer por parábolas: Um homem plantou uma vinha, cercou-a, fundou [nela] uma prensa de uvas, edificou uma torre, e a arrendou a uns lavradores; e partiu-se daquela terra."}, {"numero": 2, "texto": "E, quando chegou o tempo, mandou um servo aos lavradores, para que recebesse dos lavradores do fruto da vinha."}, {"numero": 3, "texto": "Mas eles, tomando-o à força, feriram-no, e mandaram-no vazio."}, {"numero": 4, "texto": "E voltou a lhes mandar outro servo; e eles, apedrejando-o, feriram-no na cabeça e voltaram a mandá-lo maltratado."}, {"numero": 5, "texto": "E voltou a mandar outro, ao qual mataram, e [mandou] muitos outros, e a uns feriram, e a outros mataram."}, {"numero": 6, "texto": "Tendo ele, pois, ainda um, o seu filho amado, mandou-lhes também por último a este, dizendo: Pelo menos respeitarão o meu filho."}, {"numero": 7, "texto": "Mas aqueles lavradores disseram entre si: Este é o herdeiro; vinde, e o matemos; então a herança será nossa."}, {"numero": 8, "texto": "E pegando dele, mataram[-no] , e lançaram[-no] fora da vinha."}, {"numero": 9, "texto": "Que, pois, o senhor da vinha fará? Ele virá, destruirá aos lavradores, e dará a vinha a outros."}, {"numero": 10, "texto": "Acaso ainda não lestes esta escritura: “A pedra que os edificadores rejeitaram, esta foi feita por cabeça de esquina."}, {"numero": 11, "texto": "Pelo Senhor foi feito isto, e é maravilhoso em nossos olhos”?"}, {"numero": 12, "texto": "E buscavam prendê-lo, mas temiam a multidão; porque entendiam que era contra eles que dizia aquela parábola; então o deixaram e se retiraram."}, {"numero": 13, "texto": "E mandaram-lhe alguns dos fariseus e dos herodianos, para que o apanhassem em [alguma] palavra."}, {"numero": 14, "texto": "Eles se aproximaram e lhe disseram: Mestre, sabemos que és homem de verdade, e não te interessa [agradar] a ninguém, porque não te importas com a aparência humana, mas com verdade ensinas o caminho de Deus. É lícito pagar tributo a César, ou não? Devemos pagar, ou não devemos?"}, {"numero": 15, "texto": "E ele, entendendo a hipocrisia deles, disse-lhes: Por que estais me tentando? Trazei-me uma moeda, para que eu a veja."}, {"numero": 16, "texto": "E trouxeram. E perguntou-lhes: De quem é esta imagem, e a inscrição? E eles lhe disseram: De César."}, {"numero": 17, "texto": "Então Jesus, lhes respondeu: Dai, pois, a César o que é de César, e a Deus o que é de Deus. E admiram-se dele."}, {"numero": 18, "texto": "E vieram a ele os saduceus, que dizem não haver ressurreição, e perguntaram-lhe:"}, {"numero": 19, "texto": "Mestre, Moisés nos escreveu que, se o irmão de alguém morresse, e deixasse mulher, mas não filhos, que seu irmão se casasse com a viúva , e gerasse descendência ao seu irmão."}, {"numero": 20, "texto": "Houve, pois, sete irmãos, e o primeiro casou-se com a mulher, e morrendo, não deixou descendente."}, {"numero": 21, "texto": "Casou-se com ela também o segundo, e morreu; e nem este deixou descendente; e o terceiro da mesma maneira."}, {"numero": 22, "texto": "Os sete casaram-se com ela, mas não deixaram descendente. Finalmente, depois de todos, morreu também a mulher."}, {"numero": 23, "texto": "Na ressurreição, pois, quando ressuscitarem, ela será a mulher de qual deles? Porque os sete a tiveram por mulher."}, {"numero": 24, "texto": "E Jesus lhes respondeu: Acaso não é por isso que errais, por não conhecerdes as Escrituras, nem o poder de Deus?"}, {"numero": 25, "texto": "Pois, quando ressuscitarem dos mortos, nem se casarão, nem se darão em casamento; mas serão como os anjos que estão nos céus."}, {"numero": 26, "texto": "E quanto aos mortos que ressuscitarão, não lestes no livro de Moisés, como Deus lhe falou com a sarça, dizendo: Eu sou o Deus de Abraão, o Deus de Isaque, e o Deus de Jacó?"}, {"numero": 27, "texto": "Deus não é [Deus] de mortos, mas de vivos. Portanto errais muito."}, {"numero": 28, "texto": "Então aproximou-se dele um dos escribas, que os havia ouvido discutir. Como ele sabia que [Jesus] havia lhes respondido bem, perguntou-lhe: Qual é o primeiro mandamento de todos?"}, {"numero": 29, "texto": "E Jesus lhe respondeu: O primeiro de todos os mandamentos é: “Ouve Israel, o Senhor nosso Deus é o único Senhor;"}, {"numero": 30, "texto": "amarás, pois, ao Senhor teu Deus com todo o teu coração, com toda a tua alma, com todo o teu entendimento, e com todas as tuas forças.” Este é o primeiro mandamento."}, {"numero": 31, "texto": "E o segundo é semelhante: “Amarás ao teu próximo como a ti mesmo”. Não há outro mandamento maior que estes."}, {"numero": 32, "texto": "E o escriba lhe disse: Muito bem, Mestre, com verdade disseste que há um só Deus, e não há outro além dele."}, {"numero": 33, "texto": "E que amá-lo com todo o coração, com todo o entendimento, com toda a alma, e com todas as forças; e amar ao próximo como a si mesmo, é mais de que todos os holocaustos e sacrifícios."}, {"numero": 34, "texto": "Jesus viu que ele havia respondido sabiamente, e disse-lhe: Não estás longe do Reino de Deus. E ninguém mais ousou lhe perguntar."}, {"numero": 35, "texto": "E Jesus respondia e dizia, enquanto ensinava no templo: Como os escribas dizem que o Cristo é filho de Davi?"}, {"numero": 36, "texto": "Porque o mesmo Davi disse pelo Espírito Santo: Disse o Senhor ao meu Senhor, senta-te à minha direita, até que eu ponha os teus inimigos debaixo dos teus pés."}, {"numero": 37, "texto": "Ora, [se] o próprio Davi o chama de Senhor, como, pois, é so eu filho?E a grande multidão o ouvia de boa vontade."}, {"numero": 38, "texto": "E dizia-lhes em seu ensino: Cuidado com os escribas, que gostam de andar com roupas compridas, das saudações nas praças,"}, {"numero": 39, "texto": "das primeiras cadeiras nas sinagogas, e dos primeiros assentos nas ceias."}, {"numero": 40, "texto": "que devoram as casas das viúvas, com pretexto de longas orações. Esses receberão mais grave condenação."}, {"numero": 41, "texto": "Quando Jesus estava sentado de frente à arca do tesouro, observava como a multidão lançava dinheiro na arca do tesouro; e muitos ricos lançavam muito."}, {"numero": 42, "texto": "E uma pobre viúva veio, e lançou duas pequenas moedas, de pouco valor."}, {"numero": 43, "texto": "Então [Jesus] chamou a si os seus discípulos, e disse-lhes: Em verdade vos digo que esta pobre viúva lançou mais que todos os que lançaram na arca do tesouro;"}, {"numero": 44, "texto": "Porque todos lançaram daquilo que lhes sobra; mas esta, da sua pobreza lançou tudo o que tinha, todo o seu sustento."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 12, 'en', '[{"numero": 1, "texto": "And he began to speak unto them by parables. A certain man planted a vineyard, and set an hedge about it, and digged a place for the winefat, and built a tower, and let it out to husbandmen, and went into a far country."}, {"numero": 2, "texto": "And at the season he sent to the husbandmen a servant, that he might receive from the husbandmen of the fruit of the vineyard."}, {"numero": 3, "texto": "And they caught him, and beat him, and sent him away empty."}, {"numero": 4, "texto": "And again he sent unto them another servant; and at him they cast stones, and wounded him in the head, and sent him away shamefully handled."}, {"numero": 5, "texto": "And again he sent another; and him they killed, and many others; beating some, and killing some."}, {"numero": 6, "texto": "Having yet therefore one son, his wellbeloved, he sent him also last unto them, saying, They will reverence my son."}, {"numero": 7, "texto": "But those husbandmen said among themselves, This is the heir; come, let us kill him, and the inheritance shall be ours.''"}, {"numero": 8, "texto": "And they took him, and killed him, and cast him out of the vineyard."}, {"numero": 9, "texto": "What shall therefore the lord of the vineyard do? he will come and destroy the husbandmen, and will give the vineyard unto others."}, {"numero": 10, "texto": "And have ye not read this scripture; The stone which the builders rejected is become the head of the corner:"}, {"numero": 11, "texto": "This was the Lord''s doing, and it is marvellous in our eyes?"}, {"numero": 12, "texto": "And they sought to lay hold on him, but feared the people: for they knew that he had spoken the parable against them: and they left him, and went their way."}, {"numero": 13, "texto": "And they send unto him certain of the Pharisees and of the Herodians, to catch him in his words."}, {"numero": 14, "texto": "And when they were come, they say unto him, Master, we know that thou art true, and carest for no man: for thou regardest not the person of men, but teachest the way of God in truth: Is it lawful to give tribute to Caesar, or not?"}, {"numero": 15, "texto": "Shall we give, or shall we not give? But he, knowing their hypocrisy, said unto them, Why tempt ye me? bring me a penny, that I may see it."}, {"numero": 16, "texto": "And they brought it. And he saith unto them, Whose is this image and superscription? And they said unto him, Caesar''s."}, {"numero": 17, "texto": "And Jesus answering said unto them, Render to Caesar the things that are Caesar''s, and to God the things that are God''s. And they marvelled at him."}, {"numero": 18, "texto": "Then come unto him the Sadducees, which say there is no resurrection; and they asked him, saying,"}, {"numero": 19, "texto": "Master, Moses wrote unto us, If a man''s brother die, and leave his wife behind him, and leave no children, that his brother should take his wife, and raise up seed unto his brother."}, {"numero": 20, "texto": "Now there were seven brethren: and the first took a wife, and dying left no seed."}, {"numero": 21, "texto": "And the second took her, and died, neither left he any seed: and the third likewise."}, {"numero": 22, "texto": "And the seven had her, and left no seed: last of all the woman died also."}, {"numero": 23, "texto": "In the resurrection therefore, when they shall rise, whose wife shall she be of them? for the seven had her to wife."}, {"numero": 24, "texto": "And Jesus answering said unto them, Do ye not therefore err, because ye know not the scriptures, neither the power of God?"}, {"numero": 25, "texto": "For when they shall rise from the dead, they neither marry, nor are given in marriage; but are as the angels which are in heaven."}, {"numero": 26, "texto": "And as touching the dead, that they rise: have ye not read in the book of Moses, how in the bush God spake unto him, saying, I am the God of Abraham, and the God of Isaac, and the God of Jacob?"}, {"numero": 27, "texto": "He is not the God of the dead, but the God of the living: ye therefore do greatly err."}, {"numero": 28, "texto": "And one of the scribes came, and having heard them reasoning together, and perceiving that he had answered them well, asked him, Which is the first commandment of all?"}, {"numero": 29, "texto": "And Jesus answered him, The first of all the commandments is, Hear, O Israel; The Lord our God is one Lord:"}, {"numero": 30, "texto": "And thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind, and with all thy strength: this is the first commandment."}, {"numero": 31, "texto": "And the second is like, namely this, Thou shalt love thy neighbour as thyself. There is none other commandment greater than these."}, {"numero": 32, "texto": "And the scribe said unto him, Well, Master, thou hast said the truth: for there is one God; and there is none other but he:"}, {"numero": 33, "texto": "And to love him with all the heart, and with all the understanding, and with all the soul, and with all the strength, and to love his neighbour as himself, is more than all whole burnt offerings and sacrifices."}, {"numero": 34, "texto": "And when Jesus saw that he answered discreetly, he said unto him, Thou art not far from the kingdom of God. And no man after that durst ask him any question."}, {"numero": 35, "texto": "And Jesus answered and said, while he taught in the temple, How say the scribes that Christ is the son of David?"}, {"numero": 36, "texto": "For David himself said by the Holy Ghost, The Lord said to my Lord, Sit thou on my right hand, till I make thine enemies thy footstool."}, {"numero": 37, "texto": "David therefore himself calleth him Lord; and whence is he then his son? And the common people heard him gladly."}, {"numero": 38, "texto": "And he said unto them in his doctrine, Beware of the scribes, which love to go in long clothing, and love salutations in the marketplaces,"}, {"numero": 39, "texto": "And the chief seats in the synagogues, and the uppermost rooms at feasts:"}, {"numero": 40, "texto": "Which devour widows'' houses, and for a pretence make long prayers: these shall receive greater damnation."}, {"numero": 41, "texto": "And Jesus sat over against the treasury, and beheld how the people cast money into the treasury: and many that were rich cast in much."}, {"numero": 42, "texto": "And there came a certain poor widow, and she threw in two mites, which make a farthing."}, {"numero": 43, "texto": "And he called unto him his disciples, and saith unto them, Verily I say unto you, That this poor widow hath cast more in, than all they which have cast into the treasury:"}, {"numero": 44, "texto": "For all they did cast in of their abundance; but she of her want did cast in all that she had, even all her living."}]'::jsonb, 'King James Version'),
  ('Mc', 12, 'fr', '[{"numero": 1, "texto": "Jésus se mit ensuite à leur parler en paraboles. Un homme planta une vigne. Il l''''entoura d''''une haie, creusa un pressoir, et bâtit une tour; puis il l''''afferma à des vignerons, et quitta le pays."}, {"numero": 2, "texto": "Au temps de la récolte, il envoya un serviteur vers les vignerons, pour recevoir d''''eux une part du produit de la vigne."}, {"numero": 3, "texto": "S''''étant saisis de lui, ils le battirent, et le renvoyèrent à vide."}, {"numero": 4, "texto": "Il envoya de nouveau vers eux un autre serviteur; ils le frappèrent à la tête, et l''''outragèrent."}, {"numero": 5, "texto": "Il en envoya un troisième, qu''''ils tuèrent; puis plusieurs autres, qu''''ils battirent ou tuèrent."}, {"numero": 6, "texto": "Il avait encore un fils bien-aimé; il l''''envoya vers eux le dernier, en disant: Ils auront du respect pour mon fils."}, {"numero": 7, "texto": "Mais ces vignerons dirent entre eux: Voici l''''héritier; venez, tuons-le, et l''''héritage sera à nous."}, {"numero": 8, "texto": "Et ils se saisirent de lui, le tuèrent, et le jetèrent hors de la vigne."}, {"numero": 9, "texto": "Maintenant, que fera le maître de la vigne? Il viendra, fera périr les vignerons, et il donnera la vigne à d''''autres."}, {"numero": 10, "texto": "N''''avez-vous pas lu cette parole de l''''Ecriture: La pierre qu''''ont rejetée ceux qui bâtissaient Est devenue la principale de l''''angle;"}, {"numero": 11, "texto": "C''''est par la volonté du Seigneur qu''''elle l''''est devenue, Et c''''est un prodige à nos yeux?"}, {"numero": 12, "texto": "Ils cherchaient à se saisir de lui, mais ils craignaient la foule. Ils avaient compris que c''''était pour eux que Jésus avait dit cette parabole. Et ils le quittèrent, et s''''en allèrent."}, {"numero": 13, "texto": "Ils envoyèrent auprès de Jésus quelques-uns des pharisiens et des hérodiens, afin de le surprendre par ses propres paroles."}, {"numero": 14, "texto": "Et ils vinrent lui dire: Maître, nous savons que tu es vrai, et que tu ne t''''inquiètes de personne; car tu ne regardes pas à l''''apparence des hommes, et tu enseignes la voie de Dieu selon la vérité. Est-il permis, ou non, de payer le tribut à César?"}, {"numero": 15, "texto": "Devons-nous payer, ou ne pas payer? Jésus, connaissant leur hypocrisie, leur répondit: Pourquoi me tentez-vous? Apportez-moi un denier, afin que je le voie."}, {"numero": 16, "texto": "Ils en apportèrent un; et Jésus leur demanda: De qui sont cette effigie et cette inscription? De César, lui répondirent-ils."}, {"numero": 17, "texto": "Alors il leur dit: Rendez à César ce qui est à César, et à Dieu ce qui est à Dieu. Et ils furent à son égard dans l''''étonnement."}, {"numero": 18, "texto": "Les sadducéens, qui disent qu''''il n''''y a point de résurrection, vinrent auprès de Jésus, et lui firent cette question:"}, {"numero": 19, "texto": "Maître, voici ce que Moïse nous a prescrit: Si le frère de quelqu''''un meurt, et laisse une femme, sans avoir d''''enfants, son frère épousera sa veuve, et suscitera une postérité à son frère."}, {"numero": 20, "texto": "Or, il y avait sept frères. Le premier se maria, et mourut sans laisser de postérité."}, {"numero": 21, "texto": "Le second prit la veuve pour femme, et mourut sans laisser de postérité. Il en fut de même du troisième,"}, {"numero": 22, "texto": "et aucun des sept ne laissa de postérité. Après eux tous, la femme mourut aussi."}, {"numero": 23, "texto": "A la résurrection, duquel d''''entre eux sera-t-elle la femme? Car les sept l''''ont eue pour femme."}, {"numero": 24, "texto": "Jésus leur répondit: N''''êtes-vous pas dans l''''erreur, parce que vous ne comprenez ni les Ecritures, ni la puissance de Dieu?"}, {"numero": 25, "texto": "Car, à la résurrection des morts, les hommes ne prendront point de femmes, ni les femmes de maris, mais ils seront comme les anges dans les cieux."}, {"numero": 26, "texto": "Pour ce qui est de la résurrection des morts, n''''avez-vous pas lu, dans le livre de Moïse, ce que Dieu lui dit, à propos du buisson: Je suis le Dieu d''''Abraham, le Dieu d''''Isaac, et le Dieu de Jacob?"}, {"numero": 27, "texto": "Dieu n''''est pas Dieu des morts, mais des vivants. Vous êtes grandement dans l''''erreur."}, {"numero": 28, "texto": "Un des scribes, qui les avait entendus discuter, sachant que Jésus avait bien répondu aux sadducéens, s''''approcha, et lui demanda: Quel est le premier de tous les commandements?"}, {"numero": 29, "texto": "Jésus répondit: Voici le premier: Ecoute, Israël, le Seigneur, notre Dieu, est l''''unique Seigneur;"}, {"numero": 30, "texto": "et: Tu aimeras le Seigneur, ton Dieu, de tout ton coeur, de toute ton âme, de toute ta pensée, et de toute ta force."}, {"numero": 31, "texto": "Voici le second: Tu aimeras ton prochain comme toi-même. Il n''''y a pas d''''autre commandement plus grand que ceux-là."}, {"numero": 32, "texto": "Le scribe lui dit: Bien, maître; tu as dit avec vérité que Dieu est unique, et qu''''il n''''y en a point d''''autre que lui,"}, {"numero": 33, "texto": "et que l''''aimer de tout son coeur, de toute sa pensée, de toute son âme et de toute sa force, et aimer son prochain comme soi-même, c''''est plus que tous les holocaustes et tous les sacrifices."}, {"numero": 34, "texto": "Jésus, voyant qu''''il avait répondu avec intelligence, lui dit: Tu n''''es pas loin du royaume de Dieu. Et personne n''''osa plus lui proposer des questions."}, {"numero": 35, "texto": "Jésus, continuant à enseigner dans le temple, dit: Comment les scribes disent-ils que le Christ est fils de David?"}, {"numero": 36, "texto": "David lui-même, animé par l''''Esprit-Saint, a dit: Le Seigneur a dit à mon Seigneur: Assieds-toi à ma droite, Jusqu''''à ce que je fasse de tes ennemis ton marchepied."}, {"numero": 37, "texto": "David lui-même l''''appelle Seigneur; comment donc est-il son fils? Et une grande foule l''''écoutait avec plaisir."}, {"numero": 38, "texto": "Il leur disait dans son enseignement: Gardez-vous des scribes, qui aiment à se promener en robes longues, et à être salués dans les places publiques;"}, {"numero": 39, "texto": "qui recherchent les premiers sièges dans les synagogues, et les premières places dans les festins;"}, {"numero": 40, "texto": "qui dévorent les maisons des veuves, et qui font pour l''''apparence de longues prières. Ils seront jugés plus sévèrement."}, {"numero": 41, "texto": "Jésus, s''''étant assis vis-à-vis du tronc, regardait comment la foule y mettait de l''''argent. Plusieurs riches mettaient beaucoup."}, {"numero": 42, "texto": "Il vint aussi une pauvre veuve, elle y mit deux petites pièces, faisant un quart de sou."}, {"numero": 43, "texto": "Alors Jésus, ayant appelé ses disciples, leur dit: Je vous le dis en vérité, cette pauvre veuve a donné plus qu''''aucun de ceux qui ont mis dans le tronc;"}, {"numero": 44, "texto": "car tous ont mis de leur superflu, mais elle a mis de son nécessaire, tout ce qu''''elle possédait, tout ce qu''''elle avait pour vivre."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 12, 'es', '[{"numero": 1, "texto": "Y COMENZÓ á hablarles por parábolas: Plantó un hombre una viña, y la cercó con seto, y cavó un lagar, y edificó una torre, y la arrendó á labradores, y se partió lejos."}, {"numero": 2, "texto": "Y envió un siervo á los labradores, al tiempo, para que tomase de los labradores del fruto de la viña."}, {"numero": 3, "texto": "Mas ellos, tomándole, le hirieron, y le enviaron vacío."}, {"numero": 4, "texto": "Y volvió á enviarles otro siervo; mas apedreándole, le hirieron en la cabeza, y volvieron á enviarle afrentado."}, {"numero": 5, "texto": "Y volvió á enviar otro, y á aquél mataron; y á otros muchos, hiriendo á unos y matando á otros."}, {"numero": 6, "texto": "Teniendo pues aún un hijo suyo amado, enviólo también á ellos el postrero, diciendo: Tendrán en reverencia á mi hijo."}, {"numero": 7, "texto": "Mas aquellos labradores dijeron entre sí: Este es el heredero; venid, matémosle, y la heredad será nuestra."}, {"numero": 8, "texto": "Y prendiéndole, le mataron, y echaron fuera de la viña."}, {"numero": 9, "texto": "¿Qué, pues, hará el señor de la viña? Vendrá, y destruirá á estos labradores, y dará su viña á otros."}, {"numero": 10, "texto": "¿Ni aun esta Escritura habéis leído: La piedra que desecharon los que edificaban, ésta es puesta por cabeza de esquina;"}, {"numero": 11, "texto": "Por el Señor es hecho esto, y es cosa maravillosa en nuestros ojos?"}, {"numero": 12, "texto": "Y procuraban prenderle, porque entendían que decía á ellos aquella parábola; mas temían á la multitud; y dejándole, se fueron."}, {"numero": 13, "texto": "Y envían á él algunos de los Fariseos y de los Herodianos, para que le sorprendiesen en alguna palabra."}, {"numero": 14, "texto": "Y viniendo ellos, le dicen: Maestro, sabemos que eres hombre de verdad, y que no te cuidas de nadie; porque no miras á la apariencia de hombres, antes con verdad enseñas el camino de Dios: ¿Es lícito dar tributo á César, ó no? ¿Daremos, ó no daremos?"}, {"numero": 15, "texto": "Entonces él, como entendía la hipocresía de ellos, les dijo: ¿Por qué me tentáis? Traedme la moneda para que la vea."}, {"numero": 16, "texto": "Y ellos se la trajeron y les dice: ¿Cúya es esta imagen y esta inscripción? Y ellos le dijeron: De César."}, {"numero": 17, "texto": "Y respondiendo Jesús, les dijo: Dad lo que es de César á César; y lo que es de Dios, á Dios. Y se maravillaron de ello."}, {"numero": 18, "texto": "Entonces vienen á él los Saduceos, que dicen que no hay resurrección, y le preguntaron, diciendo:"}, {"numero": 19, "texto": "Maestro, Moisés nos escribió, que si el hermano de alguno muriese, y dejase mujer, y no dejase hijos, que su hermano tome su mujer, y levante linaje á su hermano."}, {"numero": 20, "texto": "Fueron siete hermanos: y el primero tomó mujer, y muriendo, no dejó simiente;"}, {"numero": 21, "texto": "Y la tomó el segundo, y murió, y ni aquél tampoco dejó simiente; y el tercero, de la misma manera."}, {"numero": 22, "texto": "Y la tomaron los siete, y tampoco dejaron simiente: á la postre murió también la mujer."}, {"numero": 23, "texto": "En la resurrección, pues, cuando resucitaren, ¿de cuál de ellos será mujer? porque los siete la tuvieron por mujer."}, {"numero": 24, "texto": "Entonces respondiendo Jesús, les dice: ¿No erráis por eso, porque no sabéis las Escrituras, ni la potencia de Dios?"}, {"numero": 25, "texto": "Porque cuando resucitarán de los muertos, ni se casarán, ni serán dados en casamiento, mas son como los ángeles que están en los cielos."}, {"numero": 26, "texto": "Y de que los muertos hayan de resucitar, ¿no habéis leído en el libro de Moisés cómo le habló Dios en la zarza, diciendo: Yo soy el Dios de Abraham, y el Dios de Isaac, y el Dios de Jacob?"}, {"numero": 27, "texto": "No es Dios de muertos, mas Dios de vivos; así que vosotros mucho erráis."}, {"numero": 28, "texto": "Y llegándose uno de los escribas, que los había oído disputar, y sabía que les había respondido bien, le preguntó: ¿Cuál es el primer mandamiento de todos?"}, {"numero": 29, "texto": "Y Jesús le respondió: El primer mandamiento de todos es: Oye, Israel, el Señor nuestro Dios, el Señor uno es."}, {"numero": 30, "texto": "Amarás pues al Señor tu Dios de todo tu corazón, y de toda tu alma, y de toda tu mente, y de todas tus fuerzas; este es el principal mandamiento."}, {"numero": 31, "texto": "Y el segundo es semejante á él: Amarás á tu prójimo como á ti mismo. No hay otro mandamiento mayor que éstos."}, {"numero": 32, "texto": "Entonces el escriba le dijo: Bien, Maestro, verdad has dicho, que uno es Dios, y no hay otro fuera de él;"}, {"numero": 33, "texto": "Y que amarle de todo corazón, y de todo entendimiento, y de toda el alma, y de todas las fuerzas, y amar al prójimo como á sí mismo, más es que todos los holocaustos y sacrificios."}, {"numero": 34, "texto": "Jesús entonces, viendo que había respondido sabiamente, le dice: No estás lejos del reino de Dios. Y ya ninguno osaba preguntarle."}, {"numero": 35, "texto": "Y respondiendo Jesús decía, enseñando en el templo: ¿Cómo dicen los escribas que el Cristo es hijo de David?"}, {"numero": 36, "texto": "Porque el mismo David dijo por el Espíritu Santo: Dijo el Señor á mi Señor: Siéntate á mi diestra, hasta que ponga tus enemigos por estrado de tus pies."}, {"numero": 37, "texto": "Luego llamándole el mismo David Señor, ¿de dónde, pues, es su hijo? Y los que eran del común del pueblo le oían de buena gana."}, {"numero": 38, "texto": "Y les decía en su doctrina: Guardaos de los escribas, que quieren andar con ropas largas, y aman las salutaciones en las plazas,"}, {"numero": 39, "texto": "Y las primeras sillas en las sinagogas, y los primeros asientos en las cenas;"}, {"numero": 40, "texto": "Que devoran las casas de las viudas, y por pretexto hacen largas oraciones. Estos recibirán mayor juicio."}, {"numero": 41, "texto": "Y estando sentado Jesús delante del arca de la ofrenda, miraba cómo el pueblo echaba dinero en el arca: y muchos ricos echaban mucho."}, {"numero": 42, "texto": "Y como vino una viuda pobre, echó dos blancas, que son un maravedí."}, {"numero": 43, "texto": "Entonces llamando á sus discípulos, les dice: De cierto os digo que esta viuda pobre echó más que todos los que han echado en el arca:"}, {"numero": 44, "texto": "Porque todos han echado de lo que les sobra; mas ésta, de su pobreza echó todo lo que tenía, todo su alimento."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 13, 'pt', '[{"numero": 1, "texto": "Quando ele estava saindo do templo, um de seus discípulos lhe disse: Mestre, olha que pedras, e que edifícios!"}, {"numero": 2, "texto": "Jesus respondeu, dizendo-lhe: Vês estes grandes edifícios? Não será deixada pedra sobre pedra, que não seja derrubada."}, {"numero": 3, "texto": "Depois, sentando-se ele no monte das Oliveiras, de frente ao templo, Pedro, Tiago, João, e André perguntaram-lhe à parte:"}, {"numero": 4, "texto": "Dize-nos, quando serão essas coisas? E que sinal haverá de quando todas essas coisas se cumprirão?"}, {"numero": 5, "texto": "E Jesus, respondendo-lhes, começou a dizer: Cuidado! ninguém vos engane;"}, {"numero": 6, "texto": "porque muitos virão em meu nome, dizendo: “Sou eu”, e enganarão a muitos."}, {"numero": 7, "texto": "E quando ouvirdes de guerras e de rumores de guerras, não vos perturbeis; porque [assim] deve acontecer; mas ainda não será o fim."}, {"numero": 8, "texto": "Porque nação se levantará contra nação, e reino contra reino, e haverá terremotos em muitos lugares, e haverá fomes e tumultos. Estes serão os princípios das dores."}, {"numero": 9, "texto": "Mas cuidai de vós mesmos; porque vos entregarão em tribunais e em sinagogas; sereis açoitados, e sereis levados diante de governadores e reis, por causa de mim, para que lhes haja testemunho."}, {"numero": 10, "texto": "Mas antes o Evangelho deve ser pregado entre todas as nações."}, {"numero": 11, "texto": "Porém, quando vos levarem para vos entregar, não estejais ansiosos antecipadamente do que deveis dizer, nem o planejeis; mas o que naquela hora for dado, isso falai. Porque não sois vós os que falais, mas o Espírito Santo."}, {"numero": 12, "texto": "E o irmão entregará ao irmão à morte, e o pai ao filho; e os filhos se levantarão contra os pais, e os matarão."}, {"numero": 13, "texto": "E sereis odiados por todos por causa do meu nome; mas quem perseverar até o fim, esse será salvo."}, {"numero": 14, "texto": "E quando virdes a abominação da desolação, que foi dita pelo profeta Daniel, estar onde não deve, (quem lê, entenda), então os que estiverem na Judeia, fujam para os montes."}, {"numero": 15, "texto": "E quem estiver sobre telhado, não desça para a casa, nem entre para tomar alguma coisa de sua casa."}, {"numero": 16, "texto": "E quem estiver no campo, não volte atrás, para tomar sua roupa."}, {"numero": 17, "texto": "Mas ai das grávidas, e das que amamentarem naqueles dias!"}, {"numero": 18, "texto": "Orai, porém, para que a vossa fuga não aconteça no inverno."}, {"numero": 19, "texto": "Porque aqueles dias serão de tal aflição, qual nunca foi desde o princípio da criação das coisas, que Deus criou, até agora, nem jamais será."}, {"numero": 20, "texto": "E se o Senhor não encurtasse aqueles dias, ninguém se salvaria; mas por causa dos escolhidos, que escolheu, ele encurtou aqueles dias."}, {"numero": 21, "texto": "Então se alguém vos disser: “Eis aqui o Cristo”; ou “ei-lo ali”, não creiais nele."}, {"numero": 22, "texto": "Porque se levantarão falsos cristos, e falsos profetas, que farão sinais e prodígios, para enganar, se possível, até os escolhidos."}, {"numero": 23, "texto": "Vós, porém, tende cuidado; eis que tenho vos dito tudo com antecedência."}, {"numero": 24, "texto": "Mas naqueles dias, depois daquela aflição, o sol se escurecerá, e a lua não dará seu brilho;"}, {"numero": 25, "texto": "as estrelas do céu cairão, e as forças que estão nos céus se abalarão."}, {"numero": 26, "texto": "Então verão o Filho do homem vir nas nuvens, com grande poder e glória."}, {"numero": 27, "texto": "Ele então enviará os seus anjos, e ajuntará os seus escolhidos dos quatro ventos, desde a extremidade da terra, até a extremidade do céu."}, {"numero": 28, "texto": "E aprendei a parábola da figueira: Quando o seu ramo já vai ficando tenro, e brota folhas, bem sabeis que o verão já está perto."}, {"numero": 29, "texto": "Assim também vós, quando virdes suceder estas coisas, sabei que já está perto, às portas."}, {"numero": 30, "texto": "Em verdade vos digo que não passará esta geração, até que todas estas coisas aconteçam."}, {"numero": 31, "texto": "O céu e a terra passarão, mas as minhas palavras em maneira nenhuma passarão."}, {"numero": 32, "texto": "Porém daquele dia e hora ninguém sabe, nem os anjos que estão no céu, nem o Filho, a não ser somente o Pai."}, {"numero": 33, "texto": "Olhai, vigiai, e orai; porque não sabeis quando será o tempo."}, {"numero": 34, "texto": "Assim como o homem que, partindo-se para fora de sua terra, deixou sua casa, e deu autoridade aos seus servos, e a cada um o seu trabalho, e mandou ao porteiro que vigiasse,"}, {"numero": 35, "texto": "assim também vigiai, porque não sabeis quando virá o Senhor da casa; se à tarde, se à meia-noite, se ao cantar do galo, se pela manhã,"}, {"numero": 36, "texto": "para que ele não venha de repente, e vos ache dormindo."}, {"numero": 37, "texto": "E as coisas que vos digo, digo a todos: Vigiai."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 13, 'en', '[{"numero": 1, "texto": "And as he went out of the temple, one of his disciples saith unto him, Master, see what manner of stones and what buildings are here!"}, {"numero": 2, "texto": "And Jesus answering said unto him, Seest thou these great buildings? there shall not be left one stone upon another, that shall not be thrown down."}, {"numero": 3, "texto": "And as he sat upon the mount of Olives over against the temple, Peter and James and John and Andrew asked him privately,"}, {"numero": 4, "texto": "Tell us, when shall these things be? and what shall be the sign when all these things shall be fulfilled?"}, {"numero": 5, "texto": "And Jesus answering them began to say, Take heed lest any man deceive you:"}, {"numero": 6, "texto": "For many shall come in my name, saying, I am Christ; and shall deceive many."}, {"numero": 7, "texto": "And when ye shall hear of wars and rumours of wars, be ye not troubled: for such things must needs be; but the end shall not be yet."}, {"numero": 8, "texto": "For nation shall rise against nation, and kingdom against kingdom: and there shall be earthquakes in divers places, and there shall be famines and troubles: these are the beginnings of sorrows."}, {"numero": 9, "texto": "But take heed to yourselves: for they shall deliver you up to councils; and in the synagogues ye shall be beaten: and ye shall be brought before rulers and kings for my sake, for a testimony against them."}, {"numero": 10, "texto": "And the gospel must first be published among all nations."}, {"numero": 11, "texto": "But when they shall lead you, and deliver you up, take no thought beforehand what ye shall speak, neither do ye premeditate: but whatsoever shall be given you in that hour, that speak ye: for it is not ye that speak, but the Holy Ghost."}, {"numero": 12, "texto": "Now the brother shall betray the brother to death, and the father the son; and children shall rise up against their parents, and shall cause them to be put to death."}, {"numero": 13, "texto": "And ye shall be hated of all men for my name''s sake: but he that shall endure unto the end, the same shall be saved."}, {"numero": 14, "texto": "But when ye shall see the abomination of desolation, spoken of by Daniel the prophet, standing where it ought not, (let him that readeth understand,) then let them that be in Judaea flee to the mountains:"}, {"numero": 15, "texto": "And let him that is on the housetop not go down into the house, neither enter therein, to take any thing out of his house:"}, {"numero": 16, "texto": "And let him that is in the field not turn back again for to take up his garment."}, {"numero": 17, "texto": "But woe to them that are with child, and to them that give suck in those days!"}, {"numero": 18, "texto": "And pray ye that your flight be not in the winter."}, {"numero": 19, "texto": "For in those days shall be affliction, such as was not from the beginning of the creation which God created unto this time, neither shall be."}, {"numero": 20, "texto": "And except that the Lord had shortened those days, no flesh should be saved: but for the elect''s sake, whom he hath chosen, he hath shortened the days."}, {"numero": 21, "texto": "And then if any man shall say to you, Lo, here is Christ; or, lo, he is there; believe him not:"}, {"numero": 22, "texto": "For false Christs and false prophets shall rise, and shall shew signs and wonders, to seduce, if it were possible, even the elect."}, {"numero": 23, "texto": "But take ye heed: behold, I have foretold you all things."}, {"numero": 24, "texto": "But in those days, after that tribulation, the sun shall be darkened, and the moon shall not give her light,"}, {"numero": 25, "texto": "And the stars of heaven shall fall, and the powers that are in heaven shall be shaken."}, {"numero": 26, "texto": "And then shall they see the Son of man coming in the clouds with great power and glory."}, {"numero": 27, "texto": "And then shall he send his angels, and shall gather together his elect from the four winds, from the uttermost part of the earth to the uttermost part of heaven."}, {"numero": 28, "texto": "Now learn a parable of the fig tree; When her branch is yet tender, and putteth forth leaves, ye know that summer is near:"}, {"numero": 29, "texto": "So ye in like manner, when ye shall see these things come to pass, know that it is nigh, even at the doors."}, {"numero": 30, "texto": "Verily I say unto you, that this generation shall not pass, till all these things be done."}, {"numero": 31, "texto": "Heaven and earth shall pass away: but my words shall not pass away."}, {"numero": 32, "texto": "But of that day and that hour knoweth no man, no, not the angels which are in heaven, neither the Son, but the Father."}, {"numero": 33, "texto": "Take ye heed, watch and pray: for ye know not when the time is."}, {"numero": 34, "texto": "For the Son of Man is as a man taking a far journey, who left his house, and gave authority to his servants, and to every man his work, and commanded the porter to watch."}, {"numero": 35, "texto": "Watch ye therefore: for ye know not when the master of the house cometh, at even, or at midnight, or at the cockcrowing, or in the morning:"}, {"numero": 36, "texto": "Lest coming suddenly he find you sleeping."}, {"numero": 37, "texto": "And what I say unto you I say unto all, Watch."}]'::jsonb, 'King James Version'),
  ('Mc', 13, 'fr', '[{"numero": 1, "texto": "Lorsque Jésus sortit du temple, un de ses disciples lui dit: Maître, regarde quelles pierres, et quelles constructions!"}, {"numero": 2, "texto": "Jésus lui répondit: Vois-tu ces grandes constructions? Il ne restera pas pierre sur pierre qui ne soit renversée."}, {"numero": 3, "texto": "Il s''''assit sur la montagne des oliviers, en face du temple. Et Pierre, Jacques, Jean et André lui firent en particulier cette question:"}, {"numero": 4, "texto": "Dis-nous, quand cela arrivera-t-il, et à quel signe connaîtra-t-on que toutes ces choses vont s''''accomplir?"}, {"numero": 5, "texto": "Jésus se mit alors à leur dire: Prenez garde que personne ne vous séduise."}, {"numero": 6, "texto": "Car plusieurs viendront sous mon nom, disant; C''''est moi. Et ils séduiront beaucoup de gens."}, {"numero": 7, "texto": "Quand vous entendrez parler de guerres et de bruits de guerres, ne soyez pas troublés, car il faut que ces choses arrivent. Mais ce ne sera pas encore la fin."}, {"numero": 8, "texto": "Une nation s''''élèvera contre une nation, et un royaume contre un royaume; il y aura des tremblements de terre en divers lieux, il y aura des famines. Ce ne sera que le commencement des douleurs."}, {"numero": 9, "texto": "Prenez garde à vous-mêmes. On vous livrera aux tribunaux, et vous serez battus de verges dans les synagogues; vous comparaîtrez devant des gouverneurs et devant des rois, à cause de moi, pour leur servir de témoignage."}, {"numero": 10, "texto": "Il faut premièrement que la bonne nouvelle soit prêchée à toutes les nations."}, {"numero": 11, "texto": "Quand on vous emmènera pour vous livrer, ne vous inquiétez pas d''''avance de ce que vous aurez à dire, mais dites ce qui vous sera donné à l''''heure même; car ce n''''est pas vous qui parlerez, mais l''''Esprit-Saint."}, {"numero": 12, "texto": "Le frère livrera son frère à la mort, et le père son enfant; les enfants se soulèveront contre leurs parents, et les feront mourir."}, {"numero": 13, "texto": "Vous serez haïs de tous, à cause de mon nom, mais celui qui persévérera jusqu''''à la fin sera sauvé."}, {"numero": 14, "texto": "Lorsque vous verrez l''''abomination de la désolation établie là où elle ne doit pas être, -que celui qui lit fasse attention, -alors, que ceux qui seront en Judée fuient dans les montagnes;"}, {"numero": 15, "texto": "que celui qui sera sur le toit ne descende pas et n''''entre pas pour prendre quelque chose dans sa maison;"}, {"numero": 16, "texto": "et que celui qui sera dans les champs ne retourne pas en arrière pour prendre son manteau."}, {"numero": 17, "texto": "Malheur aux femmes qui seront enceintes et à celles qui allaiteront en ces jours-là!"}, {"numero": 18, "texto": "Priez pour que ces choses n''''arrivent pas en hiver."}, {"numero": 19, "texto": "Car la détresse, en ces jours, sera telle qu''''il n''''y en a point eu de semblable depuis le commencement du monde que Dieu a créé jusqu''''à présent, et qu''''il n''''y en aura jamais."}, {"numero": 20, "texto": "Et, si le Seigneur n''''avait abrégé ces jours, personne ne serait sauvé; mais il les a abrégés, à cause des élus qu''''il a choisis."}, {"numero": 21, "texto": "Si quelqu''''un vous dit alors: Le Christ est ici, ou: Il est là\", ne le croyez pas."}, {"numero": 22, "texto": "Car il s''''élèvera de faux Christs et de faux prophètes; ils feront des prodiges et des miracles pour séduire les élus, s''''il était possible."}, {"numero": 23, "texto": "Soyez sur vos gardes: je vous ai tout annoncé d''''avance."}, {"numero": 24, "texto": "Mais dans ces jours, après cette détresse, le soleil s''''obscurcira, la lune ne donnera plus sa lumière,"}, {"numero": 25, "texto": "les étoiles tomberont du ciel, et les puissances qui sont dans les cieux seront ébranlées."}, {"numero": 26, "texto": "Alors on verra le Fils de l''''homme venant sur les nuées avec une grande puissance et avec gloire."}, {"numero": 27, "texto": "Alors il enverra les anges, et il rassemblera les élus des quatre vents, de l''''extrémité de la terre jusqu''''à l''''extrémité du ciel."}, {"numero": 28, "texto": "Instruisez-vous par une comparaison tirée du figuier. Dès que ses branches deviennent tendres, et que les feuilles poussent, vous connaissez que l''''été est proche."}, {"numero": 29, "texto": "De même, quand vous verrez ces choses arriver, sachez que le Fils de l''''homme est proche, à la porte."}, {"numero": 30, "texto": "Je vous le dis en vérité, cette génération ne passera point, que tout cela n''''arrive."}, {"numero": 31, "texto": "Le ciel et la terre passeront, mais mes paroles ne passeront point."}, {"numero": 32, "texto": "Pour ce qui est du jour ou de l''''heure, personne ne le sait, ni les anges dans le ciel, ni le Fils, mais le Père seul."}, {"numero": 33, "texto": "Prenez garde, veillez et priez; car vous ne savez quand ce temps viendra."}, {"numero": 34, "texto": "Il en sera comme d''''un homme qui, partant pour un voyage, laisse sa maison, remet l''''autorité à ses serviteurs, indique à chacun sa tâche, et ordonne au portier de veiller."}, {"numero": 35, "texto": "Veillez donc, car vous ne savez quand viendra le maître de la maison, ou le soir, ou au milieu de la nuit, ou au chant du coq, ou le matin;"}, {"numero": 36, "texto": "craignez qu''''il ne vous trouve endormis, à son arrivée soudaine."}, {"numero": 37, "texto": "Ce que je vous dis, je le dis à tous: Veillez."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 13, 'es', '[{"numero": 1, "texto": "Y SALIENDO del templo, le dice uno de sus discípulos: Maestro, mira qué piedras, y qué edificios."}, {"numero": 2, "texto": "Y Jesús respondiendo, le dijo: ¿Ves estos grandes edificios? no quedará piedra sobre piedra que no sea derribada."}, {"numero": 3, "texto": "Y sentándose en el monte de las Olivas delante del templo, le preguntaron aparte Pedro y Jacobo y Juan y Andrés:"}, {"numero": 4, "texto": "Dinos, ¿cuándo serán estas cosas? ¿y qué señal habrá cuando todas estas cosas han de cumplirse?"}, {"numero": 5, "texto": "Y Jesús respondiéndoles, comenzó á decir: Mirad, que nadie os engañe;"}, {"numero": 6, "texto": "Porque vendrán muchos en mi nombre, diciendo: Yo soy el Cristo; y engañarán á muchos."}, {"numero": 7, "texto": "Mas cuando oyereis de guerras y de rumores de guerras no os turbéis, porque conviene hacerse así; mas aun no será el fin."}, {"numero": 8, "texto": "Porque se levantará nación contra nación, y reino contra reino; y habrá terremotos en muchos lugares, y habrá hambres y alborotos; principios de dolores serán estos."}, {"numero": 9, "texto": "Mas vosotros mirad por vosotros: porque os entregarán en los concilios, y en sinagogas seréis azotados: y delante de presidentes y de reyes seréis llamados por causa de mí, en testimonio á ellos."}, {"numero": 10, "texto": "Y á todas las gentes conviene que el evangelio sea predicado antes."}, {"numero": 11, "texto": "Y cuando os trajeren para entregaros, no premeditéis qué habéis de decir, ni lo penséis: mas lo que os fuere dado en aquella hora, eso hablad; porque no sois vosotros los que habláis, sino el Espíritu Santo."}, {"numero": 12, "texto": "Y entregará á la muerte el hermano al hermano, y el padre al hijo: y se levantarán los hijos contra los padres, y los matarán."}, {"numero": 13, "texto": "Y seréis aborrecidos de todos por mi nombre: mas el que perseverare hasta el fin, éste será salvo."}, {"numero": 14, "texto": "Empero cuando viereis la abominación de asolamiento, que fué dicha por el profeta Daniel, que estará donde no debe (el que lee, entienda), entonces los que estén en Judea huyan á los montes;"}, {"numero": 15, "texto": "Y el que esté sobre el terrado, no descienda á la casa, ni entre para tomar algo de su casa;"}, {"numero": 16, "texto": "Y el que estuviere en el campo, no vuelva atrás á tomar su capa."}, {"numero": 17, "texto": "Mas ¡ay de las preñadas, y de las que criaren en aquellos días!"}, {"numero": 18, "texto": "Orad pues, que no acontezca vuestra huída en invierno."}, {"numero": 19, "texto": "Porque aquellos días serán de aflicción, cual nunca fué desde el principio de la creación que crió Dios, hasta este tiempo, ni será."}, {"numero": 20, "texto": "Y si el Señor no hubiese abreviado aquellos días, ninguna carne se salvaría; mas por causa de los escogidos que él escogió, abrevió aquellos días."}, {"numero": 21, "texto": "Y entonces si alguno os dijere: He aquí, aquí está el Cristo; ó, He aquí, allí está, no le creáis."}, {"numero": 22, "texto": "Porque se levantarán falsos Cristos y falsos profetas, y darán señales y prodigios, para engañar, si se pudiese hacer, aun á los escogidos."}, {"numero": 23, "texto": "Mas vosotros mirad; os lo he dicho antes todo."}, {"numero": 24, "texto": "Empero en aquellos días, después de aquella aflicción, el sol se obscurecerá, y la luna no dará su resplandor;"}, {"numero": 25, "texto": "Y las estrellas caerán del cielo, y las virtudes que están en los cielos serán conmovidas;"}, {"numero": 26, "texto": "Y entonces verán al Hijo del hombre, que vendrá en las nubes con mucha potestad y gloria."}, {"numero": 27, "texto": "Y entonces enviará sus ángeles, y juntará sus escogidos de los cuatro vientos, desde el cabo de la tierra hasta el cabo del cielo."}, {"numero": 28, "texto": "De la higuera aprended la semejanza: Cuando su rama ya se enternece, y brota hojas, conocéis que el verano está cerca:"}, {"numero": 29, "texto": "Así también vosotros, cuando viereis hacerse estas cosas, conoced que está cerca, á las puertas."}, {"numero": 30, "texto": "De cierto os digo que no pasará esta generación, que todas estas cosas no sean hechas."}, {"numero": 31, "texto": "El cielo y la tierra pasarán, mas mis palabras no pasarán."}, {"numero": 32, "texto": "Empero de aquel día y de la hora, nadie sabe; ni aun los ángeles que están en el cielo, ni el Hijo, sino el Padre."}, {"numero": 33, "texto": "Mirad, velad y orad: porque no sabéis cuándo será el tiempo."}, {"numero": 34, "texto": "Como el hombre que partiéndose lejos, dejó su casa, y dió facultad á sus siervos, y á cada uno su obra, y al portero mandó que velase:"}, {"numero": 35, "texto": "Velad pues, porque no sabéis cuándo el señor de la casa vendrá; si á la tarde, ó á la media noche, ó al canto del gallo, ó á la mañana;"}, {"numero": 36, "texto": "Porque cuando viniere de repente, no os halle durmiendo."}, {"numero": 37, "texto": "Y las cosas que á vosotros digo, á todos las digo: Velad."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 14, 'pt', '[{"numero": 1, "texto": "E dali a dois dias era a Páscoa, e [a festa] dos pães sem fermento; e os chefes dos sacerdotes, e os escribas buscavam um meio de prendê-lo através de um engano, e o matarem."}, {"numero": 2, "texto": "Diziam, porém: “Não na festa, para que não aconteça tumulto entre o povo.”"}, {"numero": 3, "texto": "E estando ele em Betânia, na casa de Simão o Leproso, sentado [à mesa] , veio uma mulher, que tinha um vaso de alabastro, de óleo perfumado de nardo puro, de muito preço, e quebrando o vaso de alabastro, derramou-o sobre a cabeça dele."}, {"numero": 4, "texto": "E houve alguns que em si mesmos se indignaram, e disseram: “Para que foi feito este desperdício do óleo perfumado?"}, {"numero": 5, "texto": "Porque isto podia ter sido vendido por mais de trezentos denários, e seria dado aos pobres.” E reclamavam contra ela."}, {"numero": 6, "texto": "Porém Jesus disse: “Deixai-a; por que a incomodais? Ela me fez boa obra."}, {"numero": 7, "texto": "Porque pobres sempre tendes convosco; e quando quiserdes, podeis lhes fazer bem; porém a mim, nem sempre me tendes."}, {"numero": 8, "texto": "Esta fez o que podia; adiantou-se para ungir o meu corpo, para a sepultura."}, {"numero": 9, "texto": "Em verdade vos digo, que onde quer que em todo o mundo este Evangelho for pregado, também o que esta fez será dito em sua memória.”"}, {"numero": 10, "texto": "E Judas Iscariotes, um dos doze, foi aos chefes dos sacerdotes, para o entregar a eles."}, {"numero": 11, "texto": "E eles ouvindo, alegraram-se; e prometeram lhe dar dinheiro; e buscava como o entregaria em tempo oportuno."}, {"numero": 12, "texto": "E o primeiro dia dos pães sem fermento, quando sacrificavam [o cordeiro da] Páscoa, seus discípulos lhe disseram: “Onde queres que vamos preparar para comerdes a Páscoa?”"}, {"numero": 13, "texto": "E mandou dois de seus discípulos, e disse-lhes: “Ide à cidade, e um homem que leva um cântaro de água vos encontrará, a ele segui."}, {"numero": 14, "texto": "E onde quer que ele entrar, dizei ao senhor da casa: O Mestre diz: Onde está o cômodo onde comerei Páscoa com meus discípulos?"}, {"numero": 15, "texto": "E ele vos mostrará um grande salão, ornado e preparado; ali fazei os preparativos para nós.”"}, {"numero": 16, "texto": "E seusdiscípulos saíram, e vieram à cidade, e acharam como havia lhes dito, e prepararam a Páscoa."}, {"numero": 17, "texto": "E chegada a tarde, veio com os doze."}, {"numero": 18, "texto": "E quando se sentaram [à mesa] , e comeram, Jesus disse: “Em verdade vos digo, que um de vós, que está comendo comigo, me trairá.”"}, {"numero": 19, "texto": "E eles começaram a se entristecer, e a lhe dizer um após outro: “Por acaso sou eu?” E outro: “Por acaso sou eu?”"}, {"numero": 20, "texto": "Porém ele lhes respondeu: “[É] um dos doze, o que está molhando [a mão] comigo no prato."}, {"numero": 21, "texto": "Em verdade o Filho do homem vai, como está escrito sobre ele; mas ai daquele homem por quem o Filho do homem é traído; bom lhe fosse ao tal homem não haver nascido.”"}, {"numero": 22, "texto": "E enquanto eles comiam, Jesus tomou o pão; e bendizendo, partiu-o, deu-lhes, e disse: “Tomai, comei, isto é o meu corpo.”"}, {"numero": 23, "texto": "E tomando o copo, e dando graças, deu-lhes; e todos beberam dele."}, {"numero": 24, "texto": "E disse-lhes: “Isto é o meu sangue, o do novo testamento, que é derramado por muitos."}, {"numero": 25, "texto": "Em verdade vos digo, que não beberei mais do fruto da vide, até aquele dia, quando o beber novo no Reino de Deus.”"}, {"numero": 26, "texto": "E depois de cantarem um hino, saíram para o monte das Oliveiras."}, {"numero": 27, "texto": "E Jesus lhes disse: “Todos vós falhareis comigo esta noite; porque está escrito: Ferirei ao pastor, e as ovelhas serão dispersas."}, {"numero": 28, "texto": "Mas depois de eu haver ressuscitado, irei adiante de vós para a Galileia.”"}, {"numero": 29, "texto": "E Pedro lhe disse: “Ainda que todos falhem, eu não [falharei] .”"}, {"numero": 30, "texto": "Jesus lhe disse: “Em verdade te digo, que hoje, nesta noite, antes que o galo cante duas vezes, me negarás três vezes.”"}, {"numero": 31, "texto": "Mas [Pedro] , insistindo, dizia: “Ainda que me seja necessário morrer contigo, em maneira nenhuma te negarei.” E todos diziam também da mesma maneira."}, {"numero": 32, "texto": "E vieram ao lugar, cujo nome era Getsêmani, e disse a seus discípulos: “Sentai-vos aqui, enquanto eu oro.”"}, {"numero": 33, "texto": "E tomou consigo Pedro, Tiago, e João, e começou a ficar muito apavorado e angustiado."}, {"numero": 34, "texto": "E disse-lhes: “Minha alma totalmente está triste até a morte; ficai-vos aqui, e vigiai.”"}, {"numero": 35, "texto": "Então ele foi um pouco mais adiante, e prostrou-se em terra. E orou, que se fosse possível, afastasse dele aquela hora."}, {"numero": 36, "texto": "E disse: “Aba, Pai, todas as coisas te são possíveis; passa de mim este copo; porém não [se faça] o que eu quero, mas sim o que tu [queres] .”"}, {"numero": 37, "texto": "Depois veio de volta, e os achou dormindo; e disse a Pedro: “Simão, estás dormindo? Não podes vigiar uma hora?"}, {"numero": 38, "texto": "Vigiai, e orai, para que não entreis em tentação; o espírito em verdade [está] pronto, mas a carne [é] fraca.”"}, {"numero": 39, "texto": "E depois que se foi novamente, orou, dizendo as mesmas palavras."}, {"numero": 40, "texto": "Quando voltou, achou-os outra vez dormindo; porque os olhos deles estavam pesados, e não sabiam o que lhe responder."}, {"numero": 41, "texto": "E veio a terceira vez, e disse-lhes: “Ainda estais dormindo e descansando? Basta, chegada é a hora. Eis que o Filho do homem é entregue em mãos dos pecadores."}, {"numero": 42, "texto": "Levantai-vos, vamos; eis que o que me trai está perto."}, {"numero": 43, "texto": "E logo, enquanto ele ainda estava falando, veio Judas, que era um dos doze, e com ele uma grande multidão, com espadas e bastões, da parte dos chefes dos sacerdotes, dos escribas, dos anciãos."}, {"numero": 44, "texto": "E o que o traía lhes tinha dado um sinal comum, dizendo: “Ao que eu beijar, é esse; prendei-o, e levai-o em segurança.”"}, {"numero": 45, "texto": "E quando veio, logo foi-se a ele, e disse-lhe: “Rabi, Rabi”, e o beijou."}, {"numero": 46, "texto": "Então o agarraram, e o prenderam."}, {"numero": 47, "texto": "E um dos que estavam ali presentes puxou a espada, feriu o servo do sumo sacerdote, e cortou-lhe a orelha."}, {"numero": 48, "texto": "Jesus começou a lhes dizer: “Viestes me prender com espadas e bastões, como [se eu fosse] um bandido?"}, {"numero": 49, "texto": "Todo dia eu estava convosco no templo, ensinando, e não me prendestes; mas [assim se faz] para que as Escrituras se cumpram.”"}, {"numero": 50, "texto": "Então todos o deixaram, e fugiram."}, {"numero": 51, "texto": "E certo rapaz o seguia, envolto num lençol sobre o [corpo] nu. E os rapazes o agarraram."}, {"numero": 52, "texto": "Mas ele largou o lençol, e fugiu deles nu."}, {"numero": 53, "texto": "E levaram Jesus ao sumo sacerdote; e ajuntaram-se a ele todos os chefes dos sacerdotes, os anciãos, e os escribas."}, {"numero": 54, "texto": "E Pedro o seguiu de longe até dentro do pátio do sumo sacerdote, e ficou sentado com os oficiais, esquentando-se ao fogo."}, {"numero": 55, "texto": "E os chefes dos sacerdotes, e todo o supremo conselho buscavam [algum] testemunho contra Jesus, para o matarem, e não [o] achavam."}, {"numero": 56, "texto": "Porque muitos davam falso testemunho contra ele, mas os testemunhos não concordavam entre si."}, {"numero": 57, "texto": "E alguns se levantavam e davam falso testemunho contra ele, dizendo:"}, {"numero": 58, "texto": "“Nós o ouvimos dizer: Eu derrubarei este templo feito por mãos, e em três dias construirei outro feito não por mãos."}, {"numero": 59, "texto": "E nem assim o testemunho deles era concordante."}, {"numero": 60, "texto": "Então o sumo sacerdote levantou-se no meio, e perguntou a Jesus: “Não respondes nada? O que estes testemunham contra ti?”"}, {"numero": 61, "texto": "Mas ele ficou calado, e nada respondeu. O sumo sacerdote voltou a lhe perguntar: “És tu o Cristo, o Filho daquele que é Bendito?”"}, {"numero": 62, "texto": "Jesus respondeu: “Eu sou. E vereis o Filho do homem sentado à direita do Poderoso , e vindo com as nuvens do céu.”"}, {"numero": 63, "texto": "E o sumo sacerdote, rasgando suas roupas, disse: “Para que mais necessitamos de testemunhas?"}, {"numero": 64, "texto": "Vós ouvistes a blasfêmia. Que vos parece?” E todos o condenaram como culpado de morte."}, {"numero": 65, "texto": "E alguns começaram a cuspir nele, e a cobrir o rosto dele; e a dar-lhe de socos, e dizer-lhe: “Profetiza”. E os oficiais lhe davam bofetadas."}, {"numero": 66, "texto": "E, enquanto Pedro estava no pátio abaixo, veio uma das servas do sumo sacerdote."}, {"numero": 67, "texto": "Quando ela viu Pedro, que estava sentado esquentando-se, olhou para ele, e disse: “Também tu estavas com Jesus, o Nazareno.”"}, {"numero": 68, "texto": "Mas ele negou, dizendo: “Não [o] conheço, nem sei o que dizes.”; e saiu para o alpendre. Então o galo cantou."}, {"numero": 69, "texto": "A serva o viu outra vez, e começou a dizer aos que ali estavam: “Este é um deles”."}, {"numero": 70, "texto": "Mas ele o negou de novo. E pouco depois, outra vez os que ali estavam disseram a Pedro: “Verdadeiramente tu és um deles; pois também és galileu”, e a tua fala é semelhante”."}, {"numero": 71, "texto": "Então ele começou a amaldiçoar e a jurar, [dizendo] : “Não conheço esse homem de quem dizeis.”"}, {"numero": 72, "texto": "O galo cantou a segunda vez. E Pedro se lembrou da palavra que Jesus havia lhe dito: “Antes que o galo cante duas vezes, tu me negarás três vezes.” Então ele retirou-se dali e chorou."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 14, 'en', '[{"numero": 1, "texto": "After two days was the feast of the passover, and of unleavened bread: and the chief priests and the scribes sought how they might take him by craft, and put him to death."}, {"numero": 2, "texto": "But they said, Not on the feast day, lest there be an uproar of the people."}, {"numero": 3, "texto": "And being in Bethany in the house of Simon the leper, as he sat at meat, there came a woman having an alabaster box of ointment of spikenard very precious; and she brake the box, and poured it on his head."}, {"numero": 4, "texto": "And there were some that had indignation within themselves, and said, Why was this waste of the ointment made?"}, {"numero": 5, "texto": "For it might have been sold for more than three hundred pence, and have been given to the poor. And they murmured against her."}, {"numero": 6, "texto": "And Jesus said, Let her alone; why trouble ye her? she hath wrought a good work on me."}, {"numero": 7, "texto": "For ye have the poor with you always, and whensoever ye will ye may do them good: but me ye have not always."}, {"numero": 8, "texto": "She hath done what she could: she is come aforehand to anoint my body to the burying."}, {"numero": 9, "texto": "Verily I say unto you, Wheresoever this gospel shall be preached throughout the whole world, this also that she hath done shall be spoken of for a memorial of her."}, {"numero": 10, "texto": "And Judas Iscariot, one of the twelve, went unto the chief priests, to betray him unto them."}, {"numero": 11, "texto": "And when they heard it, they were glad, and promised to give him money. And he sought how he might conveniently betray him."}, {"numero": 12, "texto": "And the first day of unleavened bread, when they killed the passover, his disciples said unto him, Where wilt thou that we go and prepare that thou mayest eat the passover?"}, {"numero": 13, "texto": "And he sendeth forth two of his disciples, and saith unto them, Go ye into the city, and there shall meet you a man bearing a pitcher of water: follow him."}, {"numero": 14, "texto": "And wheresoever he shall go in, say ye to the goodman of the house, The Master saith, Where is the guestchamber, where I shall eat the passover with my disciples?"}, {"numero": 15, "texto": "And he will shew you a large upper room furnished and prepared: there make ready for us."}, {"numero": 16, "texto": "And his disciples went forth, and came into the city, and found as he had said unto them: and they made ready the passover."}, {"numero": 17, "texto": "And in the evening he cometh with the twelve."}, {"numero": 18, "texto": "And as they sat and did eat, Jesus said, Verily I say unto you, One of you which eateth with me shall betray me."}, {"numero": 19, "texto": "And they began to be sorrowful, and to say unto him one by one, Is it I? and another said, Is it I?"}, {"numero": 20, "texto": "And he answered and said unto them, It is one of the twelve, that dippeth with me in the dish."}, {"numero": 21, "texto": "The Son of man indeed goeth, as it is written of him: but woe to that man by whom the Son of man is betrayed! good were it for that man if he had never been born."}, {"numero": 22, "texto": "And as they did eat, Jesus took bread, and blessed, and brake it, and gave to them, and said, Take, eat: this is my body."}, {"numero": 23, "texto": "And he took the cup, and when he had given thanks, he gave it to them: and they all drank of it."}, {"numero": 24, "texto": "And he said unto them, This is my blood of the new testament, which is shed for many."}, {"numero": 25, "texto": "Verily I say unto you, I will drink no more of the fruit of the vine, until that day that I drink it new in the kingdom of God."}, {"numero": 26, "texto": "And when they had sung an hymn, they went out into the mount of Olives."}, {"numero": 27, "texto": "And Jesus saith unto them, All ye shall be offended because of me this night: for it is written, I will smite the shepherd, and the sheep shall be scattered."}, {"numero": 28, "texto": "But after that I am risen, I will go before you into Galilee."}, {"numero": 29, "texto": "But Peter said unto him, Although all shall be offended, yet will not I."}, {"numero": 30, "texto": "And Jesus saith unto him, Verily I say unto thee, That this day, even in this night, before the cock crow twice, thou shalt deny me thrice."}, {"numero": 31, "texto": "But he spake the more vehemently, If I should die with thee, I will not deny thee in any wise. Likewise also said they all."}, {"numero": 32, "texto": "And they came to a place which was named Gethsemane: and he saith to his disciples, Sit ye here, while I shall pray."}, {"numero": 33, "texto": "And he taketh with him Peter and James and John, and began to be sore amazed, and to be very heavy;"}, {"numero": 34, "texto": "And saith unto them, My soul is exceeding sorrowful unto death: tarry ye here, and watch."}, {"numero": 35, "texto": "And he went forward a little, and fell on the ground, and prayed that, if it were possible, the hour might pass from him."}, {"numero": 36, "texto": "And he said, Abba, Father, all things are possible unto thee; take away this cup from me: nevertheless not what I will, but what thou wilt."}, {"numero": 37, "texto": "And he cometh, and findeth them sleeping, and saith unto Peter, Simon, sleepest thou? couldest not thou watch one hour?"}, {"numero": 38, "texto": "Watch ye and pray, lest ye enter into temptation. The spirit truly is ready, but the flesh is weak."}, {"numero": 39, "texto": "And again he went away, and prayed, and spake the same words."}, {"numero": 40, "texto": "And when he returned, he found them asleep again, (for their eyes were heavy,) neither wist they what to answer him."}, {"numero": 41, "texto": "And he cometh the third time, and saith unto them, Sleep on now, and take your rest: it is enough, the hour is come; behold, the Son of man is betrayed into the hands of sinners."}, {"numero": 42, "texto": "Rise up, let us go; lo, he that betrayeth me is at hand."}, {"numero": 43, "texto": "And immediately, while he yet spake, cometh Judas, one of the twelve, and with him a great multitude with swords and staves, from the chief priests and the scribes and the elders."}, {"numero": 44, "texto": "And he that betrayed him had given them a token, saying, Whomsoever I shall kiss, that same is he; take him, and lead him away safely."}, {"numero": 45, "texto": "And as soon as he was come, he goeth straightway to him, and saith, Master, master; and kissed him."}, {"numero": 46, "texto": "And they laid their hands on him, and took him."}, {"numero": 47, "texto": "And one of them that stood by drew a sword, and smote a servant of the high priest, and cut off his ear."}, {"numero": 48, "texto": "And Jesus answered and said unto them, Are ye come out, as against a thief, with swords and with staves to take me?"}, {"numero": 49, "texto": "I was daily with you in the temple teaching, and ye took me not: but the scriptures must be fulfilled."}, {"numero": 50, "texto": "And they all forsook him, and fled."}, {"numero": 51, "texto": "And there followed him a certain young man, having a linen cloth cast about his naked body; and the young men laid hold on him:"}, {"numero": 52, "texto": "And he left the linen cloth, and fled from them naked."}, {"numero": 53, "texto": "And they led Jesus away to the high priest: and with him were assembled all the chief priests and the elders and the scribes."}, {"numero": 54, "texto": "And Peter followed him afar off, even into the palace of the high priest: and he sat with the servants, and warmed himself at the fire."}, {"numero": 55, "texto": "And the chief priests and all the council sought for witness against Jesus to put him to death; and found none."}, {"numero": 56, "texto": "For many bare false witness against him, but their witness agreed not together."}, {"numero": 57, "texto": "And there arose certain, and bare false witness against him, saying,"}, {"numero": 58, "texto": "We heard him say, I will destroy this temple that is made with hands, and within three days I will build another made without hands."}, {"numero": 59, "texto": "But neither so did their witness agree together."}, {"numero": 60, "texto": "And the high priest stood up in the midst, and asked Jesus, saying, Answerest thou nothing? what is it which these witness against thee?"}, {"numero": 61, "texto": "But he held his peace, and answered nothing. Again the high priest asked him, and said unto him, Art thou the Christ, the Son of the Blessed?"}, {"numero": 62, "texto": "And Jesus said, I am: and ye shall see the Son of man sitting on the right hand of power, and coming in the clouds of heaven."}, {"numero": 63, "texto": "Then the high priest rent his clothes, and saith, What need we any further witnesses?"}, {"numero": 64, "texto": "Ye have heard the blasphemy: what think ye? And they all condemned him to be guilty of death."}, {"numero": 65, "texto": "And some began to spit on him, and to cover his face, and to buffet him, and to say unto him, Prophesy: and the servants did strike him with the palms of their hands."}, {"numero": 66, "texto": "And as Peter was beneath in the palace, there cometh one of the maids of the high priest:"}, {"numero": 67, "texto": "And when she saw Peter warming himself, she looked upon him, and said, And thou also wast with Jesus of Nazareth."}, {"numero": 68, "texto": "But he denied, saying, I know not, neither understand I what thou sayest. And he went out into the porch; and the cock crew."}, {"numero": 69, "texto": "And a maid saw him again, and began to say to them that stood by, This is one of them."}, {"numero": 70, "texto": "And he denied it again. And a little after, they that stood by said again to Peter, Surely thou art one of them: for thou art a Galilaean, and thy speech agreeth thereto."}, {"numero": 71, "texto": "But he began to curse and to swear, saying, I know not this man of whom ye speak."}, {"numero": 72, "texto": "And the second time the cock crew. And Peter called to mind the word that Jesus said unto him, Before the cock crow twice, thou shalt deny me thrice. And when he thought thereon, he wept."}]'::jsonb, 'King James Version'),
  ('Mc', 14, 'fr', '[{"numero": 1, "texto": "La fête de Pâque et des pains sans levain devait avoir lieu deux jours après. Les principaux sacrificateurs et les scribes cherchaient les moyens d''''arrêter Jésus par ruse, et de le faire mourir."}, {"numero": 2, "texto": "Car ils disaient: Que ce ne soit pas pendant la fête, afin qu''''il n''''y ait pas de tumulte parmi le peuple."}, {"numero": 3, "texto": "Comme Jésus était à Béthanie, dans la maison de Simon le lépreux, une femme entra, pendant qu''''il se trouvait à table. Elle tenait un vase d''''albâtre, qui renfermait un parfum de nard pur de grand prix; et, ayant rompu le vase, elle répandit le parfum sur la tête de Jésus."}, {"numero": 4, "texto": "Quelques-uns exprimèrent entre eux leur indignation: A quoi bon perdre ce parfum?"}, {"numero": 5, "texto": "On aurait pu le vendre plus de trois cents deniers, et les donner aux pauvres. Et ils s''''irritaient contre cette femme."}, {"numero": 6, "texto": "Mais Jésus dit: Laissez-la. Pourquoi lui faites-vous de la peine? Elle a fait une bonne action à mon égard;"}, {"numero": 7, "texto": "car vous avez toujours les pauvres avec vous, et vous pouvez leur faire du bien quand vous voulez, mais vous ne m''''avez pas toujours."}, {"numero": 8, "texto": "Elle a fait ce qu''''elle a pu; elle a d''''avance embaumé mon corps pour la sépulture."}, {"numero": 9, "texto": "Je vous le dis en vérité, partout où la bonne nouvelle sera prêchée, dans le monde entier, on racontera aussi en mémoire de cette femme ce qu''''elle a fait."}, {"numero": 10, "texto": "Judas Iscariot, l''''un des douze, alla vers les principaux sacrificateurs, afin de leur livrer Jésus."}, {"numero": 11, "texto": "Après l''''avoir entendu, ils furent dans la joie, et promirent de lui donner de l''''argent. Et Judas cherchait une occasion favorable pour le livrer."}, {"numero": 12, "texto": "Le premier jour des pains sans levain, où l''''on immolait la Pâque, les disciples de Jésus lui dirent: Où veux-tu que nous allions te préparer la Pâque?"}, {"numero": 13, "texto": "Et il envoya deux de ses disciples, et leur dit: Allez à la ville; vous rencontrerez un homme portant une cruche d''''eau, suivez-le."}, {"numero": 14, "texto": "Quelque part qu''''il entre, dites au maître de la maison: Le maître dit: Où est le lieu où je mangerai la Pâque avec mes disciples?"}, {"numero": 15, "texto": "Et il vous montrera une grande chambre haute, meublée et toute prête: c''''est là que vous nous préparerez la Pâque."}, {"numero": 16, "texto": "Les disciples partirent, arrivèrent à la ville, et trouvèrent les choses comme il le leur avait dit; et ils préparèrent la Pâque."}, {"numero": 17, "texto": "Le soir étant venu, il arriva avec les douze."}, {"numero": 18, "texto": "Pendant qu''''ils étaient à table et qu''''ils mangeaient, Jésus dit: Je vous le dis en vérité, l''''un de vous, qui mange avec moi, me livrera."}, {"numero": 19, "texto": "Ils commencèrent à s''''attrister, et à lui dire, l''''un après l''''autre: Est-ce moi?"}, {"numero": 20, "texto": "Il leur répondit: C''''est l''''un des douze, qui met avec moi la main dans le plat."}, {"numero": 21, "texto": "Le Fils de l''''homme s''''en va selon ce qui est écrit de lui. Mais malheur à l''''homme par qui le Fils de l''''homme est livré! Mieux vaudrait pour cet homme qu''''il ne fût pas né."}, {"numero": 22, "texto": "Pendant qu''''ils mangeaient, Jésus prit du pain; et, après avoir rendu grâces, il le rompit, et le leur donna, en disant: Prenez, ceci est mon corps."}, {"numero": 23, "texto": "Il prit ensuite une coupe; et, après avoir rendu grâces, il la leur donna, et ils en burent tous."}, {"numero": 24, "texto": "Et il leur dit: Ceci est mon sang, le sang de l''''alliance, qui est répandu pour plusieurs."}, {"numero": 25, "texto": "Je vous le dis en vérité, je ne boirai plus jamais du fruit de la vigne, jusqu''''au jour où je le boirai nouveau dans le royaume de Dieu."}, {"numero": 26, "texto": "Après avoir chanté les cantiques, ils se rendirent à la montagne des oliviers."}, {"numero": 27, "texto": "Jésus leur dit: Vous serez tous scandalisés; car il est écrit: Je frapperai le berger, et les brebis seront dispersées."}, {"numero": 28, "texto": "Mais, après que je serai ressuscité, je vous précéderai en Galilée."}, {"numero": 29, "texto": "Pierre lui dit: Quand tous seraient scandalisés, je ne serai pas scandalisé."}, {"numero": 30, "texto": "Et Jésus lui dit: Je te le dis en vérité, toi, aujourd''''hui, cette nuit même, avant que le coq chante deux fois, tu me renieras trois fois."}, {"numero": 31, "texto": "Mais Pierre reprit plus fortement: Quand il me faudrait mourir avec toi, je ne te renierai pas. Et tous dirent la même chose."}, {"numero": 32, "texto": "Ils allèrent ensuite dans un lieu appelé Gethsémané, et Jésus dit à ses disciples: Asseyez-vous ici, pendant que je prierai."}, {"numero": 33, "texto": "Il prit avec lui Pierre, Jacques et Jean, et il commença à éprouver de la frayeur et des angoisses."}, {"numero": 34, "texto": "Il leur dit: Mon âme est triste jusqu''''à la mort; restez ici, et veillez."}, {"numero": 35, "texto": "Puis, ayant fait quelques pas en avant, il se jeta contre terre, et pria que, s''''il était possible, cette heure s''''éloignât de lui."}, {"numero": 36, "texto": "Il disait: Abba, Père, toutes choses te sont possibles, éloigne de moi cette coupe! Toutefois, non pas ce que je veux, mais ce que tu veux."}, {"numero": 37, "texto": "Et il vint vers les disciples, qu''''il trouva endormis, et il dit à Pierre: Simon, tu dors! Tu n''''as pu veiller une heure!"}, {"numero": 38, "texto": "Veillez et priez, afin que vous ne tombiez pas en tentation; l''''esprit est bien disposé, mais la chair est faible."}, {"numero": 39, "texto": "Il s''''éloigna de nouveau, et fit la même prière."}, {"numero": 40, "texto": "Il revint, et les trouva encore endormis; car leurs yeux étaient appesantis. Ils ne surent que lui répondre."}, {"numero": 41, "texto": "Il revint pour la troisième fois, et leur dit: Dormez maintenant, et reposez-vous! C''''est assez! L''''heure est venue; voici, le Fils de l''''homme est livré aux mains des pécheurs."}, {"numero": 42, "texto": "Levez-vous, allons; voici, celui qui me livre s''''approche."}, {"numero": 43, "texto": "Et aussitôt, comme il parlait encore, arriva Judas l''''un des douze, et avec lui une foule armée d''''épées et de bâtons, envoyée par les principaux sacrificateurs, par les scribes et par les anciens."}, {"numero": 44, "texto": "Celui qui le livrait leur avait donné ce signe: Celui que je baiserai, c''''est lui; saisissez-le, et emmenez-le sûrement."}, {"numero": 45, "texto": "Dès qu''''il fut arrivé, il s''''approcha de Jésus, disant: Rabbi! Et il le baisa."}, {"numero": 46, "texto": "Alors ces gens mirent la main sur Jésus, et le saisirent."}, {"numero": 47, "texto": "Un de ceux qui étaient là, tirant l''''épée, frappa le serviteur du souverain sacrificateur, et lui emporta l''''oreille."}, {"numero": 48, "texto": "Jésus, prenant la parole, leur dit: Vous êtes venus, comme après un brigand, avec des épées et des bâtons, pour vous emparer de moi."}, {"numero": 49, "texto": "J''''étais tous les jours parmi vous, enseignant dans le temple, et vous ne m''''avez pas saisi. Mais c''''est afin que les Ecritures soient accomplies."}, {"numero": 50, "texto": "Alors tous l''''abandonnèrent, et prirent la fuite."}, {"numero": 51, "texto": "Un jeune homme le suivait, n''''ayant sur le corps qu''''un drap. On se saisit de lui;"}, {"numero": 52, "texto": "mais il lâcha son vêtement, et se sauva tout nu."}, {"numero": 53, "texto": "Ils emmenèrent Jésus chez le souverain sacrificateur, où s''''assemblèrent tous les principaux sacrificateurs, les anciens et les scribes."}, {"numero": 54, "texto": "Pierre le suivit de loin jusque dans l''''intérieur de la cour du souverain sacrificateur; il s''''assit avec les serviteurs, et il se chauffait près du feu."}, {"numero": 55, "texto": "Les principaux sacrificateurs et tout le sanhédrin cherchaient un témoignage contre Jésus, pour le faire mourir, et ils n''''en trouvaient point;"}, {"numero": 56, "texto": "car plusieurs rendaient de faux témoignages contre lui, mais les témoignages ne s''''accordaient pas."}, {"numero": 57, "texto": "Quelques-uns se levèrent, et portèrent un faux témoignage contre lui, disant:"}, {"numero": 58, "texto": "Nous l''''avons entendu dire: Je détruirai ce temple fait de main d''''homme, et en trois jours j''''en bâtirai un autre qui ne sera pas fait de main d''''homme."}, {"numero": 59, "texto": "Même sur ce point-là leur témoignage ne s''''accordait pas."}, {"numero": 60, "texto": "Alors le souverain sacrificateur, se levant au milieu de l''''assemblée, interrogea Jésus, et dit: Ne réponds-tu rien? Qu''''est-ce que ces gens déposent contre toi?"}, {"numero": 61, "texto": "Jésus garda le silence, et ne répondit rien. Le souverain sacrificateur l''''interrogea de nouveau, et lui dit: Es-tu le Christ, le Fils du Dieu béni?"}, {"numero": 62, "texto": "Jésus répondit: Je le suis. Et vous verrez le Fils de l''''homme assis à la droite de la puissance de Dieu, et venant sur les nuées du ciel."}, {"numero": 63, "texto": "Alors le souverain sacrificateur déchira ses vêtements, et dit: Qu''''avons-nous encore besoin de témoins?"}, {"numero": 64, "texto": "Vous avez entendu le blasphème. Que vous en semble? Tous le condamnèrent comme méritant la mort."}, {"numero": 65, "texto": "Et quelques-uns se mirent à cracher sur lui, à lui voiler le visage et à le frapper à coups de poing, en lui disant: Devine! Et les serviteurs le reçurent en lui donnant des soufflets."}, {"numero": 66, "texto": "Pendant que Pierre était en bas dans la cour, il vint une des servantes du souverain sacrificateur."}, {"numero": 67, "texto": "Voyant Pierre qui se chauffait, elle le regarda, et lui dit: Toi aussi, tu étais avec Jésus de Nazareth."}, {"numero": 68, "texto": "Il le nia, disant: Je ne sais pas, je ne comprends pas ce que tu veux dire. Puis il sortit pour aller dans le vestibule. Et le coq chanta."}, {"numero": 69, "texto": "La servante, l''''ayant vu, se mit de nouveau à dire à ceux qui étaient présents: Celui-ci est de ces gens-là."}, {"numero": 70, "texto": "Et il le nia de nouveau. Peu après, ceux qui étaient présents dirent encore à Pierre: Certainement tu es de ces gens-là, car tu es Galiléen."}, {"numero": 71, "texto": "Alors il commença à faire des imprécations et à jurer: Je ne connais pas cet homme dont vous parlez."}, {"numero": 72, "texto": "Aussitôt, pour la seconde fois, le coq chanta. Et Pierre se souvint de la parole que Jésus lui avait dite: Avant que le coq chante deux fois, tu me renieras trois fois. Et en y réfléchissant, il pleurait."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 14, 'es', '[{"numero": 1, "texto": "Y DOS días después era la Pascua y los días de los panes sin levadura: y procuraban los príncipes de los sacerdotes y los escribas cómo le prenderían por engaño, y le matarían."}, {"numero": 2, "texto": "Y decían: No en el día de la fiesta, porque no se haga alboroto del pueblo."}, {"numero": 3, "texto": "Y estando él en Bethania en casa de Simón el leproso, y sentado á la mesa, vino una mujer teniendo un alabastro de ungüento de nardo espique de mucho precio; y quebrando el alabastro, derramóselo sobre su cabeza."}, {"numero": 4, "texto": "Y hubo algunos que se enojaron dentro de sí, y dijeron: ¿Para qué se ha hecho este desperdicio de ungüento?"}, {"numero": 5, "texto": "Porque podía esto ser vendido por más de trescientos denarios, y darse á los pobres. Y murmuraban contra ella."}, {"numero": 6, "texto": "Mas Jesús dijo: Dejadla; ¿por qué la fatigáis? buena obra me ha hecho;"}, {"numero": 7, "texto": "Que siempre tendréis los pobres con vosotros, y cuando quisiereis les podréis hacer bien; mas á mí no siempre me tendréis."}, {"numero": 8, "texto": "Esta ha hecho lo que podía; porque se ha anticipado á ungir mi cuerpo para la sepultura."}, {"numero": 9, "texto": "De cierto os digo que donde quiera que fuere predicado este evangelio en todo el mundo, también esto que ha hecho ésta, será dicho para memoria de ella."}, {"numero": 10, "texto": "Entonces Judas Iscariote, uno de los doce, vino á los príncipes de los sacerdotes, para entregársele."}, {"numero": 11, "texto": "Y ellos oyéndolo se holgaron, y prometieron que le darían dineros. Y buscaba oportunidad cómo le entregaría."}, {"numero": 12, "texto": "Y el primer día de los panes sin levadura, cuando sacrificaban la pascua, sus discípulos le dicen: ¿Dónde quieres que vayamos á disponer para que comas la pascua?"}, {"numero": 13, "texto": "Y envía dos de sus discípulos, y les dice: Id á la ciudad, y os encontrará un hombre que lleva un cántaro de agua; seguidle;"}, {"numero": 14, "texto": "Y donde entrare, decid al señor de la casa: El Maestro dice: ¿Dónde está el aposento donde he de comer la pascua con mis discípulos?"}, {"numero": 15, "texto": "Y él os mostrará un gran cenáculo ya preparado: aderezad para nosotros allí."}, {"numero": 16, "texto": "Y fueron sus discípulos, y vinieron á la ciudad, y hallaron como les había dicho; y aderezaron la pascua."}, {"numero": 17, "texto": "Y llegada la tarde, fué con los doce."}, {"numero": 18, "texto": "Y como se sentaron á la mesa y comiesen, dice Jesús: De cierto os digo que uno de vosotros, que come conmigo, me ha de entregar."}, {"numero": 19, "texto": "Entonces ellos comenzaron á entristecerse, y á decirle cada uno por sí: ¿Seré yo? Y el otro: ¿Seré yo?"}, {"numero": 20, "texto": "Y él respondiendo les dijo: Es uno de los doce que moja conmigo en el plato."}, {"numero": 21, "texto": "A la verdad el Hijo del hombre va, como está de él escrito; mas ¡ay de aquel hombre por quien el Hijo del hombre es entregado! bueno le fuera á aquel hombre si nunca hubiera nacido."}, {"numero": 22, "texto": "Y estando ellos comiendo, tomó Jesús pan, y bendiciendo, partió y les dió, y dijo: Tomad, esto es mi cuerpo."}, {"numero": 23, "texto": "Y tomando el vaso, habiendo hecho gracias, les dió: y bebieron de él todos."}, {"numero": 24, "texto": "Y les dice: Esto es mi sangre del nuevo pacto, que por muchos es derramada."}, {"numero": 25, "texto": "De cierto os digo que no beberé más del fruto de la vid, hasta aquel día cuando lo beberé nuevo en el reino de Dios."}, {"numero": 26, "texto": "Y como hubieron cantado el himno, se salieron al monte de las Olivas."}, {"numero": 27, "texto": "Jesús entonces les dice: Todos seréis escandalizados en mí esta noche; porque escrito está: Heriré al pastor, y serán derramadas las ovejas."}, {"numero": 28, "texto": "Mas después que haya resucitado, iré delante de vosotros á Galilea."}, {"numero": 29, "texto": "Entonces Pedro le dijo: Aunque todos sean escandalizados, mas no yo."}, {"numero": 30, "texto": "Y le dice Jesús: De cierto te digo que tú, hoy, en esta noche, antes que el gallo haya cantado dos veces, me negarás tres veces."}, {"numero": 31, "texto": "Mas él con mayor porfía decía: Si me fuere menester morir contigo, no te negaré. También todos decían lo mismo."}, {"numero": 32, "texto": "Y vienen al lugar que se llama Gethsemaní, y dice á sus discípulos: Sentaos aquí, entre tanto que yo oro."}, {"numero": 33, "texto": "Y toma consigo á Pedro y á Jacobo y á Juan, y comenzó á atemorizarse, y á angustiarse."}, {"numero": 34, "texto": "Y les dice: Está muy triste mi alma, hasta la muerte: esperad aquí y velad."}, {"numero": 35, "texto": "Y yéndose un poco adelante, se postró en tierra, y oró que si fuese posible, pasase de él aquella hora."}, {"numero": 36, "texto": "Y decía: Abba, Padre, todas las cosas son á ti posibles; traspasa de mí este vaso; empero no lo que yo quiero, sino lo que tú."}, {"numero": 37, "texto": "Y vino y los halló durmiendo; y dice á Pedro: ¿Simón, duermes? ¿No has podido velar una hora?"}, {"numero": 38, "texto": "Velad y orad, para que no entréis en tentación: el espíritu á la verdad es presto, mas la carne enferma."}, {"numero": 39, "texto": "Y volviéndose á ir, oró, y dijo las mismas palabras."}, {"numero": 40, "texto": "Y vuelto, los halló otra vez durmiendo, porque los ojos de ellos estaban cargados; y no sabían qué responderle."}, {"numero": 41, "texto": "Y vino la tercera vez, y les dice: Dormid ya y descansad: basta, la hora es venida; he aquí, el Hijo del hombre es entregado en manos de los pecadores."}, {"numero": 42, "texto": "Levantaos, vamos: he aquí, el que me entrega está cerca."}, {"numero": 43, "texto": "Y luego, aun hablando él, vino Judas, que era uno de los doce, y con él una compañía con espadas y palos, de parte de los príncipes de los sacerdotes, y de los escribas y de los ancianos."}, {"numero": 44, "texto": "Y el que le entregaba les había dado señal común, diciendo: Al que yo besare, aquél es: prendedle, y llevadle con seguridad."}, {"numero": 45, "texto": "Y como vino, se acercó luego á él, y le dice: Maestro, Maestro. Y le besó."}, {"numero": 46, "texto": "Entonces ellos echaron en él sus manos, y le prendieron."}, {"numero": 47, "texto": "Y uno de los que estaban allí, sacando la espada, hirió al siervo del sumo sacerdote, y le cortó la oreja."}, {"numero": 48, "texto": "Y respondiendo Jesús, les dijo: ¿Como á ladrón habéis salido con espadas y con palos á tomarme?"}, {"numero": 49, "texto": "Cada día estaba con vosotros enseñando en el templo, y no me tomasteis; pero es así, para que se cumplan las Escrituras."}, {"numero": 50, "texto": "Entonces dejándole todos sus discípulos, huyeron."}, {"numero": 51, "texto": "Empero un mancebillo le seguía cubierto de una sábana sobre el cuerpo desnudo; y los mancebos le prendieron:"}, {"numero": 52, "texto": "Mas él, dejando la sábana, se huyó de ellos desnudo."}, {"numero": 53, "texto": "Y trajeron á Jesús al sumo sacerdote; y se juntaron á él todos los príncipes de los sacerdotes y los ancianos y los escribas."}, {"numero": 54, "texto": "Empero Pedro le siguió de lejos hasta dentro del patio del sumo sacerdote; y estaba sentado con los servidores, y calentándose al fuego."}, {"numero": 55, "texto": "Y los príncipes de los sacerdotes y todo el concilio buscaban testimonio contra Jesús, para entregarle á la muerte; mas no lo hallaban."}, {"numero": 56, "texto": "Porque muchos decían falso testimonio contra él; mas sus testimonios no concertaban."}, {"numero": 57, "texto": "Entonces levantándose unos, dieron falso testimonio contra él, diciendo:"}, {"numero": 58, "texto": "Nosotros le hemos oído decir: Yo derribaré este templo que es hecho de mano, y en tres días edificaré otro echo sin mano."}, {"numero": 59, "texto": "Mas ni aun así se concertaba el testimonio de ellos."}, {"numero": 60, "texto": "Entonces el sumo sacerdote, levantándose en medio, preguntó á Jesús, diciendo: ¿No respondes algo? ¿Qué atestiguan éstos contra ti?"}, {"numero": 61, "texto": "Mas él callaba, y nada respondía. El sumo sacerdote le volvió á preguntar, y le dice: ¿Eres tú el Cristo, el Hijo del Bendito?"}, {"numero": 62, "texto": "Y Jesús le dijo: Yo soy; y veréis al Hijo del hombre sentado á la diestra de la potencia de Dios, y viniendo en las nubes del cielo."}, {"numero": 63, "texto": "Entonces el sumo sacerdote, rasgando sus vestidos, dijo: ¿Qué más tenemos necesidad de testigos?"}, {"numero": 64, "texto": "Oído habéis la blasfemia: ¿qué os parece? Y ellos todos le condenaron ser culpado de muerte."}, {"numero": 65, "texto": "Y algunos comenzaron á escupir en él, y cubrir su rostro, y á darle bofetadas, y decirle: Profetiza. Y los servidores le herían de bofetadas."}, {"numero": 66, "texto": "Y estando Pedro abajo en el atrio, vino una de las criadas del sumo sacerdote;"}, {"numero": 67, "texto": "Y como vió á Pedro que se calentaba, mirándole, dice: Y tú con Jesús el Nazareno estabas."}, {"numero": 68, "texto": "Mas él negó, diciendo: No conozco, ni sé lo que dices. Y se salió fuera á la entrada; y cantó el gallo."}, {"numero": 69, "texto": "Y la criada viéndole otra vez, comenzó á decir á los que estaban allí: Este es de ellos."}, {"numero": 70, "texto": "Mas él negó otra vez. Y poco después, los que estaban allí dijeron otra vez á Pedro: Verdaderamente tú eres de ellos; porque eres Galileo, y tu habla es semejante."}, {"numero": 71, "texto": "Y él comenzó á maldecir y á jurar: No conozco á este hombre de quien habláis."}, {"numero": 72, "texto": "Y el gallo cantó la segunda vez: y Pedro se acordó de las palabras que Jesús le había dicho: Antes que el gallo cante dos veces, me negarás tres veces. Y pensando en esto, lloraba."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 15, 'pt', '[{"numero": 1, "texto": "E logo ao amanhecer, os chefes dos sacerdotes tiveram uma reunião com os anciãos, com os escribas, e com todo o supremo conselho; e, amarrando Jesus, levaram [-no] e [o] entregaram a Pilatos."}, {"numero": 2, "texto": "E Pilatos lhe perguntou: És tu o Rei dos Judeus? E ele lhe respondeu: Tu o dizes."}, {"numero": 3, "texto": "E os chefes dos sacerdotes o acusavam de muitas coisas, porém ele nada respondia."}, {"numero": 4, "texto": "E outra vez Pilatos lhe perguntou: Não respondes nada? Olha quantas [coisas] testemunham contra ti!"}, {"numero": 5, "texto": "Mas Jesus nada mais respondeu, de maneira que Pilatos ficou surpreso."}, {"numero": 6, "texto": "Na festa, [Pilatos] lhes soltava um preso, qualquer um que pedissem."}, {"numero": 7, "texto": "E havia um chamado Barrabás, preso com [outros] revoltosos, que numa rebelião havia cometido uma morte."}, {"numero": 8, "texto": "E a multidão, gritando, começou a pedir, como sempre lhes havia feito."}, {"numero": 9, "texto": "E Pilatos lhes respondeu: Quereis que eu vos solte o Rei dos Judeus?"}, {"numero": 10, "texto": "(Porque ele sabia que os chefes dos sacerdotes haviam o entregue por inveja)."}, {"numero": 11, "texto": "Mas os chefes dos sacerdotes incitaram a multidão, para que, em vez disso, lhes soltasse Barrabás."}, {"numero": 12, "texto": "E Pilatos, respondendo, disse-lhes outra vez: Que, pois, quereis que eu faça com aquele a quem chamais Rei dos Judeus?"}, {"numero": 13, "texto": "E eles voltaram a clamar: Crucifica-o!"}, {"numero": 14, "texto": "Mas Pilatos lhes disse: Por quê? Que mal ele fez? E eles gritavam ainda mais: Crucifica-o!"}, {"numero": 15, "texto": "Então Pilatos, querendo satisfazer à multidão, soltou-lhes Barrabás; e entregou Jesus açoitado, para que fosse crucificado."}, {"numero": 16, "texto": "E os soldados o levaram para o pátio, que é o pretório; e convocaram toda a tropa."}, {"numero": 17, "texto": "E o vestiram de púrpura; teceram uma coroa de espinhos, e puseram nele."}, {"numero": 18, "texto": "E começaram a saudá-lo: Viva! Ó Rei dos Judeus!"}, {"numero": 19, "texto": "E feriram a sua cabeça com uma cana, cuspiram nele, e, ajoelhados, o adoraram."}, {"numero": 20, "texto": "Quando o escarneceram, despiram-lhe a púrpura, vestiram-no com as suas próprias roupas, e o levaram afora, para o crucificarem."}, {"numero": 21, "texto": "E forçaram um Simão cireneu, que estava passando, vindo do campo, o pai de Alexandre e de Rufo, para que levasse sua cruz."}, {"numero": 22, "texto": "E o levaram ao lugar de Gólgota, que traduzido é: o lugar da caveira."}, {"numero": 23, "texto": "E ofereceram-lhe a beber vinho misturado com mirra; mas ele não o tomou."}, {"numero": 24, "texto": "E havendo o crucificado, repartiram a roupas dele, lançando-lhes sortes, para o que cada um levaria."}, {"numero": 25, "texto": "Era a hora terceira, e o crucificaram."}, {"numero": 26, "texto": "E a descrição de sua acusação estava acima escrita: O REI DOS JUDEUS."}, {"numero": 27, "texto": "E crucificaram com ele dois ladrões, um à sua direita, e outro à esquerda."}, {"numero": 28, "texto": "E cumpriu-se a Escritura que diz: E foi contado com os malfeitores."}, {"numero": 29, "texto": "E os que passavam blasfemavam dele, balançando suas cabeças, e dizendo: Ah! tu que derrubas o templo, e em três dias o edificas,"}, {"numero": 30, "texto": "salva a ti mesmo, e desce da cruz!"}, {"numero": 31, "texto": "E da mesma maneira também os chefes dos sacerdotes, com os escribas, diziam aos outros, escarnecendo: Ele salvou a outros, a si mesmo não pode salvar!"}, {"numero": 32, "texto": "Que o Cristo, o Rei de Israel, desça agora da cruz, para que o vejamos, e creiamos! Os que estavam crucificados com ele também o insultavam."}, {"numero": 33, "texto": "E vinda a hora sexta, vieram trevas sobre toda a terra, até a hora nona."}, {"numero": 34, "texto": "E na hora nona, Jesus exclamou em alta voz: ELOÍ, ELOÍ, LAMÁ SABACTÂNI, que traduzido é: Deus meu, Deus meu, por que me desamparaste?"}, {"numero": 35, "texto": "E alguns dos que ali estavam, quando ouviram, disseram: Eis que ele está chamando Elias."}, {"numero": 36, "texto": "E um correu, encheu de vinagre uma esponja; e pondo-a em uma cana, dava-lhe de beber, dizendo: Deixai, vejamos se Elias virá tirá-lo."}, {"numero": 37, "texto": "E Jesus bradou em grande voz, então expirou."}, {"numero": 38, "texto": "E o véu do Templo se rasgou em dois do alto abaixo."}, {"numero": 39, "texto": "E o centurião que estava ali diante dele, vendo que havia expirado bradando assim, disse: Verdadeiramente este homem era Filho de Deus."}, {"numero": 40, "texto": "E também estavam ali [algumas] mulheres olhando de longe, entre as quais estava também Maria Madalena, e Maria (mãe de Tiago o menor e de José), e Salomé;"}, {"numero": 41, "texto": "as quais também, quando ele estava na Galileia, o seguiam, e o serviam; e outras muitas, que haviam subido com ele a Jerusalém."}, {"numero": 42, "texto": "E quando já vinha o final da tarde, porque era a preparação, que é o dia antes de sábado,"}, {"numero": 43, "texto": "Veio José de Arimateia, honrado membro do conselho, que também esperava o Reino de Deus, e com ousadia foi a Pilatos, e pediu o corpo de Jesus."}, {"numero": 44, "texto": "Pilatos se surpreendeu de que já fosse morto. E chamou a si o centurião, e perguntou-lhe se já era morto já havia muito tempo."}, {"numero": 45, "texto": "Quando ele recebeu a explicação do centurião, deu o corpo a José,"}, {"numero": 46, "texto": "o qual comprou um lençol fino, e tirando-o [da cruz] , envolveu-o no lençol fino. Em seguida, ele o pôs num sepulcro escavado em uma rocha, e rolouuma pedra à porta do sepulcro."}, {"numero": 47, "texto": "Maria Madalena e Maria [mãe] de José olharam onde o puseram."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 15, 'en', '[{"numero": 1, "texto": "And straightway in the morning the chief priests held a consultation with the elders and scribes and the whole council, and bound Jesus, and carried him away, and delivered him to Pilate."}, {"numero": 2, "texto": "And Pilate asked him, Art thou the King of the Jews? And he answering said unto them, Thou sayest it."}, {"numero": 3, "texto": "And the chief priests accused him of many things: but he answered nothing."}, {"numero": 4, "texto": "And Pilate asked him again, saying, Answerest thou nothing? behold how many things they witness against thee."}, {"numero": 5, "texto": "But Jesus yet answered nothing; so that Pilate marvelled."}, {"numero": 6, "texto": "Now at that feast he released unto them one prisoner, whomsoever they desired."}, {"numero": 7, "texto": "And there was one named Barabbas, which lay bound with them that had made insurrection with him, who had committed murder in the insurrection."}, {"numero": 8, "texto": "And the multitude crying aloud began to desire him to do as he had ever done unto them."}, {"numero": 9, "texto": "But Pilate answered them, saying, Will ye that I release unto you the King of the Jews?"}, {"numero": 10, "texto": "For he knew that the chief priests had delivered him for envy."}, {"numero": 11, "texto": "But the chief priests moved the people, that he should rather release Barabbas unto them."}, {"numero": 12, "texto": "And Pilate answered and said again unto them, What will ye then that I shall do unto him whom ye call the King of the Jews?"}, {"numero": 13, "texto": "And they cried out again, Crucify him."}, {"numero": 14, "texto": "Then Pilate said unto them, Why, what evil hath he done? And they cried out the more exceedingly, Crucify him."}, {"numero": 15, "texto": "And so Pilate, willing to content the people, released Barabbas unto them, and delivered Jesus, when he had scourged him, to be crucified."}, {"numero": 16, "texto": "And the soldiers led him away into the hall, called Praetorium; and they call together the whole band."}, {"numero": 17, "texto": "And they clothed him with purple, and platted a crown of thorns, and put it about his head,"}, {"numero": 18, "texto": "And began to salute him, Hail, King of the Jews!"}, {"numero": 19, "texto": "And they smote him on the head with a reed, and did spit upon him, and bowing their knees worshipped him."}, {"numero": 20, "texto": "And when they had mocked him, they took off the purple from him, and put his own clothes on him, and led him out to crucify him."}, {"numero": 21, "texto": "And they compel one Simon a Cyrenian, who passed by, coming out of the country, the father of Alexander and Rufus, to bear his cross."}, {"numero": 22, "texto": "And they bring him unto the place Golgotha, which is, being interpreted, The place of a skull."}, {"numero": 23, "texto": "And they gave him to drink wine mingled with myrrh: but he received it not."}, {"numero": 24, "texto": "And when they had crucified him, they parted his garments, casting lots upon them, what every man should take."}, {"numero": 25, "texto": "And it was the third hour, and they crucified him."}, {"numero": 26, "texto": "And the superscription of his accusation was written over, The King Of The Jews."}, {"numero": 27, "texto": "And with him they crucify two thieves; the one on his right hand, and the other on his left."}, {"numero": 28, "texto": "And the scripture was fulfilled, which saith, And he was numbered with the transgressors."}, {"numero": 29, "texto": "And they that passed by railed on him, wagging their heads, and saying, Ah, thou that destroyest the temple, and buildest it in three days,"}, {"numero": 30, "texto": "Save thyself, and come down from the cross."}, {"numero": 31, "texto": "Likewise also the chief priests mocking said among themselves with the scribes, He saved others; himself he cannot save."}, {"numero": 32, "texto": "Let Christ the King of Israel descend now from the cross, that we may see and believe. And they that were crucified with him reviled him."}, {"numero": 33, "texto": "And when the sixth hour was come, there was darkness over the whole land until the ninth hour."}, {"numero": 34, "texto": "And at the ninth hour Jesus cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My God, my God, why hast thou forsaken me?"}, {"numero": 35, "texto": "And some of them that stood by, when they heard it, said, Behold, he calleth Elias."}, {"numero": 36, "texto": "And one ran and filled a spunge full of vinegar, and put it on a reed, and gave him to drink, saying, Let alone; let us see whether Elias will come to take him down."}, {"numero": 37, "texto": "And Jesus cried with a loud voice, and gave up the ghost."}, {"numero": 38, "texto": "And the veil of the temple was rent in twain from the top to the bottom."}, {"numero": 39, "texto": "And when the centurion, which stood over against him, saw that he so cried out, and gave up the ghost, he said, Truly this man was the Son of God."}, {"numero": 40, "texto": "There were also women looking on afar off: among whom was Mary Magdalene, and Mary the mother of James the less and of Joses, and Salome;"}, {"numero": 41, "texto": "(Who also, when he was in Galilee, followed him, and ministered unto him;) and many other women which came up with him unto Jerusalem."}, {"numero": 42, "texto": "And now when the even was come, because it was the preparation, that is, the day before the sabbath,"}, {"numero": 43, "texto": "Joseph of Arimathaea, an honourable counsellor, which also waited for the kingdom of God, came, and went in boldly unto Pilate, and craved the body of Jesus."}, {"numero": 44, "texto": "And Pilate marvelled if he were already dead: and calling unto him the centurion, he asked him whether he had been any while dead."}, {"numero": 45, "texto": "And when he knew it of the centurion, he gave the body to Joseph."}, {"numero": 46, "texto": "And he bought fine linen, and took him down, and wrapped him in the linen, and laid him in a sepulchre which was hewn out of a rock, and rolled a stone unto the door of the sepulchre."}, {"numero": 47, "texto": "And Mary Magdalene and Mary the mother of Joses beheld where he was laid."}]'::jsonb, 'King James Version'),
  ('Mc', 15, 'fr', '[{"numero": 1, "texto": "Dès le matin, les principaux sacrificateurs tinrent conseil avec les anciens et les scribes, et tout le sanhédrin. Après avoir lié Jésus, ils l''''emmenèrent, et le livrèrent à Pilate."}, {"numero": 2, "texto": "Pilate l''''interrogea: Es-tu le roi des Juifs? Jésus lui répondit: Tu le dis."}, {"numero": 3, "texto": "Les principaux sacrificateurs portaient contre lui plusieurs accusations."}, {"numero": 4, "texto": "Pilate l''''interrogea de nouveau: Ne réponds-tu rien? Vois de combien de choses ils t''''accusent."}, {"numero": 5, "texto": "Et Jésus ne fit plus aucune réponse, ce qui étonna Pilate."}, {"numero": 6, "texto": "A chaque fête, il relâchait un prisonnier, celui que demandait la foule."}, {"numero": 7, "texto": "Il y avait en prison un nommé Barabbas avec ses complices, pour un meurtre qu''''ils avaient commis dans une sédition."}, {"numero": 8, "texto": "La foule, étant montée, se mit à demander ce qu''''il avait coutume de leur accorder."}, {"numero": 9, "texto": "Pilate leur répondit: Voulez-vous que je vous relâche le roi des Juifs?"}, {"numero": 10, "texto": "Car il savait que c''''était par envie que les principaux sacrificateurs l''''avaient livré."}, {"numero": 11, "texto": "Mais les chefs des sacrificateurs excitèrent la foule, afin que Pilate leur relâchât plutôt Barabbas."}, {"numero": 12, "texto": "Pilate, reprenant la parole, leur dit: Que voulez-vous donc que je fasse de celui que vous appelez le roi des Juifs?"}, {"numero": 13, "texto": "Ils crièrent de nouveau: Crucifie-le!"}, {"numero": 14, "texto": "Pilate leur dit: Quel mal a-t-il fait? Et ils crièrent encore plus fort: Crucifie-le!"}, {"numero": 15, "texto": "Pilate, voulant satisfaire la foule, leur relâcha Barabbas; et, après avoir fait battre de verges Jésus, il le livra pour être crucifié."}, {"numero": 16, "texto": "Les soldats conduisirent Jésus dans l''''intérieur de la cour, c''''est-à-dire, dans le prétoire, et ils assemblèrent toute la cohorte."}, {"numero": 17, "texto": "Ils le revêtirent de pourpre, et posèrent sur sa tête une couronne d''''épines, qu''''ils avaient tressée."}, {"numero": 18, "texto": "Puis ils se mirent à le saluer: Salut, roi des Juifs!"}, {"numero": 19, "texto": "Et ils lui frappaient la tête avec un roseau, crachaient sur lui, et, fléchissant les genoux, ils se prosternaient devant lui."}, {"numero": 20, "texto": "Après s''''être ainsi moqués de lui, ils lui ôtèrent la pourpre, lui remirent ses vêtements, et l''''emmenèrent pour le crucifier."}, {"numero": 21, "texto": "Ils forcèrent à porter la croix de Jésus un passant qui revenait des champs, Simon de Cyrène, père d''''Alexandre et de Rufus;"}, {"numero": 22, "texto": "et ils conduisirent Jésus au lieu nommé Golgotha, ce qui signifie lieu du crâne."}, {"numero": 23, "texto": "Ils lui donnèrent à boire du vin mêlé de myrrhe, mais il ne le prit pas."}, {"numero": 24, "texto": "Ils le crucifièrent, et se partagèrent ses vêtements, en tirant au sort pour savoir ce que chacun aurait."}, {"numero": 25, "texto": "C''''était la troisième heure, quand ils le crucifièrent."}, {"numero": 26, "texto": "L''''inscription indiquant le sujet de sa condamnation portait ces mots: Le roi des Juifs."}, {"numero": 27, "texto": "Ils crucifièrent avec lui deux brigands, l''''un à sa droite, et l''''autre à sa gauche."}, {"numero": 28, "texto": "Ainsi fut accompli ce que dit l''''Ecriture: Il a été mis au nombre des malfaiteurs."}, {"numero": 29, "texto": "Les passants l''''injuriaient, et secouaient la tête, en disant: Hé! toi qui détruis le temple, et qui le rebâtis en trois jours,"}, {"numero": 30, "texto": "sauve-toi toi-même, en descendant de la croix!"}, {"numero": 31, "texto": "Les principaux sacrificateurs aussi, avec les scribes, se moquaient entre eux, et disaient: Il a sauvé les autres, et il ne peut se sauver lui-même!"}, {"numero": 32, "texto": "Que le Christ, le roi d''''Israël, descende maintenant de la croix, afin que nous voyions et que nous croyions! Ceux qui étaient crucifiés avec lui l''''insultaient aussi."}, {"numero": 33, "texto": "La sixième heure étant venue, il y eut des ténèbres sur toute la terre, jusqu''''à la neuvième heure."}, {"numero": 34, "texto": "Et à la neuvième heure, Jésus s''''écria d''''une voix forte: Eloï, Eloï, lama sabachthani? ce qui signifie: Mon Dieu, mon Dieu, pourquoi m''''as-tu abandonné?"}, {"numero": 35, "texto": "Quelques-uns de ceux qui étaient là, l''''ayant entendu, dirent: Voici, il appelle Elie."}, {"numero": 36, "texto": "Et l''''un d''''eux courut remplir une éponge de vinaigre, et, l''''ayant fixée à un roseau, il lui donna à boire, en disant: Laissez, voyons si Elie viendra le descendre."}, {"numero": 37, "texto": "Mais Jésus, ayant poussé un grand cri, expira."}, {"numero": 38, "texto": "Le voile du temple se déchira en deux, depuis le haut jusqu''''en bas."}, {"numero": 39, "texto": "Le centenier, qui était en face de Jésus, voyant qu''''il avait expiré de la sorte, dit: Assurément, cet homme était Fils de Dieu."}, {"numero": 40, "texto": "Il y avait aussi des femmes qui regardaient de loin. Parmi elles étaient Marie de Magdala, Marie, mère de Jacques le mineur et de Joses, et Salomé,"}, {"numero": 41, "texto": "qui le suivaient et le servaient lorsqu''''il était en Galilée, et plusieurs autres qui étaient montées avec lui à Jérusalem."}, {"numero": 42, "texto": "Le soir étant venu, comme c''''était la préparation, c''''est-à-dire, la veille du sabbat, -"}, {"numero": 43, "texto": "arriva Joseph d''''Arimathée, conseiller de distinction, qui lui-même attendait aussi le royaume de Dieu. Il osa se rendre vers Pilate, pour demander le corps de Jésus."}, {"numero": 44, "texto": "Pilate s''''étonna qu''''il fût mort si tôt; fit venir le centenier et lui demanda s''''il était mort depuis longtemps."}, {"numero": 45, "texto": "S''''en étant assuré par le centenier, il donna le corps à Joseph."}, {"numero": 46, "texto": "Et Joseph, ayant acheté un linceul, descendit Jésus de la croix, l''''enveloppa du linceul, et le déposa dans un sépulcre taillé dans le roc. Puis il roula une pierre à l''''entrée du sépulcre."}, {"numero": 47, "texto": "Marie de Magdala, et Marie, mère de Joses, regardaient où on le mettait."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 15, 'es', '[{"numero": 1, "texto": "Y LUEGO por la mañana, habiendo tenido consejo los príncipes de los sacerdotes con los ancianos, y con los escribas, y con todo el concilio, llevaron á Jesús atado, y le entregaron á Pilato."}, {"numero": 2, "texto": "Y Pilato le preguntó: ¿Eres tú el Rey de los Judíos? Y respondiendo él, le dijo: Tú lo dices."}, {"numero": 3, "texto": "Y los príncipes de los sacerdotes le acusaban mucho."}, {"numero": 4, "texto": "Y le preguntó otra vez Pilato, diciendo: ¿No respondes algo? Mira de cuántas cosas te acusan."}, {"numero": 5, "texto": "Mas Jesús ni aun con eso respondió; de modo que Pilato se maravillaba."}, {"numero": 6, "texto": "Empero en el día de la fiesta les soltaba un preso, cualquiera que pidiesen."}, {"numero": 7, "texto": "Y había uno, que se llamaba Barrabás, preso con sus compañeros de motín que habían hecho muerte en una revuelta."}, {"numero": 8, "texto": "Y viniendo la multitud, comenzó á pedir hiciese como siempre les había hecho."}, {"numero": 9, "texto": "Y Pilato les respondió, diciendo: ¿Queréis que os suelte al Rey de los Judíos?"}, {"numero": 10, "texto": "Porque conocía que por envidia le habían entregado los príncipes de los sacerdotes."}, {"numero": 11, "texto": "Mas los príncipes de los sacerdotes incitaron á la multitud, que les soltase antes á Barrabás."}, {"numero": 12, "texto": "Y respondiendo Pilato, les dice otra vez: ¿Qué pues queréis que haga del que llamáis Rey de los Judíos?"}, {"numero": 13, "texto": "Y ellos volvieron á dar voces: Crucifícale."}, {"numero": 14, "texto": "Mas Pilato les decía: ¿Pues qué mal ha hecho? Y ellos daban más voces: Crucifícale."}, {"numero": 15, "texto": "Y Pilato, queriendo satisfacer al pueblo, les soltó á Barrabás, y entregó á Jesús, después de azotarle, para que fuese crucificado."}, {"numero": 16, "texto": "Entonces los soldados le llevaron dentro de la sala, es á saber, al Pretorio; y convocan toda la cohorte."}, {"numero": 17, "texto": "Y le visten de púrpura; y poniéndole una corona tejida de espinas,"}, {"numero": 18, "texto": "Comenzaron luego á saludarle: ¡Salve, Rey de los Judíos!"}, {"numero": 19, "texto": "Y le herían en la cabeza con una caña, y escupían en él, y le adoraban hincadas las rodillas."}, {"numero": 20, "texto": "Y cuando le hubieron escarnecido, le desnudaron la púrpura, y le vistieron sus propios vestidos, y le sacaron para crucificarle."}, {"numero": 21, "texto": "Y cargaron á uno que pasaba, Simón Cireneo, padre de Alejandro y de Rufo, que venía del campo, para que llevase su cruz."}, {"numero": 22, "texto": "Y le llevan al lugar de Gólgotha, que declarado quiere decir: Lugar de la Calavera."}, {"numero": 23, "texto": "Y le dieron á beber vino mezclado con mirra; mas él no lo tomó."}, {"numero": 24, "texto": "Y cuando le hubieron crucificado, repartieron sus vestidos, echando suertes sobre ellos, qué llevaría cada uno."}, {"numero": 25, "texto": "Y era la hora de las tres cuando le crucificaron."}, {"numero": 26, "texto": "Y el título escrito de su causa era: EL REY DE LOS JUDIOS."}, {"numero": 27, "texto": "Y crucificaron con él dos ladrones, uno á su derecha, y el otro á su izquierda."}, {"numero": 28, "texto": "Y se cumplió la Escritura, que dice: Y con los inicuos fué contado."}, {"numero": 29, "texto": "Y los que pasaban le denostaban, meneando sus cabezas, y diciendo: ¡Ah! tú que derribas el templo de Dios, y en tres días lo edificas,"}, {"numero": 30, "texto": "Sálvate á ti mismo, y desciende de la cruz."}, {"numero": 31, "texto": "Y de esta manera también los príncipes de los sacerdotes escarneciendo, decían unos á otros, con los escribas: A otros salvó, á sí mismo no se puede salvar."}, {"numero": 32, "texto": "El Cristo, Rey de Israel, descienda ahora de la cruz, para que veamos y creamos. También los que estaban crucificados con él le denostaban."}, {"numero": 33, "texto": "Y cuando vino la hora de sexta, fueron hechas tinieblas sobre toda la tierra hasta la hora de nona."}, {"numero": 34, "texto": "Y á la hora de nona, exclamó Jesús á gran voz, diciendo: Eloi, Eloi, ¿lama sabachthani? que declarado, quiere decir: Dios mío, Dios mío, ¿por qué me has desamparado?"}, {"numero": 35, "texto": "Y oyéndole unos de los que estaban allí, decían: He aquí, llama á Elías."}, {"numero": 36, "texto": "Y corrió uno, y empapando una esponja en vinagre, y poniéndola en una caña, le dió á beber, diciendo: Dejad, veamos si vendrá Elías á quitarle."}, {"numero": 37, "texto": "Mas Jesús, dando una grande voz, espiró."}, {"numero": 38, "texto": "Entonces el velo del templo se rasgó en dos, de alto á bajo."}, {"numero": 39, "texto": "Y el centurión que estaba delante de él, viendo que había espirado así clamando, dijo: Verdaderamente este hombre era el Hijo de Dios."}, {"numero": 40, "texto": "Y también estaban algunas mujeres mirando de lejos; entre las cuales estaba María Magdalena, y María la madre de Jacobo el menor y de José, y Salomé;"}, {"numero": 41, "texto": "Las cuales, estando aún él en Galilea, le habían seguido, y le servían; y otras muchas que juntamente con él habían subido á Jerusalem."}, {"numero": 42, "texto": "Y cuando fué la tarde, porque era la preparación, es decir, la víspera del sábado,"}, {"numero": 43, "texto": "José de Arimatea, senador noble, que también esperaba el reino de Dios, vino, y osadamente entró á Pilato, y pidió el cuerpo de Jesús."}, {"numero": 44, "texto": "Y Pilato se maravilló que ya fuese muerto; y haciendo venir al centurión, preguntóle si era ya muerto."}, {"numero": 45, "texto": "Y enterado del centurión, dió el cuerpo á José:"}, {"numero": 46, "texto": "El cual compró una sábana, y quitándole, le envolvió en la sábana: y le puso en un sepulcro que estaba cavado en una peña; y revolvió una piedra á la puerta del sepulcro."}, {"numero": 47, "texto": "Y María Magdalena, y María madre de José, miraban donde era puesto."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mc', 16, 'pt', '[{"numero": 1, "texto": "Havendo passado o sábado, Maria Madalena, e Maria [mãe] de Tiago, e Salomé, compraram especiarias, para irem o ungir."}, {"numero": 2, "texto": "E de manhã muito cedo, o primeiro dia da semana, vieram ao sepulcro, ao nascer do sol."}, {"numero": 3, "texto": "E diziam umas às outras: Quem rolará para nós a pedra da porta do sepulcro?"}, {"numero": 4, "texto": "Pois era muito grande. E quando observaram, viram que já a pedra estava havia sido rolada;"}, {"numero": 5, "texto": "e entrando no sepulcro, viram um rapaz sentado à direita, vestido com uma roupa comprida branca; e elas se espantaram."}, {"numero": 6, "texto": "Mas ele lhes disse: Não vos espanteis. Vós buscais a Jesus Nazareno crucificado. Ele já ressuscitou, não está aqui. Eis aqui o lugar onde o puseram."}, {"numero": 7, "texto": "Porém ide, dizei a seus discípulos e a Pedro, que ele vai adiante de para a Galileia; ali o vereis, como ele vos disse."}, {"numero": 8, "texto": "Então elas, saindo apressadamente, fugiram do sepulcro, porque temor e espanto as haviam tomado; e não disseram nada a ninguém, porque tinham medo."}, {"numero": 9, "texto": "E havendo ressuscitado pela manhã, no primeiro [dia] da semana, [Jesus] apareceu primeiramente a Maria Madalena, da qual havia expulsado sete demônios."}, {"numero": 10, "texto": "Ela se foi, e anunciou aos que estiveram com ele, que estavam tristes e chorando."}, {"numero": 11, "texto": "Quando ouviram que ele estava vivo, e que havia sido visto por ela, eles não creram."}, {"numero": 12, "texto": "E depois ele apareceu em outra forma a dois deles, que estavam indo pelo caminho ao campo."}, {"numero": 13, "texto": "E estes foram anunciar aos outros; mas também não creram neles."}, {"numero": 14, "texto": "Finalmente ele apareceu aos onze, estando eles sentados juntos; e repreendeu pela incredulidade e dureza de coração deles, por não terem crido nos que já o haviam visto ressuscitado."}, {"numero": 15, "texto": "E disse-lhes: Ide por todo o mundo, pregai o Evangelho a toda criatura."}, {"numero": 16, "texto": "Quem crer e for batizado será salvo; mas quem não crer será condenado."}, {"numero": 17, "texto": "E estes sinais seguirão aos que crerem: em meu nome expulsarão demônios; falarão novas línguas;"}, {"numero": 18, "texto": "pegarão serpentes com as mãos; e se beberem algo mortífero, não lhes fará dano algum; porão as mãos sobre os enfermos, e sararão."}, {"numero": 19, "texto": "Então o Senhor, depois de haver lhes falado, foi recebido acima no céu, e sentou-se à direita de Deus."}, {"numero": 20, "texto": "E eles saíram e pregaram por todas as partes, [com] o Senhor operando com eles, e confirmando a palavra com os sinais que se seguiam. Amém."}]'::jsonb, 'Almeida Livre'),
  ('Mc', 16, 'en', '[{"numero": 1, "texto": "And when the sabbath was past, Mary Magdalene, and Mary the mother of James, and Salome, had bought sweet spices, that they might come and anoint him."}, {"numero": 2, "texto": "And very early in the morning the first day of the week, they came unto the sepulchre at the rising of the sun."}, {"numero": 3, "texto": "And they said among themselves, Who shall roll us away the stone from the door of the sepulchre?"}, {"numero": 4, "texto": "And when they looked, they saw that the stone was rolled away: for it was very great."}, {"numero": 5, "texto": "And entering into the sepulchre, they saw a young man sitting on the right side, clothed in a long white garment; and they were affrighted."}, {"numero": 6, "texto": "And he saith unto them, Be not affrighted: Ye seek Jesus of Nazareth, which was crucified: he is risen; he is not here: behold the place where they laid him."}, {"numero": 7, "texto": "But go your way, tell his disciples and Peter that he goeth before you into Galilee: there shall ye see him, as he said unto you."}, {"numero": 8, "texto": "And they went out quickly, and fled from the sepulchre; for they trembled and were amazed: neither said they any thing to any man; for they were afraid."}, {"numero": 9, "texto": "Now when Jesus was risen early the first day of the week, he appeared first to Mary Magdalene, out of whom he had cast seven devils."}, {"numero": 10, "texto": "And she went and told them that had been with him, as they mourned and wept."}, {"numero": 11, "texto": "And they, when they had heard that he was alive, and had been seen of her, believed not."}, {"numero": 12, "texto": "After that he appeared in another form unto two of them, as they walked, and went into the country."}, {"numero": 13, "texto": "And they went and told it unto the residue: neither believed they them."}, {"numero": 14, "texto": "Afterward he appeared unto the eleven as they sat at meat, and upbraided them with their unbelief and hardness of heart, because they believed not them which had seen him after he was risen."}, {"numero": 15, "texto": "And he said unto them, Go ye into all the world, and preach the gospel to every creature."}, {"numero": 16, "texto": "He that believeth and is baptized shall be saved; but he that believeth not shall be damned."}, {"numero": 17, "texto": "And these signs shall follow them that believe; In my name shall they cast out devils; they shall speak with new tongues;"}, {"numero": 18, "texto": "They shall take up serpents; and if they drink any deadly thing, it shall not hurt them; they shall lay hands on the sick, and they shall recover."}, {"numero": 19, "texto": "So then after the Lord had spoken unto them, he was received up into heaven, and sat on the right hand of God."}, {"numero": 20, "texto": "And they went forth, and preached every where, the Lord working with them, and confirming the word with signs following. Amen."}]'::jsonb, 'King James Version'),
  ('Mc', 16, 'fr', '[{"numero": 1, "texto": "Lorsque le sabbat fut passé, Marie de Magdala, Marie, mère de Jacques, et Salomé, achetèrent des aromates, afin d''''aller embaumer Jésus."}, {"numero": 2, "texto": "Le premier jour de la semaine, elles se rendirent au sépulcre, de grand matin, comme le soleil venait de se lever."}, {"numero": 3, "texto": "Elles disaient entre elles: Qui nous roulera la pierre loin de l''''entrée du sépulcre?"}, {"numero": 4, "texto": "Et, levant les yeux, elles aperçurent que la pierre, qui était très grande, avait été roulée."}, {"numero": 5, "texto": "Elles entrèrent dans le sépulcre, virent un jeune homme assis à droite vêtu d''''une robe blanche, et elles furent épouvantées."}, {"numero": 6, "texto": "Il leur dit: Ne vous épouvantez pas; vous cherchez Jésus de Nazareth, qui a été crucifié; il est ressuscité, il n''''est point ici; voici le lieu où on l''''avait mis."}, {"numero": 7, "texto": "Mais allez dire à ses disciples et à Pierre qu''''il vous précède en Galilée: c''''est là que vous le verrez, comme il vous l''''a dit."}, {"numero": 8, "texto": "Elles sortirent du sépulcre et s''''enfuirent. La peur et le trouble les avaient saisies; et elles ne dirent rien à personne, à cause de leur effroi."}, {"numero": 9, "texto": "Jésus, étant ressuscité le matin du premier jour de la semaine, apparut d''''abord à Marie de Magdala, de laquelle il avait chassé sept démons."}, {"numero": 10, "texto": "Elle alla en porter la nouvelle à ceux qui avaient été avec lui, et qui s''''affligeaient et pleuraient."}, {"numero": 11, "texto": "Quand ils entendirent qu''''il vivait, et qu''''elle l''''avait vu, ils ne le crurent point."}, {"numero": 12, "texto": "Après cela, il apparut, sous une autre forme, à deux d''''entre eux qui étaient en chemin pour aller à la campagne."}, {"numero": 13, "texto": "Ils revinrent l''''annoncer aux autres, qui ne les crurent pas non plus."}, {"numero": 14, "texto": "Enfin, il apparut aux onze, pendant qu''''ils étaient à table; et il leur reprocha leur incrédulité et la dureté de leur coeur, parce qu''''ils n''''avaient pas cru ceux qui l''''avaient vu ressuscité."}, {"numero": 15, "texto": "Puis il leur dit: Allez par tout le monde, et prêchez la bonne nouvelle à toute la création."}, {"numero": 16, "texto": "Celui qui croira et qui sera baptisé sera sauvé, mais celui qui ne croira pas sera condamné."}, {"numero": 17, "texto": "Voici les miracles qui accompagneront ceux qui auront cru: en mon nom, ils chasseront les démons; ils parleront de nouvelles langues;"}, {"numero": 18, "texto": "ils saisiront des serpents; s''''ils boivent quelque breuvage mortel, il ne leur fera point de mal; ils imposeront les mains aux malades, et les malades, seront guéris."}, {"numero": 19, "texto": "Le Seigneur, après leur avoir parlé, fut enlevé au ciel, et il s''''assit à la droite de Dieu."}, {"numero": 20, "texto": "Et ils s''''en allèrent prêcher partout. Le Seigneur travaillait avec eux, et confirmait la parole par les miracles qui l''''accompagnaient."}]'::jsonb, 'Louis Segond 1910'),
  ('Mc', 16, 'es', '[{"numero": 1, "texto": "Y COMO pasó el sábado, María Magdalena, y María madre de Jacobo, y Salomé, compraron drogas aromáticas, para venir á ungirle."}, {"numero": 2, "texto": "Y muy de mañana, el primer día de la semana, vienen al sepulcro, ya salido el sol."}, {"numero": 3, "texto": "Y decían entre sí: ¿Quién nos revolverá la piedra de la puerta del sepulcro?"}, {"numero": 4, "texto": "Y como miraron, ven la piedra revuelta; que era muy grande."}, {"numero": 5, "texto": "Y entradas en el sepulcro, vieron un mancebo sentado al lado derecho, cubierto de una larga ropa blanca; y se espantaron."}, {"numero": 6, "texto": "Mas él les dice: No os asustéis: buscáis á Jesús Nazareno, el que fué crucificado; resucitado há, no está aquí; he aquí el lugar en donde le pusieron."}, {"numero": 7, "texto": "Mas id, decid á sus discípulos y á Pedro, que él va antes que vosotros á Galilea: allí le veréis, como os dijo."}, {"numero": 8, "texto": "Y ellas se fueron huyendo del sepulcro; porque las había tomado temblor y espanto; ni decían nada á nadie, porque tenían miedo."}, {"numero": 9, "texto": "Mas como Jesús resucitó por la mañana, el primer día de la semana, apareció primeramente á María Magdalena, de la cual había echado siete demonios."}, {"numero": 10, "texto": "Yendo ella, lo hizo saber á los que habían estado con él, que estaban tristes y llorando."}, {"numero": 11, "texto": "Y ellos como oyeron que vivía, y que había sido visto de ella, no lo creyeron."}, {"numero": 12, "texto": "Mas después apareció en otra forma á dos de ellos que iban caminando, yendo al campo."}, {"numero": 13, "texto": "Y ellos fueron, y lo hicieron saber á los otros; y ni aun á ellos creyeron."}, {"numero": 14, "texto": "Finalmente se apareció á los once mismos, estando sentados á la mesa, y censuróles su incredulidad y dureza de corazón, que no hubiesen creído á los que le habían visto resucitado."}, {"numero": 15, "texto": "Y les dijo: Id por todo el mundo; predicad el evangelio á toda criatura."}, {"numero": 16, "texto": "El que creyere y fuere bautizado, será salvo; mas el que no creyere, será condenado."}, {"numero": 17, "texto": "Y estas señales seguirán á los que creyeren: En mi nombre echarán fuera demonios; hablarán nuevas lenguas;"}, {"numero": 18, "texto": "Quitarán serpientes, y si bebieren cosa mortífera, no les dañará; sobre los enfermos pondrán sus manos, y sanarán."}, {"numero": 19, "texto": "Y el Señor, después que les habló, fué recibido arriba en el cielo, y sentóse á la diestra de Dios."}, {"numero": 20, "texto": "Y ellos, saliendo, predicaron en todas partes, obrando con ellos el Señor, y confirmando la palabra con las señales que se seguían. Amén."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ml', 3, 'pt', '[{"numero": 1, "texto": "Eis que eu enviarei o meu mensageiro, que preparará o caminho adiante de mim; e de repente virá a seu templo o Senhor a quem vós buscais, o mensageiro do pacto a quem vós desejais. Eis que ele vem,diz o SENHOR dos exércitos."}, {"numero": 2, "texto": "Mas quem poderá suportar o dia de sua vinda? Quem conseguirá ficar de pé quando ele aparecer? Porque ele será como fogo do ourives, e como o sabão de lavandeiros."}, {"numero": 3, "texto": "E ele se sentará como refinador e purificador da prata; pois ele limpará os filhos de Levi, e os refinará como o ouro e como a prata; então trarão ao SENHOR oferta com justiça."}, {"numero": 4, "texto": "E a oferta de Judá e de Jerusalém será suave ao SENHOR, como nos dias antigos, e como nos anos passados."}, {"numero": 5, "texto": "E eu me achegarei a vós para o julgamento; e prontamente serei testemunha contra os feiticeiros e adúlteros, e contra os que juram falsamente, e os que oprimem o empregado em seu salário, a viúva, e o órfão, e pervertem [o direito] do estrangeiro, e não me temem,diz o SENHOR dos exércitos."}, {"numero": 6, "texto": "Porque eu o SENHOR, não me mudo; por isso que vós, filhos de Jacó, não sois consumidos."}, {"numero": 7, "texto": "Desde os dias de vossos pais vos desviastes de minhas leis, e não as guardastes. Voltai-vos a mim, e eu me voltarei a vós,diz o SENHOR dos exércitos. Mas vós dizeis: Em que temos de voltar?"}, {"numero": 8, "texto": "Pode o ser humano roubar a Deus? Vós, pois, me roubais. Mas vós dizeis: Em que te roubamos? Nos dízimos e nas ofertas."}, {"numero": 9, "texto": "Com maldição sois amaldiçoados porque vós me roubais, toda a nação."}, {"numero": 10, "texto": "Trazei todos os dízimos à casa do tesouro, para que haja alimento em minha casa; e provai-me nisto, diz o SENHOR dos exércitos, se não vos abrir as janelas dos céu, e derramar sobre vós bênção transbordante."}, {"numero": 11, "texto": "E por causa de vós repreenderei ao devorador, para não corrompa vosso fruto da terra; e vossa vide no campo não será estéril,diz o SENHOR dos exércitos."}, {"numero": 12, "texto": "E todas as nações vos chamarão bem-aventurados; porque vós sereis terra agradável,diz o SENHOR dos exércitos."}, {"numero": 13, "texto": "Vossas palavras têm sido duras contra mim,diz o SENHOR. Mas vós dizeis: O que temos falado contra ti?"}, {"numero": 14, "texto": "Vós dizeis: É inútil servir a Deus; pois que proveito [temos tido] em guardarmos seus mandamentos e andarmos lamentando diante do SENHOR dos exércitos?"}, {"numero": 15, "texto": "Chamemos de sortudos os soberbos, pois os que praticam perversidade prosperam; mesmo tentando a Deus, eles escapam."}, {"numero": 16, "texto": "Então aqueles que temeram ao SENHOR falaram cada um a seu próximo, e o SENHOR prestou atenção e ouviu; e foi escrito um livro de memória diante dele para os que temem ao SENHOR, e para os que se honraram o seu nome."}, {"numero": 17, "texto": "E eles serão minha propriedade especial no dia que eu preparo,diz o SENHOR dos exércitos; e os pouparei como o homem que poupa a seu filho que lhe serve."}, {"numero": 18, "texto": "Então voltareis a ver a diferença entre o justo e o perverso, entre o que serve a Deus e o que não lhe serve."}]'::jsonb, 'Almeida Livre'),
  ('Ml', 3, 'en', '[{"numero": 1, "texto": "Behold, I will send my messenger, and he shall prepare the way before me: and the Lord, whom ye seek, shall suddenly come to his temple, even the messenger of the covenant, whom ye delight in: behold, he shall come, saith the Lord of hosts."}, {"numero": 2, "texto": "But who may abide the day of his coming? and who shall stand when he appeareth? for he is like a refiner''s fire, and like fullers'' soap:"}, {"numero": 3, "texto": "And he shall sit as a refiner and purifier of silver: and he shall purify the sons of Levi, and purge them as gold and silver, that they may offer unto the Lord an offering in righteousness."}, {"numero": 4, "texto": "Then shall the offering of Judah and Jerusalem be pleasant unto the Lord, as in the days of old, and as in former years."}, {"numero": 5, "texto": "And I will come near to you to judgment; and I will be a swift witness against the sorcerers, and against the adulterers, and against false swearers, and against those that oppress the hireling in his wages, the widow, and the fatherless, and that turn aside the stranger from his right, and fear not me, saith the Lord of hosts."}, {"numero": 6, "texto": "For I am the Lord, I change not; therefore ye sons of Jacob are not consumed."}, {"numero": 7, "texto": "Even from the days of your fathers ye are gone away from mine ordinances, and have not kept them. Return unto me, and I will return unto you, saith the Lord of hosts. But ye said, Wherein shall we return?"}, {"numero": 8, "texto": "Will a man rob God? Yet ye have robbed me. But ye say, Wherein have we robbed thee? In tithes and offerings."}, {"numero": 9, "texto": "Ye are cursed with a curse: for ye have robbed me, even this whole nation."}, {"numero": 10, "texto": "Bring ye all the tithes into the storehouse, that there may be meat in mine house, and prove me now herewith, saith the Lord of hosts, if I will not open you the windows of heaven, and pour you out a blessing, that there shall not be room enough to receive it."}, {"numero": 11, "texto": "And I will rebuke the devourer for your sakes, and he shall not destroy the fruits of your ground; neither shall your vine cast her fruit before the time in the field, saith the Lord of hosts."}, {"numero": 12, "texto": "And all nations shall call you blessed: for ye shall be a delightsome land, saith the Lord of hosts."}, {"numero": 13, "texto": "Your words have been stout against me, saith the Lord. Yet ye say, What have we spoken so much against thee?"}, {"numero": 14, "texto": "Ye have said, It is vain to serve God: and what profit is it that we have kept his ordinance, and that we have walked mournfully before the Lord of hosts?"}, {"numero": 15, "texto": "And now we call the proud happy; yea, they that work wickedness are set up; yea, they that tempt God are even delivered."}, {"numero": 16, "texto": "Then they that feared the Lord spake often one to another: and the Lord hearkened, and heard it, and a book of remembrance was written before him for them that feared the Lord, and that thought upon his name."}, {"numero": 17, "texto": "And they shall be mine, saith the Lord of hosts, in that day when I make up my jewels; and I will spare them, as a man spareth his own son that serveth him."}, {"numero": 18, "texto": "Then shall ye return, and discern between the righteous and the wicked, between him that serveth God and him that serveth him not."}]'::jsonb, 'King James Version'),
  ('Ml', 3, 'fr', '[{"numero": 1, "texto": "Voici, j''''enverrai mon messager; Il préparera le chemin devant moi. Et soudain entrera dans son temple le Seigneur que vous cherchez; Et le messager de l''''alliance que vous désirez, voici, il vient, Dit l''''Eternel des armées."}, {"numero": 2, "texto": "Qui pourra soutenir le jour de sa venue? Qui restera debout quand il paraîtra? Car il sera comme le feu du fondeur, Comme la potasse des foulons."}, {"numero": 3, "texto": "Il s''''assiéra, fondra et purifiera l''''argent; Il purifiera les fils de Lévi, Il les épurera comme on épure l''''or et l''''argent, Et ils présenteront à l''''Eternel des offrandes avec justice."}, {"numero": 4, "texto": "Alors l''''offrande de Juda et de Jérusalem sera agréable à l''''Eternel, Comme aux anciens jours, comme aux années d''''autrefois."}, {"numero": 5, "texto": "Je m''''approcherai de vous pour le jugement, Et je me hâterai de témoigner contre les enchanteurs et les adultères, Contre ceux qui jurent faussement, Contre ceux qui retiennent le salaire du mercenaire, Qui oppriment la veuve et l''''orphelin, Qui font tort à l''''étranger, et ne me craignent pas, Dit l''''Eternel des armées."}, {"numero": 6, "texto": "Car je suis l''''Eternel, je ne change pas; Et vous, enfants de Jacob, vous n''''avez pas été consumés."}, {"numero": 7, "texto": "Depuis le temps de vos pères, vous vous êtes écartés de mes ordonnances, Vous ne les avez point observées. Revenez à moi, et je reviendrai à vous, dit l''''Eternel des armées. Et vous dites: En quoi devons-nous revenir?"}, {"numero": 8, "texto": "Un homme trompe-t-il Dieu? Car vous me trompez, Et vous dites: En quoi t''''avons-nous trompé? Dans les dîmes et les offrandes."}, {"numero": 9, "texto": "Vous êtes frappés par la malédiction, Et vous me trompez, La nation tout entière!"}, {"numero": 10, "texto": "Apportez à la maison du trésor toutes les dîmes, Afin qu''''il y ait de la nourriture dans ma maison; Mettez-moi de la sorte à l''''épreuve, Dit l''''Eternel des armées. Et vous verrez si je n''''ouvre pas pour vous les écluses des cieux, Si je ne répands pas sur vous la bénédiction en abondance."}, {"numero": 11, "texto": "Pour vous je menacerai celui qui dévore, Et il ne vous détruira pas les fruits de la terre, Et la vigne ne sera pas stérile dans vos campagnes, Dit l''''Eternel des armées."}, {"numero": 12, "texto": "Toutes les nations vous diront heureux, Car vous serez un pays de délices, Dit l''''Eternel des armées."}, {"numero": 13, "texto": "Vos paroles sont rudes contre moi, dit l''''Eternel. Et vous dites: Qu''''avons-nous dit contre toi?"}, {"numero": 14, "texto": "Vous avez dit: C''''est en vain que l''''on sert Dieu; Qu''''avons-nous gagné à observer ses préceptes, Et à marcher avec tristesse A cause de l''''Eternel des armées?"}, {"numero": 15, "texto": "Maintenant nous estimons heureux les hautains; Oui, les méchants prospèrent; Oui, ils tentent Dieu, et ils échappent!"}, {"numero": 16, "texto": "Alors ceux qui craignent l''''Eternel se parlèrent l''''un à l''''autre; L''''Eternel fut attentif, et il écouta; Et un livre de souvenir fut écrit devant lui Pour ceux qui craignent l''''Eternel Et qui honorent son nom."}, {"numero": 17, "texto": "Ils seront à moi, dit l''''Eternel des armées, Ils m''''appartiendront, au jour que je prépare; J''''aurai compassion d''''eux, Comme un homme a compassion de son fils qui le sert."}, {"numero": 18, "texto": "Et vous verrez de nouveau la différence Entre le juste et le méchant, Entre celui qui sert Dieu Et celui qui ne le sert pas."}]'::jsonb, 'Louis Segond 1910'),
  ('Ml', 3, 'es', '[{"numero": 1, "texto": "HE aquí, yo envío mi mensajero, el cual preparará el camino delante de mí: y luego vendrá á su templo el Señor á quien vosotros buscáis, y el ángel del pacto, á quien deseáis vosotros. He aquí viene, ha dicho Jehová de los ejércitos."}, {"numero": 2, "texto": "¿Y quién podrá sufrir el tiempo de su venida? ó ¿quién podrá estar cuando él se mostrará? Porque él es como fuego purificador, y como jabón de lavadores."}, {"numero": 3, "texto": "Y sentarse ha para afinar y limpiar la plata: porque limpiará los hijos de Leví, los afinará como á oro y como á plata; y ofrecerán á Jehová ofrenda con justicia."}, {"numero": 4, "texto": "Y será suave á Jehová la ofrenda de Judá y de Jerusalem, como en los días pasados, y como en los años antiguos."}, {"numero": 5, "texto": "Y llegarme he á vosotros á juicio; y seré pronto testigo contra los hechiceros y adúlteros; y contra los que juran mentira, y los que detienen el salario del jornalero, de la viuda, y del huérfano, y los que hacen agravio al extranjero, no teniendo temor de mí, dice Jehová de los ejércitos."}, {"numero": 6, "texto": "Porque yo Jehová, no me mudo; y así vosotros, hijos de Jacob, no habéis sido consumidos."}, {"numero": 7, "texto": "Desde los días de vuestros padres os habéis apartado de mis leyes, y no las guardasteis. Tornaos á mí, y yo me tornaré á vosotros, ha dicho Jehová de los ejércitos. Mas dijisteis: ¿En qué hemos de tornar?"}, {"numero": 8, "texto": "¿Robará el hombre á Dios? Pues vosotros me habéis robado. Y dijisteis: ¿En qué te hemos robado? Los diezmos y las primicias."}, {"numero": 9, "texto": "Malditos sois con maldición, porque vosotros, la nación toda, me habéis robado."}, {"numero": 10, "texto": "Traed todos los diezmos al alfolí, y haya alimento en mi casa; y probadme ahora en esto, dice Jehová de los ejércitos, si no os abriré las ventanas de los cielos, y vaciaré sobre vosotros bendición hasta que sobreabunde."}, {"numero": 11, "texto": "Increparé también por vosotros al devorador, y no os corromperá el fruto de la tierra; ni vuestra vid en el campo abortará, dice Jehová de los ejércitos."}, {"numero": 12, "texto": "Y todas las gentes os dirán bienaventurados; porque seréis tierra deseable, dice Jehová de los ejércitos."}, {"numero": 13, "texto": "Vuestras palabras han prevalecido contra mí, dice Jehová. Y dijisteis: ¿Qué hemos hablado contra ti?"}, {"numero": 14, "texto": "Habéis dicho: Por demás es servir á Dios; ¿y qué aprovecha que guardemos su ley, y que andemos tristes delante de Jehová de los ejércitos?"}, {"numero": 15, "texto": "Decimos pues ahora, que bienaventurados los soberbios, y también que los que hacen impiedad son los prosperados: bien que tentaron á Dios, escaparon."}, {"numero": 16, "texto": "Entonces los que temen á Jehová hablaron cada uno á su compañero; y Jehová escuchó y oyó, y fué escrito libro de memoria delante de él para los que temen á Jehová, y para los que piensan en su nombre."}, {"numero": 17, "texto": "Y serán para mí especial tesoro, ha dicho Jehová de los ejércitos, en el día que yo tengo de hacer: y perdonarélos como el hombre que perdona á su hijo que le sirve."}, {"numero": 18, "texto": "Entonces os tornaréis, y echaréis de ver la diferencia entre el justo y el malo, entre el que sirve á Dios y el que no le sirve."}]'::jsonb, 'Reina-Valera 1909'),
  ('Ml', 4, 'pt', '[{"numero": 1, "texto": "Porque eis que aquele dia vem ardendo como forno; todos os soberbos e todos os que praticam perversidade serão [como a] palha; e o dia que está por vir os queimará, diz o SENHOR dos exércitos, de maneira que não lhes deixará nem raiz nem ramo."}, {"numero": 2, "texto": "Mas para vós, que temeis o meu nome, o Sol da justiça nascerá, trazendo cura em suas asas; e saireis, e saltareis de alegria como bezerros do curral."}, {"numero": 3, "texto": "E pisareis os perversos, porque serão cinza debaixo das plantas dos vossos pés, no dia que eu preparo, diz o SENHOR dos exércitos."}, {"numero": 4, "texto": "Lembrai-vos da lei de meu servo Moisés, que lhe mandei em Horebe estatutos e regras para todo Israel."}, {"numero": 5, "texto": "Eis que eu vos envio o profeta Elias, antes que venha o grande e temível dia do SENHOR."}, {"numero": 6, "texto": "Ele converterá o coração dos pais aos filhos, e o coração dos filhos aos pais; para que eu não venha e fira a terra com maldição."}]'::jsonb, 'Almeida Livre'),
  ('Ml', 4, 'en', '[{"numero": 1, "texto": "For, behold, the day cometh, that shall burn as an oven; and all the proud, yea, and all that do wickedly, shall be stubble: and the day that cometh shall burn them up, saith the Lord of hosts, that it shall leave them neither root nor branch."}, {"numero": 2, "texto": "But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall."}, {"numero": 3, "texto": "And ye shall tread down the wicked; for they shall be ashes under the soles of your feet in the day that I shall do this, saith the Lord of hosts."}, {"numero": 4, "texto": "Remember ye the law of Moses my servant, which I commanded unto him in Horeb for all Israel, with the statutes and judgments."}, {"numero": 5, "texto": "Behold, I will send you Elijah the prophet before the coming of the great and dreadful day of the Lord:"}, {"numero": 6, "texto": "And he shall turn the heart of the fathers to the children, and the heart of the children to their fathers, lest I come and smite the earth with a curse."}]'::jsonb, 'King James Version'),
  ('Ml', 4, 'fr', '[{"numero": 1, "texto": "Car voici, le jour vient, Ardent comme une fournaise. Tous les hautains et tous les méchants seront comme du chaume; Le jour qui vient les embrasera, Dit l''''Eternel des armées, Il ne leur laissera ni racine ni rameau."}, {"numero": 2, "texto": "Mais pour vous qui craignez mon nom, se lèvera Le soleil de la justice, Et la guérison sera sous ses ailes; Vous sortirez, et vous sauterez comme les veaux d''''une étable,"}, {"numero": 3, "texto": "Et vous foulerez les méchants, Car ils seront comme de la cendre Sous la plante de vos pieds, Au jour que je prépare, Dit l''''Eternel des armées."}, {"numero": 4, "texto": "Souvenez-vous de la loi de Moïse, mon serviteur, Auquel j''''ai prescrit en Horeb, pour tout Israël, Des préceptes et des ordonnances."}, {"numero": 5, "texto": "Voici, je vous enverrai Elie, le prophète, Avant que le jour de l''''Eternel arrive, Ce jour grand et redoutable."}, {"numero": 6, "texto": "Il ramènera le coeur des pères à leurs enfants, Et le coeur des enfants à leurs pères, De peur que je ne vienne frapper le pays d''''interdit."}]'::jsonb, 'Louis Segond 1910'),
  ('Ml', 4, 'es', '[{"numero": 1, "texto": "PORQUE he aquí, viene el día ardiente como un horno; y todos los soberbios, y todos los que hacen maldad, serán estopa; y aquel día que vendrá, los abrasará, ha dicho Jehová de los ejércitos, el cual no les dejará ni raíz ni rama."}, {"numero": 2, "texto": "Mas á vosotros los que teméis mi nombre, nacerá el Sol de justicia, y en sus alas traerá salud: y saldréis, y saltaréis como becerros de la manada."}, {"numero": 3, "texto": "Y hollaréis á los malos, los cuales serán ceniza bajo las plantas de vuestros pies, en el día que yo hago, ha dicho Jehová de los ejércitos."}, {"numero": 4, "texto": "Acordaos de la ley de Moisés mi siervo, al cual encargué en Horeb ordenanzas y leyes para todo Israel."}, {"numero": 5, "texto": "He aquí, yo os envío á Elías el profeta, antes que venga el día de Jehová grande y terrible."}, {"numero": 6, "texto": "El convertirá el corazón de los padres á los hijos, y el corazón de los hijos á los padres: no sea que yo venga, y con destrucción hiera la tierra."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mq', 4, 'pt', '[{"numero": 1, "texto": "Mas acontecerá nos últimos dias que o monte da casa do SENHOR será firmado no cume de montes, e será mais elevado que os morros; e os povos correrão a ele."}, {"numero": 2, "texto": "E muitas nações virão e dirão: Vinde, e subamos ao monte do SENHOR, à casa do Deus de Jacó; e ele nos ensinará seus caminhos, e nós andaremos em suas veredas; porque a lei virá de Sião, e a palavra do SENHOR de Jerusalém."}, {"numero": 3, "texto": "E ele julgará entre muitos povos, e corrigirá poderosas nações até muito longe; e adaptarão suas espadas para enxadas, e suas lanças para foices; nação não erguerá espada contra nação, nem mais aprenderão a [fazer] guerra."}, {"numero": 4, "texto": "E cada um se sentará debaixo de sua videira e debaixo de sua figueira, e não haverá quem lhes cause medo; porque a boca do SENHOR dos exércitos assim falou."}, {"numero": 5, "texto": "Pois todos os povos andam cada um no nome de seus deuses; nós, porém, andaremos no nome do SENHOR nosso Deus para todo o sempre."}, {"numero": 6, "texto": "Naquele dia,diz o SENHOR, reunirei a que mancava, e ajuntarei a que havia sido expulsa, e a que eu tinha maltratado."}, {"numero": 7, "texto": "E farei da que mancava um [povo] restante, da que havia sido expulsa uma nação poderosa; e o SENHOR reinará sobre eles no monte de Sião desde agora para sempre."}, {"numero": 8, "texto": "E tu, ó torre de vigilância do rebanho, tu fortaleza da filha de Sião, virá a ti o primeiro domínio; o reino chegará à filha de Jerusalém."}, {"numero": 9, "texto": "Agora por que gritas tanto? Não há rei em ti? Pereceu teu conselheiro, para que tenhas sido tomada por dores como as de parto?"}, {"numero": 10, "texto": "Sofre dores e contorce-te, ó filha de Sião, como mulher em trabalho de parto; porque agora sairás da cidade, e morarás no campo, e virás até a Babilônia; [porém] ali tu serás livrada, ali o SENHOR te redimirá da mão de teus inimigos."}, {"numero": 11, "texto": "Mas agora muitas nações se reuniram contra ti, e dizem: Seja profanada, e nossos olhos vejam a desgraça de Sião."}, {"numero": 12, "texto": "Mas elas não sabem os pensamentos do SENHOR, nem entendem seu conselho; de que ele as ajuntou como a feixes para a eira."}, {"numero": 13, "texto": "Levanta-te e trilha, ó filha de Sião, porque tornarei teu chifre de ferro, e tuas unhas de bronze, e esmiuçarás muitos povos; e consagrarás ao SENHOR seus ganhos, e seus bens ao Senhor de toda a terra."}]'::jsonb, 'Almeida Livre'),
  ('Mq', 4, 'en', '[{"numero": 1, "texto": "But in the last days it shall come to pass, that the mountain of the house of the Lord shall be established in the top of the mountains, and it shall be exalted above the hills; and people shall flow unto it."}, {"numero": 2, "texto": "And many nations shall come, and say, Come, and let us go up to the mountain of the Lord, and to the house of the God of Jacob; and he will teach us of his ways, and we will walk in his paths: for the law shall go forth of Zion, and the word of the Lord from Jerusalem."}, {"numero": 3, "texto": "And he shall judge among many people, and rebuke strong nations afar off; and they shall beat their swords into plowshares, and their spears into pruninghooks: nation shall not lift up a sword against nation, neither shall they learn war any more."}, {"numero": 4, "texto": "But they shall sit every man under his vine and under his fig tree; and none shall make them afraid: for the mouth of the Lord of hosts hath spoken it."}, {"numero": 5, "texto": "For all people will walk every one in the name of his god, and we will walk in the name of the Lord our God for ever and ever."}, {"numero": 6, "texto": "In that day, saith the Lord, will I assemble her that halteth, and I will gather her that is driven out, and her that I have afflicted;"}, {"numero": 7, "texto": "And I will make her that halted a remnant, and her that was cast far off a strong nation: and the Lord shall reign over them in mount Zion from henceforth, even for ever."}, {"numero": 8, "texto": "And thou, O tower of the flock, the strong hold of the daughter of Zion, unto thee shall it come, even the first dominion; the kingdom shall come to the daughter of Jerusalem."}, {"numero": 9, "texto": "Now why dost thou cry out aloud? is there no king in thee? is thy counsellor perished? for pangs have taken thee as a woman in travail."}, {"numero": 10, "texto": "Be in pain, and labour to bring forth, O daughter of Zion, like a woman in travail: for now shalt thou go forth out of the city, and thou shalt dwell in the field, and thou shalt go even to Babylon; there shalt thou be delivered; there the Lord shall redeem thee from the hand of thine enemies."}, {"numero": 11, "texto": "Now also many nations are gathered against thee, that say, Let her be defiled, and let our eye look upon Zion."}, {"numero": 12, "texto": "But they know not the thoughts of the Lord, neither understand they his counsel: for he shall gather them as the sheaves into the floor."}, {"numero": 13, "texto": "Arise and thresh, O daughter of Zion: for I will make thine horn iron, and I will make thy hoofs brass: and thou shalt beat in pieces many people: and I will consecrate their gain unto the Lord, and their substance unto the Lord of the whole earth."}]'::jsonb, 'King James Version'),
  ('Mq', 4, 'fr', '[{"numero": 1, "texto": "Il arrivera, dans la suite des temps, Que la montagne de la maison de l''''Eternel Sera fondée sur le sommet des montagnes, Qu''''elle s''''élèvera par-dessus les collines, Et que les peuples y afflueront."}, {"numero": 2, "texto": "Des nations s''''y rendront en foule, et diront: Venez, et montons à la montagne de l''''Eternel, A la maison du Dieu de Jacob, Afin qu''''il nous enseigne ses voies, Et que nous marchions dans ses sentiers. Car de Sion sortira la loi, Et de Jérusalem la parole de l''''Eternel."}, {"numero": 3, "texto": "Il sera le juge d''''un grand nombre de peuples, L''''arbitre de nations puissantes, lointaines. De leurs glaives ils forgeront des hoyaux, Et de leurs lances des serpes; Une nation ne tirera plus l''''épée contre une autre, Et l''''on n''''apprendra plus la guerre."}, {"numero": 4, "texto": "Ils habiteront chacun sous sa vigne et sous son figuier, Et il n''''y aura personne pour les troubler; Car la bouche de l''''Eternel des armées a parlé."}, {"numero": 5, "texto": "Tandis que tous les peuples marchent, chacun au nom de son dieu, Nous marcherons, nous, au nom de l''''Eternel, notre Dieu, A toujours et à perpétuité."}, {"numero": 6, "texto": "En ce jour-là, dit l''''Eternel, je recueillerai les boiteux, Je rassemblerai ceux qui étaient chassés, Ceux que j''''avais maltraités."}, {"numero": 7, "texto": "Des boiteux je ferai un reste, De ceux qui étaient chassés une nation puissante; Et l''''Eternel régnera sur eux, à la montagne de Sion, Dès lors et pour toujours."}, {"numero": 8, "texto": "Et toi, tour du troupeau, colline de la fille de Sion, A toi viendra, à toi arrivera l''''ancienne domination, Le royaume de la fille de Jérusalem."}, {"numero": 9, "texto": "Pourquoi maintenant pousses-tu des cris? N''''as-tu point de roi, plus de conseiller, Pour que la douleur te saisisse comme une femme qui accouche?"}, {"numero": 10, "texto": "Fille de Sion, souffre et gémis comme une femme qui accouche! Car maintenant tu sortiras de la ville et tu habiteras dans les champs, Et tu iras jusqu''''à Babylone; Là tu seras délivrée, C''''est là que l''''Eternel te rachètera de la main de tes ennemis."}, {"numero": 11, "texto": "Maintenant plusieurs nations se sont rassemblées contre toi: Qu''''elle soit profanée, disent-elles, Et que nos yeux se rassasient dans Sion!"}, {"numero": 12, "texto": "Mais elles ne connaissent pas les pensées de l''''Eternel, Elles ne comprennent pas ses desseins, Elles ignorent qu''''il les a rassemblées comme des gerbes dans l''''aire."}, {"numero": 13, "texto": "Fille de Sion, lève-toi et foule! Je te ferai une corne de fer et des ongles d''''airain, Et tu broieras des peuples nombreux; Tu consacreras leurs biens à l''''Eternel, Leurs richesses au Seigneur de toute la terre."}]'::jsonb, 'Louis Segond 1910'),
  ('Mq', 4, 'es', '[{"numero": 1, "texto": "Y ACONTECERÁ en los postreros tiempos, que el monte de la casa de Jehová será constituído por cabecera de montes, y más alto que los collados, y correrán á él pueblos."}, {"numero": 2, "texto": "Y vendrán muchas gentes, y dirán: Venid, y subamos al monte de Jehová, y á la casa del Dios de Jacob; y enseñarános en sus caminos, y andaremos por sus veredas: porque de Sión saldrá la ley, y de Jerusalem la palabra de Jehová."}, {"numero": 3, "texto": "Y juzgará entre muchos pueblos, y corregirá fuertes gentes hasta muy lejos: y martillarán sus espadas para azadones, y sus lanzas para hoces: no alzará espada gente contra gente, ni más se ensayarán para la guerra."}, {"numero": 4, "texto": "Y cada uno se sentará debajo de su vid y debajo de su higuera, y no habrá quien amedrente: porque la boca de Jehová de los ejércitos lo ha hablado."}, {"numero": 5, "texto": "Bien que todos los pueblos anduvieren cada uno en el nombre de sus dioses, nosotros con todo andaremos en el nombre de Jehová nuestro Dios para siempre y eternalmente."}, {"numero": 6, "texto": "En aquel día, dice Jehová, juntaré la coja, y recogeré la amontada, y á la que afligí;"}, {"numero": 7, "texto": "Y pondré á la coja para sucesión, y á la descarriada para nación robusta: y Jehová reinará sobre ellos en el monte de Sión desde ahora para siempre."}, {"numero": 8, "texto": "Y tú, oh torre del rebaño, la fortaleza de la hija de Sión vendrá hasta ti: y el señorío primero, el reino vendrá á la hija de Jerusalem."}, {"numero": 9, "texto": "Ahora ¿por qué gritas tanto? ¿No hay rey en ti? ¿Pereció tu consejero, que te ha tomado dolor como de mujer de parto?"}, {"numero": 10, "texto": "Duélete y gime, hija de Sión, como mujer de parto; porque ahora saldrás de la ciudad, y morarás en el campo, y llegarás hasta Babilonia: allí serás librada, allí te redimirá Jehová de la mano de tus enemigos."}, {"numero": 11, "texto": "Ahora empero se han juntado muchas gentes contra ti, y dicen: Sea profanada, y vean nuestros ojos su deseo sobre Sión."}, {"numero": 12, "texto": "Mas ellos no conocieron los pensamientos de Jehová, ni entendieron su consejo: por lo cual los juntó como gavillas en la era."}, {"numero": 13, "texto": "Levántate y trilla, hija de Sión, porque tu cuerno tornaré de hierro, y tus uñas de metal, y desmenuzarás muchos pueblos; y consagrarás á Jehová sus robos, y sus riquezas al Señor de toda la tierra."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 1, 'pt', '[{"numero": 1, "texto": "Livro da geração de Jesus Cristo, filho de Davi, filho de Abraão."}, {"numero": 2, "texto": "Abraão gerou a Isaque; e Isaque gerou a Jacó; e Jacó gerou a Judá e a seus irmãos."}, {"numero": 3, "texto": "E Judá gerou de Tamar a Perez e a Zerá; e Perez gerou a Esrom, e Esrom gerou a Arão."}, {"numero": 4, "texto": "E Arão gerou a Aminadabe; e Aminadabe gerou a Naassom; e Naassom gerou a Salmom."}, {"numero": 5, "texto": "E Salmom gerou de Raabe a Boaz; e Boaz gerou de Rute a Obede; e Obede gerou a Jessé."}, {"numero": 6, "texto": "E Jessé gerou ao rei Davi; e o rei Davi gerou Salomão da que [fora mulher] de Urias."}, {"numero": 7, "texto": "E Salomão gerou a Roboão; e Roboão gerou a Abias; e Abias gerou a Asa."}, {"numero": 8, "texto": "E Asa gerou a Josafá; e Josafá gerou a Jorão; e Jorão gerou a Uzias."}, {"numero": 9, "texto": "E Uzias gerou a Jotão; e Jotão gerou a Acaz; e Acaz gerou a Ezequias."}, {"numero": 10, "texto": "E Ezequias gerou a Manassés; e Manassés gerou a Amom; e Amom gerou a Josias."}, {"numero": 11, "texto": "E Josias gerou a Jeconias, e a seus irmãos no [tempo do] exílio babilônico."}, {"numero": 12, "texto": "E depois do exílio babilônico Jeconias gerou a Salatiel; e Salatiel gerou a Zorobabel."}, {"numero": 13, "texto": "E Zorobabel gerou a Abiúde; e Abiúde gerou a Eliaquim; e Eliaquim gerou a Azor."}, {"numero": 14, "texto": "E Azor gerou a Sadoque; e Sadoque gerou a Aquim; e Aquim gerou a Eliúde."}, {"numero": 15, "texto": "E Eliúde gerou a Eleazar; e Eleazar gerou a Matã; e Matã gerou a Jacó."}, {"numero": 16, "texto": "E Jacó gerou a José, o marido de Maria, da qual nasceu Jesus, chamado o Cristo."}, {"numero": 17, "texto": "De maneira que todas as gerações desde Abraão até Davi são catorze gerações; e desde Davi até o exílio babilônico catorze gerações; e desde o exílio babilônico até Cristo catorze gerações."}, {"numero": 18, "texto": "E o nascimento de Jesus Cristo foi assim: estando sua mãe Maria desposada com José, antes que se ajuntassem, ela foi achada grávida do Espírito Santo."}, {"numero": 19, "texto": "Então José, seu marido, sendo justo, e não querendo a expor à infâmia, pensou em deixá-la secretamente."}, {"numero": 20, "texto": "E ele, pretendendo isto, eis que um anjo do Senhor lhe apareceu em sonho, dizendo: José, filho de Davi, não temas receber Maria, tua mulher, porque o que nela está concebido é do Espírito Santo."}, {"numero": 21, "texto": "E ela dará à luz um filho, e tu chamarás seu nome Jesus; porque ele salvará seu povo de seus pecados."}, {"numero": 22, "texto": "E tudo isto aconteceu para que se cumprisse o que foi dito pelo Senhor por meio do profeta, que disse:"}, {"numero": 23, "texto": "Eis que a virgem conceberá, e dará à luz um filho, e chamarão seu nome Emanuel, que traduzido é: Deus conosco."}, {"numero": 24, "texto": "E despertando José do sonho, fez como o anjo do Senhor tinha lhe mandado, e recebeu sua mulher."}, {"numero": 25, "texto": "E ele não a conheceu [intimamente] ,até que ela deu à luz o filho dela, o primogênito, e lhe pôs por nome JESUS."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 1, 'en', '[{"numero": 1, "texto": "The book of the generation of Jesus Christ, the son of David, the son of Abraham."}, {"numero": 2, "texto": "Abraham begat Isaac; and Isaac begat Jacob; and Jacob begat Judas and his brethren;"}, {"numero": 3, "texto": "And Judas begat Phares and Zara of Thamar; and Phares begat Esrom; and Esrom begat Aram;"}, {"numero": 4, "texto": "And Aram begat Aminadab; and Aminadab begat Naasson; and Naasson begat Salmon;"}, {"numero": 5, "texto": "And Salmon begat Booz of Rachab; and Booz begat Obed of Ruth; and Obed begat Jesse;"}, {"numero": 6, "texto": "And Jesse begat David the king; and David the king begat Solomon of her that had been the wife of Urias;"}, {"numero": 7, "texto": "And Solomon begat Roboam; and Roboam begat Abia; and Abia begat Asa;"}, {"numero": 8, "texto": "And Asa begat Josaphat; and Josaphat begat Joram; and Joram begat Ozias;"}, {"numero": 9, "texto": "And Ozias begat Joatham; and Joatham begat Achaz; and Achaz begat Ezekias;"}, {"numero": 10, "texto": "And Ezekias begat Manasses; and Manasses begat Amon; and Amon begat Josias;"}, {"numero": 11, "texto": "And Josias begat Jechonias and his brethren, about the time they were carried away to Babylon:"}, {"numero": 12, "texto": "And after they were brought to Babylon, Jechonias begat Salathiel; and Salathiel begat Zorobabel;"}, {"numero": 13, "texto": "And Zorobabel begat Abiud; and Abiud begat Eliakim; and Eliakim begat Azor;"}, {"numero": 14, "texto": "And Azor begat Sadoc; and Sadoc begat Achim; and Achim begat Eliud;"}, {"numero": 15, "texto": "And Eliud begat Eleazar; and Eleazar begat Matthan; and Matthan begat Jacob;"}, {"numero": 16, "texto": "And Jacob begat Joseph the husband of Mary, of whom was born Jesus, who is called Christ."}, {"numero": 17, "texto": "So all the generations from Abraham to David are fourteen generations; and from David until the carrying away into Babylon are fourteen generations; and from the carrying away into Babylon unto Christ are fourteen generations."}, {"numero": 18, "texto": "Now the birth of Jesus Christ was on this wise: When as his mother Mary was espoused to Joseph, before they came together, she was found with child of the Holy Ghost."}, {"numero": 19, "texto": "Then Joseph her husband, being a just man, and not willing to make her a public example, was minded to put her away privily."}, {"numero": 20, "texto": "But while he thought on these things, behold, the angel of the Lord appeared unto him in a dream, saying, Joseph, thou son of David, fear not to take unto thee Mary thy wife: for that which is conceived in her is of the Holy Ghost."}, {"numero": 21, "texto": "And she shall bring forth a son, and thou shalt call his name Jesus: for he shall save his people from their sins."}, {"numero": 22, "texto": "Now all this was done, that it might be fulfilled which was spoken of the Lord by the prophet, saying,"}, {"numero": 23, "texto": "Behold, a virgin shall be with child, and shall bring forth a son, and they shall call his name Emmanuel, which being interpreted is, God with us."}, {"numero": 24, "texto": "Then Joseph being raised from sleep did as the angel of the Lord had bidden him, and took unto him his wife:"}, {"numero": 25, "texto": "And knew her not till she had brought forth her firstborn son: and he called his name Jesus."}]'::jsonb, 'King James Version'),
  ('Mt', 1, 'fr', '[{"numero": 1, "texto": "Généalogie de Jésus-Christ, fils de David, fils d''''Abraham."}, {"numero": 2, "texto": "Abraham engendra Isaac; Isaac engendra Jacob; Jacob engendra Juda et ses frères;"}, {"numero": 3, "texto": "Juda engendra de Thamar Pharès et Zara; Pharès engendra Esrom; Esrom engendra Aram;"}, {"numero": 4, "texto": "Aram engendra Aminadab; Aminadab engendra Naasson; Naasson engendra Salmon;"}, {"numero": 5, "texto": "Salmon engendra Boaz de Rahab; Boaz engendra Obed de Ruth; Obed engendra Isaï;"}, {"numero": 6, "texto": "Isaï engendra David. Le roi David engendra Salomon de la femme d''''Urie;"}, {"numero": 7, "texto": "Salomon engendra Roboam; Roboam engendra Abia; Abia engendra Asa;"}, {"numero": 8, "texto": "Asa engendra Josaphat; Josaphat engendra Joram; Joram engendra Ozias;"}, {"numero": 9, "texto": "Ozias engendra Joatham; Joatham engendra Achaz; Achaz engendra Ezéchias;"}, {"numero": 10, "texto": "Ezéchias engendra Manassé; Manassé engendra Amon; Amon engendra Josias;"}, {"numero": 11, "texto": "Josias engendra Jéchonias et ses frères, au temps de la déportation à Babylone."}, {"numero": 12, "texto": "Après la déportation à Babylone, Jéchonias engendra Salathiel; Salathiel engendra Zorobabel;"}, {"numero": 13, "texto": "Zorobabel engendra Abiud; Abiud engendra Eliakim; Eliakim engendra Azor;"}, {"numero": 14, "texto": "Azor engendra Sadok; Sadok engendra Achim; Achim engendra Eliud;"}, {"numero": 15, "texto": "Eliud engendra Eléazar; Eléazar engendra Matthan; Matthan engendra Jacob;"}, {"numero": 16, "texto": "Jacob engendra Joseph, l''''époux de Marie, de laquelle est né Jésus, qui est appelé Christ."}, {"numero": 17, "texto": "Il y a donc en tout quatorze générations depuis Abraham jusqu''''à David, quatorze générations depuis David jusqu''''à la déportation à Babylone, et quatorze générations depuis la déportation à Babylone jusqu''''au Christ."}, {"numero": 18, "texto": "Voici de quelle manière arriva la naissance de Jésus-Christ. Marie, sa mère, ayant été fiancée à Joseph, se trouva enceinte, par la vertu du Saint-Esprit, avant qu''''ils eussent habité ensemble."}, {"numero": 19, "texto": "Joseph, son époux, qui était un homme de bien et qui ne voulait pas la diffamer, se proposa de rompre secrètement avec elle."}, {"numero": 20, "texto": "Comme il y pensait, voici, un ange du Seigneur lui apparut en songe, et dit: Joseph, fils de David, ne crains pas de prendre avec toi Marie, ta femme, car l''''enfant qu''''elle a conçu vient du Saint-Esprit;"}, {"numero": 21, "texto": "elle enfantera un fils, et tu lui donneras le nom de Jésus; c''''est lui qui sauvera son peuple de ses péchés."}, {"numero": 22, "texto": "Tout cela arriva afin que s''''accomplît ce que le Seigneur avait annoncé par le prophète:"}, {"numero": 23, "texto": "Voici, la vierge sera enceinte, elle enfantera un fils, et on lui donnera le nom d''''Emmanuel, ce qui signifie Dieu avec nous."}, {"numero": 24, "texto": "Joseph s''''étant réveillé fit ce que l''''ange du Seigneur lui avait ordonné, et il prit sa femme avec lui."}, {"numero": 25, "texto": "Mais il ne la connut point jusqu''''à ce qu''''elle eût enfanté un fils, auquel il donna le nom de Jésus."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 1, 'es', '[{"numero": 1, "texto": "LIBRO de la generación de Jesucristo, hijo de David, hijo de Abraham."}, {"numero": 2, "texto": "Abraham engendró á Isaac: é Isaac engendró á Jacob: y Jacob engendró á Judas y á sus hermanos:"}, {"numero": 3, "texto": "Y Judas engendró de Thamar á Phares y á Zara: y Phares engendró á Esrom: y Esrom engendró á Aram:"}, {"numero": 4, "texto": "Y Aram engendró á Aminadab: y Aminadab engendró á Naassón: y Naassón engendró á Salmón:"}, {"numero": 5, "texto": "Y Salmón engendró de Rachâb á Booz, y Booz engendró de Ruth á Obed: y Obed engendró á Jessé:"}, {"numero": 6, "texto": "Y Jessé engendró al rey David: y el rey David engendró á Salomón de la que fué mujer de Urías:"}, {"numero": 7, "texto": "Y Salomón engendró á Roboam: y Roboam engendró á Abía: y Abía engendró á Asa:"}, {"numero": 8, "texto": "Y Asa engendró á Josaphat: y Josaphat engendró á Joram: y Joram engendró á Ozías:"}, {"numero": 9, "texto": "Y Ozías engendró á Joatam: y Joatam engendró á Achâz: y Achâz engendró á Ezechîas:"}, {"numero": 10, "texto": "Y Ezechîas engendró á Manasés: y Manasés engendró á Amón: y Amón engendró á Josías:"}, {"numero": 11, "texto": "Y Josías engendró á Jechônías y á sus hermanos, en la transmigración de Babilonia."}, {"numero": 12, "texto": "Y después de la transmigración de Babilonia, Jechônías engendró á Salathiel: y Salathiel engendró á Zorobabel:"}, {"numero": 13, "texto": "Y Zorobabel engendró á Abiud: y Abiud engendró á Eliachîm: y Eliachîm engendró á Azor:"}, {"numero": 14, "texto": "Y Azor engendró á Sadoc: y Sadoc engendró á Achîm: y Achîm engendró á Eliud:"}, {"numero": 15, "texto": "Y Eliud engendró á Eleazar: y Eleazar engendró á Mathán: y Mathán engendró á Jacob:"}, {"numero": 16, "texto": "Y Jacob engendró á José, marido de María, de la cual nació Jesús, el cual es llamado el Cristo."}, {"numero": 17, "texto": "De manera que todas las generaciones desde Abraham hasta David son catorce generaciones: y desde David hasta la transmigración de Babilonia, catorce generaciones: y desde la transmigración de Babilonia hasta Cristo, catorce generaciones."}, {"numero": 18, "texto": "Y el nacimiento de Jesucristo fué así: Que siendo María su madre desposada con José, antes que se juntasen, se halló haber concebido del Espíritu Santo."}, {"numero": 19, "texto": "Y José su marido, como era justo, y no quisiese infamarla, quiso dejarla secretamente."}, {"numero": 20, "texto": "Y pensando él en esto, he aquí el ángel del Señor le aparece en sueños, diciendo: José, hijo de David, no temas de recibir á María tu mujer, porque lo que en ella es engendrado, del Espíritu Santo es."}, {"numero": 21, "texto": "Y parirá un hijo, y llamarás su nombre JESUS, porque él salvará á su pueblo de sus pecados."}, {"numero": 22, "texto": "Todo esto aconteció para que se cumpliese lo que fué dicho por el Señor, por el profeta que dijo:"}, {"numero": 23, "texto": "He aquí la virgen concebirá y parirá un hijo, y llamarás su nombre Emmanuel, que declarado, es: Con nosotros Dios."}, {"numero": 24, "texto": "Y despertando José del sueño, hizo como el ángel del Señor le había mandado, y recibió á su mujer."}, {"numero": 25, "texto": "Y no la conoció hasta que parió á su hijo primogénito: y llamó su nombre JESUS."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 2, 'pt', '[{"numero": 1, "texto": "E sendo Jesus já nascido em Belém da Judeia, nos dias do rei Herodes, eis que vieram uns magos do oriente a Jerusalém,"}, {"numero": 2, "texto": "Dizendo: Onde está o Rei nascido dos Judeus? Porque vimos sua estrela no oriente, e viemos adorá-lo."}, {"numero": 3, "texto": "E o rei Herodes, ao ouvir [isto] , ficou perturbado, e com ele toda Jerusalém."}, {"numero": 4, "texto": "E tendo reunido todos os chefes dos sacerdotes e escribas do povo, perguntou-lhes onde o Cristo havia de nascer."}, {"numero": 5, "texto": "E eles lhe disseram: Em Belém da Judeia, porque assim está escrito pelo profeta:"}, {"numero": 6, "texto": "E tu Belém, terra de Judá, de maneira nenhuma és a menor entre as lideranças de Judá, porque de ti sairá o Guia que apascentará meu povo Israel."}, {"numero": 7, "texto": "Então Herodes, chamando secretamente os magos, perguntou-lhes com precisão sobre o tempo em que a estrela havia aparecido."}, {"numero": 8, "texto": "E enviando-os a Belém, disse: Ide, e investigai cuidadosamente pelo menino; e quando o achardes, avisai-me, para que também eu venha e o adore."}, {"numero": 9, "texto": "Depois de ouvirem o rei, eles foram embora. E eis que a estrela que tinham visto no oriente ia adiante deles, até que ela chegou, e ficou parada sobre onde o menino estava."}, {"numero": 10, "texto": "E eles, vendo a estrela, jubilaram muito com grande alegria."}, {"numero": 11, "texto": "E entrando na casa, acharam o menino com sua mãe Maria, e prostrando-se o adoraram. E abrindo seus tesouros, ofereceram-lhe presentes: ouro, incenso, e mirra."}, {"numero": 12, "texto": "E sendo por divina revelação avisados em sonho que não voltassem a Herodes, partiram para sua terra por outro caminho."}, {"numero": 13, "texto": "E tendo eles partido, eis que um anjo do Senhor apareceu a José em sonho, dizendo: Levanta-te, toma o menino e sua mãe, e foge para o Egito; e fica lá até que eu te diga, porque Herodes buscará o menino para o matar."}, {"numero": 14, "texto": "Então ele se despertou, tomou o menino e sua mãe de noite, e foi para o Egito;"}, {"numero": 15, "texto": "E esteve lá até a morte de Herodes, para que se cumprisse o que foi dito pelo Senhor por meio do profeta, que disse: Do Egito chamei o meu Filho."}, {"numero": 16, "texto": "Então Herodes, ao ver que tinha sido enganado pelos magos, irou-se muito, e mandou matar todos os meninos em Belém e em todos os limites de sua região, [da idade] de dois anos e abaixo, conforme o tempo que tinha perguntado com precisão dos magos."}, {"numero": 17, "texto": "Então se cumpriu o que foi dito pelo profeta Jeremias, que disse:"}, {"numero": 18, "texto": "Uma voz se ouviu em Ramá, lamentação, choro, e grande pranto; Raquel chorava por seus filhos, e não quis ser consolada, pois já não existem."}, {"numero": 19, "texto": "Mas depois de Herodes ter morrido, eis que um anjo do Senhor apareceu no Egito a José em sonho,"}, {"numero": 20, "texto": "Dizendo: Levanta-te, toma o menino e sua mãe, e vai para a terra de Israel, porque já morreram os que procuravam a morte do menino."}, {"numero": 21, "texto": "Então ele se levantou, tomou o menino e sua mãe, e veio para a terra de Israel."}, {"numero": 22, "texto": "Porém ao ouvir que Arquelau reinava na Judeia em lugar de seu pai Herodes, ele teve medo de ir para lá; mas avisado por divina revelação em sonho, foi para a região da Galileia,"}, {"numero": 23, "texto": "E veio a habitar na cidade chamada Nazaré, para que se cumprisse o que foi dito pelos profetas, que: Ele será chamado de Nazareno."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 2, 'en', '[{"numero": 1, "texto": "Now when Jesus was born in Bethlehem of Judaea in the days of Herod the king, behold, there came wise men from the east to Jerusalem,"}, {"numero": 2, "texto": "Saying, Where is he that is born King of the Jews? for we have seen his star in the east, and are come to worship him."}, {"numero": 3, "texto": "When Herod the king had heard these things, he was troubled, and all Jerusalem with him."}, {"numero": 4, "texto": "And when he had gathered all the chief priests and scribes of the people together, he demanded of them where Christ should be born."}, {"numero": 5, "texto": "And they said unto him, In Bethlehem of Judaea: for thus it is written by the prophet,"}, {"numero": 6, "texto": "And thou Bethlehem, in the land of Juda, art not the least among the princes of Juda: for out of thee shall come a Governor, that shall rule my people Israel."}, {"numero": 7, "texto": "Then Herod, when he had privily called the wise men, enquired of them diligently what time the star appeared."}, {"numero": 8, "texto": "And he sent them to Bethlehem, and said, Go and search diligently for the young child; and when ye have found him, bring me word again, that I may come and worship him also."}, {"numero": 9, "texto": "When they had heard the king, they departed; and, lo, the star, which they saw in the east, went before them, till it came and stood over where the young child was."}, {"numero": 10, "texto": "When they saw the star, they rejoiced with exceeding great joy."}, {"numero": 11, "texto": "And when they were come into the house, they saw the young child with Mary his mother, and fell down, and worshipped him: and when they had opened their treasures, they presented unto him gifts; gold, and frankincense and myrrh."}, {"numero": 12, "texto": "And being warned of God in a dream that they should not return to Herod, they departed into their own country another way."}, {"numero": 13, "texto": "And when they were departed, behold, the angel of the Lord appeareth to Joseph in a dream, saying, Arise, and take the young child and his mother, and flee into Egypt, and be thou there until I bring thee word: for Herod will seek the young child to destroy him."}, {"numero": 14, "texto": "When he arose, he took the young child and his mother by night, and departed into Egypt:"}, {"numero": 15, "texto": "And was there until the death of Herod: that it might be fulfilled which was spoken of the Lord by the prophet, saying, Out of Egypt have I called my son."}, {"numero": 16, "texto": "Then Herod, when he saw that he was mocked of the wise men, was exceeding wroth, and sent forth, and slew all the children that were in Bethlehem, and in all the coasts thereof, from two years old and under, according to the time which he had diligently inquired of the wise men."}, {"numero": 17, "texto": "Then was fulfilled that which was spoken by Jeremiah the prophet, saying,"}, {"numero": 18, "texto": "In Rama was there a voice heard, lamentation, and weeping, and great mourning, Rachel weeping for her children, and would not be comforted, because they are not."}, {"numero": 19, "texto": "But when Herod was dead, behold, an angel of the Lord appeareth in a dream to Joseph in Egypt,"}, {"numero": 20, "texto": "Saying, Arise, and take the young child and his mother, and go into the land of Israel: for they are dead which sought the young child''s life."}, {"numero": 21, "texto": "And he arose, and took the young child and his mother, and came into the land of Israel."}, {"numero": 22, "texto": "But when he heard that Archelaus did reign in Judaea in the room of his father Herod, he was afraid to go thither: notwithstanding, being warned of God in a dream, he turned aside into the parts of Galilee:"}, {"numero": 23, "texto": "And he came and dwelt in a city called Nazareth: that it might be fulfilled which was spoken by the prophets, He shall be called a Nazarene."}]'::jsonb, 'King James Version'),
  ('Mt', 2, 'fr', '[{"numero": 1, "texto": "Jésus étant né à Bethléhem en Judée, au temps du roi Hérode, voici des mages d''''Orient arrivèrent à Jérusalem,"}, {"numero": 2, "texto": "et dirent: Où est le roi des Juifs qui vient de naître? car nous avons vu son étoile en Orient, et nous sommes venus pour l''''adorer."}, {"numero": 3, "texto": "Le roi Hérode, ayant appris cela, fut troublé, et tout Jérusalem avec lui."}, {"numero": 4, "texto": "Il assembla tous les principaux sacrificateurs et les scribes du peuple, et il s''''informa auprès d''''eux où devait naître le Christ."}, {"numero": 5, "texto": "Ils lui dirent: A Bethléhem en Judée; car voici ce qui a été écrit par le prophète:"}, {"numero": 6, "texto": "Et toi, Bethléhem, terre de Juda, Tu n''''es certes pas la moindre entre les principales villes de Juda, Car de toi sortira un chef Qui paîtra Israël, mon peuple."}, {"numero": 7, "texto": "Alors Hérode fit appeler en secret les mages, et s''''enquit soigneusement auprès d''''eux depuis combien de temps l''''étoile brillait."}, {"numero": 8, "texto": "Puis il les envoya à Bethléhem, en disant: Allez, et prenez des informations exactes sur le petit enfant; quand vous l''''aurez trouvé, faites-le-moi savoir, afin que j''''aille aussi moi-même l''''adorer."}, {"numero": 9, "texto": "Après avoir entendu le roi, ils partirent. Et voici, l''''étoile qu''''ils avaient vue en Orient marchait devant eux jusqu''''à ce qu''''étant arrivée au-dessus du lieu où était le petit enfant, elle s''''arrêta."}, {"numero": 10, "texto": "Quand ils aperçurent l''''étoile, ils furent saisis d''''une très grande joie."}, {"numero": 11, "texto": "Ils entrèrent dans la maison, virent le petit enfant avec Marie, sa mère, se prosternèrent et l''''adorèrent; ils ouvrirent ensuite leurs trésors, et lui offrirent en présent de l''''or, de l''''encens et de la myrrhe."}, {"numero": 12, "texto": "Puis, divinement avertis en songe de ne pas retourner vers Hérode, ils regagnèrent leur pays par un autre chemin."}, {"numero": 13, "texto": "Lorsqu''''ils furent partis, voici, un ange du Seigneur apparut en songe à Joseph, et dit: Lève-toi, prends le petit enfant et sa mère, fuis en Egypte, et restes-y jusqu''''à ce que je te parle; car Hérode cherchera le petit enfant pour le faire périr."}, {"numero": 14, "texto": "Joseph se leva, prit de nuit le petit enfant et sa mère, et se retira en Egypte."}, {"numero": 15, "texto": "Il y resta jusqu''''à la mort d''''Hérode, afin que s''''accomplît ce que le Seigneur avait annoncé par le prophète: J''''ai appelé mon fils hors d''''Egypte."}, {"numero": 16, "texto": "Alors Hérode, voyant qu''''il avait été joué par les mages, se mit dans une grande colère, et il envoya tuer tous les enfants de deux ans et au-dessous qui étaient à Bethléhem et dans tout son territoire, selon la date dont il s''''était soigneusement enquis auprès des mages."}, {"numero": 17, "texto": "Alors s''''accomplit ce qui avait été annoncé par Jérémie, le prophète:"}, {"numero": 18, "texto": "On a entendu des cris à Rama, Des pleurs et de grandes lamentations: Rachel pleure ses enfants, Et n''''a pas voulu être consolée, Parce qu''''ils ne sont plus."}, {"numero": 19, "texto": "Quand Hérode fut mort, voici, un ange du Seigneur apparut en songe à Joseph, en Egypte,"}, {"numero": 20, "texto": "et dit: Lève-toi, prends le petit enfant et sa mère, et va dans le pays d''''Israël, car ceux qui en voulaient à la vie du petit enfant sont morts."}, {"numero": 21, "texto": "Joseph se leva, prit le petit enfant et sa mère, et alla dans le pays d''''Israël."}, {"numero": 22, "texto": "Mais, ayant appris qu''''Archélaüs régnait sur la Judée à la place d''''Hérode, son père, il craignit de s''''y rendre; et, divinement averti en songe, il se retira dans le territoire de la Galilée,"}, {"numero": 23, "texto": "et vint demeurer dans une ville appelée Nazareth, afin que s''''accomplît ce qui avait été annoncé par les prophètes: Il sera appelé Nazaréen."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 2, 'es', '[{"numero": 1, "texto": "Y COMO fué nacido Jesús en Bethlehem de Judea en días del rey Herodes, he aquí unos magos vinieron del oriente á Jerusalem,"}, {"numero": 2, "texto": "Diciendo: ¿Dónde está el Rey de los Judíos, que ha nacido? porque su estrella hemos visto en el oriente, y venimos á adorarle."}, {"numero": 3, "texto": "Y oyendo esto el rey Herodes, se turbó, y toda Jerusalem con él."}, {"numero": 4, "texto": "Y convocados todos los príncipes de los sacerdotes, y los escribas del pueblo, les preguntó dónde había de nacer el Cristo."}, {"numero": 5, "texto": "Y ellos le dijeron: En Bethlehem de Judea; porque así está escrito por el profeta:"}, {"numero": 6, "texto": "Y tú, Bethlehem, de tierra de Judá, no eres muy pequeña entre los príncipes de Judá; porque de ti saldrá un guiador, que apacentará á mi pueblo Israel."}, {"numero": 7, "texto": "Entonces Herodes, llamando en secreto á los magos, entendió de ellos diligentemente el tiempo del aparecimiento de la estrella;"}, {"numero": 8, "texto": "Y enviándolos á Bethlehem, dijo: Andad allá, y preguntad con diligencia por el niño; y después que le hallareis, hacédmelo saber, para que yo también vaya y le adore."}, {"numero": 9, "texto": "Y ellos, habiendo oído al rey, se fueron: y he aquí la estrella que habían visto en el oriente, iba delante de ellos, hasta que llegando, se puso sobre donde estaba el niño."}, {"numero": 10, "texto": "Y vista la estrella, se regocijaron con muy grande gozo."}, {"numero": 11, "texto": "Y entrando en la casa, vieron al niño con su madre María, y postrándose, le adoraron; y abriendo sus tesoros, le ofrecieron dones, oro é incienso y mirra."}, {"numero": 12, "texto": "Y siendo avisados por revelación en sueños que no volviesen á Herodes, se volvieron á su tierra por otro camino."}, {"numero": 13, "texto": "Y partidos ellos, he aquí el ángel del Señor aparece en sueños á José, diciendo: Levántate, y toma al niño y á su madre, y huye á Egipto, y estáte allá hasta que yo te lo diga; porque ha de acontecer, que Herodes buscará al niño para matarlo."}, {"numero": 14, "texto": "Y él despertando, tomó al niño y á su madre de noche, y se fué á Egipto;"}, {"numero": 15, "texto": "Y estuvo allá hasta la muerte de Herodes: para que se cumpliese lo que fué dicho por el Señor, por el profeta que dijo: De Egipto llamé á mi Hijo."}, {"numero": 16, "texto": "Herodes entonces, como se vió burlado de los magos, se enojó mucho, y envió, y mató á todos los niños que había en Bethlehem y en todos sus términos, de edad de dos años abajo, conforme al tiempo que había entendido de los magos."}, {"numero": 17, "texto": "Entonces fué cumplido lo que se había dicho por el profeta Jeremías, que dijo:"}, {"numero": 18, "texto": "Voz fué oída en Ramá, grande lamentación, lloro y gemido: Rachêl que llora sus hijos; y no quiso ser consolada, porque perecieron."}, {"numero": 19, "texto": "Mas muerto Herodes, he aquí el ángel del Señor aparece en sueños á José en Egipto,"}, {"numero": 20, "texto": "Diciendo: Levántate, y toma al niño y á su madre, y vete á tierra de Israel; que muertos son los que procuraban la muerte del niño."}, {"numero": 21, "texto": "Entonces él se levantó, y tomó al niño y á su madre, y se vino á tierra de Israel."}, {"numero": 22, "texto": "Y oyendo que Archelao reinaba en Judea en lugar de Herodes su padre, temió ir allá: mas amonestado por revelación en sueños, se fué á las partes de Galilea."}, {"numero": 23, "texto": "Y vino, y habitó en la ciudad que se llama Nazaret: para que se cumpliese lo que fué dicho por los profetas, que había de ser llamado Nazareno."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 3, 'pt', '[{"numero": 1, "texto": "E naqueles dias veio João Batista, pregando no deserto da Judeia,"}, {"numero": 2, "texto": "E dizendo: Arrependei-vos, porque perto está o Reino dos céus."}, {"numero": 3, "texto": "Porque este é aquele que foi declarado pelo profeta Isaías, que disse: Voz do que clama no deserto: “Preparai o caminho do Senhor; endireitai suas veredas”."}, {"numero": 4, "texto": "Este João tinha sua roupa de pelos de camelo e um cinto de couro ao redor de sua cintura, e seu alimento era gafanhotos e mel silvestre."}, {"numero": 5, "texto": "Então vinham até ele [moradores] de Jerusalém, de toda a Judeia, e de toda a região próxima do Jordão;"}, {"numero": 6, "texto": "E eram por ele batizados no Jordão, confessando os seus pecados."}, {"numero": 7, "texto": "Mas quando ele viu muitos dos fariseus e dos saduceus que vinham ao seu batismo, disse-lhes: Ninhada de víboras! Quem vos ensinou a fugir da ira futura?"}, {"numero": 8, "texto": "Dai, pois, frutos condizentes com o arrependimento."}, {"numero": 9, "texto": "E não imagineis, dizendo em vós mesmos: “Temos por pai a Abraão”, porque eu vos digo que até destas pedras Deus pode fazer surgir filhos a Abraão."}, {"numero": 10, "texto": "E agora mesmoo machado está posto à raiz das árvores; portanto toda árvore que não dá bom fruto é cortada e lançada ao fogo."}, {"numero": 11, "texto": "Realmente eu vos batizo com água para arrependimento, mas aquele que vem após mim é mais poderoso do que eu; suas sandálias não sou digno de levar. Ele vos batizará com o Espírito Santo e com fogo."}, {"numero": 12, "texto": "Ele tem sua pá na mão; limpará sua eira, e recolherá seu trigo no celeiro; mas queimará a palha com fogo que nunca se apaga."}, {"numero": 13, "texto": "Então Jesus veio da Galileia ao Jordão até João para ser por ele batizado."}, {"numero": 14, "texto": "Mas João lhe impedia, dizendo: Eu preciso ser batizado por ti, e tu vens a mim?"}, {"numero": 15, "texto": "Porém Jesus lhe respondeu: Permite por agora, porque assim nos convém cumprir toda a justiça. Então ele o permitiu."}, {"numero": 16, "texto": "E tendo Jesus sido batizado, subiu logo da água. E eis que os céus se lhe abriram, e ele viu o Espírito de Deus descendo como uma pomba, vindo sobre ele."}, {"numero": 17, "texto": "E eis uma voz dos céus, dizendo: Este é o meu Filho amado, em quem me agrado."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 3, 'en', '[{"numero": 1, "texto": "In those days came John the Baptist, preaching in the wilderness of Judaea,"}, {"numero": 2, "texto": "And saying, Repent ye: for the kingdom of heaven is at hand."}, {"numero": 3, "texto": "For this is he that was spoken of by the prophet Esaias, saying, The voice of one crying in the wilderness, Prepare ye the way of the Lord, make his paths straight."}, {"numero": 4, "texto": "And the same John had his raiment of camel''s hair, and a leathern girdle about his loins; and his meat was locusts and wild honey."}, {"numero": 5, "texto": "Then went out to him Jerusalem, and all Judaea, and all the region round about Jordan,"}, {"numero": 6, "texto": "And were baptized of him in Jordan, confessing their sins."}, {"numero": 7, "texto": "But when he saw many of the Pharisees and Sadducees come to his baptism, he said unto them, O generation of vipers, who hath warned you to flee from the wrath to come?"}, {"numero": 8, "texto": "Bring forth therefore fruits meet for repentance:"}, {"numero": 9, "texto": "And think not to say within yourselves, We have Abraham to our father: for I say unto you, that God is able of these stones to raise up children unto Abraham."}, {"numero": 10, "texto": "And now also the axe is laid unto the root of the trees: therefore every tree which bringeth not forth good fruit is hewn down, and cast into the fire."}, {"numero": 11, "texto": "I indeed baptize you with water unto repentance. but he that cometh after me is mightier than I, whose shoes I am not worthy to bear: he shall baptize you with the Holy Ghost, and with fire:"}, {"numero": 12, "texto": "Whose fan is in his hand, and he will throughly purge his floor, and gather his wheat into the garner; but he will burn up the chaff with unquenchable fire."}, {"numero": 13, "texto": "Then cometh Jesus from Galilee to Jordan unto John, to be baptized of him."}, {"numero": 14, "texto": "But John forbad him, saying, I have need to be baptized of thee, and comest thou to me?"}, {"numero": 15, "texto": "And Jesus answering said unto him, Suffer it to be so now: for thus it becometh us to fulfil all righteousness. Then he suffered him."}, {"numero": 16, "texto": "And Jesus, when he was baptized, went up straightway out of the water: and, lo, the heavens were opened unto him, and he saw the Spirit of God descending like a dove, and lighting upon him:"}, {"numero": 17, "texto": "And lo a voice from heaven, saying, This is my beloved Son, in whom I am well pleased."}]'::jsonb, 'King James Version'),
  ('Mt', 3, 'fr', '[{"numero": 1, "texto": "En ce temps-là parut Jean Baptiste, prêchant dans le désert de Judée."}, {"numero": 2, "texto": "Il disait: Repentez-vous, car le royaume des cieux est proche."}, {"numero": 3, "texto": "Jean est celui qui avait été annoncé par Esaïe, le prophète, lorsqu''''il dit: C''''est ici la voix de celui qui crie dans le désert: Préparez le chemin du Seigneur, Aplanissez ses sentiers."}, {"numero": 4, "texto": "Jean avait un vêtement de poils de chameau, et une ceinture de cuir autour des reins. Il se nourrissait de sauterelles et de miel sauvage."}, {"numero": 5, "texto": "Les habitants de Jérusalem, de toute la Judée et de tout le pays des environs du Jourdain, se rendaient auprès de lui;"}, {"numero": 6, "texto": "et, confessant leurs péchés, ils se faisaient baptiser par lui dans le fleuve du Jourdain."}, {"numero": 7, "texto": "Mais, voyant venir à son baptême beaucoup de pharisiens et de sadducéens, il leur dit: Races de vipères, qui vous a appris à fuir la colère à venir?"}, {"numero": 8, "texto": "Produisez donc du fruit digne de la repentance,"}, {"numero": 9, "texto": "et ne prétendez pas dire en vous-mêmes: Nous avons Abraham pour père! Car je vous déclare que de ces pierres-ci Dieu peut susciter des enfants à Abraham."}, {"numero": 10, "texto": "Déjà la cognée est mise à la racine des arbres: tout arbre donc qui ne produit pas de bons fruits sera coupé et jeté au feu."}, {"numero": 11, "texto": "Moi, je vous baptise d''''eau, pour vous amener à la repentance; mais celui qui vient après moi est plus puissant que moi, et je ne suis pas digne de porter ses souliers. Lui, il vous baptisera du Saint-Esprit et de feu."}, {"numero": 12, "texto": "Il a son van à la main; il nettoiera son aire, et il amassera son blé dans le grenier, mais il brûlera la paille dans un feu qui ne s''''éteint point."}, {"numero": 13, "texto": "Alors Jésus vint de la Galilée au Jourdain vers Jean, pour être baptisé par lui."}, {"numero": 14, "texto": "Mais Jean s''''y opposait, en disant: C''''est moi qui ai besoin d''''être baptisé par toi, et tu viens à moi!"}, {"numero": 15, "texto": "Jésus lui répondit: Laisse faire maintenant, car il est convenable que nous accomplissions ainsi tout ce qui est juste. Et Jean ne lui résista plus."}, {"numero": 16, "texto": "Dès que Jésus eut été baptisé, il sortit de l''''eau. Et voici, les cieux s''''ouvrirent, et il vit l''''Esprit de Dieu descendre comme une colombe et venir sur lui."}, {"numero": 17, "texto": "Et voici, une voix fit entendre des cieux ces paroles: Celui-ci est mon Fils bien-aimé, en qui j''''ai mis toute mon affection."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 3, 'es', '[{"numero": 1, "texto": "Y EN aquellos días vino Juan el Bautista predicando en el desierto de Judea,"}, {"numero": 2, "texto": "Y diciendo: Arrepentíos, que el reino de los cielos se ha acercado."}, {"numero": 3, "texto": "Porque éste es aquel del cual fué dicho por el profeta Isaías, que dijo: Voz de uno que clama en el desierto: Aparejad el camino del Señor, enderezad sus veredas."}, {"numero": 4, "texto": "Y tenía Juan su vestido de pelos de camellos, y una cinta de cuero alrededor de sus lomos; y su comida era langostas y miel silvestre."}, {"numero": 5, "texto": "Entonces salía á él Jerusalem, y toda Judea, y toda la provincia de alrededor del Jordán;"}, {"numero": 6, "texto": "Y eran bautizados de él en el Jordán, confesando sus pecados."}, {"numero": 7, "texto": "Y viendo él muchos de los Fariseos y de los Saduceos, que venían á su bautismo, decíales: Generación de víboras, ¿quién os ha enseñado á huir de la ira que vendrá?"}, {"numero": 8, "texto": "Haced pues frutos dignos de arrepentimiento,"}, {"numero": 9, "texto": "Y no penséis decir dentro de vosotros: A Abraham tenemos por padre: porque yo os digo, que puede Dios despertar hijos á Abraham aun de estas piedras."}, {"numero": 10, "texto": "Ahora, ya también la segur está puesta á la raíz de los árboles; y todo árbol que no hace buen fruto, es cortado y echado en el fuego."}, {"numero": 11, "texto": "Yo á la verdad os bautizo en agua para arrepentimiento; mas el que viene tras mí, más poderoso es que yo; los zapatos del cual yo no soy digno de llevar; él os bautizará en Espíritu Santo y en fuego."}, {"numero": 12, "texto": "Su aventador en su mano está, y aventará su era: y allegará su trigo en el alfolí, y quemará la paja en fuego que nunca se apagará."}, {"numero": 13, "texto": "Entonces Jesús vino de Galilea á Juan al Jordán, para ser bautizado de él."}, {"numero": 14, "texto": "Mas Juan lo resistía mucho, diciendo: Yo he menester ser bautizado de ti, ¿y tú vienes á mí?"}, {"numero": 15, "texto": "Empero respondiendo Jesús le dijo: Deja ahora; porque así nos conviene cumplir toda justicia. Entonces le dejó."}, {"numero": 16, "texto": "Y Jesús, después que fué bautizado, subió luego del agua; y he aquí los cielos le fueron abiertos, y vió al Espíritu de Dios que descendía como paloma, y venía sobre él."}, {"numero": 17, "texto": "Y he aquí una voz de los cielos que decía: Este es mi Hijo amado, en el cual tengo contentamiento."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 4, 'pt', '[{"numero": 1, "texto": "Então Jesus foi levado pelo Espírito ao deserto para ser tentado pelo diabo."}, {"numero": 2, "texto": "E depois de jejuar quarenta dias e quarenta noites, teve fome."}, {"numero": 3, "texto": "E o tentador se aproximou dele, e disse: Se tu és o Filho de Deus, dize que estas pedras se tornem pães."}, {"numero": 4, "texto": "Mas [Jesus] respondeu: Está escrito: Não só de pão viverá o ser humano, mas de toda palavra que sai da boca de Deus."}, {"numero": 5, "texto": "Então o diabo o levou consigo à santa cidade, e o pôs sobre o ponto mais alto do Templo,"}, {"numero": 6, "texto": "E disse-lhe: Se tu és o Filho de Deus, lança-te abaixo, porque está escrito que: Mandará a seus anjos acerca de ti, e te tomarão pelas mãos, para que nunca com teu pé tropeces em pedra alguma."}, {"numero": 7, "texto": "Jesus lhe disse: Também está escrito: Não tentarás o Senhor teu Deus."}, {"numero": 8, "texto": "Outra vez o diabo o levou consigo a um monte muito alto, e lhe mostrou todos os reinos do mundo, e a glória deles,"}, {"numero": 9, "texto": "E disse-lhe: Tudo isto te darei se, prostrado, me adorares."}, {"numero": 10, "texto": "Então Jesus disse: Vai embora, Satanás! Porque está escrito: Ao Senhor teu Deus adorarás, e só a ele cultuarás."}, {"numero": 11, "texto": "Então o diabo o deixou; e eis que chegaram anjos, e o serviram."}, {"numero": 12, "texto": "Mas quando Jesus ouviu que João estava preso, voltou para a Galileia."}, {"numero": 13, "texto": "E deixando Nazaré, veio a morar em Cafarnaum, [cidade] marítima, nos limites de Zebulom e Naftali,"}, {"numero": 14, "texto": "para que se cumprisse o que foi anunciado pelo profeta Isaías, que disse:"}, {"numero": 15, "texto": "A terra de Zebulom e a terra de Naftali, caminho do mar, além do Jordão, a Galileia dos gentios;"}, {"numero": 16, "texto": "O povo sentado em trevas viu uma grande luz; aos sentados em região e sombra da morte, a luz lhes apareceu."}, {"numero": 17, "texto": "Desde então Jesus começou a pregar e a dizer: Arrependei-vos, porque perto está o Reino dos céus."}, {"numero": 18, "texto": "Enquanto Jesus andava junto ao mar da Galileia, viu dois irmãos: Simão, chamado Pedro, e seu irmão André, lançarem a rede ao mar, porque eram pescadores."}, {"numero": 19, "texto": "E disse-lhes: Vinde após mim, e eu vos farei pescadores de gente."}, {"numero": 20, "texto": "Então eles logo deixaram as redes e o seguiram."}, {"numero": 21, "texto": "E passando dali, viu outros dois irmãos: Tiago, [filho] de Zebedeu, e seu irmão João, em um barco, com seu pai Zebedeu, que estavam consertando suas redes; e ele os chamou."}, {"numero": 22, "texto": "E eles logo deixaram o barco e seu pai, e o seguiram."}, {"numero": 23, "texto": "E Jesus rodeava toda a Galileia, ensinando em suas sinagogas, pregando o Evangelho do Reino, e curando toda enfermidade e toda doença no povo."}, {"numero": 24, "texto": "Sua fama corria por toda a Síria, e traziam-lhe todos que sofriam de algum mal, tendo diversas enfermidades e tormentos, e os endemoninhados, epiléticos, e paralíticos; e ele os curava."}, {"numero": 25, "texto": "E muitas multidões da Galileia, de Decápolis, de Jerusalém, da Judeia, e dalém do Jordão o seguiam."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 4, 'en', '[{"numero": 1, "texto": "Then was Jesus led up of the Spirit into the wilderness to be tempted of the devil."}, {"numero": 2, "texto": "And when he had fasted forty days and forty nights, he was afterward an hungred."}, {"numero": 3, "texto": "And when the tempter came to him, he said, If thou be the Son of God, command that these stones be made bread."}, {"numero": 4, "texto": "But he answered and said, It is written, Man shall not live by bread alone, but by every word that proceedeth out of the mouth of God."}, {"numero": 5, "texto": "Then the devil taketh him up into the holy city, and setteth him on a pinnacle of the temple,"}, {"numero": 6, "texto": "And saith unto him, If thou be the Son of God, cast thyself down: for it is written, He shall give his angels charge concerning thee: and in their hands they shall bear thee up, lest at any time thou dash thy foot against a stone."}, {"numero": 7, "texto": "Jesus said unto him, It is written again, Thou shalt not tempt the Lord thy God."}, {"numero": 8, "texto": "Again, the devil taketh him up into an exceeding high mountain, and sheweth him all the kingdoms of the world, and the glory of them;"}, {"numero": 9, "texto": "And saith unto him, All these things will I give thee, if thou wilt fall down and worship me."}, {"numero": 10, "texto": "Then saith Jesus unto him, Get thee hence, Satan: for it is written, Thou shalt worship the Lord thy God, and him only shalt thou serve."}, {"numero": 11, "texto": "Then the devil leaveth him, and, behold, angels came and ministered unto him."}, {"numero": 12, "texto": "Now when Jesus had heard that John was cast into prison, he departed into Galilee;"}, {"numero": 13, "texto": "And leaving Nazareth, he came and dwelt in Capernaum, which is upon the sea coast, in the borders of Zabulon and Nephthalim:"}, {"numero": 14, "texto": "That it might be fulfilled which was spoken by Esaias the prophet, saying,"}, {"numero": 15, "texto": "The land of Zabulon, and the land of Nephthalim, by the way of the sea, beyond Jordan, Galilee of the Gentiles;"}, {"numero": 16, "texto": "The people which sat in darkness saw great light; and to them which sat in the region and shadow of death light is sprung up."}, {"numero": 17, "texto": "From that time Jesus began to preach, and to say, Repent: for the kingdom of heaven is at hand."}, {"numero": 18, "texto": "And Jesus, walking by the sea of Galilee, saw two brethren, Simon called Peter, and Andrew his brother, casting a net into the sea: for they were fishers."}, {"numero": 19, "texto": "And he saith unto them, Follow me, and I will make you fishers of men."}, {"numero": 20, "texto": "And they straightway left their nets, and followed him."}, {"numero": 21, "texto": "And going on from thence, he saw other two brethren, James the son of Zebedee, and John his brother, in a ship with Zebedee their father, mending their nets; and he called them."}, {"numero": 22, "texto": "And they immediately left the ship and their father, and followed him."}, {"numero": 23, "texto": "And Jesus went about all Galilee, teaching in their synagogues, and preaching the gospel of the kingdom, and healing all manner of sickness and all manner of disease among the people."}, {"numero": 24, "texto": "And his fame went throughout all Syria: and they brought unto him all sick people that were taken with divers diseases and torments, and those which were possessed with devils, and those which were lunatick, and those that had the palsy; and he healed them."}, {"numero": 25, "texto": "And there followed him great multitudes of people from Galilee, and from Decapolis, and from Jerusalem, and from Judaea, and from beyond Jordan."}]'::jsonb, 'King James Version'),
  ('Mt', 4, 'fr', '[{"numero": 1, "texto": "Alors Jésus fut emmené par l''''Esprit dans le désert, pour être tenté par le diable."}, {"numero": 2, "texto": "Après avoir jeûné quarante jours et quarante nuits, il eut faim."}, {"numero": 3, "texto": "Le tentateur, s''''étant approché, lui dit: Si tu es Fils de Dieu, ordonne que ces pierres deviennent des pains."}, {"numero": 4, "texto": "Jésus répondit: Il est écrit: L''''homme ne vivra pas de pain seulement, mais de toute parole qui sort de la bouche de Dieu."}, {"numero": 5, "texto": "Le diable le transporta dans la ville sainte, le plaça sur le haut du temple,"}, {"numero": 6, "texto": "et lui dit: Si tu es Fils de Dieu, jette-toi en bas; car il est écrit: Il donnera des ordres à ses anges à ton sujet; Et ils te porteront sur les mains, De peur que ton pied ne heurte contre une pierre."}, {"numero": 7, "texto": "Jésus lui dit: Il est aussi écrit: Tu ne tenteras point le Seigneur, ton Dieu."}, {"numero": 8, "texto": "Le diable le transporta encore sur une montagne très élevée, lui montra tous les royaumes du monde et leur gloire,"}, {"numero": 9, "texto": "et lui dit: Je te donnerai toutes ces choses, si tu te prosternes et m''''adores."}, {"numero": 10, "texto": "Jésus lui dit: Retire-toi, Satan! Car il est écrit: Tu adoreras le Seigneur, ton Dieu, et tu le serviras lui seul."}, {"numero": 11, "texto": "Alors le diable le laissa. Et voici, des anges vinrent auprès de Jésus, et le servaient."}, {"numero": 12, "texto": "Jésus, ayant appris que Jean avait été livré, se retira dans la Galilée."}, {"numero": 13, "texto": "Il quitta Nazareth, et vint demeurer à Capernaüm, située près de la mer, dans le territoire de Zabulon et de Nephthali,"}, {"numero": 14, "texto": "afin que s''''accomplît ce qui avait été annoncé par Esaïe, le prophète:"}, {"numero": 15, "texto": "Le peuple de Zabulon et de Nephthali, De la contrée voisine de la mer, du pays au delà du Jourdain, Et de la Galilée des Gentils,"}, {"numero": 16, "texto": "Ce peuple, assis dans les ténèbres, A vu une grande lumière; Et sur ceux qui étaient assis dans la région et l''''ombre de la mort La lumière s''''est levée."}, {"numero": 17, "texto": "Dès ce moment Jésus commença à prêcher, et à dire: Repentez-vous, car le royaume des cieux est proche."}, {"numero": 18, "texto": "Comme il marchait le long de la mer de Galilée, il vit deux frères, Simon, appelé Pierre, et André, son frère, qui jetaient un filet dans la mer; car ils étaient pêcheurs."}, {"numero": 19, "texto": "Il leur dit: Suivez-moi, et je vous ferai pêcheurs d''''hommes."}, {"numero": 20, "texto": "Aussitôt, ils laissèrent les filets, et le suivirent."}, {"numero": 21, "texto": "De là étant allé plus loin, il vit deux autres frères, Jacques, fils de Zébédée, et Jean, son frère, qui étaient dans une barque avec Zébédée, leur père, et qui réparaient leurs filets. Il les appela,"}, {"numero": 22, "texto": "et aussitôt ils laissèrent la barque et leur père, et le suivirent."}, {"numero": 23, "texto": "Jésus parcourait toute la Galilée, enseignant dans les synagogues, prêchant la bonne nouvelle du royaume, et guérissant toute maladie et toute infirmité parmi le peuple."}, {"numero": 24, "texto": "Sa renommée se répandit dans toute la Syrie, et on lui amenait tous ceux qui souffraient de maladies et de douleurs de divers genres, des démoniaques, des lunatiques, des paralytiques; et il les guérissait."}, {"numero": 25, "texto": "Une grande foule le suivit, de la Galilée, de la Décapole, de Jérusalem, de la Judée, et d''''au delà du Jourdain."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 4, 'es', '[{"numero": 1, "texto": "ENTONCES Jesús fué llevado del Espíritu al desierto, para ser tentado del diablo."}, {"numero": 2, "texto": "Y habiendo ayunado cuarenta días y cuarenta noches, después tuvo hambre."}, {"numero": 3, "texto": "Y llegándose á él el tentador, dijo: Si eres Hijo de Dios, di que estas piedras se hagan pan."}, {"numero": 4, "texto": "Mas él respondiendo, dijo: Escrito está: No con solo el pan vivirá el hombre, mas con toda palabra que sale de la boca de Dios."}, {"numero": 5, "texto": "Entonces el diablo le pasa á la santa ciudad, y le pone sobre las almenas del templo,"}, {"numero": 6, "texto": "Y le dice: Si eres Hijo de Dios, échate abajo; que escrito está: A sus ángeles mandará por ti, y te alzarán en las manos, para que nunca tropieces con tu pie en piedra."}, {"numero": 7, "texto": "Jesús le dijo: Escrito está además: No tentarás al Señor tu Dios."}, {"numero": 8, "texto": "Otra vez le pasa el diablo á un monte muy alto, y le muestra todos los reinos del mundo, y su gloria,"}, {"numero": 9, "texto": "Y dícele: Todo esto te daré, si postrado me adorares."}, {"numero": 10, "texto": "Entonces Jesús le dice: Vete, Satanás, que escrito está: Al Señor tu Dios adorarás y á él solo servirás."}, {"numero": 11, "texto": "El diablo entonces le dejó: y he aquí los ángeles llegaron y le servían."}, {"numero": 12, "texto": "Mas oyendo Jesús que Juan era preso, se volvió á Galilea;"}, {"numero": 13, "texto": "Y dejando á Nazaret, vino y habitó en Capernaum, ciudad marítima, en los confines de Zabulón y de Nephtalim:"}, {"numero": 14, "texto": "Para que se cumpliese lo que fué dicho por el profeta Isaías, que dijo:"}, {"numero": 15, "texto": "La tierra de Zabulón, y la tierra de Nephtalim, camino de la mar, de la otra parte del Jordán, Galilea de los Gentiles;"}, {"numero": 16, "texto": "El pueblo asentado en tinieblas, vió gran luz; y á los sentados en región y sombra de muerte, luz les esclareció."}, {"numero": 17, "texto": "Desde entonces comenzó Jesús á predicar, y á decir: Arrepentíos, que el reino de los cielos se ha acercado."}, {"numero": 18, "texto": "Y andando Jesús junto á la mar de Galilea, vió á dos hermanos, Simón, que es llamado Pedro, y Andrés su hermano, que echaban la red en la mar; porque eran pescadores."}, {"numero": 19, "texto": "Y díceles: Venid en pos de mí, y os haré pescadores de hombres."}, {"numero": 20, "texto": "Ellos entonces, dejando luego las redes, le siguieron."}, {"numero": 21, "texto": "Y pasando de allí vió otros dos hermanos, Jacobo, hijo de Zebedeo, y Juan su hermano, en el barco con Zebedeo, su padre, que remendaban sus redes; y los llamó."}, {"numero": 22, "texto": "Y ellos, dejando luego el barco y á su padre, le siguieron."}, {"numero": 23, "texto": "Y rodeó Jesús toda Galilea, enseñando en las sinagogas de ellos, y predicando el evangelio del reino, y sanando toda enfermedad y toda dolencia en el pueblo."}, {"numero": 24, "texto": "Y corría su fama por toda la Siria; y le trajeron todos los que tenían mal: los tomados de diversas enfermedades y tormentos, y los endemoniados, y lunáticos, y paralíticos, y los sanó."}, {"numero": 25, "texto": "Y le siguieron muchas gentes de Galilea y de Decápolis y de Jerusalem y de Judea y de la otra parte del Jordán."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 5, 'pt', '[{"numero": 1, "texto": "E quando [Jesus] viu as multidões, subiu a um monte; e sentando-se, achegaram-se a ele os seus discípulos."}, {"numero": 2, "texto": "Então ele abriu sua boca e lhes ensinou, dizendo:"}, {"numero": 3, "texto": "Benditos são os humildes de espírito, porque deles é o Reino dos céus."}, {"numero": 4, "texto": "Benditos são os que choram, porque eles serão consolados."}, {"numero": 5, "texto": "Benditos são os mansos, porque eles herdarão a terra."}, {"numero": 6, "texto": "Benditos são os que têm fome e sede de justiça, porque eles serão saciados."}, {"numero": 7, "texto": "Benditos são os misericordiosos, porque eles alcançarão misericórdia."}, {"numero": 8, "texto": "Benditos são os limpos de coração, porque eles verão a Deus."}, {"numero": 9, "texto": "Benditos são os pacíficos, porque eles serão chamados filhos de Deus."}, {"numero": 10, "texto": "Benditos são os que sofrem perseguição por causa da justiça, porque deles é o Reino dos céus."}, {"numero": 11, "texto": "Benditos sois vós, quando vos insultarem, perseguirem, e mentirem, falando contra vós todo mal por minha causa."}, {"numero": 12, "texto": "Jubilai e alegrai-vos, porque grande é vossa recompensa nos céus; pois assim perseguiram aos profetas que foram antes de vós."}, {"numero": 13, "texto": "Vós sois o sal da terra; mas se o sal perder seu sabor, com que se salgará? Para nada mais presta, a não ser para se lançar fora, e ser pisado pelas pessoas."}, {"numero": 14, "texto": "Vós sois a luz do mundo; não se pode esconder uma cidade fundada sobre o monte;"}, {"numero": 15, "texto": "Nem se acende a lâmpada para se pôr debaixo de um cesto, mas sim na luminária, e ilumina a todos quantos estão na casa."}, {"numero": 16, "texto": "Assim brilhe vossa luz diante das pessoas, para que vejam vossas boas obras, e glorifiquem ao vosso Pai, que está nos céus."}, {"numero": 17, "texto": "Não penseis que vim para revogar a Lei ou os Profetas; não vim para revogar, mas sim para cumprir."}, {"numero": 18, "texto": "Porque em verdade vos digo que, até que o céu e a terra passem, nem um jota nem um til passará da Lei até que tudo se cumpra."}, {"numero": 19, "texto": "Portanto qualquer um que desobedecer a um destes menores mandamentos, e assim ensinar às pessoas, será chamado o menor no Reino dos céus; porém qualquer que [os] cumprir e ensinar, esse será chamado grande no Reino dos céus."}, {"numero": 20, "texto": "Porque eu vos digo que se a vossa justiça não for maior que a dos escribas e dos fariseus, de maneira nenhuma entrareis no Reino dos céus."}, {"numero": 21, "texto": "Ouvistes o que foi dito aos antigos: “Não cometerás homicídio”; “mas qualquer um que cometer homicídio será réu do julgamento”."}, {"numero": 22, "texto": "Porém eu vos digo que qualquer um que se irar contra seu irmão sem razão será réu do julgamento. E qualquer um que disser a seu irmão: “Idiota!” será réu do tribunal. E qualquer que [lhe] disser: “Louco!” será réu do fogo do inferno."}, {"numero": 23, "texto": "Portanto, se trouxeres tua oferta ao altar, e ali te lembrares que teu irmão tem algo contra ti,"}, {"numero": 24, "texto": "Deixa ali tua oferta diante do altar e vai primeiro reconciliar-te com teu irmão, e então vem oferecer a tua oferta."}, {"numero": 25, "texto": "Faze acordo depressa com teu adversário, enquanto estás com ele no caminho, para não acontecer que o adversário te entregue ao juiz, e o juiz te entregue ao oficial, e te lancem na prisão."}, {"numero": 26, "texto": "Em verdade te digo que não sairás dali enquanto não pagares a última moeda."}, {"numero": 27, "texto": "Ouvistes o que foi dito aos antigos: “Não adulterarás”."}, {"numero": 28, "texto": "Porém eu vos digo que qualquer um que olhar para uma mulher para a cobiçar, em seu coração já adulterou com ela."}, {"numero": 29, "texto": "Se o teu olho direito te faz pecar, arranca-o e lança-o de ti; porque é melhor para ti que um dos teus membros se perca do que o teu corpo todo seja lançado no inferno."}, {"numero": 30, "texto": "E se a tua mão direita te faz pecar, corta-a e lança-a de ti; porque é melhor para ti que um dos teus membros se perca do que o teu corpo todo seja lançado no inferno."}, {"numero": 31, "texto": "Também foi dito: “Qualquer um que se divorciar de sua mulher, dê a ela carta de divórcio."}, {"numero": 32, "texto": "Porém eu vos digo que qualquer um que se divorciar de sua mulher, a menos que seja por causa de pecado sexual, faz com que ela adultere; e qualquer um que se casar com a divorciada comete adultério."}, {"numero": 33, "texto": "Também ouvistes que foi dito aos antigos: “Não jurarás falsamente”, “mas cumprirás ao Senhor os teus juramentos”."}, {"numero": 34, "texto": "Porém eu vos digo que de maneira nenhuma jureis; nem pelo céu, porque é o trono de Deus;"}, {"numero": 35, "texto": "Nem pela terra, porque é o suporte de seus pés; nem por Jerusalém, porque é a cidade do grande Rei."}, {"numero": 36, "texto": "Nem por tua cabeça jurarás, pois nem sequer um cabelo podes tornar branco ou preto."}, {"numero": 37, "texto": "Mas seja vosso falar: “sim”, “sim”, “não”, “não”; porque o que disso passa procede do maligno."}, {"numero": 38, "texto": "Ouvistes o que foi dito: “Olho por olho, e dente por dente”."}, {"numero": 39, "texto": "Mas eu vos digo que não resistais a quem for mau; em vez disso, a qualquer um que te bater à tua face direita, apresenta-lhe também a outra."}, {"numero": 40, "texto": "E ao que quiser disputar contigo, e te tomar tua túnica, deixa-lhe também a capa."}, {"numero": 41, "texto": "E se qualquer um te obrigar a caminhar uma milha, vai com ele duas."}, {"numero": 42, "texto": "Dá a quem te pedir; e não te desvies de quem quiser de ti tomar emprestado."}, {"numero": 43, "texto": "Ouvistes o que foi dito: “Amarás teu próximo”, e “odiarás teu inimigo”."}, {"numero": 44, "texto": "Porém eu vos digo: amai vossos inimigos, bendizei os que vos maldizem, fazei bem aos que vos odeiam, e orai pelos que vos maltratam e vos perseguem,"}, {"numero": 45, "texto": "Para que sejais filhos de vosso Pai que está nos céus; porque ele faz seu sol sair sobre maus e bons, e chover sobre justos e injustos."}, {"numero": 46, "texto": "Pois se amardes os que vos amam, que recompensa tereis? Não fazem os publicanos também o mesmo?"}, {"numero": 47, "texto": "E se saudardes somente os vossos irmãos, o que fazeis de mais? Não fazem os publicanos também assim?"}, {"numero": 48, "texto": "Portanto, sede vós perfeitos, assim como vosso Pai que está nos céus é perfeito."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 5, 'en', '[{"numero": 1, "texto": "And seeing the multitudes, he went up into a mountain: and when he was set, his disciples came unto him:"}, {"numero": 2, "texto": "And he opened his mouth, and taught them, saying,"}, {"numero": 3, "texto": "Blessed are the poor in spirit: for theirs is the kingdom of heaven."}, {"numero": 4, "texto": "Blessed are they that mourn: for they shall be comforted."}, {"numero": 5, "texto": "Blessed are the meek: for they shall inherit the earth."}, {"numero": 6, "texto": "Blessed are they which do hunger and thirst after righteousness: for they shall be filled."}, {"numero": 7, "texto": "Blessed are the merciful: for they shall obtain mercy."}, {"numero": 8, "texto": "Blessed are the pure in heart: for they shall see God."}, {"numero": 9, "texto": "Blessed are the peacemakers: for they shall be called the children of God."}, {"numero": 10, "texto": "Blessed are they which are persecuted for righteousness'' sake: for theirs is the kingdom of heaven."}, {"numero": 11, "texto": "Blessed are ye, when men shall revile you, and persecute you, and shall say all manner of evil against you falsely, for my sake."}, {"numero": 12, "texto": "Rejoice, and be exceeding glad: for great is your reward in heaven: for so persecuted they the prophets which were before you."}, {"numero": 13, "texto": "Ye are the salt of the earth: but if the salt have lost his savour, wherewith shall it be salted? it is thenceforth good for nothing, but to be cast out, and to be trodden under foot of men."}, {"numero": 14, "texto": "Ye are the light of the world. A city that is set on an hill cannot be hid."}, {"numero": 15, "texto": "Neither do men light a candle, and put it under a bushel, but on a candlestick; and it giveth light unto all that are in the house."}, {"numero": 16, "texto": "Let your light so shine before men, that they may see your good works, and glorify your Father which is in heaven."}, {"numero": 17, "texto": "Think not that I am come to destroy the law, or the prophets: I am not come to destroy, but to fulfil."}, {"numero": 18, "texto": "For verily I say unto you, Till heaven and earth pass, one jot or one tittle shall in no wise pass from the law, till all be fulfilled."}, {"numero": 19, "texto": "Whosoever therefore shall break one of these least commandments, and shall teach men so, he shall be called the least in the kingdom of heaven: but whosoever shall do and teach them, the same shall be called great in the kingdom of heaven."}, {"numero": 20, "texto": "For I say unto you, That except your righteousness shall exceed the righteousness of the scribes and Pharisees, ye shall in no case enter into the kingdom of heaven."}, {"numero": 21, "texto": "Ye have heard that it was said of them of old time, Thou shalt not kill; and whosoever shall kill shall be in danger of the judgment:"}, {"numero": 22, "texto": "But I say unto you, That whosoever is angry with his brother without a cause shall be in danger of the judgment: and whosoever shall say to his brother, Raca, shall be in danger of the council: but whosoever shall say, Thou fool, shall be in danger of hell fire."}, {"numero": 23, "texto": "Therefore if thou bring thy gift to the altar, and there rememberest that thy brother hath ought against thee;"}, {"numero": 24, "texto": "Leave there thy gift before the altar, and go thy way; first be reconciled to thy brother, and then come and offer thy gift."}, {"numero": 25, "texto": "Agree with thine adversary quickly, whiles thou art in the way with him; lest at any time the adversary deliver thee to the judge, and the judge deliver thee to the officer, and thou be cast into prison."}, {"numero": 26, "texto": "Verily I say unto thee, Thou shalt by no means come out thence, till thou hast paid the uttermost farthing."}, {"numero": 27, "texto": "Ye have heard that it was said by them of old time, Thou shalt not commit adultery:"}, {"numero": 28, "texto": "But I say unto you, That whosoever looketh on a woman to lust after her hath committed adultery with her already in his heart."}, {"numero": 29, "texto": "And if thy right eye offend thee, pluck it out, and cast it from thee: for it is profitable for thee that one of thy members should perish, and not that thy whole body should be cast into hell."}, {"numero": 30, "texto": "And if thy right hand offend thee, cut it off, and cast it from thee: for it is profitable for thee that one of thy members should perish, and not that thy whole body should be cast into hell."}, {"numero": 31, "texto": "It hath been said, Whosoever shall put away his wife, let him give her a writing of divorcement:"}, {"numero": 32, "texto": "But I say unto you, That whosoever shall put away his wife, saving for the cause of fornication, causeth her to commit adultery: and whosoever shall marry her that is divorced committeth adultery."}, {"numero": 33, "texto": "Again, ye have heard that it hath been said by them of old time, Thou shalt not forswear thyself, but shalt perform unto the Lord thine oaths:"}, {"numero": 34, "texto": "But I say unto you, Swear not at all; neither by heaven; for it is God''s throne:"}, {"numero": 35, "texto": "Nor by the earth; for it is his footstool: neither by Jerusalem; for it is the city of the great King."}, {"numero": 36, "texto": "Neither shalt thou swear by thy head, because thou canst not make one hair white or black."}, {"numero": 37, "texto": "But let your communication be, Yea, yea; Nay, nay: for whatsoever is more than these cometh of evil."}, {"numero": 38, "texto": "Ye have heard that it hath been said, An eye for an eye, and a tooth for a tooth:"}, {"numero": 39, "texto": "But I say unto you, That ye resist not evil: but whosoever shall smite thee on thy right cheek, turn to him the other also."}, {"numero": 40, "texto": "And if any man will sue thee at the law, and take away thy coat, let him have thy cloak also."}, {"numero": 41, "texto": "And whosoever shall compel thee to go a mile, go with him twain."}, {"numero": 42, "texto": "Give to him that asketh thee, and from him that would borrow of thee turn not thou away."}, {"numero": 43, "texto": "Ye have heard that it hath been said, Thou shalt love thy neighbour, and hate thine enemy."}, {"numero": 44, "texto": "But I say unto you, Love your enemies, bless them that curse you, do good to them that hate you, and pray for them which despitefully use you, and persecute you;"}, {"numero": 45, "texto": "That ye may be the children of your Father which is in heaven: for he maketh his sun to rise on the evil and on the good, and sendeth rain on the just and on the unjust."}, {"numero": 46, "texto": "For if ye love them which love you, what reward have ye? do not even the publicans the same?"}, {"numero": 47, "texto": "And if ye salute your brethren only, what do ye more than others? do not even the publicans so?"}, {"numero": 48, "texto": "Be ye therefore perfect, even as your Father which is in heaven is perfect."}]'::jsonb, 'King James Version'),
  ('Mt', 5, 'fr', '[{"numero": 1, "texto": "Voyant la foule, Jésus monta sur la montagne; et, après qu''''il se fut assis, ses disciples s''''approchèrent de lui."}, {"numero": 2, "texto": "Puis, ayant ouvert la bouche, il les enseigna, et dit:"}, {"numero": 3, "texto": "Heureux les pauvres en esprit, car le royaume des cieux est à eux!"}, {"numero": 4, "texto": "Heureux les affligés, car ils seront consolés!"}, {"numero": 5, "texto": "Heureux les débonnaires, car ils hériteront la terre!"}, {"numero": 6, "texto": "Heureux ceux qui ont faim et soif de la justice, car ils seront rassasiés!"}, {"numero": 7, "texto": "Heureux les miséricordieux, car ils obtiendront miséricorde!"}, {"numero": 8, "texto": "Heureux ceux qui ont le coeur pur, car ils verront Dieu!"}, {"numero": 9, "texto": "Heureux ceux qui procurent la paix, car ils seront appelés fils de Dieu!"}, {"numero": 10, "texto": "Heureux ceux qui sont persécutés pour la justice, car le royaume des cieux est à eux!"}, {"numero": 11, "texto": "Heureux serez-vous, lorsqu''''on vous outragera, qu''''on vous persécutera et qu''''on dira faussement de vous toute sorte de mal, à cause de moi."}, {"numero": 12, "texto": "Réjouissez-vous et soyez dans l''''allégresse, parce que votre récompense sera grande dans les cieux; car c''''est ainsi qu''''on a persécuté les prophètes qui ont été avant vous."}, {"numero": 13, "texto": "Vous êtes le sel de la terre. Mais si le sel perd sa saveur, avec quoi la lui rendra-t-on? Il ne sert plus qu''''à être jeté dehors, et foulé aux pieds par les hommes."}, {"numero": 14, "texto": "Vous êtes la lumière du monde. Une ville située sur une montagne ne peut être cachée;"}, {"numero": 15, "texto": "et on n''''allume pas une lampe pour la mettre sous le boisseau, mais on la met sur le chandelier, et elle éclaire tous ceux qui sont dans la maison."}, {"numero": 16, "texto": "Que votre lumière luise ainsi devant les hommes, afin qu''''ils voient vos bonnes oeuvres, et qu''''ils glorifient votre Père qui est dans les cieux."}, {"numero": 17, "texto": "Ne croyez pas que je sois venu pour abolir la loi ou les prophètes; je suis venu non pour abolir, mais pour accomplir."}, {"numero": 18, "texto": "Car, je vous le dis en vérité, tant que le ciel et la terre ne passeront point, il ne disparaîtra pas de la loi un seul iota ou un seul trait de lettre, jusqu''''à ce que tout soit arrivé."}, {"numero": 19, "texto": "Celui donc qui supprimera l''''un de ces plus petits commandements, et qui enseignera aux hommes à faire de même, sera appelé le plus petit dans le royaume des cieux; mais celui qui les observera, et qui enseignera à les observer, celui-là sera appelé grand dans le royaume des cieux."}, {"numero": 20, "texto": "Car, je vous le dis, si votre justice ne surpasse celle des scribes et des pharisiens, vous n''''entrerez point dans le royaume des cieux."}, {"numero": 21, "texto": "Vous avez entendu qu''''il a été dit aux anciens: Tu ne tueras point; celui qui tuera mérite d''''être puni par les juges."}, {"numero": 22, "texto": "Mais moi, je vous dis que quiconque se met en colère contre son frère mérite d''''être puni par les juges; que celui qui dira à son frère: Raca! mérite d''''être puni par le sanhédrin; et que celui qui lui dira: Insensé! mérite d''''être puni par le feu de la géhenne."}, {"numero": 23, "texto": "Si donc tu présentes ton offrande à l''''autel, et que là tu te souviennes que ton frère a quelque chose contre toi,"}, {"numero": 24, "texto": "laisse là ton offrande devant l''''autel, et va d''''abord te réconcilier avec ton frère; puis, viens présenter ton offrande."}, {"numero": 25, "texto": "Accorde-toi promptement avec ton adversaire, pendant que tu es en chemin avec lui, de peur qu''''il ne te livre au juge, que le juge ne te livre à l''''officier de justice, et que tu ne sois mis en prison."}, {"numero": 26, "texto": "Je te le dis en vérité, tu ne sortiras pas de là que tu n''''aies payé le dernier quadrant."}, {"numero": 27, "texto": "Vous avez appris qu''''il a été dit: Tu ne commettras point d''''adultère."}, {"numero": 28, "texto": "Mais moi, je vous dis que quiconque regarde une femme pour la convoiter a déjà commis un adultère avec elle dans son coeur."}, {"numero": 29, "texto": "Si ton oeil droit est pour toi une occasion de chute, arrache-le et jette-le loin de toi; car il est avantageux pour toi qu''''un seul de tes membres périsse, et que ton corps entier ne soit pas jeté dans la géhenne."}, {"numero": 30, "texto": "Et si ta main droite est pour toi une occasion de chute, coupe-la et jette-la loin de toi; car il est avantageux pour toi qu''''un seul de tes membres périsse, et que ton corps entier n''''aille pas dans la géhenne."}, {"numero": 31, "texto": "Il a été dit: Que celui qui répudie sa femme lui donne une lettre de divorce."}, {"numero": 32, "texto": "Mais moi, je vous dis que celui qui répudie sa femme, sauf pour cause d''''infidélité, l''''expose à devenir adultère, et que celui qui épouse une femme répudiée commet un adultère."}, {"numero": 33, "texto": "Vous avez encore appris qu''''il a été dit aux anciens: Tu ne te parjureras point, mais tu t''''acquitteras envers le Seigneur de ce que tu as déclaré par serment."}, {"numero": 34, "texto": "Mais moi, je vous dis de ne jurer aucunement, ni par le ciel, parce que c''''est le trône de Dieu;"}, {"numero": 35, "texto": "ni par la terre, parce que c''''est son marchepied; ni par Jérusalem, parce que c''''est la ville du grand roi."}, {"numero": 36, "texto": "Ne jure pas non plus par ta tête, car tu ne peux rendre blanc ou noir un seul cheveu."}, {"numero": 37, "texto": "Que votre parole soit oui, oui, non, non; ce qu''''on y ajoute vient du malin."}, {"numero": 38, "texto": "Vous avez appris qu''''il a été dit: oeil pour oeil, et dent pour dent."}, {"numero": 39, "texto": "Mais moi, je vous dis de ne pas résister au méchant. Si quelqu''''un te frappe sur la joue droite, présente-lui aussi l''''autre."}, {"numero": 40, "texto": "Si quelqu''''un veut plaider contre toi, et prendre ta tunique, laisse-lui encore ton manteau."}, {"numero": 41, "texto": "Si quelqu''''un te force à faire un mille, fais-en deux avec lui."}, {"numero": 42, "texto": "Donne à celui qui te demande, et ne te détourne pas de celui qui veut emprunter de toi."}, {"numero": 43, "texto": "Vous avez appris qu''''il a été dit: Tu aimeras ton prochain, et tu haïras ton ennemi."}, {"numero": 44, "texto": "Mais moi, je vous dis: Aimez vos ennemis, bénissez ceux qui vous maudissent, faites du bien à ceux qui vous haïssent, et priez pour ceux qui vous maltraitent et qui vous persécutent,"}, {"numero": 45, "texto": "afin que vous soyez fils de votre Père qui est dans les cieux; car il fait lever son soleil sur les méchants et sur les bons, et il fait pleuvoir sur les justes et sur les injustes."}, {"numero": 46, "texto": "Si vous aimez ceux qui vous aiment, quelle récompense méritez-vous? Les publicains aussi n''''agissent-ils pas de même?"}, {"numero": 47, "texto": "Et si vous saluez seulement vos frères, que faites-vous d''''extraordinaire? Les païens aussi n''''agissent-ils pas de même?"}, {"numero": 48, "texto": "Soyez donc parfaits, comme votre Père céleste est parfait."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 5, 'es', '[{"numero": 1, "texto": "Y VIENDO las gentes, subió al monte; y sentándose, se llegaron á él sus discípulos."}, {"numero": 2, "texto": "Y abriendo su boca, les enseñaba, diciendo:"}, {"numero": 3, "texto": "Bienaventurados los pobres en espíritu: porque de ellos es el reino de los cielos."}, {"numero": 4, "texto": "Bienaventurados los que lloran: porque ellos recibirán consolación."}, {"numero": 5, "texto": "Bienaventurados los mansos: porque ellos recibirán la tierra por heredad."}, {"numero": 6, "texto": "Bienaventurados los que tienen hambre y sed de justicia: porque ellos serán hartos."}, {"numero": 7, "texto": "Bienaventurados los misericordiosos: porque ellos alcanzarán misericordia."}, {"numero": 8, "texto": "Bienaventurados los de limpio corazón: porque ellos verán á Dios."}, {"numero": 9, "texto": "Bienaventurados los pacificadores: porque ellos serán llamados hijos de Dios."}, {"numero": 10, "texto": "Bienaventurados los que padecen persecución por causa de la justicia: porque de ellos es el reino de los cielos."}, {"numero": 11, "texto": "Bienaventurados sois cuando os vituperaren y os persiguieren, y dijeren de vosotros todo mal por mi causa, mintiendo."}, {"numero": 12, "texto": "Gozaos y alegraos; porque vuestra merced es grande en los cielos: que así persiguieron á los profetas que fueron antes de vosotros."}, {"numero": 13, "texto": "Vosotros sois la sal de la tierra: y si la sal se desvaneciere ¿con qué será salada? no vale más para nada, sino para ser echada fuera y hollada de los hombres."}, {"numero": 14, "texto": "Vosotros sois la luz del mundo: una ciudad asentada sobre un monte no se puede esconder."}, {"numero": 15, "texto": "Ni se enciende una lámpara y se pone debajo de un almud, mas sobre el candelero, y alumbra á todos los que están en casa."}, {"numero": 16, "texto": "Así alumbre vuestra luz delante de los hombres, para que vean vuestras obras buenas, y glorifiquen á vuestro Padre que está en los cielos."}, {"numero": 17, "texto": "No penséis que he venido para abrogar la ley ó los profetas: no he venido para abrogar, sino á cumplir."}, {"numero": 18, "texto": "Porque de cierto os digo, que hasta que perezca el cielo y la tierra, ni una jota ni un tilde perecerá de la ley, hasta que todas las cosas sean hechas."}, {"numero": 19, "texto": "De manera que cualquiera que infringiere uno de estos mandamientos muy pequeños, y así enseñare á los hombres, muy pequeño será llamado en el reino de los cielos: mas cualquiera que hiciere y enseñare, éste será llamado grande en el reino de los cielos."}, {"numero": 20, "texto": "Porque os digo, que si vuestra justicia no fuere mayor que la de los escribas y de los Fariseos, no entraréis en el reino de los cielos."}, {"numero": 21, "texto": "Oísteis que fué dicho á los antiguos: No matarás; mas cualquiera que matare, será culpado del juicio."}, {"numero": 22, "texto": "Mas yo os digo, que cualquiera que se enojare locamente con su hermano, será culpado del juicio; y cualquiera que dijere á su hermano, Raca, será culpado del concejo; y cualquiera que dijere, Fatuo, será culpado del infierno del fuego."}, {"numero": 23, "texto": "Por tanto, si trajeres tu presente al altar, y allí te acordares de que tu hermano tiene algo contra ti,"}, {"numero": 24, "texto": "Deja allí tu presente delante del altar, y vete, vuelve primero en amistad con tu hermano, y entonces ven y ofrece tu presente."}, {"numero": 25, "texto": "Concíliate con tu adversario presto, entre tanto que estás con él en el camino; porque no acontezca que el adversario te entregue al juez, y el juez te entregue al alguacil, y seas echado en prisión."}, {"numero": 26, "texto": "De cierto te digo, que no saldrás de allí, hasta que pagues el último cuadrante."}, {"numero": 27, "texto": "Oísteis que fué dicho: No adulterarás:"}, {"numero": 28, "texto": "Mas yo os digo, que cualquiera que mira á una mujer para codiciarla, ya adulteró con ella en su corazón."}, {"numero": 29, "texto": "Por tanto, si tu ojo derecho te fuere ocasión de caer, sácalo, y échalo de ti: que mejor te es que se pierda uno de tus miembros, que no que todo tu cuerpo sea echado al infierno."}, {"numero": 30, "texto": "Y si tu mano derecha te fuere ocasión de caer, córtala, y échala de ti: que mejor te es que se pierda uno de tus miembros, que no que todo tu cuerpo sea echado al infierno."}, {"numero": 31, "texto": "También fué dicho: Cualquiera que repudiare á su mujer, déle carta de divorcio:"}, {"numero": 32, "texto": "Mas yo os digo, que el que repudiare á su mujer, fuera de causa de fornicación, hace que ella adultere; y el que se casare con la repudiada, comete adulterio."}, {"numero": 33, "texto": "Además habéis oído que fué dicho á los antiguos: No te perjurarás; mas pagarás al Señor tus juramentos."}, {"numero": 34, "texto": "Mas yo os digo: No juréis en ninguna manera: ni por el cielo, porque es el trono de Dios;"}, {"numero": 35, "texto": "Ni por la tierra, porque es el estrado de sus pies; ni por Jerusalem, porque es la ciudad del gran Rey."}, {"numero": 36, "texto": "Ni por tu cabeza jurarás, porque no puedes hacer un cabello blanco ó negro."}, {"numero": 37, "texto": "Mas sea vuestro hablar: Sí, sí; No, no; porque lo que es más de esto, de mal procede."}, {"numero": 38, "texto": "Oísteis que fué dicho á los antiguos: Ojo por ojo, y diente por diente."}, {"numero": 39, "texto": "Mas yo os digo: No resistáis al mal; antes á cualquiera que te hiriere en tu mejilla diestra, vuélvele también la otra;"}, {"numero": 40, "texto": "Y al que quisiere ponerte á pleito y tomarte tu ropa, déjale también la capa;"}, {"numero": 41, "texto": "Y á cualquiera que te cargare por una milla, ve con él dos."}, {"numero": 42, "texto": "Al que te pidiere, dale; y al que quisiere tomar de ti prestado, no se lo rehuses."}, {"numero": 43, "texto": "Oísteis que fué dicho: Amarás á tu prójimo, y aborrecerás á tu enemigo."}, {"numero": 44, "texto": "Mas yo os digo: Amad á vuestros enemigos, bendecid á los que os maldicen, haced bien á los que os aborrecen, y orad por los que os ultrajan y os persiguen;"}, {"numero": 45, "texto": "Para que seáis hijos de vuestro Padre que está en los cielos: que hace que su sol salga sobre malos y buenos, y llueve sobre justos é injustos."}, {"numero": 46, "texto": "Porque si amareis á los que os aman, ¿qué recompensa tendréis? ¿no hacen también lo mismo los publicanos?"}, {"numero": 47, "texto": "Y si abrazareis á vuestros hermanos solamente, ¿qué hacéis de más? ¿no hacen también así los Gentiles?"}, {"numero": 48, "texto": "Sed, pues, vosotros perfectos, como vuestro Padre que está en los cielos es perfecto."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 6, 'pt', '[{"numero": 1, "texto": "Ficai atentos para que não façais vossa esmola diante das pessoas a fim de que sejais vistos por elas; de outra maneira não tereis recompensa de vosso Pai que está nos céus."}, {"numero": 2, "texto": "Portanto, quando fizeres esmola, não faças tocar trombeta diante de ti, como fazem os hipócritas nas sinagogas e nas ruas, para serem honrados pelas pessoas; em verdade vos digo que já receberam sua recompensa."}, {"numero": 3, "texto": "Mas quando tu fizeres esmola, não saiba tua mão esquerda o que faz a tua direita;"}, {"numero": 4, "texto": "Para que a tua esmola seja em segredo, e teu Pai, que vê em segredo, ele te recompensará em público."}, {"numero": 5, "texto": "E quando orares, não sejas como os hipócritas; porque eles amam orar em pé nas sinagogas e nas esquinas das ruas para serem vistos pelas pessoas. Em verdade vos digo que já receberam sua recompensa."}, {"numero": 6, "texto": "Porém tu, quando orares, entra em teu quarto, fecha tua porta, e ora a teu Pai, que está em segredo; e teu Pai, que vê em segredo, ele te recompensará em público."}, {"numero": 7, "texto": "E quando orardes, não façais repetições inúteis como os gentios, que pensam que por muito falarem serão ouvidos."}, {"numero": 8, "texto": "Não sejais, pois, semelhantes a eles; porque vosso Pai sabe o que necessitais, antes que vós peçais a ele."}, {"numero": 9, "texto": "Vós, portanto, orareis assim: Pai nosso, que estás nos céus, santificado seja o teu nome."}, {"numero": 10, "texto": "Venha o teu Reino. Seja feita a tua vontade, tanto na terra, assim como no céu."}, {"numero": 11, "texto": "O pão nosso de cada dia nos dá hoje."}, {"numero": 12, "texto": "E perdoa-nos nossas dívidas, assim como nós também perdoamos aos nossos devedores."}, {"numero": 13, "texto": "E não nos conduzas à tentação, mas livra-nos do mal; porque teu é o Reino, o poder, e a glória, para sempre, Amém."}, {"numero": 14, "texto": "Porque se perdoardes às pessoas suas ofensas, vosso Pai celestial também vos perdoará;"}, {"numero": 15, "texto": "Mas se não perdoardes às pessoas suas ofensas, também vosso Pai não vos perdoará vossas ofensas."}, {"numero": 16, "texto": "E quando jejuardes, não vos mostreis tristonhos, como os hipócritas; porque eles desfiguram seus rostos, para parecerem aos outros que jejuam. Em verdade vos digo que eles já receberam sua recompensa."}, {"numero": 17, "texto": "Porém tu, quando jejuares, unge a tua cabeça e lava o teu rosto,"}, {"numero": 18, "texto": "Para não pareceres às pessoas que jejuas, mas sim ao teu Pai, que está em segredo; e teu Pai, que vê em segredo, ele te recompensará em público."}, {"numero": 19, "texto": "Não ajunteis para vós tesouros na terra, onde e a traça e a ferrugem gastam, e onde os ladrões invadem e roubam;"}, {"numero": 20, "texto": "Mas ajuntai para vós tesouros no céu, onde nem a traça nem a ferrugem gastam, e onde os ladrões não invadem nem roubam."}, {"numero": 21, "texto": "Porque onde estiver o vosso tesouro, ali estará também o vosso coração."}, {"numero": 22, "texto": "A lâmpada do corpo é o olho; portanto, se o teu olho for puro, todo o teu corpo será cheio de luz."}, {"numero": 23, "texto": "Porém se o teu olho for maligno, todo o teu corpo será cheio de trevas. Assim, se a luz que há em ti são trevas, como são grandes [essas] trevas!"}, {"numero": 24, "texto": "Ninguém pode servir a dois senhores; pois ou odiará um e amará outro; ou se apegará a um, e desprezará o outro. Não podeis servir a Deus e às riquezas."}, {"numero": 25, "texto": "Por isso vos digo: não andeis ansiosos por vossa vida, sobre o que haveis de comer, ou que haveis de beber; nem por vosso corpo, sobre com que vos haveis de vestir. Não é a vida mais que o alimento, e o corpo [mais] que a roupa?"}, {"numero": 26, "texto": "Olhai para as aves do céu, que não semeiam, nem ceifam, nem ajuntam em celeiros; e contudo vosso Pai celestial as alimenta. Não sois vós muito mais importantes que elas?"}, {"numero": 27, "texto": "E qual de vós poderá, por sua ansiedade, acrescentar um côvado à sua estatura?"}, {"numero": 28, "texto": "E por que andais ansiosos pela roupa? Prestai atenção aos lírios do campo, como crescem; eles nem trabalham nem fiam."}, {"numero": 29, "texto": "Mas eu vos digo que nem mesmo Salomão, em toda a sua glória, se vestiu como um deles."}, {"numero": 30, "texto": "Se Deus veste desta maneira a erva do campo, que hoje existe, e amanhã é lançada no forno, não [vestirá] ele muito mais a vós, que tendes pouca fé?"}, {"numero": 31, "texto": "Não andeis, pois, ansiosos, dizendo: “Que comeremos?” Ou “Que beberemos?” Ou “Com que nos vestiremos?”"}, {"numero": 32, "texto": "Porque os gentios buscam todas estas coisas, e vosso Pai celestial sabe que necessitais destas coisas, todas elas."}, {"numero": 33, "texto": "Mas buscai primeiramente o Reino de Deus e a sua justiça, e todas estas coisas vos serão acrescentadas."}, {"numero": 34, "texto": "Não andeis, pois, ansiosos pelo dia de amanhã, porque o amanhã cuidará de si mesmo. Basta a cada dia o seu mal."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 6, 'en', '[{"numero": 1, "texto": "Take heed that ye do not your alms before men, to be seen of them: otherwise ye have no reward of your Father which is in heaven."}, {"numero": 2, "texto": "Therefore when thou doest thine alms, do not sound a trumpet before thee, as the hypocrites do in the synagogues and in the streets, that they may have glory of men. Verily I say unto you, They have their reward."}, {"numero": 3, "texto": "But when thou doest alms, let not thy left hand know what thy right hand doeth:"}, {"numero": 4, "texto": "That thine alms may be in secret: and thy Father which seeth in secret himself shall reward thee openly."}, {"numero": 5, "texto": "And when thou prayest, thou shalt not be as the hypocrites are: for they love to pray standing in the synagogues and in the corners of the streets, that they may be seen of men. Verily I say unto you, They have their reward."}, {"numero": 6, "texto": "But thou, when thou prayest, enter into thy closet, and when thou hast shut thy door, pray to thy Father which is in secret; and thy Father which seeth in secret shall reward thee openly."}, {"numero": 7, "texto": "But when ye pray, use not vain repetitions, as the heathen do: for they think that they shall be heard for their much speaking."}, {"numero": 8, "texto": "Be not ye therefore like unto them: for your Father knoweth what things ye have need of, before ye ask him."}, {"numero": 9, "texto": "After this manner therefore pray ye: Our Father which art in heaven, Hallowed be thy name."}, {"numero": 10, "texto": "Thy kingdom come, Thy will be done in earth, as it is in heaven."}, {"numero": 11, "texto": "Give us this day our daily bread."}, {"numero": 12, "texto": "And forgive us our debts, as we forgive our debtors."}, {"numero": 13, "texto": "And lead us not into temptation, but deliver us from evil: For thine is the kingdom, and the power, and the glory, for ever. Amen."}, {"numero": 14, "texto": "For if ye forgive men their trespasses, your heavenly Father will also forgive you:"}, {"numero": 15, "texto": "But if ye forgive not men their trespasses, neither will your Father forgive your trespasses."}, {"numero": 16, "texto": "Moreover when ye fast, be not, as the hypocrites, of a sad countenance: for they disfigure their faces, that they may appear unto men to fast. Verily I say unto you, They have their reward."}, {"numero": 17, "texto": "But thou, when thou fastest, anoint thine head, and wash thy face;"}, {"numero": 18, "texto": "That thou appear not unto men to fast, but unto thy Father which is in secret: and thy Father, which seeth in secret, shall reward thee openly."}, {"numero": 19, "texto": "Lay not up for yourselves treasures upon earth, where moth and rust doth corrupt, and where thieves break through and steal:"}, {"numero": 20, "texto": "But lay up for yourselves treasures in heaven, where neither moth nor rust doth corrupt, and where thieves do not break through nor steal:"}, {"numero": 21, "texto": "For where your treasure is, there will your heart be also."}, {"numero": 22, "texto": "The light of the body is the eye: if therefore thine eye be single, thy whole body shall be full of light."}, {"numero": 23, "texto": "But if thine eye be evil, thy whole body shall be full of darkness. If therefore the light that is in thee be darkness, how great is that darkness!"}, {"numero": 24, "texto": "No man can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon."}, {"numero": 25, "texto": "Therefore I say unto you, Take no thought for your life, what ye shall eat, or what ye shall drink; nor yet for your body, what ye shall put on. Is not the life more than meat, and the body than raiment?"}, {"numero": 26, "texto": "Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?"}, {"numero": 27, "texto": "Which of you by taking thought can add one cubit unto his stature?"}, {"numero": 28, "texto": "And why take ye thought for raiment? Consider the lilies of the field, how they grow; they toil not, neither do they spin:"}, {"numero": 29, "texto": "And yet I say unto you, That even Solomon in all his glory was not arrayed like one of these."}, {"numero": 30, "texto": "Wherefore, if God so clothe the grass of the field, which to day is, and to morrow is cast into the oven, shall he not much more clothe you, O ye of little faith?"}, {"numero": 31, "texto": "Therefore take no thought, saying, What shall we eat? or, What shall we drink? or, Wherewithal shall we be clothed?"}, {"numero": 32, "texto": "(For after all these things do the Gentiles seek:) for your heavenly Father knoweth that ye have need of all these things."}, {"numero": 33, "texto": "But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you."}, {"numero": 34, "texto": "Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof."}]'::jsonb, 'King James Version'),
  ('Mt', 6, 'fr', '[{"numero": 1, "texto": "Gardez-vous de pratiquer votre justice devant les hommes, pour en être vus; autrement, vous n''''aurez point de récompense auprès de votre Père qui est dans les cieux."}, {"numero": 2, "texto": "Lors donc que tu fais l''''aumône, ne sonne pas de la trompette devant toi, comme font les hypocrites dans les synagogues et dans les rues, afin d''''être glorifiés par les hommes. Je vous le dis en vérité, ils reçoivent leur récompense."}, {"numero": 3, "texto": "Mais quand tu fais l''''aumône, que ta main gauche ne sache pas ce que fait ta droite,"}, {"numero": 4, "texto": "afin que ton aumône se fasse en secret; et ton Père, qui voit dans le secret, te le rendra."}, {"numero": 5, "texto": "Lorsque vous priez, ne soyez pas comme les hypocrites, qui aiment à prier debout dans les synagogues et aux coins des rues, pour être vus des hommes. Je vous le dis en vérité, ils reçoivent leur récompense."}, {"numero": 6, "texto": "Mais quand tu pries, entre dans ta chambre, ferme ta porte, et prie ton Père qui est là dans le lieu secret; et ton Père, qui voit dans le secret, te le rendra."}, {"numero": 7, "texto": "En priant, ne multipliez pas de vaines paroles, comme les païens, qui s''''imaginent qu''''à force de paroles ils seront exaucés."}, {"numero": 8, "texto": "Ne leur ressemblez pas; car votre Père sait de quoi vous avez besoin, avant que vous le lui demandiez."}, {"numero": 9, "texto": "Voici donc comment vous devez prier: Notre Père qui es aux cieux! Que ton nom soit sanctifié;"}, {"numero": 10, "texto": "que ton règne vienne; que ta volonté soit faite sur la terre comme au ciel."}, {"numero": 11, "texto": "Donne-nous aujourd''''hui notre pain quotidien;"}, {"numero": 12, "texto": "pardonne-nous nos offenses, comme nous aussi nous pardonnons à ceux qui nous ont offensés;"}, {"numero": 13, "texto": "ne nous induis pas en tentation, mais délivre-nous du malin. Car c''''est à toi qu''''appartiennent, dans tous les siècles, le règne, la puissance et la gloire. Amen!"}, {"numero": 14, "texto": "Si vous pardonnez aux hommes leurs offenses, votre Père céleste vous pardonnera aussi;"}, {"numero": 15, "texto": "mais si vous ne pardonnez pas aux hommes, votre Père ne vous pardonnera pas non plus vos offenses."}, {"numero": 16, "texto": "Lorsque vous jeûnez, ne prenez pas un air triste, comme les hypocrites, qui se rendent le visage tout défait, pour montrer aux hommes qu''''ils jeûnent. Je vous le dis en vérité, ils reçoivent leur récompense."}, {"numero": 17, "texto": "Mais quand tu jeûnes, parfume ta tête et lave ton visage,"}, {"numero": 18, "texto": "afin de ne pas montrer aux hommes que tu jeûnes, mais à ton Père qui est là dans le lieu secret; et ton Père, qui voit dans le secret, te le rendra."}, {"numero": 19, "texto": "Ne vous amassez pas des trésors sur la terre, où la teigne et la rouille détruisent, et où les voleurs percent et dérobent;"}, {"numero": 20, "texto": "mais amassez-vous des trésors dans le ciel, où la teigne et la rouille ne détruisent point, et où les voleurs ne percent ni ne dérobent."}, {"numero": 21, "texto": "Car là où est ton trésor, là aussi sera ton coeur."}, {"numero": 22, "texto": "L''''oeil est la lampe du corps. Si ton oeil est en bon état, tout ton corps sera éclairé;"}, {"numero": 23, "texto": "mais si ton oeil est en mauvais état, tout ton corps sera dans les ténèbres. Si donc la lumière qui est en toi est ténèbres, combien seront grandes ces ténèbres!"}, {"numero": 24, "texto": "Nul ne peut servir deux maîtres. Car, ou il haïra l''''un, et aimera l''''autre; ou il s''''attachera à l''''un, et méprisera l''''autre. Vous ne pouvez servir Dieu et Mamon."}, {"numero": 25, "texto": "C''''est pourquoi je vous dis: Ne vous inquiétez pas pour votre vie de ce que vous mangerez, ni pour votre corps, de quoi vous serez vêtus. La vie n''''est-elle pas plus que la nourriture, et le corps plus que le vêtement?"}, {"numero": 26, "texto": "Regardez les oiseaux du ciel: ils ne sèment ni ne moissonnent, et ils n''''amassent rien dans des greniers; et votre Père céleste les nourrit. Ne valez-vous pas beaucoup plus qu''''eux?"}, {"numero": 27, "texto": "Qui de vous, par ses inquiétudes, peut ajouter une coudée à la durée de sa vie?"}, {"numero": 28, "texto": "Et pourquoi vous inquiéter au sujet du vêtement? Considérez comment croissent les lis des champs: ils ne travaillent ni ne filent;"}, {"numero": 29, "texto": "cependant je vous dis que Salomon même, dans toute sa gloire, n''''a pas été vêtu comme l''''un d''''eux."}, {"numero": 30, "texto": "Si Dieu revêt ainsi l''''herbe des champs, qui existe aujourd''''hui et qui demain sera jetée au four, ne vous vêtira-t-il pas à plus forte raison, gens de peu de foi?"}, {"numero": 31, "texto": "Ne vous inquiétez donc point, et ne dites pas: Que mangerons-nous? que boirons-nous? de quoi serons-nous vêtus?"}, {"numero": 32, "texto": "Car toutes ces choses, ce sont les païens qui les recherchent. Votre Père céleste sait que vous en avez besoin."}, {"numero": 33, "texto": "Cherchez premièrement le royaume et la justice de Dieu; et toutes ces choses vous seront données par-dessus."}, {"numero": 34, "texto": "Ne vous inquiétez donc pas du lendemain; car le lendemain aura soin de lui-même. A chaque jour suffit sa peine."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 6, 'es', '[{"numero": 1, "texto": "MIRAD que no hagáis vuestra justicia delante de los hombres, para ser vistos de ellos: de otra manera no tendréis merced de vuestro Padre que está en los cielos."}, {"numero": 2, "texto": "Cuando pues haces limosna, no hagas tocar trompeta delante de ti, como hacen los hipócritas en las sinagogas y en las plazas, para ser estimados de los hombres: de cierto os digo, que ya tienen su recompensa."}, {"numero": 3, "texto": "Mas cuando tú haces limosna, no sepa tu izquierda lo que hace tu derecha;"}, {"numero": 4, "texto": "Para que sea tu limosna en secreto: y tu Padre que ve en secreto, él te recompensará en público."}, {"numero": 5, "texto": "Y cuando oras, no seas como los hipócritas; porque ellos aman el orar en las sinagogas, y en los cantones de las calles en pie, para ser vistos de los hombres: de cierto os digo, que ya tienen su pago."}, {"numero": 6, "texto": "Mas tú, cuando oras, éntrate en tu cámara, y cerrada tu puerta, ora á tu Padre que está en secreto; y tu Padre que ve en secreto, te recompensará en público."}, {"numero": 7, "texto": "Y orando, no seáis prolijos, como los Gentiles; que piensan que por su parlería serán oídos."}, {"numero": 8, "texto": "No os hagáis, pues, semejantes á ellos; porque vuestro Padre sabe de qué cosas tenéis necesidad, antes que vosotros le pidáis."}, {"numero": 9, "texto": "Vosotros pues, oraréis así: Padre nuestro que estás en los cielos, santificado sea tu nombre."}, {"numero": 10, "texto": "Venga tu reino. Sea hecha tu voluntad, como en el cielo, así también en la tierra."}, {"numero": 11, "texto": "Danos hoy nuestro pan cotidiano."}, {"numero": 12, "texto": "Y perdónanos nuestras deudas, como también nosotros perdonamos á nuestros deudores."}, {"numero": 13, "texto": "Y no nos metas en tentación, mas líbranos del mal: porque tuyo es el reino, y el poder, y la gloria, por todos los siglos. Amén."}, {"numero": 14, "texto": "Porque si perdonareis á los hombres sus ofensas, os perdonará también á vosotros vuestro Padre celestial."}, {"numero": 15, "texto": "Mas si no perdonareis á los hombres sus ofensas, tampoco vuestro Padre os perdonará vuestras ofensas."}, {"numero": 16, "texto": "Y cuando ayunáis, no seáis como los hipócritas, austeros; porque ellos demudan sus rostros para parecer á los hombres que ayunan: de cierto os digo, que ya tienen su pago."}, {"numero": 17, "texto": "Mas tú, cuando ayunas, unge tu cabeza y lava tu rostro;"}, {"numero": 18, "texto": "Para no parecer á los hombres que ayunas, sino á tu Padre que está en secreto: y tu Padre que ve en secreto, te recompensará en público."}, {"numero": 19, "texto": "No os hagáis tesoros en la tierra, donde la polilla y el orín corrompe, y donde ladrones minan y hurtan;"}, {"numero": 20, "texto": "Mas haceos tesoros en el cielo, donde ni polilla ni orín corrompe, y donde ladrones no minan ni hurtan:"}, {"numero": 21, "texto": "Porque donde estuviere vuestro tesoro, allí estará vuestro corazón."}, {"numero": 22, "texto": "La lámpara del cuerpo es el ojo: así que, si tu ojo fuere sincero, todo tu cuerpo será luminoso:"}, {"numero": 23, "texto": "Mas si tu ojo fuere malo, todo tu cuerpo será tenebroso. Así que, si la lumbre que en ti hay son tinieblas, ¿cuántas serán las mismas tinieblas?"}, {"numero": 24, "texto": "Ninguno puede servir á dos señores; porque ó aborrecerá al uno y amará al otro, ó se llegará al uno y menospreciará al otro: no podéis servir á Dios y á Mammón."}, {"numero": 25, "texto": "Por tanto os digo: No os congojéis por vuestra vida, qué habéis de comer, ó qué habéis de beber; ni por vuestro cuerpo, qué habéis de vestir: ¿no es la vida más que el alimento, y el cuerpo que el vestido?"}, {"numero": 26, "texto": "Mirad las aves del cielo, que no siembran, ni siegan, ni allegan en alfolíes; y vuestro Padre celestial las alimenta. ¿No sois vosotros mucho mejores que ellas?"}, {"numero": 27, "texto": "Mas ¿quién de vosotros podrá, congojándose, añadir á su estatura un codo?"}, {"numero": 28, "texto": "Y por el vestido ¿por qué os congojáis? Reparad los lirios del campo, cómo crecen; no trabajan ni hilan;"}, {"numero": 29, "texto": "Mas os digo, que ni aun Salomón con toda su gloria fué vestido así como uno de ellos."}, {"numero": 30, "texto": "Y si la hierba del campo que hoy es, y mañana es echada en el horno, Dios la viste así, ¿no hará mucho más á vosotros, hombres de poca fe?"}, {"numero": 31, "texto": "No os congojéis pues, diciendo: ¿Qué comeremos, ó qué beberemos, ó con qué nos cubriremos?"}, {"numero": 32, "texto": "Porque los Gentiles buscan todas estas cosas: que vuestro Padre celestial sabe que de todas estas cosas habéis menester."}, {"numero": 33, "texto": "Mas buscad primeramente el reino de Dios y su justicia, y todas estas cosas os serán añadidas."}, {"numero": 34, "texto": "Así que, no os congojéis por el día de mañana; que el día de mañana traerá su fatiga: basta al día su afán."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 7, 'pt', '[{"numero": 1, "texto": "Não julgueis, para que não sejais julgados."}, {"numero": 2, "texto": "Porque com o juízo que julgardes sereis julgados; e com a medida que medirdes vos medirão de volta."}, {"numero": 3, "texto": "Ora, por que vês o cisco que está no olho de teu irmão e não enxergas a trave que está em teu próprio olho?"}, {"numero": 4, "texto": "Ou como dirás a teu irmão: “Deixa-me tirar o cisco do teu olho”, se eis que há uma trave em teu próprio olho?"}, {"numero": 5, "texto": "Hipócrita! Tira primeiro a trave do teu olho, e então verás claramente para tirar o cisco do olho de teu irmão."}, {"numero": 6, "texto": "Não deis o que é santo aos cães, nem lanceis vossas pérolas diante dos porcos, para não acontecer de as pisarem com os pés e, virando-se, vos despedacem."}, {"numero": 7, "texto": "Pedi, e vos será dado; buscai, e achareis; batei, e vos será aberto;"}, {"numero": 8, "texto": "Pois qualquer um que pede recebe; e quem busca acha; e ao que bate lhe é aberto."}, {"numero": 9, "texto": "E quem há dentre vós que, se seu filho pedir pão, lhe dará uma pedra?"}, {"numero": 10, "texto": "E se pedir peixe, lhe dará uma serpente?"}, {"numero": 11, "texto": "Ora, se vós, sendo maus, sabeis dar bons presentes a vossos filhos, quanto mais o vosso Pai, que está nos céus, dará coisas boas aos que lhe pedirem!"}, {"numero": 12, "texto": "Portanto tudo o que quiserdes que os outros vos façam, fazei-lhes vós também assim; porque esta é a Lei e os Profetas."}, {"numero": 13, "texto": "Entrai pela porta estreita; porque larga é a porta, e espaçoso o caminho que leva à perdição; e muitos são os que por ela entram."}, {"numero": 14, "texto": "Porque estreita é a porta, e apertado o caminho que leva à vida; e são poucos os que a acham."}, {"numero": 15, "texto": "Tende cuidado, porém, com os falsos profetas, que vêm a vós com roupa de ovelhas, mas por dentro são lobos vorazes."}, {"numero": 16, "texto": "Vós os conhecereis pelos seus frutos. Por acaso se colhem uvas dos espinheiros, ou figos dos cardos?"}, {"numero": 17, "texto": "Assim toda boa árvore dá bons frutos, mas a arvore má dá frutos maus."}, {"numero": 18, "texto": "A boa árvore não pode dar frutos maus, nem a árvore má dar bons frutos."}, {"numero": 19, "texto": "Toda árvore que não dá bom fruto é cortada e lançada ao fogo."}, {"numero": 20, "texto": "Portanto vós os conhecereis pelos seus frutos."}, {"numero": 21, "texto": "Não é qualquer um que me diz: “Senhor, Senhor” que entrará no Reino dos céus; mas sim aquele que faz a vontade do meu Pai que está nos céus."}, {"numero": 22, "texto": "Muitos me dirão naquele dia: “Senhor, Senhor! Não profetizamos em teu nome? E em teu nome não expulsamos os demônios? E em teu nome não fizemos muitas maravilhas?”"}, {"numero": 23, "texto": "Então claramente lhes direi: “Nunca vos conheci. Afastai-vos de mim, transgressores!”"}, {"numero": 24, "texto": "Portanto todo o que ouve estas minhas palavras e as pratica, eu o compararei ao homem prudente, que construiu sua casa sobre a rocha."}, {"numero": 25, "texto": "E a chuva desceu, correntezas vieram, ventos sopraram, e atingiram aquela casa; e ela não caiu, porque estava fundada sobre a rocha."}, {"numero": 26, "texto": "Porém todo o que ouve estas minhas palavras e não as pratica, eu o compararei ao homem tolo, que construiu sua casa sobre a areia."}, {"numero": 27, "texto": "E a chuva desceu, correntezas vieram, ventos sopraram, e atingiram aquela casa; e ela caiu, e sua queda foi grande."}, {"numero": 28, "texto": "E aconteceu que, quando Jesus terminou estas palavras, as multidões estavam admiradas de sua doutrina,"}, {"numero": 29, "texto": "porque ele os ensinava como tendo autoridade, e não como os escribas."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 7, 'en', '[{"numero": 1, "texto": "Judge not, that ye be not judged."}, {"numero": 2, "texto": "For with what judgment ye judge, ye shall be judged: and with what measure ye mete, it shall be measured to you again."}, {"numero": 3, "texto": "And why beholdest thou the mote that is in thy brother''s eye, but considerest not the beam that is in thine own eye?"}, {"numero": 4, "texto": "Or how wilt thou say to thy brother, Let me pull out the mote out of thine eye; and, behold, a beam is in thine own eye?"}, {"numero": 5, "texto": "Thou hypocrite, first cast out the beam out of thine own eye; and then shalt thou see clearly to cast out the mote out of thy brother''s eye."}, {"numero": 6, "texto": "Give not that which is holy unto the dogs, neither cast ye your pearls before swine, lest they trample them under their feet, and turn again and rend you."}, {"numero": 7, "texto": "Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you:"}, {"numero": 8, "texto": "For every one that asketh receiveth; and he that seeketh findeth; and to him that knocketh it shall be opened."}, {"numero": 9, "texto": "Or what man is there of you, whom if his son ask bread, will he give him a stone?"}, {"numero": 10, "texto": "Or if he ask a fish, will he give him a serpent?"}, {"numero": 11, "texto": "If ye then, being evil, know how to give good gifts unto your children, how much more shall your Father which is in heaven give good things to them that ask him?"}, {"numero": 12, "texto": "Therefore all things whatsoever ye would that men should do to you, do ye even so to them: for this is the law and the prophets."}, {"numero": 13, "texto": "Enter ye in at the strait gate: for wide is the gate, and broad is the way, that leadeth to destruction, and many there be which go in thereat:"}, {"numero": 14, "texto": "Because strait is the gate, and narrow is the way, which leadeth unto life, and few there be that find it."}, {"numero": 15, "texto": "Beware of false prophets, which come to you in sheep''s clothing, but inwardly they are ravening wolves."}, {"numero": 16, "texto": "Ye shall know them by their fruits. Do men gather grapes of thorns, or figs of thistles?"}, {"numero": 17, "texto": "Even so every good tree bringeth forth good fruit; but a corrupt tree bringeth forth evil fruit."}, {"numero": 18, "texto": "A good tree cannot bring forth evil fruit, neither can a corrupt tree bring forth good fruit."}, {"numero": 19, "texto": "Every tree that bringeth not forth good fruit is hewn down, and cast into the fire."}, {"numero": 20, "texto": "Wherefore by their fruits ye shall know them."}, {"numero": 21, "texto": "Not every one that saith unto me, Lord, Lord, shall enter into the kingdom of heaven; but he that doeth the will of my Father which is in heaven."}, {"numero": 22, "texto": "Many will say to me in that day, Lord, Lord, have we not prophesied in thy name? and in thy name have cast out devils? and in thy name done many wonderful works?"}, {"numero": 23, "texto": "And then will I profess unto them, I never knew you: depart from me, ye that work iniquity."}, {"numero": 24, "texto": "Therefore whosoever heareth these sayings of mine, and doeth them, I will liken him unto a wise man, which built his house upon a rock:"}, {"numero": 25, "texto": "And the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell not: for it was founded upon a rock."}, {"numero": 26, "texto": "And every one that heareth these sayings of mine, and doeth them not, shall be likened unto a foolish man, which built his house upon the sand:"}, {"numero": 27, "texto": "And the rain descended, and the floods came, and the winds blew, and beat upon that house; and it fell: and great was the fall of it."}, {"numero": 28, "texto": "And it came to pass, when Jesus had ended these sayings, the people were astonished at his doctrine:"}, {"numero": 29, "texto": "For he taught them as one having authority, and not as the scribes."}]'::jsonb, 'King James Version'),
  ('Mt', 7, 'fr', '[{"numero": 1, "texto": "Ne jugez point, afin que vous ne soyez point jugés."}, {"numero": 2, "texto": "Car on vous jugera du jugement dont vous jugez, et l''''on vous mesurera avec la mesure dont vous mesurez."}, {"numero": 3, "texto": "Pourquoi vois-tu la paille qui est dans l''''oeil de ton frère, et n''''aperçois-tu pas la poutre qui est dans ton oeil?"}, {"numero": 4, "texto": "Ou comment peux-tu dire à ton frère: Laisse-moi ôter une paille de ton oeil, toi qui as une poutre dans le tien?"}, {"numero": 5, "texto": "Hypocrite, ôte premièrement la poutre de ton oeil, et alors tu verras comment ôter la paille de l''''oeil de ton frère."}, {"numero": 6, "texto": "Ne donnez pas les choses saintes aux chiens, et ne jetez pas vos perles devant les pourceaux, de peur qu''''ils ne les foulent aux pieds, ne se retournent et ne vous déchirent."}, {"numero": 7, "texto": "Demandez, et l''''on vous donnera; cherchez, et vous trouverez; frappez, et l''''on vous ouvrira."}, {"numero": 8, "texto": "Car quiconque demande reçoit, celui qui cherche trouve, et l''''on ouvre à celui qui frappe."}, {"numero": 9, "texto": "Lequel de vous donnera une pierre à son fils, s''''il lui demande du pain?"}, {"numero": 10, "texto": "Ou, s''''il demande un poisson, lui donnera-t-il un serpent?"}, {"numero": 11, "texto": "Si donc, méchants comme vous l''''êtes, vous savez donner de bonnes choses à vos enfants, à combien plus forte raison votre Père qui est dans les cieux donnera-t-il de bonnes choses à ceux qui les lui demandent."}, {"numero": 12, "texto": "Tout ce que vous voulez que les hommes fassent pour vous, faites-le de même pour eux, car c''''est la loi et les prophètes."}, {"numero": 13, "texto": "Entrez par la porte étroite. Car large est la porte, spacieux est le chemin qui mènent à la perdition, et il y en a beaucoup qui entrent par là."}, {"numero": 14, "texto": "Mais étroite est la porte, resserré le chemin qui mènent à la vie, et il y en a peu qui les trouvent."}, {"numero": 15, "texto": "Gardez-vous des faux prophètes. Ils viennent à vous en vêtements de brebis, mais au dedans ce sont des loups ravisseurs."}, {"numero": 16, "texto": "Vous les reconnaîtrez à leurs fruits. Cueille-t-on des raisins sur des épines, ou des figues sur des chardons?"}, {"numero": 17, "texto": "Tout bon arbre porte de bons fruits, mais le mauvais arbre porte de mauvais fruits."}, {"numero": 18, "texto": "Un bon arbre ne peut porter de mauvais fruits, ni un mauvais arbre porter de bons fruits."}, {"numero": 19, "texto": "Tout arbre qui ne porte pas de bons fruits est coupé et jeté au feu."}, {"numero": 20, "texto": "C''''est donc à leurs fruits que vous les reconnaîtrez."}, {"numero": 21, "texto": "Ceux qui me disent: Seigneur, Seigneur! n''''entreront pas tous dans le royaume des cieux, mais celui-là seul qui fait la volonté de mon Père qui est dans les cieux."}, {"numero": 22, "texto": "Plusieurs me diront en ce jour-là: Seigneur, Seigneur, n''''avons-nous pas prophétisé par ton nom? n''''avons-nous pas chassé des démons par ton nom? et n''''avons-nous pas fait beaucoup de miracles par ton nom?"}, {"numero": 23, "texto": "Alors je leur dirai ouvertement: Je ne vous ai jamais connus, retirez-vous de moi, vous qui commettez l''''iniquité."}, {"numero": 24, "texto": "C''''est pourquoi, quiconque entend ces paroles que je dis et les met en pratique, sera semblable à un homme prudent qui a bâti sa maison sur le roc."}, {"numero": 25, "texto": "La pluie est tombée, les torrents sont venus, les vents ont soufflé et se sont jetés contre cette maison: elle n''''est point tombée, parce qu''''elle était fondée sur le roc."}, {"numero": 26, "texto": "Mais quiconque entend ces paroles que je dis, et ne les met pas en pratique, sera semblable à un homme insensé qui a bâti sa maison sur le sable."}, {"numero": 27, "texto": "La pluie est tombée, les torrents sont venus, les vents ont soufflé et ont battu cette maison: elle est tombée, et sa ruine a été grande."}, {"numero": 28, "texto": "Après que Jésus eut achevé ces discours, la foule fut frappée de sa doctrine;"}, {"numero": 29, "texto": "car il enseignait comme ayant autorité, et non pas comme leurs scribes."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 7, 'es', '[{"numero": 1, "texto": "NO juzguéis, para que no seáis juzgados."}, {"numero": 2, "texto": "Porque con el juicio con que juzgáis, seréis juzgados; y con la medida con que medís, os volverán á medir."}, {"numero": 3, "texto": "Y ¿por qué miras la mota que está en el ojo de tu hermano, y no echas de ver la viga que está en tu ojo?"}, {"numero": 4, "texto": "O ¿cómo dirás á tu hermano: Espera, echaré de tu ojo la mota, y he aquí la viga en tu ojo?"}, {"numero": 5, "texto": "¡Hipócrita! echa primero la viga de tu ojo, y entonces mirarás en echar la mota del ojo de tu hermano."}, {"numero": 6, "texto": "No deis lo santo á los perros, ni echéis vuestras perlas delante de los puercos; porque no las rehuellen con sus pies, y vuelvan y os despedacen."}, {"numero": 7, "texto": "Pedid, y se os dará; buscad, y hallaréis; llamad, y se os abrirá."}, {"numero": 8, "texto": "Porque cualquiera que pide, recibe; y el que busca, halla; y al que llama, se abrirá."}, {"numero": 9, "texto": "¿Qué hombre hay de vosotros, á quien si su hijo pidiere pan, le dará una piedra?"}, {"numero": 10, "texto": "¿Y si le pidiere un pez, le dará una serpiente?"}, {"numero": 11, "texto": "Pues si vosotros, siendo malos, sabéis dar buenas dádivas á vuestros hijos, ¿cuánto más vuestro Padre que está en los cielos, dará buenas cosas á los que le piden?"}, {"numero": 12, "texto": "Así que, todas las cosas que quisierais que los hombres hiciesen con vosotros, así también haced vosotros con ellos; porque esta es la ley y los profetas."}, {"numero": 13, "texto": "Entrad por la puerta estrecha: porque ancha es la puerta, y espacioso el camino que lleva á perdición, y muchos son los que entran por ella."}, {"numero": 14, "texto": "Porque estrecha es la puerta, y angosto el camino que lleva á la vida, y pocos son los que la hallan."}, {"numero": 15, "texto": "Y guardaos de los falsos profetas, que vienen á vosotros con vestidos de ovejas, mas de dentro son lobos rapaces."}, {"numero": 16, "texto": "Por sus frutos los conoceréis. ¿Cógense uvas de los espinos, ó higos de los abrojos?"}, {"numero": 17, "texto": "Así, todo buen árbol lleva buenos frutos; mas el árbol maleado lleva malos frutos."}, {"numero": 18, "texto": "No puede el buen árbol llevar malos frutos, ni el árbol maleado llevar frutos buenos."}, {"numero": 19, "texto": "Todo árbol que no lleva buen fruto, córtase y échase en el fuego."}, {"numero": 20, "texto": "Así que, por sus frutos los conoceréis."}, {"numero": 21, "texto": "No todo el que me dice: Señor, Señor, entrará en el reino de los cielos: mas el que hiciere la voluntad de mi Padre que está en los cielos."}, {"numero": 22, "texto": "Muchos me dirán en aquel día: Señor, Señor, ¿no profetizamos en tu nombre, y en tu nombre lanzamos demonios, y en tu nombre hicimos muchos milagros?"}, {"numero": 23, "texto": "Y entonces les protestaré: Nunca os conocí; apartaos de mí, obradores de maldad."}, {"numero": 24, "texto": "Cualquiera, pues, que me oye estas palabras, y las hace, le compararé á un hombre prudente, que edificó su casa sobre la peña;"}, {"numero": 25, "texto": "Y descendió lluvia, y vinieron ríos, y soplaron vientos, y combatieron aquella casa; y no cayó: porque estaba fundada sobre la peña."}, {"numero": 26, "texto": "Y cualquiera que me oye estas palabras, y no las hace, le compararé á un hombre insensato, que edificó su casa sobre la arena;"}, {"numero": 27, "texto": "Y descendió lluvia, y vinieron ríos, y soplaron vientos, é hicieron ímpetu en aquella casa; y cayó, y fué grande su ruina."}, {"numero": 28, "texto": "Y fué que, como Jesús acabó estas palabras, las gentes se admiraban de su doctrina;"}, {"numero": 29, "texto": "Porque les enseñaba como quien tiene autoridad, y no como los escribas."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 8, 'pt', '[{"numero": 1, "texto": "Quando ele desceu do monte, muitas multidões o seguiram."}, {"numero": 2, "texto": "E eis que um leproso veio e prostrou-se diante dele, dizendo: Senhor, se quiseres, podes me limpar."}, {"numero": 3, "texto": "Jesus estendeu a mão e o tocou, dizendo: Quero, sê limpo. E logo ele ficou limpo de sua lepra."}, {"numero": 4, "texto": "Então Jesus lhe disse: Tem o cuidado de dizeres a ninguém; mas vai mostrar-te ao sacerdote, e oferece a oferta que Moisés ordenou, para que lhes haja testemunho."}, {"numero": 5, "texto": "Quando Jesus entrou em Cafarnaum, veio a ele um centurião, rogando-lhe,"}, {"numero": 6, "texto": "E dizendo: Senhor, o meu servo jaz em casa, paralítico, e gravemente atormentado."}, {"numero": 7, "texto": "E Jesus lhe disse: Eu irei, e o curarei."}, {"numero": 8, "texto": "E o centurião respondeu: Senhor, não sou digno de que entres sob meu telhado; mas dize somente uma palavra, e o meu servo sarará."}, {"numero": 9, "texto": "Pois eu também sou homem debaixo de autoridade, e tenho debaixo de meu comando soldados; e digo a este: “Vai”, e ele vai; e ao outro: “Vem”, e vem; e a meu servo: “Faze isto”, e ele faz."}, {"numero": 10, "texto": "Quando Jesus ouviu [isto] , maravilhou-se, e disse aos que o seguiam: Em verdade vos digo que nem mesmo em Israel encontrei tanta fé."}, {"numero": 11, "texto": "Mas eu vos digo que muitos virão do oriente e do ocidente, e se sentarão à mesa com Abraão, Isaque, e Jacó, no Reino dos céus."}, {"numero": 12, "texto": "Os filhos do reino, porém, serão lançados nas trevas de fora; ali haverá pranto e ranger de dentes."}, {"numero": 13, "texto": "Então Jesus disse ao centurião: Vai, e assim como creste, a ti seja feito.E naquela mesma hora o servo dele foi sarado."}, {"numero": 14, "texto": "E quando Jesus veio à casa de Pedro, viu a sogra dele, deitada e com febre."}, {"numero": 15, "texto": "Ele tocou a mão dela, e a febre a deixou. Então ela se levantou e começou a servi-los."}, {"numero": 16, "texto": "Quando chegou o anoitecer, trouxeram-lhe muitos endemoninhados. Ele expulsou-lhes os espíritos com a palavra, e curou todos os que estavam doentes,"}, {"numero": 17, "texto": "Para que se cumprisse o que havia sido dito pelo profeta Isaías, que disse: Ele tomou sobre si as nossas enfermidades, e levou as nossas doenças."}, {"numero": 18, "texto": "E Jesus, ao ver muitas multidões ao redor de si, mandou que passassem para a outra margem."}, {"numero": 19, "texto": "Então um escriba se aproximou, e disse-lhe: Mestre, eu te seguirei aonde quer que fores."}, {"numero": 20, "texto": "Jesus lhe respondeu: As raposas têm covis, e as aves do céu ninhos; mas o Filho do homem não tem onde recostar a cabeça."}, {"numero": 21, "texto": "E outro dos seus discípulos lhe disse: Senhor, permite-me ir primeiro enterrar meu pai."}, {"numero": 22, "texto": "Porém Jesus lhe disse: Segue-me, e deixa aos mortos enterrarem seus mortos."}, {"numero": 23, "texto": "Então ele entrou no barco, e seus discípulos o seguiram."}, {"numero": 24, "texto": "E eis que se levantou no mar uma tormenta tão grande que o barco era coberto pelas ondas; porém ele dormia."}, {"numero": 25, "texto": "E seus discípulos se aproximaram para acordá-lo, dizendo: Senhor, salva-nos! Estamos sendo destruídos!"}, {"numero": 26, "texto": "E ele lhes respondeu: Por que temeis, [homens] de pouca fé? Então ele se levantou e repreendeu os ventos e o mar. E houve grande calmaria."}, {"numero": 27, "texto": "E aqueles homens se maravilharam, dizendo: Quem é este, que até os ventos e o mar lhe obedecem?"}, {"numero": 28, "texto": "E quando chegou à outra margem, à terra dos gergesenos, vieram-lhe ao encontro dois endemoninhados que tinham saído dos sepulcros. Eles eram tão ferozes que ninguém podia passar por aquele caminho."}, {"numero": 29, "texto": "E eis que gritaram, dizendo: Que temos contigo, Jesus, Filho de Deus? Vieste aqui nos atormentar antes do tempo?"}, {"numero": 30, "texto": "Enquanto isso longe deles estava uma manada de muitos porcos pastando."}, {"numero": 31, "texto": "E os demônios rogaram-lhe, dizendo: Se nos expulsares, permite-nos entrar naquela manada de porcos."}, {"numero": 32, "texto": "E ele lhes disse: Ide. Então eles saíram, e entraram na manada de porcos; e eis que toda aquela manada de porcos se lançou de um precipício ao mar, e morreram nas águas."}, {"numero": 33, "texto": "E os que cuidavam dos porcos fugiram; e ao chegarem à cidade, anunciaram todas [estas] coisas, inclusive o que [havia acontecido] aos endemoninhados."}, {"numero": 34, "texto": "E eis que toda aquela cidade saiu ao encontro de Jesus; e quando o viram, rogaram-lhe que se retirasse do território deles."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 8, 'en', '[{"numero": 1, "texto": "When he was come down from the mountain, great multitudes followed him."}, {"numero": 2, "texto": "And, behold, there came a leper and worshipped him, saying, Lord, if thou wilt, thou canst make me clean."}, {"numero": 3, "texto": "And Jesus put forth his hand, and touched him, saying, I will; be thou clean. And immediately his leprosy was cleansed."}, {"numero": 4, "texto": "And Jesus saith unto him, See thou tell no man; but go thy way, shew thyself to the priest, and offer the gift that Moses commanded, for a testimony unto them."}, {"numero": 5, "texto": "And when Jesus was entered into Capernaum, there came unto him a centurion, beseeching him,"}, {"numero": 6, "texto": "And saying, Lord, my servant lieth at home sick of the palsy, grievously tormented."}, {"numero": 7, "texto": "And Jesus saith unto him, I will come and heal him."}, {"numero": 8, "texto": "The centurion answered and said, Lord, I am not worthy that thou shouldest come under my roof: but speak the word only, and my servant shall be healed."}, {"numero": 9, "texto": "For I am a man under authority, having soldiers under me: and I say to this man, Go, and he goeth; and to another, Come, and he cometh; and to my servant, Do this, and he doeth it."}, {"numero": 10, "texto": "When Jesus heard it, he marvelled, and said to them that followed, Verily I say unto you, I have not found so great faith, no, not in Israel."}, {"numero": 11, "texto": "And I say unto you, That many shall come from the east and west, and shall sit down with Abraham, and Isaac, and Jacob, in the kingdom of heaven."}, {"numero": 12, "texto": "But the children of the kingdom shall be cast out into outer darkness: there shall be weeping and gnashing of teeth."}, {"numero": 13, "texto": "And Jesus said unto the centurion, Go thy way; and as thou hast believed, so be it done unto thee. And his servant was healed in the selfsame hour."}, {"numero": 14, "texto": "And when Jesus was come into Peter''s house, he saw his wife''s mother laid, and sick of a fever."}, {"numero": 15, "texto": "And he touched her hand, and the fever left her: and she arose, and ministered unto them."}, {"numero": 16, "texto": "When the even was come, they brought unto him many that were possessed with devils: and he cast out the spirits with his word, and healed all that were sick:"}, {"numero": 17, "texto": "That it might be fulfilled which was spoken by Esaias the prophet, saying, Himself took our infirmities, and bare our sicknesses."}, {"numero": 18, "texto": "Now when Jesus saw great multitudes about him, he gave commandment to depart unto the other side."}, {"numero": 19, "texto": "And a certain scribe came, and said unto him, Master, I will follow thee whithersoever thou goest."}, {"numero": 20, "texto": "And Jesus saith unto him, The foxes have holes, and the birds of the air have nests; but the Son of man hath not where to lay his head."}, {"numero": 21, "texto": "And another of his disciples said unto him, Lord, suffer me first to go and bury my father."}, {"numero": 22, "texto": "But Jesus said unto him, Follow me; and let the dead bury their dead."}, {"numero": 23, "texto": "And when he was entered into a ship, his disciples followed him."}, {"numero": 24, "texto": "And, behold, there arose a great tempest in the sea, insomuch that the ship was covered with the waves: but he was asleep."}, {"numero": 25, "texto": "And his disciples came to him, and awoke him, saying, Lord, save us: we perish."}, {"numero": 26, "texto": "And he saith unto them, Why are ye fearful, O ye of little faith? Then he arose, and rebuked the winds and the sea; and there was a great calm."}, {"numero": 27, "texto": "But the men marvelled, saying, What manner of man is this, that even the winds and the sea obey him!"}, {"numero": 28, "texto": "And when he was come to the other side into the country of the Gergesenes, there met him two possessed with devils, coming out of the tombs, exceeding fierce, so that no man might pass by that way."}, {"numero": 29, "texto": "And, behold, they cried out, saying, What have we to do with thee, Jesus, thou Son of God? art thou come hither to torment us before the time?"}, {"numero": 30, "texto": "And there was a good way off from them an herd of many swine feeding."}, {"numero": 31, "texto": "So the devils besought him, saying, If thou cast us out, suffer us to go away into the herd of swine."}, {"numero": 32, "texto": "And he said unto them, Go. And when they were come out, they went into the herd of swine: and, behold, the whole herd of swine ran violently down a steep place into the sea, and perished in the waters."}, {"numero": 33, "texto": "And they that kept them fled, and went their ways into the city, and told every thing, and what was befallen to the possessed of the devils."}, {"numero": 34, "texto": "And, behold, the whole city came out to meet Jesus: and when they saw him, they besought him that he would depart out of their coasts."}]'::jsonb, 'King James Version'),
  ('Mt', 8, 'fr', '[{"numero": 1, "texto": "Lorsque Jésus fut descendu de la montagne, une grande foule le suivit."}, {"numero": 2, "texto": "Et voici, un lépreux s''''étant approché se prosterna devant lui, et dit: Seigneur, si tu le veux, tu peux me rendre pur."}, {"numero": 3, "texto": "Jésus étendit la main, le toucha, et dit: Je le veux, sois pur. Aussitôt il fut purifié de sa lèpre."}, {"numero": 4, "texto": "Puis Jésus lui dit: Garde-toi d''''en parler à personne; mais va te montrer au sacrificateur, et présente l''''offrande que Moïse a prescrite, afin que cela leur serve de témoignage."}, {"numero": 5, "texto": "Comme Jésus entrait dans Capernaüm, un centenier l''''aborda, le priant"}, {"numero": 6, "texto": "et disant: Seigneur, mon serviteur est couché à la maison, atteint de paralysie et souffrant beaucoup."}, {"numero": 7, "texto": "Jésus lui dit: J''''irai, et je le guérirai."}, {"numero": 8, "texto": "Le centenier répondit: Seigneur, je ne suis pas digne que tu entres sous mon toit; mais dis seulement un mot, et mon serviteur sera guéri."}, {"numero": 9, "texto": "Car, moi qui suis soumis à des supérieurs, j''''ai des soldats sous mes ordres; et je dis à l''''un: Va! et il va; à l''''autre: Viens! et il vient; et à mon serviteur: Fais cela! et il le fait."}, {"numero": 10, "texto": "Après l''''avoir entendu, Jésus fut dans l''''étonnement, et il dit à ceux qui le suivaient: Je vous le dis en vérité, même en Israël je n''''ai pas trouvé une aussi grande foi."}, {"numero": 11, "texto": "Or, je vous déclare que plusieurs viendront de l''''orient et de l''''occident, et seront à table avec Abraham, Isaac et Jacob, dans le royaume des cieux."}, {"numero": 12, "texto": "Mais les fils du royaume seront jetés dans les ténèbres du dehors, où il y aura des pleurs et des grincements de dents."}, {"numero": 13, "texto": "Puis Jésus dit au centenier: Va, qu''''il te soit fait selon ta foi. Et à l''''heure même le serviteur fut guéri."}, {"numero": 14, "texto": "Jésus se rendit ensuite à la maison de Pierre, dont il vit la belle-mère couchée et ayant la fièvre."}, {"numero": 15, "texto": "Il toucha sa main, et la fièvre la quitta; puis elle se leva, et le servit."}, {"numero": 16, "texto": "Le soir, on amena auprès de Jésus plusieurs démoniaques. Il chassa les esprits par sa parole, et il guérit tous les malades,"}, {"numero": 17, "texto": "afin que s''''accomplît ce qui avait été annoncé par Esaïe, le prophète: Il a pris nos infirmités, et il s''''est chargé de nos maladies."}, {"numero": 18, "texto": "Jésus, voyant une grande foule autour de lui, donna l''''ordre de passer à l''''autre bord."}, {"numero": 19, "texto": "Un scribe s''''approcha, et lui dit: Maître, je te suivrai partout où tu iras."}, {"numero": 20, "texto": "Jésus lui répondit: Les renards ont des tanières, et les oiseaux du ciel ont des nids; mais le Fils de l''''homme n''''a pas où reposer sa tête."}, {"numero": 21, "texto": "Un autre, d''''entre les disciples, lui dit: Seigneur, permets-moi d''''aller d''''abord ensevelir mon père."}, {"numero": 22, "texto": "Mais Jésus lui répondit: Suis-moi, et laisse les morts ensevelir leurs morts."}, {"numero": 23, "texto": "Il monta dans la barque, et ses disciples le suivirent."}, {"numero": 24, "texto": "Et voici, il s''''éleva sur la mer une si grande tempête que la barque était couverte par les flots. Et lui, il dormait."}, {"numero": 25, "texto": "Les disciples s''''étant approchés le réveillèrent, et dirent: Seigneur, sauve-nous, nous périssons!"}, {"numero": 26, "texto": "Il leur dit: Pourquoi avez-vous peur, gens de peu de foi? Alors il se leva, menaça les vents et la mer, et il y eut un grand calme."}, {"numero": 27, "texto": "Ces hommes furent saisis d''''étonnement: Quel est celui-ci, disaient-ils, à qui obéissent même les vents et la mer?"}, {"numero": 28, "texto": "Lorsqu''''il fut à l''''autre bord, dans le pays des Gadaréniens, deux démoniaques, sortant des sépulcres, vinrent au-devant de lui. Ils étaient si furieux que personne n''''osait passer par là."}, {"numero": 29, "texto": "Et voici, ils s''''écrièrent: Qu''''y a-t-il entre nous et toi, Fils de Dieu? Es-tu venu ici pour nous tourmenter avant le temps?"}, {"numero": 30, "texto": "Il y avait loin d''''eux un grand troupeau de pourceaux qui paissaient."}, {"numero": 31, "texto": "Les démons priaient Jésus, disant: Si tu nous chasses, envoie-nous dans ce troupeau de pourceaux."}, {"numero": 32, "texto": "Il leur dit: Allez! Ils sortirent, et entrèrent dans les pourceaux. Et voici, tout le troupeau se précipita des pentes escarpées dans la mer, et ils périrent dans les eaux."}, {"numero": 33, "texto": "Ceux qui les faisaient paître s''''enfuirent, et allèrent dans la ville raconter tout ce qui s''''était passé et ce qui était arrivé aux démoniaques."}, {"numero": 34, "texto": "Alors toute la ville sortit à la rencontre de Jésus; et, dès qu''''ils le virent, ils le supplièrent de quitter leur territoire."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 8, 'es', '[{"numero": 1, "texto": "Y COMO descendió del monte, le seguían muchas gentes."}, {"numero": 2, "texto": "Y he aquí un leproso vino, y le adoraba, diciendo: Señor, si quisieres, puedes limpiarme."}, {"numero": 3, "texto": "Y extendiendo Jesús su mano, le tocó, diciendo: Quiero; sé limpio. Y luego su lepra fué limpiada."}, {"numero": 4, "texto": "Entonces Jesús le dijo: Mira, no lo digas á nadie; mas ve, muéstrate al sacerdote, y ofrece el presente que mandó Moisés, para testimonio á ellos."}, {"numero": 5, "texto": "Y entrando Jesús en Capernaum, vino á él un centurión, rogándole,"}, {"numero": 6, "texto": "Y diciendo: Señor, mi mozo yace en casa paralítico, gravemente atormentado."}, {"numero": 7, "texto": "Y Jesús le dijo: Yo iré y le sanaré."}, {"numero": 8, "texto": "Y respondió el centurión, y dijo: Señor, no soy digno de que entres debajo de mi techado; mas solamente di la palabra, y mi mozo sanará."}, {"numero": 9, "texto": "Porque también yo soy hombre bajo de potestad, y tengo bajo de mí soldados: y digo á éste: Ve, y va; y al otro: Ven, y viene; y á mi siervo: Haz esto, y lo hace."}, {"numero": 10, "texto": "Y oyendo Jesús, se maravilló, y dijo á los que le seguían: De cierto os digo, que ni aun en Israel he hallado fe tanta."}, {"numero": 11, "texto": "Y os digo que vendrán muchos del oriente y del occidente, y se sentarán con Abraham, é Isaac, y Jacob, en el reino de los cielos:"}, {"numero": 12, "texto": "Mas los hijos del reino serán echados á las tinieblas de afuera: allí será el lloro y el crujir de dientes."}, {"numero": 13, "texto": "Entonces Jesús dijo al centurión: Ve, y como creiste te sea hecho. Y su mozo fué sano en el mismo momento."}, {"numero": 14, "texto": "Y vino Jesús á casa de Pedro, y vió á su suegra echada en cama, y con fiebre."}, {"numero": 15, "texto": "Y tocó su mano, y la fiebre la dejó: y ella se levantó, y les servía."}, {"numero": 16, "texto": "Y como fué ya tarde, trajeron á él muchos endemoniados; y echó los demonios con la palabra, y sanó á todos los enfermos;"}, {"numero": 17, "texto": "Para que se cumpliese lo que fué dicho por el profeta Isaías, que dijo: El mismo tomó nuestras enfermedades, y llevó nuestras dolencias."}, {"numero": 18, "texto": "Y viendo Jesús muchas gentes alrededor de sí, mandó pasar á la otra parte del lago."}, {"numero": 19, "texto": "Y llegándose un escriba, le dijo: Maestro, te seguiré á donde quiera que fueres."}, {"numero": 20, "texto": "Y Jesús le dijo: Las zorras tienen cavernas, y las aves del cielo nidos; mas el Hijo del hombre no tiene donde recueste su cabeza."}, {"numero": 21, "texto": "Y otro de sus discípulos le dijo: Señor, dame licencia para que vaya primero, y entierre á mi padre."}, {"numero": 22, "texto": "Y Jesús le dijo: Sígueme; deja que los muertos entierren á sus muertos."}, {"numero": 23, "texto": "Y entrando él en el barco, sus discípulos le siguieron."}, {"numero": 24, "texto": "Y he aquí, fué hecho en la mar un gran movimiento, que el barco se cubría de las ondas; mas él dormía."}, {"numero": 25, "texto": "Y llegándose sus discípulos, le despertaron, diciendo: Señor, sálvanos, que perecemos."}, {"numero": 26, "texto": "Y él les dice: ¿Por qué teméis, hombres de poca fe? Entonces, levantándose, reprendió á los vientos y á la mar; y fué grande bonanza."}, {"numero": 27, "texto": "Y los hombres se maravillaron, diciendo: ¿Qué hombre es éste, que aun los vientos y la mar le obedecen?"}, {"numero": 28, "texto": "Y como él hubo llegado en la otra ribera al país de los Gergesenos, le vinieron al encuentro dos endemoniados que salían de los sepulcros, fieros en gran manera, que nadie podía pasar por aquel camino."}, {"numero": 29, "texto": "Y he aquí clamaron, diciendo: ¿Qué tenemos contigo, Jesús, Hijo de Dios? ¿has venido acá á molestarnos antes de tiempo?"}, {"numero": 30, "texto": "Y estaba lejos de ellos un hato de muchos puercos paciendo."}, {"numero": 31, "texto": "Y los demonios le rogaron, diciendo: Si nos echas, permítenos ir á aquel hato de puercos."}, {"numero": 32, "texto": "Y les dijo: Id. Y ellos salieron, y se fueron á aquel hato de puercos: y he aquí, todo el hato de los puercos se precipitó de un despeñadero en la mar, y murieron en las aguas."}, {"numero": 33, "texto": "Y los porqueros huyeron, y viniendo á la ciudad, contaron todas las cosas, y lo que había pasado con los endemoniados."}, {"numero": 34, "texto": "Y he aquí, toda la ciudad salió á encontrar á Jesús: y cuando le vieron, le rogaban que saliese de sus términos."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 9, 'pt', '[{"numero": 1, "texto": "Então ele entrou no barco, passou para a outra margem, e veio à sua própria cidade."}, {"numero": 2, "texto": "E eis que lhe trouxeram um paralítico, deitado em um leito. Quando Jesus viu a fé deles, disse ao paralítico: Tem bom ânimo, filho! Teus pecados são perdoados."}, {"numero": 3, "texto": "E eis que alguns dos escribas disseram entre si: Ele blasfema."}, {"numero": 4, "texto": "Mas Jesus, conhecendo seus pensamentos, disse: “Por que pensais o mal em vossos corações?"}, {"numero": 5, "texto": "Pois o que é mais fácil? Dizer: ‘Teus pecados estão perdoados’, ou dizer: ‘Levanta-te, e anda’?"}, {"numero": 6, "texto": "Ora, para que saibais que o Filho do homem tem autoridade na terra para perdoar pecados”, (Ele, então, disse ao paralítico): Levanta-te, toma o teu leito, e vai para tua casa."}, {"numero": 7, "texto": "E este se levantou e foi para sua casa."}, {"numero": 8, "texto": "Quando as multidões viram [isto] , ficaram maravilhadas, e glorificaram a Deus, que tinha dado tal autoridade aos homens."}, {"numero": 9, "texto": "E Jesus, ao passar dali, viu um homem sentado na coletoria de impostos, chamado Mateus; e disse-lhe: Segue-me. Então este se levantou e o seguiu."}, {"numero": 10, "texto": "E aconteceu que, enquanto [Jesus] estava reclinado à mesa na casa [de Mateus] , eis que muitos publicanos e pecadores vieram e se reclinaram à mesa juntamente com Jesus e seus discípulos."}, {"numero": 11, "texto": "E quando os fariseus viram [isto] , perguntaram aos seus discípulos: Por que o vosso Mestre come com publicanos e pecadores?"}, {"numero": 12, "texto": "Porém Jesus ouviu, e respondeu-lhes: Os que têm saúde não precisam de médico, mas sim os que estão doentes."}, {"numero": 13, "texto": "Mas ide aprender o que significa: ‘Quero misericórdia, e não sacrifício’. Porque eu não vim chamar os justos, mas sim, os pecadores, ao arrependimento."}, {"numero": 14, "texto": "Então os discípulos de João vieram a ele, e perguntaram: Por que nós e os fariseus jejuamos muitas vezes, mas os teus discípulos não jejuam?"}, {"numero": 15, "texto": "E Jesus lhes respondeu: Podem, por acaso, os convidados do casamento andar tristes enquanto o noivo está com eles? Mas dias virão, quando o noivo lhes for tirado, e então jejuarão."}, {"numero": 16, "texto": "E ninguém põe remendo de pano novo em roupa velha; porque tal remendo rasga a roupa, e o rompimento se torna pior."}, {"numero": 17, "texto": "Nem põem vinho novo em odres velhos; pois senão os odres se rompem, o vinho se derrama, e os odres se perdem; mas põem o vinho novo em odres novos, e ambos juntamente se conservam."}, {"numero": 18, "texto": "Enquanto ele lhes dizia estas coisas, eis que um chefe [de sinagoga] veio prostrar-se diante dele, e disse: Minha filha faleceu ainda agora; mas vem, e põe tua mão sobre ela, e ela viverá."}, {"numero": 19, "texto": "Então Jesus se levantou e o seguiu com seus discípulos."}, {"numero": 20, "texto": "(Eis, porém, que uma mulher enferma de um fluxo de sangue havia doze anos veio por detrás [dele] , e tocou a borda de sua roupa;"}, {"numero": 21, "texto": "Porque dizia consigo mesma: Se eu tão-somente tocar a roupa dele, serei curada."}, {"numero": 22, "texto": "Jesus se virou e a viu. Então disse: Tem bom ânimo, filha, a tua fé te sarou. E desde aquela hora a mulher ficou com saúde.)"}, {"numero": 23, "texto": "Quando Jesus chegou à casa daquele chefe, viu os tocadores de flauta e a multidão que fazia alvoroço,"}, {"numero": 24, "texto": "E disse-lhes: Retirai-vos, porque a menina não está morta, mas sim dormindo. E riram dele."}, {"numero": 25, "texto": "Mas quando a multidão foi expulsa, ele entrou, pegou a mão dela, e a menina se levantou."}, {"numero": 26, "texto": "E esta notícia se espalhou por toda aquela terra."}, {"numero": 27, "texto": "E saindo Jesus dali, dois cegos o seguiram, gritando: Tem compaixão de nós, Filho de Davi!"}, {"numero": 28, "texto": "E quando ele entrou em casa, os cegos vieram a ele. Jesus lhes perguntou: Credes que posso fazer isto? Eles lhe responderam: Sim, Senhor."}, {"numero": 29, "texto": "Então tocou os olhos deles, dizendo: Seja feito convosco conforme a vossa fé."}, {"numero": 30, "texto": "E os olhos deles se abriram. Então Jesus os advertiu severamente, dizendo: Tende o cuidado de que ninguém saiba disso."}, {"numero": 31, "texto": "Porém eles saíram e divulgaram a notícia acerca dele por toda aquela terra."}, {"numero": 32, "texto": "Enquanto eles saíam, eis que lhe trouxeram um homem mudo e endemoninhado."}, {"numero": 33, "texto": "Quando o demônio foi expulso, o mudo passou a falar. Então as multidões ficaram maravilhadas, e disseram: Nunca se viu algo assim em Israel!"}, {"numero": 34, "texto": "Mas os fariseus diziam: É pelo chefe dos demônios que ele expulsa os demônios."}, {"numero": 35, "texto": "Jesus percorria todas as cidades e aldeias, ensinando em suas sinagogas, pregando o Evangelho do Reino, e curando toda enfermidade e toda doença entre o povo."}, {"numero": 36, "texto": "Quando ele viu as multidões, teve compaixão delas, porque andavam cansadas e desamparadas, como ovelhas que não têm pastor."}, {"numero": 37, "texto": "Então disse aos seus discípulos: Em verdade a colheita é grande, porém os trabalhadores são poucos."}, {"numero": 38, "texto": "Portanto rogai ao Senhor da colheita que envie trabalhadores à sua colheita."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 9, 'en', '[{"numero": 1, "texto": "And he entered into a ship, and passed over, and came into his own city."}, {"numero": 2, "texto": "And, behold, they brought to him a man sick of the palsy, lying on a bed: and Jesus seeing their faith said unto the sick of the palsy; Son, be of good cheer; thy sins be forgiven thee."}, {"numero": 3, "texto": "And, behold, certain of the scribes said within themselves, This man blasphemeth."}, {"numero": 4, "texto": "And Jesus knowing their thoughts said, Wherefore think ye evil in your hearts?"}, {"numero": 5, "texto": "For whether is easier, to say, Thy sins be forgiven thee; or to say, Arise, and walk?"}, {"numero": 6, "texto": "But that ye may know that the Son of man hath power on earth to forgive sins, (then saith he to the sick of the palsy,) Arise, take up thy bed, and go unto thine house."}, {"numero": 7, "texto": "And he arose, and departed to his house."}, {"numero": 8, "texto": "But when the multitudes saw it, they marvelled, and glorified God, which had given such power unto men."}, {"numero": 9, "texto": "And as Jesus passed forth from thence, he saw a man, named Matthew, sitting at the receipt of custom: and he saith unto him, Follow me. And he arose, and followed him."}, {"numero": 10, "texto": "And it came to pass, as Jesus sat at meat in the house, behold, many publicans and sinners came and sat down with him and his disciples."}, {"numero": 11, "texto": "And when the Pharisees saw it, they said unto his disciples, Why eateth your Master with publicans and sinners?"}, {"numero": 12, "texto": "But when Jesus heard that, he said unto them, They that be whole need not a physician, but they that are sick."}, {"numero": 13, "texto": "But go ye and learn what that meaneth, I will have mercy, and not sacrifice: for I am not come to call the righteous, but sinners to repentance."}, {"numero": 14, "texto": "Then came to him the disciples of John, saying, Why do we and the Pharisees fast oft, but thy disciples fast not?"}, {"numero": 15, "texto": "And Jesus said unto them, Can the children of the bridechamber mourn, as long as the bridegroom is with them? but the days will come, when the bridegroom shall be taken from them, and then shall they fast."}, {"numero": 16, "texto": "No man putteth a piece of new cloth unto an old garment, for that which is put in to fill it up taketh from the garment, and the rent is made worse."}, {"numero": 17, "texto": "Neither do men put new wine into old bottles: else the bottles break, and the wine runneth out, and the bottles perish: but they put new wine into new bottles, and both are preserved."}, {"numero": 18, "texto": "While he spake these things unto them, behold, there came a certain ruler, and worshipped him, saying, My daughter is even now dead: but come and lay thy hand upon her, and she shall live."}, {"numero": 19, "texto": "And Jesus arose, and followed him, and so did his disciples."}, {"numero": 20, "texto": "And, behold, a woman, which was diseased with an issue of blood twelve years, came behind him, and touched the hem of his garment:"}, {"numero": 21, "texto": "For she said within herself, If I may but touch his garment, I shall be whole."}, {"numero": 22, "texto": "But Jesus turned him about, and when he saw her, he said, Daughter, be of good comfort; thy faith hath made thee whole. And the woman was made whole from that hour."}, {"numero": 23, "texto": "And when Jesus came into the ruler''s house, and saw the minstrels and the people making a noise,"}, {"numero": 24, "texto": "He said unto them, Give place: for the maid is not dead, but sleepeth. And they laughed him to scorn."}, {"numero": 25, "texto": "But when the people were put forth, he went in, and took her by the hand, and the maid arose."}, {"numero": 26, "texto": "And the fame hereof went abroad into all that land."}, {"numero": 27, "texto": "And when Jesus departed thence, two blind men followed him, crying, and saying, Thou son of David, have mercy on us."}, {"numero": 28, "texto": "And when he was come into the house, the blind men came to him: and Jesus saith unto them, Believe ye that I am able to do this? They said unto him, Yea, Lord."}, {"numero": 29, "texto": "Then touched he their eyes, saying, According to your faith be it unto you."}, {"numero": 30, "texto": "And their eyes were opened; and Jesus straitly charged them, saying, See that no man know it."}, {"numero": 31, "texto": "But they, when they were departed, spread abroad his fame in all that country."}, {"numero": 32, "texto": "As they went out, behold, they brought to him a dumb man possessed with a devil."}, {"numero": 33, "texto": "And when the devil was cast out, the dumb spake: and the multitudes marvelled, saying, It was never so seen in Israel."}, {"numero": 34, "texto": "But the Pharisees said, He casteth out devils through the prince of the devils."}, {"numero": 35, "texto": "And Jesus went about all the cities and villages, teaching in their synagogues, and preaching the gospel of the kingdom, and healing every sickness and every disease among the people."}, {"numero": 36, "texto": "But when he saw the multitudes, he was moved with compassion on them, because they fainted, and were scattered abroad, as sheep having no shepherd."}, {"numero": 37, "texto": "Then saith he unto his disciples, The harvest truly is plenteous, but the labourers are few;"}, {"numero": 38, "texto": "Pray ye therefore the Lord of the harvest, that he will send forth labourers into his harvest."}]'::jsonb, 'King James Version'),
  ('Mt', 9, 'fr', '[{"numero": 1, "texto": "Jésus, étant monté dans une barque, traversa la mer, et alla dans sa ville."}, {"numero": 2, "texto": "Et voici, on lui amena un paralytique couché sur un lit. Jésus, voyant leur foi, dit au paralytique: Prends courage, mon enfant, tes péchés te sont pardonnés."}, {"numero": 3, "texto": "Sur quoi, quelques scribes dirent au dedans d''''eux: Cet homme blasphème."}, {"numero": 4, "texto": "Et Jésus, connaissant leurs pensées, dit: Pourquoi avez-vous de mauvaises pensées dans vos coeurs?"}, {"numero": 5, "texto": "Car, lequel est le plus aisé, de dire: Tes péchés sont pardonnés, ou de dire: Lève-toi, et marche?"}, {"numero": 6, "texto": "Or, afin que vous sachiez que le Fils de l''''homme a sur la terre le pouvoir de pardonner les péchés: Lève-toi, dit-il au paralytique, prends ton lit, et va dans ta maison."}, {"numero": 7, "texto": "Et il se leva, et s''''en alla dans sa maison."}, {"numero": 8, "texto": "Quand la foule vit cela, elle fut saisie de crainte, et elle glorifia Dieu, qui a donné aux hommes un tel pouvoir."}, {"numero": 9, "texto": "De là étant allé plus loin, Jésus vit un homme assis au lieu des péages, et qui s''''appelait Matthieu. Il lui dit: Suis-moi. Cet homme se leva, et le suivit."}, {"numero": 10, "texto": "Comme Jésus était à table dans la maison, voici, beaucoup de publicains et de gens de mauvaise vie vinrent se mettre à table avec lui et avec ses disciples."}, {"numero": 11, "texto": "Les pharisiens virent cela, et ils dirent à ses disciples: Pourquoi votre maître mange-t-il avec les publicains et les gens de mauvaise vie?"}, {"numero": 12, "texto": "Ce que Jésus ayant entendu, il dit: Ce ne sont pas ceux qui se portent bien qui ont besoin de médecin, mais les malades."}, {"numero": 13, "texto": "Allez, et apprenez ce que signifie: Je prends plaisir à la miséricorde, et non aux sacrifices. Car je ne suis pas venu appeler des justes, mais des pécheurs."}, {"numero": 14, "texto": "Alors les disciples de Jean vinrent auprès de Jésus, et dirent: Pourquoi nous et les pharisiens jeûnons-nous, tandis que tes disciples ne jeûnent point?"}, {"numero": 15, "texto": "Jésus leur répondit: Les amis de l''''époux peuvent-ils s''''affliger pendant que l''''époux est avec eux? Les jours viendront où l''''époux leur sera enlevé, et alors ils jeûneront."}, {"numero": 16, "texto": "Personne ne met une pièce de drap neuf à un vieil habit; car elle emporterait une partie de l''''habit, et la déchirure serait pire."}, {"numero": 17, "texto": "On ne met pas non plus du vin nouveau dans de vieilles outres; autrement, les outres se rompent, le vin se répand, et les outres sont perdues; mais on met le vin nouveau dans des outres neuves, et le vin et les outres se conservent."}, {"numero": 18, "texto": "Tandis qu''''il leur adressait ces paroles, voici, un chef arriva, se prosterna devant lui, et dit: Ma fille est morte il y a un instant; mais viens, impose-lui les mains, et elle vivra."}, {"numero": 19, "texto": "Jésus se leva, et le suivit avec ses disciples."}, {"numero": 20, "texto": "Et voici, une femme atteinte d''''une perte de sang depuis douze ans s''''approcha par derrière, et toucha le bord de son vêtement."}, {"numero": 21, "texto": "Car elle disait en elle-même: Si je puis seulement toucher son vêtement, je serai guérie."}, {"numero": 22, "texto": "Jésus se retourna, et dit, en la voyant: Prends courage, ma fille, ta foi t''''a guérie. Et cette femme fut guérie à l''''heure même."}, {"numero": 23, "texto": "Lorsque Jésus fut arrivé à la maison du chef, et qu''''il vit les joueurs de flûte et la foule bruyante,"}, {"numero": 24, "texto": "il leur dit: Retirez-vous; car la jeune fille n''''est pas morte, mais elle dort. Et ils se moquaient de lui."}, {"numero": 25, "texto": "Quand la foule eut été renvoyée, il entra, prit la main de la jeune fille, et la jeune fille se leva."}, {"numero": 26, "texto": "Le bruit s''''en répandit dans toute la contrée."}, {"numero": 27, "texto": "Etant parti de là, Jésus fut suivi par deux aveugles, qui criaient: Aie pitié de nous, Fils de David!"}, {"numero": 28, "texto": "Lorsqu''''il fut arrivé à la maison, les aveugles s''''approchèrent de lui, et Jésus leur dit: Croyez-vous que je puisse faire cela? Oui, Seigneur, lui répondirent-ils."}, {"numero": 29, "texto": "Alors il leur toucha les yeux, en disant: Qu''''il vous soit fait selon votre foi."}, {"numero": 30, "texto": "Et leurs yeux s''''ouvrirent. Jésus leur fit cette recommandation sévère: Prenez garde que personne ne le sache."}, {"numero": 31, "texto": "Mais, dès qu''''ils furent sortis, ils répandirent sa renommée dans tout le pays."}, {"numero": 32, "texto": "Comme ils s''''en allaient, voici, on amena à Jésus un démoniaque muet."}, {"numero": 33, "texto": "Le démon ayant été chassé, le muet parla. Et la foule étonnée disait: Jamais pareille chose ne s''''est vue en Israël."}, {"numero": 34, "texto": "Mais les pharisiens dirent: C''''est par le prince des démons qu''''il chasse les démons."}, {"numero": 35, "texto": "Jésus parcourait toutes les villes et les villages, enseignant dans les synagogues, prêchant la bonne nouvelle du royaume, et guérissant toute maladie et toute infirmité."}, {"numero": 36, "texto": "Voyant la foule, il fut ému de compassion pour elle, parce qu''''elle était languissante et abattue, comme des brebis qui n''''ont point de berger."}, {"numero": 37, "texto": "Alors il dit à ses disciples: La moisson est grande, mais il y a peu d''''ouvriers."}, {"numero": 38, "texto": "Priez donc le maître de la moisson d''''envoyer des ouvriers dans sa moisson."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 9, 'es', '[{"numero": 1, "texto": "ENTONCES entrando en el barco, pasó á la otra parte, y vino á su ciudad."}, {"numero": 2, "texto": "Y he aquí le trajeron un paralítico, echado en una cama: y viendo Jesús la fe de ellos, dijo al paralítico: Confía, hijo; tus pecados te son perdonados."}, {"numero": 3, "texto": "Y he aquí, algunos de los escribas decían dentro de sí: Este blasfema."}, {"numero": 4, "texto": "Y viendo Jesús sus pensamientos, dijo: ¿Por qué pensáis mal en vuestros corazones?"}, {"numero": 5, "texto": "Porque, ¿qué es más fácil, decir: Los pecados te son perdonados; ó decir: Levántate, y anda?"}, {"numero": 6, "texto": "Pues para que sepáis que el Hijo del hombre tiene potestad en la tierra de perdonar pecados, (dice entonces al paralítico): Levántate, toma tu cama, y vete á tu casa."}, {"numero": 7, "texto": "Entonces él se levantó y se fué á su casa."}, {"numero": 8, "texto": "Y las gentes, viéndolo, se maravillaron, y glorificaron á Dios, que había dado tal potestad á los hombres."}, {"numero": 9, "texto": "Y pasando Jesús de allí, vió á un hombre que estaba sentado al banco de los públicos tributos, el cual se llamaba Mateo; y dícele: Sígueme. Y se levantó, y le siguió."}, {"numero": 10, "texto": "Y aconteció que estando él sentado á la mesa en casa, he aquí que muchos publicanos y pecadores, que habían venido, se sentaron juntamente á la mesa con Jesús y sus discípulos."}, {"numero": 11, "texto": "Y viendo esto los Fariseos, dijeron á sus discípulos: ¿Por qué come vuestro Maestro con los publicanos y pecadores?"}, {"numero": 12, "texto": "Y oyéndolo Jesús, les dijo: Los que están sanos no tienen necesidad de médico, sino los enfermos."}, {"numero": 13, "texto": "Andad pues, y aprended qué cosa es: Misericordia quiero, y no sacrificio: porque no he venido á llamar justos, sino pecadores á arrepentimiento."}, {"numero": 14, "texto": "Entonces los discípulos de Juan vienen á él, diciendo: ¿Por qué nosotros y los Fariseos ayunamos muchas veces, y tus discípulos no ayunan?"}, {"numero": 15, "texto": "Y Jesús les dijo: ¿Pueden los que son de bodas tener luto entre tanto que el esposo está con ellos? mas vendrán días cuando el esposo será quitado de ellos, y entonces ayunarán."}, {"numero": 16, "texto": "Y nadie echa remiendo de paño recio en vestido viejo; porque el tal remiendo tira del vestido, y se hace peor la rotura."}, {"numero": 17, "texto": "Ni echan vino nuevo en cueros viejos: de otra manera los cueros se rompen, y el vino se derrama, y se pierden los cueros; mas echan el vino nuevo en cueros nuevos, y lo uno y lo otro se conserva juntamente."}, {"numero": 18, "texto": "Hablando él estas cosas á ellos, he aquí vino un principal, y le adoraba, diciendo: Mi hija es muerta poco ha: mas ven y pon tu mano sobre ella, y vivirá."}, {"numero": 19, "texto": "Y se levantó Jesús, y le siguió, y sus discípulos."}, {"numero": 20, "texto": "Y he aquí una mujer enferma de flujo de sangre doce años había, llegándose por detrás, tocó la franja de su vestido:"}, {"numero": 21, "texto": "Porque decía entre sí: Si tocare solamente su vestido, seré salva."}, {"numero": 22, "texto": "Mas Jesús volviéndose, y mirándola, dijo: Confía, hija, tu fe te ha salvado. Y la mujer fué salva desde aquella hora."}, {"numero": 23, "texto": "Y llegado Jesús á casa del principal, viendo los tañedores de flautas, y la gente que hacía bullicio,"}, {"numero": 24, "texto": "Díceles: Apartaos, que la muchacha no es muerta, mas duerme. Y se burlaban de él."}, {"numero": 25, "texto": "Y como la gente fué echada fuera, entró, y tomóla de la mano, y se levantó la muchacha."}, {"numero": 26, "texto": "Y salió esta fama por toda aquella tierra."}, {"numero": 27, "texto": "Y pasando Jesús de allí, le siguieron dos ciegos, dando voces y diciendo: Ten misericordia de nosotros, Hijo de David."}, {"numero": 28, "texto": "Y llegado á la casa, vinieron á él los ciegos; y Jesús les dice: ¿Creéis que puedo hacer esto? Ellos dicen: Sí, Señor."}, {"numero": 29, "texto": "Entonces tocó los ojos de ellos, diciendo: Conforme á vuestra fe os sea hecho."}, {"numero": 30, "texto": "Y los ojos de ellos fueron abiertos. Y Jesús les encargó rigurosamente, diciendo: Mirad que nadie lo sepa."}, {"numero": 31, "texto": "Mas ellos salidos, divulgaron su fama por toda aquella tierra."}, {"numero": 32, "texto": "Y saliendo ellos, he aquí, le trajeron un hombre mudo, endemoniado."}, {"numero": 33, "texto": "Y echado fuera el demonio, el mudo habló; y las gentes se maravillaron, diciendo: Nunca ha sido vista cosa semejante en Israel."}, {"numero": 34, "texto": "Mas los Fariseos decían: Por el príncipe de los demonios echa fuera los demonios."}, {"numero": 35, "texto": "Y rodeaba Jesús por todas las ciudades y aldeas, enseñando en las sinagogas de ellos, y predicando el evangelio del reino, y sanando toda enfermedad y todo achaque en el pueblo."}, {"numero": 36, "texto": "Y viendo las gentes, tuvo compasión de ellas; porque estaban derramadas y esparcidas como ovejas que no tienen pastor."}, {"numero": 37, "texto": "Entonces dice á sus discípulos: A la verdad la mies es mucha, mas los obreros pocos."}, {"numero": 38, "texto": "Rogad, pues, al Señor de la mies, que envíe obreros á su mies."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 10, 'pt', '[{"numero": 1, "texto": "[Jesus] chamou a si os seus doze discípulos, e deu-lhes poder sobre os espíritos imundos, para os expulsarem, e curarem toda enfermidade e toda doença."}, {"numero": 2, "texto": "E os nomes dos doze apóstolos são estes: o primeiro, Simão, chamado Pedro, e seu irmão André; Tiago, [filho] de Zebedeu, e seu irmão João;"}, {"numero": 3, "texto": "Filipe e Bartolomeu; Tomé, e Mateus o publicano; Tiago, [filho] de Alfeu; e Lebeu, por sobrenomeTadeu;"}, {"numero": 4, "texto": "Simão o zeloso, e Judas Iscariotes, o mesmo que o traiu."}, {"numero": 5, "texto": "Jesus enviou esses doze, e lhes mandou, dizendo: Não ireis pelo caminho dos gentios, nem entrareis em cidade de samaritanos."}, {"numero": 6, "texto": "Em vez disso, ide às ovelhas perdidas da casa de Israel."}, {"numero": 7, "texto": "E quando fordes, proclamai, dizendo: ‘Perto está o Reino dos céus’."}, {"numero": 8, "texto": "Curai os doentes, limpai os leprosos, ressuscitai os mortos, expulsai os demônios; recebestes de graça, dai de graça."}, {"numero": 9, "texto": "Não tomeis convosco ouro, nem prata, nem cobre em vossos cintos;"}, {"numero": 10, "texto": "nem bolsas para o caminho, nem duas túnicas, nem sandálias, nem bordão; pois o trabalhador é digno de seu alimento."}, {"numero": 11, "texto": "E em qualquer cidade ou aldeia que entrardes, informai-vos de quem nela seja digno, e ficai ali até que saiais."}, {"numero": 12, "texto": "E quando entrardes na casa, saudai-a."}, {"numero": 13, "texto": "Se a casa for digna, venha sobre ela a vossa paz; mas se ela não for digna, volte para vós a vossa paz."}, {"numero": 14, "texto": "E quem quer que não vos receber, nem ouvir vossas palavras, quando sairdes daquela casa ou cidade, sacudi o pó de vossos pés."}, {"numero": 15, "texto": "Em verdade vos digo que no dia do julgamento mais tolerável será para a região de Sodoma e Gomorra do que para aquela cidade."}, {"numero": 16, "texto": "Eis que eu vos envio como ovelhas em meio de lobos; portanto, sede prudentes como as serpentes e inofensivos como pombas."}, {"numero": 17, "texto": "Porém tende cuidado com as pessoas; porque vos entregarão em tribunais, e vos açoitarão em suas sinagogas;"}, {"numero": 18, "texto": "E até perante governadores e reis sereis levados por causa de mim, para que haja testemunho a eles e aos gentios."}, {"numero": 19, "texto": "Mas quando vos entregarem, não estejais ansiosos de como ou que falareis; porque naquela mesma hora vos será dado o que deveis falar."}, {"numero": 20, "texto": "Porque não sois vós os que falais, mas sim o Espírito do vosso Pai que fala em vós."}, {"numero": 21, "texto": "E irmão entregará irmão à morte, e pai ao filho; e filhos se levantarão contra os pais, e os matarão."}, {"numero": 22, "texto": "E sereis odiados por todos por causa de meu nome; mas aquele que perseverar até o fim, esse será salvo."}, {"numero": 23, "texto": "Quando, então, vos perseguirem nesta cidade, fugi para outra; porque em verdade vos digo que não acabareis de [percorrer] as cidades de Israel, até que venha o Filho do homem."}, {"numero": 24, "texto": "O discípulo não é superior ao mestre, nem o servo superior ao seu senhor."}, {"numero": 25, "texto": "Seja suficiente ao discípulo ser como o seu mestre, e ao servo como o seu senhor; se ao chefe da casa chamaram de Belzebu, quanto mais aos membros de sua casa!"}, {"numero": 26, "texto": "Portanto, não os temais; porque nada há encoberto que não se revelará, [nada] oculto que não se saberá."}, {"numero": 27, "texto": "O que eu vos digo em trevas, dizei na luz; e o que ouvis ao ouvido, proclamai sobre os telhados."}, {"numero": 28, "texto": "E não temais os que matam o corpo, mas não podem matar a alma; temei mais aquele que pode destruir tanto a alma como o corpo no inferno."}, {"numero": 29, "texto": "Não se vendem dois pardais por uma pequena moeda? Mas nem um deles cairá em terra contra a vontade de vosso Pai."}, {"numero": 30, "texto": "E até os cabelos de vossas cabeças estão todos contados."}, {"numero": 31, "texto": "Assim, não tenhais medo; mais valeis vós que muitos pardais."}, {"numero": 32, "texto": "Portanto, todo aquele que me der reconhecimento diante das pessoas, também eu o reconhecerei diante de meu Pai, que está nos céus."}, {"numero": 33, "texto": "Porém qualquer um que me negar diante das pessoas, também eu o negarei diante de meu Pai, que está nos céus."}, {"numero": 34, "texto": "Não penseis que vim trazer paz à terra. Não vim trazer paz, mas sim espada."}, {"numero": 35, "texto": "Porque eu vim pôr em discórdia ‘o homem contra seu pai, a filha contra sua mãe, e a nora contra sua sogra."}, {"numero": 36, "texto": "E os inimigos do homem serão os de sua própria casa’."}, {"numero": 37, "texto": "Quem ama pai ou mãe mais que a mim não é digno de mim; e quem ama filho ou filha mais que a mim não é digno de mim;"}, {"numero": 38, "texto": "E quem não toma sua cruz e segue após mim não é digno de mim."}, {"numero": 39, "texto": "Quem achar sua vida a perderá; e quem, por causa de mim, perder sua vida, a achará."}, {"numero": 40, "texto": "Quem vos recebe, recebe a mim; e quem me recebe, recebe aquele que me enviou."}, {"numero": 41, "texto": "Quem recebe um profeta por reconhecê-lo como profeta receberá recompensa de profeta; e quem recebe um justo por reconhecê-lo como justo receberá recompensa de justo."}, {"numero": 42, "texto": "E qualquer um que der ainda que somente um copo de [água] fria a um destes pequenos por reconhecê-lo como discípulo, em verdade vos digo que de maneira nenhuma perderá sua recompensa."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 10, 'en', '[{"numero": 1, "texto": "And when he had called unto him his twelve disciples, he gave them power against unclean spirits, to cast them out, and to heal all manner of sickness and all manner of disease."}, {"numero": 2, "texto": "Now the names of the twelve apostles are these; The first, Simon, who is called Peter, and Andrew his brother; James the son of Zebedee, and John his brother;"}, {"numero": 3, "texto": "Philip, and Bartholomew; Thomas, and Matthew the publican; James the son of Alphaeus, and Lebbaeus, whose surname was Thaddaeus;"}, {"numero": 4, "texto": "Simon the Canaanite, and Judas Iscariot, who also betrayed him."}, {"numero": 5, "texto": "These twelve Jesus sent forth, and commanded them, saying, Go not into the way of the Gentiles, and into any city of the Samaritans enter ye not:"}, {"numero": 6, "texto": "But go rather to the lost sheep of the house of Israel."}, {"numero": 7, "texto": "And as ye go, preach, saying, The kingdom of heaven is at hand."}, {"numero": 8, "texto": "Heal the sick, cleanse the lepers, raise the dead, cast out devils: freely ye have received, freely give."}, {"numero": 9, "texto": "Provide neither gold, nor silver, nor brass in your purses,"}, {"numero": 10, "texto": "Nor scrip for your journey, neither two coats, neither shoes, nor yet staves: for the workman is worthy of his meat."}, {"numero": 11, "texto": "And into whatsoever city or town ye shall enter, enquire who in it is worthy; and there abide till ye go thence."}, {"numero": 12, "texto": "And when ye come into an house, salute it."}, {"numero": 13, "texto": "And if the house be worthy, let your peace come upon it: but if it be not worthy, let your peace return to you."}, {"numero": 14, "texto": "And whosoever shall not receive you, nor hear your words, when ye depart out of that house or city, shake off the dust of your feet."}, {"numero": 15, "texto": "Verily I say unto you, It shall be more tolerable for the land of Sodom and Gomorrha in the day of judgment, than for that city."}, {"numero": 16, "texto": "Behold, I send you forth as sheep in the midst of wolves: be ye therefore wise as serpents, and harmless as doves."}, {"numero": 17, "texto": "But beware of men: for they will deliver you up to the councils, and they will scourge you in their synagogues;"}, {"numero": 18, "texto": "And ye shall be brought before governors and kings for my sake, for a testimony against them and the Gentiles."}, {"numero": 19, "texto": "But when they deliver you up, take no thought how or what ye shall speak: for it shall be given you in that same hour what ye shall speak."}, {"numero": 20, "texto": "For it is not ye that speak, but the Spirit of your Father which speaketh in you."}, {"numero": 21, "texto": "And the brother shall deliver up the brother to death, and the father the child: and the children shall rise up against their parents, and cause them to be put to death."}, {"numero": 22, "texto": "And ye shall be hated of all men for my name''s sake: but he that endureth to the end shall be saved."}, {"numero": 23, "texto": "But when they persecute you in this city, flee ye into another: for verily I say unto you, Ye shall not have gone over the cities of Israel, till the Son of man be come."}, {"numero": 24, "texto": "The disciple is not above his master, nor the servant above his lord."}, {"numero": 25, "texto": "It is enough for the disciple that he be as his master, and the servant as his lord. If they have called the master of the house Beelzebub, how much more shall they call them of his household?"}, {"numero": 26, "texto": "Fear them not therefore: for there is nothing covered, that shall not be revealed; and hid, that shall not be known."}, {"numero": 27, "texto": "What I tell you in darkness, that speak ye in light: and what ye hear in the ear, that preach ye upon the housetops."}, {"numero": 28, "texto": "And fear not them which kill the body, but are not able to kill the soul: but rather fear him which is able to destroy both soul and body in hell."}, {"numero": 29, "texto": "Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father."}, {"numero": 30, "texto": "But the very hairs of your head are all numbered."}, {"numero": 31, "texto": "Fear ye not therefore, ye are of more value than many sparrows."}, {"numero": 32, "texto": "Whosoever therefore shall confess me before men, him will I confess also before my Father which is in heaven."}, {"numero": 33, "texto": "But whosoever shall deny me before men, him will I also deny before my Father which is in heaven."}, {"numero": 34, "texto": "Think not that I am come to send peace on earth: I came not to send peace, but a sword."}, {"numero": 35, "texto": "For I am come to set a man at variance against his father, and the daughter against her mother, and the daughter in law against her mother in law."}, {"numero": 36, "texto": "And a man''s foes shall be they of his own household."}, {"numero": 37, "texto": "He that loveth father or mother more than me is not worthy of me: and he that loveth son or daughter more than me is not worthy of me."}, {"numero": 38, "texto": "And he that taketh not his cross, and followeth after me, is not worthy of me."}, {"numero": 39, "texto": "He that findeth his life shall lose it: and he that loseth his life for my sake shall find it."}, {"numero": 40, "texto": "He that receiveth you receiveth me, and he that receiveth me receiveth him that sent me."}, {"numero": 41, "texto": "He that receiveth a prophet in the name of a prophet shall receive a prophet''s reward; and he that receiveth a righteous man in the name of a righteous man shall receive a righteous man''s reward."}, {"numero": 42, "texto": "And whosoever shall give to drink unto one of these little ones a cup of cold water only in the name of a disciple, verily I say unto you, he shall in no wise lose his reward."}]'::jsonb, 'King James Version'),
  ('Mt', 10, 'fr', '[{"numero": 1, "texto": "Puis, ayant appelé ses douze disciples, il leur donna le pouvoir de chasser les esprits impurs, et de guérir toute maladie et toute infirmité."}, {"numero": 2, "texto": "Voici les noms des douze apôtres. Le premier, Simon appelé Pierre, et André, son frère; Jacques, fils de Zébédée, et Jean, son frère;"}, {"numero": 3, "texto": "Philippe, et Barthélemy; Thomas, et Matthieu, le publicain; Jacques, fils d''''Alphée, et Thaddée;"}, {"numero": 4, "texto": "Simon le Cananite, et Judas l''''Iscariot, celui qui livra Jésus."}, {"numero": 5, "texto": "Tels sont les douze que Jésus envoya, après leur avoir donné les instructions suivantes: N''''allez pas vers les païens, et n''''entrez pas dans les villes des Samaritains;"}, {"numero": 6, "texto": "allez plutôt vers les brebis perdues de la maison d''''Israël."}, {"numero": 7, "texto": "Allez, prêchez, et dites: Le royaume des cieux est proche."}, {"numero": 8, "texto": "Guérissez les malades, ressuscitez les morts, purifiez les lépreux, chassez les démons. Vous avez reçu gratuitement, donnez gratuitement."}, {"numero": 9, "texto": "Ne prenez ni or, ni argent, ni monnaie, dans vos ceintures;"}, {"numero": 10, "texto": "ni sac pour le voyage, ni deux tuniques, ni souliers, ni bâton; car l''''ouvrier mérite sa nourriture."}, {"numero": 11, "texto": "Dans quelque ville ou village que vous entriez, informez-vous s''''il s''''y trouve quelque homme digne de vous recevoir; et demeurez chez lui jusqu''''à ce que vous partiez."}, {"numero": 12, "texto": "En entrant dans la maison, saluez-la;"}, {"numero": 13, "texto": "et, si la maison en est digne, que votre paix vienne sur elle; mais si elle n''''en est pas digne, que votre paix retourne à vous."}, {"numero": 14, "texto": "Lorsqu''''on ne vous recevra pas et qu''''on n''''écoutera pas vos paroles, sortez de cette maison ou de cette ville et secouez la poussière de vos pieds."}, {"numero": 15, "texto": "Je vous le dis en vérité: au jour du jugement, le pays de Sodome et de Gomorrhe sera traité moins rigoureusement que cette ville-là."}, {"numero": 16, "texto": "Voici, je vous envoie comme des brebis au milieu des loups. Soyez donc prudents comme les serpents, et simples comme les colombes."}, {"numero": 17, "texto": "Mettez-vous en garde contre les hommes; car ils vous livreront aux tribunaux, et ils vous battront de verges dans leurs synagogues;"}, {"numero": 18, "texto": "vous serez menés, à cause de moi, devant des gouverneurs et devant des rois, pour servir de témoignage à eux et aux païens."}, {"numero": 19, "texto": "Mais, quand on vous livrera, ne vous inquiétez ni de la manière dont vous parlerez ni de ce que vous direz: ce que vous aurez à dire vous sera donné à l''''heure même;"}, {"numero": 20, "texto": "car ce n''''est pas vous qui parlerez, c''''est l''''Esprit de votre Père qui parlera en vous."}, {"numero": 21, "texto": "Le frère livrera son frère à la mort, et le père son enfant; les enfants se soulèveront contre leurs parents, et les feront mourir."}, {"numero": 22, "texto": "Vous serez haïs de tous, à cause de mon nom; mais celui qui persévérera jusqu''''à la fin sera sauvé."}, {"numero": 23, "texto": "Quand on vous persécutera dans une ville, fuyez dans une autre. Je vous le dis en vérité, vous n''''aurez pas achevé de parcourir les villes d''''Israël que le Fils de l''''homme sera venu."}, {"numero": 24, "texto": "Le disciple n''''est pas plus que le maître, ni le serviteur plus que son seigneur."}, {"numero": 25, "texto": "Il suffit au disciple d''''être traité comme son maître, et au serviteur comme son seigneur. S''''ils ont appelé le maître de la maison Béelzébul, à combien plus forte raison appelleront-ils ainsi les gens de sa maison!"}, {"numero": 26, "texto": "Ne les craignez donc point; car il n''''y a rien de caché qui ne doive être découvert, ni de secret qui ne doive être connu."}, {"numero": 27, "texto": "Ce que je vous dis dans les ténèbres, dites-le en plein jour; et ce qui vous est dit à l''''oreille, prêchez-le sur les toits."}, {"numero": 28, "texto": "Ne craignez pas ceux qui tuent le corps et qui ne peuvent tuer l''''âme; craignez plutôt celui qui peut faire périr l''''âme et le corps dans la géhenne."}, {"numero": 29, "texto": "Ne vend-on pas deux passereaux pour un sou? Cependant, il n''''en tombe pas un à terre sans la volonté de votre Père."}, {"numero": 30, "texto": "Et même les cheveux de votre tête sont tous comptés."}, {"numero": 31, "texto": "Ne craignez donc point: vous valez plus que beaucoup de passereaux."}, {"numero": 32, "texto": "C''''est pourquoi, quiconque me confessera devant les hommes, je le confesserai aussi devant mon Père qui est dans les cieux;"}, {"numero": 33, "texto": "mais quiconque me reniera devant les hommes, je le renierai aussi devant mon Père qui est dans les cieux."}, {"numero": 34, "texto": "Ne croyez pas que je sois venu apporter la paix sur la terre; je ne suis pas venu apporter la paix, mais l''''épée."}, {"numero": 35, "texto": "Car je suis venu mettre la division entre l''''homme et son père, entre la fille et sa mère, entre la belle-fille et sa belle-mère;"}, {"numero": 36, "texto": "et l''''homme aura pour ennemis les gens de sa maison."}, {"numero": 37, "texto": "Celui qui aime son père ou sa mère plus que moi n''''est pas digne de moi, et celui qui aime son fils ou sa fille plus que moi n''''est pas digne de moi;"}, {"numero": 38, "texto": "celui qui ne prend pas sa croix, et ne me suit pas, n''''est pas digne de moi."}, {"numero": 39, "texto": "Celui qui conservera sa vie la perdra, et celui qui perdra sa vie à cause de moi la retrouvera."}, {"numero": 40, "texto": "Celui qui vous reçoit me reçoit, et celui qui me reçoit, reçoit celui qui m''''a envoyé."}, {"numero": 41, "texto": "Celui qui reçoit un prophète en qualité de prophète recevra une récompense de prophète, et celui qui reçoit un juste en qualité de juste recevra une récompense de juste."}, {"numero": 42, "texto": "Et quiconque donnera seulement un verre d''''eau froide à l''''un de ces petits parce qu''''il est mon disciple, je vous le dis en vérité, il ne perdra point sa récompense."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 10, 'es', '[{"numero": 1, "texto": "ENTONCES llamando á sus doce discípulos, les dió potestad contra los espíritus inmundos, para que los echasen fuera, y sanasen toda enfermedad y toda dolencia."}, {"numero": 2, "texto": "Y los nombres de los doce apóstoles son estos: el primero, Simón, que es dicho Pedro, y Andrés su hermano; Jacobo, hijo de Zebedeo, y Juan su hermano;"}, {"numero": 3, "texto": "Felipe, y Bartolomé; Tomás, y Mateo el publicano; Jacobo hijo de Alfeo, y Lebeo, por sobrenombre Tadeo;"}, {"numero": 4, "texto": "Simón el Cananita y Judas Iscariote, que también le entregó."}, {"numero": 5, "texto": "A estos doce envió Jesús, á los cuales dió mandamiento, diciendo: Por el camino de los Gentiles no iréis, y en ciudad de Samaritanos no entréis;"}, {"numero": 6, "texto": "Mas id antes á las ovejas perdidas de la casa de Israel."}, {"numero": 7, "texto": "Y yendo, predicad, diciendo: El reino de los cielos se ha acercado."}, {"numero": 8, "texto": "Sanad enfermos, limpiad leprosos, resucitad muertos, echad fuera demonios: de gracia recibisteis, dad de gracia."}, {"numero": 9, "texto": "No aprestéis oro, ni plata, ni cobre en vuestras bolsas;"}, {"numero": 10, "texto": "Ni alforja para el camino, ni dos ropas de vestir, ni zapatos, ni bordón; porque el obrero digno es de su alimento."}, {"numero": 11, "texto": "Mas en cualquier ciudad, ó aldea donde entrareis, investigad quién sea en ella digno, y reposad allí hasta que salgáis."}, {"numero": 12, "texto": "Y entrando en la casa, saludadla."}, {"numero": 13, "texto": "Y si la casa fuere digna, vuestra paz vendrá sobre ella; mas si no fuere digna, vuestra paz se volverá á vosotros."}, {"numero": 14, "texto": "Y cualquiera que no os recibiere, ni oyere vuestras palabras, salid de aquella casa ó ciudad, y sacudid el polvo de vuestros pies."}, {"numero": 15, "texto": "De cierto os digo, que el castigo será más tolerable á la tierra de los de Sodoma y de los de Gomorra en el día del juicio, que á aquella ciudad."}, {"numero": 16, "texto": "He aquí, yo os envío como á ovejas en medio de lobos: sed pues prudentes como serpientes, y sencillos como palomas."}, {"numero": 17, "texto": "Y guardaos de los hombres: porque os entregarán en concilios, y en sus sinagogas os azotarán;"}, {"numero": 18, "texto": "Y aun á príncipes y á reyes seréis llevados por causa de mí, por testimonio á ellos y á los Gentiles."}, {"numero": 19, "texto": "Mas cuando os entregaren, no os apuréis por cómo ó qué hablaréis; porque en aquella hora os será dado qué habéis de hablar."}, {"numero": 20, "texto": "Porque no sois vosotros los que habláis, sino el Espíritu de vuestro Padre que habla en vosotros."}, {"numero": 21, "texto": "Y el hermano entregará al hermano á la muerte, y el padre al hijo; y los hijos se levantarán contra los padres, y los harán morir."}, {"numero": 22, "texto": "Y seréis aborrecidos de todos por mi nombre; mas el que soportare hasta el fin, éste será salvo."}, {"numero": 23, "texto": "Mas cuando os persiguieren en esta ciudad, huid á la otra: porque de cierto os digo, que no acabaréis de andar todas las ciudades de Israel, que no venga el Hijo del hombre."}, {"numero": 24, "texto": "El discípulo no es más que su maestro, ni el siervo más que su señor."}, {"numero": 25, "texto": "Bástale al discípulo ser como su maestro, y al siervo como su señor. Si al padre de la familia llamaron Beelzebub, ¿cuánto más á los de su casa?"}, {"numero": 26, "texto": "Así que, no los temáis; porque nada hay encubierto, que no haya de ser manifestado; ni oculto, que no haya de saberse."}, {"numero": 27, "texto": "Lo que os digo en tinieblas, decidlo en la luz; y lo que oís al oído predicadlo desde los terrados."}, {"numero": 28, "texto": "Y no temáis á los que matan el cuerpo, mas al alma no pueden matar: temed antes á aquel que puede destruir el alma y el cuerpo en el infierno."}, {"numero": 29, "texto": "¿No se venden dos pajarillos por un cuarto? Con todo, ni uno de ellos cae á tierra sin vuestro Padre."}, {"numero": 30, "texto": "Pues aun vuestros cabellos están todos contados."}, {"numero": 31, "texto": "Así que, no temáis: más valéis vosotros que muchos pajarillos."}, {"numero": 32, "texto": "Cualquiera pues, que me confesare delante de los hombres, le confesaré yo también delante de mi Padre que está en los cielos."}, {"numero": 33, "texto": "Y cualquiera que me negare delante de los hombres, le negaré yo también delante de mi Padre que está en los cielos."}, {"numero": 34, "texto": "No penséis que he venido para meter paz en la tierra: no he venido para meter paz, sino espada."}, {"numero": 35, "texto": "Porque he venido para hacer disensión del hombre contra su padre, y de la hija contra su madre, y de la nuera contra su suegra."}, {"numero": 36, "texto": "Y los enemigos del hombre serán los de su casa."}, {"numero": 37, "texto": "El que ama padre ó madre más que á mí, no es digno de mí; y el que ama hijo ó hija más que á mí, no es digno de mí."}, {"numero": 38, "texto": "Y el que no toma su cruz, y sigue en pos de mí, no es digno de mí."}, {"numero": 39, "texto": "El que hallare su vida, la perderá; y el que perdiere su vida por causa de mí, la hallará."}, {"numero": 40, "texto": "El que os recibe á vosotros, á mí recibe; y el que á mí recibe, recibe al que me envió."}, {"numero": 41, "texto": "El que recibe profeta en nombre de profeta, merced de profeta recibirá; y el que recibe justo en nombre de justo, merced de justo recibirá."}, {"numero": 42, "texto": "Y cualquiera que diere á uno de estos pequeñitos un vaso de agua fría solamente, en nombre de discípulo, de cierto os digo, que no perderá su recompensa."}]'::jsonb, 'Reina-Valera 1909'),
  ('Mt', 11, 'pt', '[{"numero": 1, "texto": "Quando Jesus acabou de dar as ordens aos seus doze discípulos, partiu dali para ensinar e para pregar em suas cidades."}, {"numero": 2, "texto": "E João, ao ouvir na prisão as obras de Cristo, enviou [-lhe] dois de seus discípulos,"}, {"numero": 3, "texto": "Perguntando-lhe: És tu aquele que havia de vir, ou esperamos outro?"}, {"numero": 4, "texto": "Jesus lhes respondeu: Ide anunciar a João as coisas que ouvis e vedes:"}, {"numero": 5, "texto": "Os cegos veem, e os mancos andam; os leprosos são limpos, e os surdos ouvem; os mortos são ressuscitados, e aos pobres é anunciado o Evangelho;"}, {"numero": 6, "texto": "E bendito é aquele que não se ofender em mim."}, {"numero": 7, "texto": "Depois que eles se foram, Jesus começou a dizer às multidões acerca de João: Que saístes ao deserto para ver? Uma cana que se move pelo vento?"}, {"numero": 8, "texto": "Mas que saístes para ver? Um homem vestido com roupas delicadas? Eis que os que usam roupas delicadas estão nas casas dos reis."}, {"numero": 9, "texto": "Mas que saístes para ver? Um profeta? Sim, eu vos digo, e muito mais que um profeta;"}, {"numero": 10, "texto": "Porque este é aquele sobre o qual está escrito: ‘Eis que diante de tua face envio o meu mensageiro, que preparará o teu caminho diante de ti.’"}, {"numero": 11, "texto": "Em verdade vos digo que, dentre os nascidos de mulheres, não se levantou [outro] maior que João Batista; porém o menor no Reino dos céus é maior que ele."}, {"numero": 12, "texto": "E desde os dias de João Batista até agora, o Reino dos céus está sujeito à violência, e os que usam de violência se apoderam dele."}, {"numero": 13, "texto": "Porque todos os profetas e a Lei profetizaram até João."}, {"numero": 14, "texto": "E se estais dispostos a aceitar, este é o Elias que havia de vir."}, {"numero": 15, "texto": "Quem tem ouvidos para ouvir, ouça."}, {"numero": 16, "texto": "Mas com quem compararei esta geração? Semelhante é às crianças que se sentam nas praças, e chamam aos seus colegas,"}, {"numero": 17, "texto": "E dizem: ‘Tocamos flauta para vós, mas não dançastes; cantamos lamentações para vós, mas não chorastes.’"}, {"numero": 18, "texto": "Porque veio João, sem comer nem beber, e dizem: ‘Ele tem demônio.’"}, {"numero": 19, "texto": "Veio o Filho do homem, que come e bebe, e dizem: ‘Eis aqui um homem comilão e beberrão, amigo de publicanos e pecadores!’ Mas a sabedoria prova-se justa por meio de seus filhos."}, {"numero": 20, "texto": "Então ele começou a repreender as cidades em que a maioria de seus milagres haviam sido feitos, por não terem se arrependido:"}, {"numero": 21, "texto": "Ai de ti Corazim! Ai de ti Betsaida! Porque se em Tiro e em Sidom tivessem sido feitos os milagres que em vós foram feitos, há muito tempo teriam se arrependido com saco e com cinza!"}, {"numero": 22, "texto": "Porém eu vos digo que mais tolerável será para Tiro e Sidom, no dia do juízo, que para vós."}, {"numero": 23, "texto": "E tu, Cafarnaum, que estás exaltada até o céu, ao Xeol serás derrubada! Pois se em Sodoma tivessem sido feitos os milagres que foram feitos em ti, ela teria permanecido até hoje."}, {"numero": 24, "texto": "Porém eu vos digo que mais tolerável será para os da região de Sodoma, no dia de juízo, que para ti."}, {"numero": 25, "texto": "Naquele tempo Jesus pronunciou: Graças te dou, Pai, Senhor do céu e da terra, porque escondeste estas coisas aos sábios e entendidos, e as revelaste às crianças."}, {"numero": 26, "texto": "Sim, Pai, porque assim foi agradável a ti."}, {"numero": 27, "texto": "Todas as coisas me foram entregues pelo meu Pai; e ninguém conhece o Filho, a não ser o Pai; nem ninguém conhece o Pai, a não ser o Filho, e a quem o Filho [o] quiser revelar."}, {"numero": 28, "texto": "Vinde a mim todos vós que estais cansados e sobrecarregados, e eu vos farei descansar."}, {"numero": 29, "texto": "Tomai sobre vós o meu jugo e aprendei de mim, porque sou manso e humilde de coração; e encontrareis descanso para as vossas almas."}, {"numero": 30, "texto": "Pois o meu jugo é suave, e minha carga é leve."}]'::jsonb, 'Almeida Livre'),
  ('Mt', 11, 'en', '[{"numero": 1, "texto": "And it came to pass, when Jesus had made an end of commanding his twelve disciples, he departed thence to teach and to preach in their cities."}, {"numero": 2, "texto": "Now when John had heard in the prison the works of Christ, he sent two of his disciples,"}, {"numero": 3, "texto": "And said unto him, Art thou he that should come, or do we look for another?"}, {"numero": 4, "texto": "Jesus answered and said unto them, Go and shew John again those things which ye do hear and see:"}, {"numero": 5, "texto": "The blind receive their sight, and the lame walk, the lepers are cleansed, and the deaf hear, the dead are raised up, and the poor have the gospel preached to them."}, {"numero": 6, "texto": "And blessed is he, whosoever shall not be offended in me."}, {"numero": 7, "texto": "And as they departed, Jesus began to say unto the multitudes concerning John, What went ye out into the wilderness to see? A reed shaken with the wind?"}, {"numero": 8, "texto": "But what went ye out for to see? A man clothed in soft raiment? behold, they that wear soft clothing are in kings'' houses."}, {"numero": 9, "texto": "But what went ye out for to see? A prophet? yea, I say unto you, and more than a prophet."}, {"numero": 10, "texto": "For this is he, of whom it is written, Behold, I send my messenger before thy face, which shall prepare thy way before thee."}, {"numero": 11, "texto": "Verily I say unto you, Among them that are born of women there hath not risen a greater than John the Baptist: notwithstanding he that is least in the kingdom of heaven is greater than he."}, {"numero": 12, "texto": "And from the days of John the Baptist until now the kingdom of heaven suffereth violence, and the violent take it by force."}, {"numero": 13, "texto": "For all the prophets and the law prophesied until John."}, {"numero": 14, "texto": "And if ye will receive it, this is Elias, which was for to come."}, {"numero": 15, "texto": "He that hath ears to hear, let him hear."}, {"numero": 16, "texto": "But whereunto shall I liken this generation? It is like unto children sitting in the markets, and calling unto their fellows,"}, {"numero": 17, "texto": "And saying, We have piped unto you, and ye have not danced; we have mourned unto you, and ye have not lamented."}, {"numero": 18, "texto": "For John came neither eating nor drinking, and they say, He hath a devil."}, {"numero": 19, "texto": "The Son of man came eating and drinking, and they say, Behold a man gluttonous, and a winebibber, a friend of publicans and sinners. But wisdom is justified of her children."}, {"numero": 20, "texto": "Then began he to upbraid the cities wherein most of his mighty works were done, because they repented not:"}, {"numero": 21, "texto": "Woe unto thee, Chorazin! woe unto thee, Bethsaida! for if the mighty works, which were done in you, had been done in Tyre and Sidon, they would have repented long ago in sackcloth and ashes."}, {"numero": 22, "texto": "But I say unto you, It shall be more tolerable for Tyre and Sidon at the day of judgment, than for you."}, {"numero": 23, "texto": "And thou, Capernaum, which art exalted unto heaven, shalt be brought down to hell: for if the mighty works, which have been done in thee, had been done in Sodom, it would have remained until this day."}, {"numero": 24, "texto": "But I say unto you, That it shall be more tolerable for the land of Sodom in the day of judgment, than for thee."}, {"numero": 25, "texto": "At that time Jesus answered and said, I thank thee, O Father, Lord of heaven and earth, because thou hast hid these things from the wise and prudent, and hast revealed them unto babes."}, {"numero": 26, "texto": "Even so, Father: for so it seemed good in thy sight."}, {"numero": 27, "texto": "All things are delivered unto me of my Father: and no man knoweth the Son, but the Father; neither knoweth any man the Father, save the Son, and he to whomsoever the Son will reveal him."}, {"numero": 28, "texto": "Come unto me, all ye that labour and are heavy laden, and I will give you rest."}, {"numero": 29, "texto": "Take my yoke upon you, and learn of me; for I am meek and lowly in heart: and ye shall find rest unto your souls."}, {"numero": 30, "texto": "For my yoke is easy, and my burden is light."}]'::jsonb, 'King James Version'),
  ('Mt', 11, 'fr', '[{"numero": 1, "texto": "Lorsque Jésus eut achevé de donner ses instructions à ses douze disciples, il partit de là, pour enseigner et prêcher dans les villes du pays."}, {"numero": 2, "texto": "Jean, ayant entendu parler dans sa prison des oeuvres du Christ, lui fit dire par ses disciples:"}, {"numero": 3, "texto": "Es-tu celui qui doit venir, ou devons-nous en attendre un autre?"}, {"numero": 4, "texto": "Jésus leur répondit: Allez rapporter à Jean ce que vous entendez et ce que vous voyez:"}, {"numero": 5, "texto": "les aveugles voient, les boiteux marchent, les lépreux sont purifiés, les sourds entendent, les morts ressuscitent, et la bonne nouvelle est annoncée aux pauvres."}, {"numero": 6, "texto": "Heureux celui pour qui je ne serai pas une occasion de chute!"}, {"numero": 7, "texto": "Comme ils s''''en allaient, Jésus se mit à dire à la foule, au sujet de Jean: Qu''''êtes-vous allés voir au désert? un roseau agité par le vent?"}, {"numero": 8, "texto": "Mais, qu''''êtes-vous allés voir? un homme vêtu d''''habits précieux? Voici, ceux qui portent des habits précieux sont dans les maisons des rois."}, {"numero": 9, "texto": "Qu''''êtes-vous donc allés voir? un prophète? Oui, vous dis-je, et plus qu''''un prophète."}, {"numero": 10, "texto": "Car c''''est celui dont il est écrit: Voici, j''''envoie mon messager devant ta face, Pour préparer ton chemin devant toi."}, {"numero": 11, "texto": "Je vous le dis en vérité, parmi ceux qui sont nés de femmes, il n''''en a point paru de plus grand que Jean-Baptiste. Cependant, le plus petit dans le royaume des cieux est plus grand que lui."}, {"numero": 12, "texto": "Depuis le temps de Jean-Baptiste jusqu''''à présent, le royaume des cieux est forcé, et ce sont les violents qui s''''en emparent."}, {"numero": 13, "texto": "Car tous les prophètes et la loi ont prophétisé jusqu''''à Jean;"}, {"numero": 14, "texto": "et, si vous voulez le comprendre, c''''est lui qui est l''''Elie qui devait venir."}, {"numero": 15, "texto": "Que celui qui a des oreilles pour entendre entende."}, {"numero": 16, "texto": "A qui comparerai-je cette génération? Elle ressemble à des enfants assis dans des places publiques, et qui, s''''adressant à d''''autres enfants,"}, {"numero": 17, "texto": "disent: Nous vous avons joué de la flûte, et vous n''''avez pas dansé; nous avons chanté des complaintes, et vous ne vous êtes pas lamentés."}, {"numero": 18, "texto": "Car Jean est venu, ne mangeant ni ne buvant, et ils disent: Il a un démon."}, {"numero": 19, "texto": "Le Fils de l''''homme est venu, mangeant et buvant, et ils disent: C''''est un mangeur et un buveur, un ami des publicains et des gens de mauvaise vie. Mais la sagesse a été justifiée par ses oeuvres."}, {"numero": 20, "texto": "Alors il se mit à faire des reproches aux villes dans lesquelles avaient eu lieu la plupart de ses miracles, parce qu''''elles ne s''''étaient pas repenties."}, {"numero": 21, "texto": "Malheur à toi, Chorazin! malheur à toi, Bethsaïda! car, si les miracles qui ont été faits au milieu de vous avaient été faits dans Tyr et dans Sidon, il y a longtemps qu''''elles se seraient repenties, en prenant le sac et la cendre."}, {"numero": 22, "texto": "C''''est pourquoi je vous le dis: au jour du jugement, Tyr et Sidon seront traitées moins rigoureusement que vous."}, {"numero": 23, "texto": "Et toi, Capernaüm, seras-tu élevée jusqu''''au ciel? Non. Tu seras abaissée jusqu''''au séjour des morts; car, si les miracles qui ont été faits au milieu de toi avaient été faits dans Sodome, elle subsisterait encore aujourd''''hui."}, {"numero": 24, "texto": "C''''est pourquoi je vous le dis: au jour du jugement, le pays de Sodome sera traité moins rigoureusement que toi."}, {"numero": 25, "texto": "En ce temps-là, Jésus prit la parole, et dit: Je te loue, Père, Seigneur du ciel et de la terre, de ce que tu as caché ces choses aux sages et aux intelligents, et de ce que tu les as révélées aux enfants."}, {"numero": 26, "texto": "Oui, Père, je te loue de ce que tu l''''as voulu ainsi."}, {"numero": 27, "texto": "Toutes choses m''''ont été données par mon Père, et personne ne connaît le Fils, si ce n''''est le Père; personne non plus ne connaît le Père, si ce n''''est le Fils et celui à qui le Fils veut le révéler."}, {"numero": 28, "texto": "Venez à moi, vous tous qui êtes fatigués et chargés, et je vous donnerai du repos."}, {"numero": 29, "texto": "Prenez mon joug sur vous et recevez mes instructions, car je suis doux et humble de coeur; et vous trouverez du repos pour vos âmes."}, {"numero": 30, "texto": "Car mon joug est doux, et mon fardeau léger."}]'::jsonb, 'Louis Segond 1910'),
  ('Mt', 11, 'es', '[{"numero": 1, "texto": "Y FUÉ, que acabando Jesús de dar mandamientos á sus doce discípulos, se fué de allí á enseñar y á predicar en las ciudades de ellos."}, {"numero": 2, "texto": "Y oyendo Juan en la prisión los hechos de Cristo, le envió dos de sus discípulos,"}, {"numero": 3, "texto": "Diciendo: ¿Eres tú aquél que había de venir, ó esperaremos á otro?"}, {"numero": 4, "texto": "Y respondiendo Jesús, les dijo: Id, y haced saber á Juan las cosas que oís y veis:"}, {"numero": 5, "texto": "Los ciegos ven, y los cojos andan; los leprosos son limpiados, y los sordos oyen; los muertos son resucitados, y á los pobres es anunciado el evangelio."}, {"numero": 6, "texto": "Y bienaventurado es el que no fuere escandalizado en mí."}, {"numero": 7, "texto": "E idos ellos, comenzó Jesús á decir de Juan á las gentes: ¿Qué salisteis á ver al desierto? ¿una caña que es meneada del viento?"}, {"numero": 8, "texto": "Mas ¿qué salisteis á ver? ¿un hombre cubierto de delicados vestidos? He aquí, los que traen vestidos delicados, en las casas de los reyes están."}, {"numero": 9, "texto": "Mas ¿qué salisteis á ver? ¿un profeta? También os digo, y más que profeta."}, {"numero": 10, "texto": "Porque éste es de quien está escrito: He aquí, yo envío mi mensajero delante de tu faz, que aparejará tu camino delante de ti."}, {"numero": 11, "texto": "De cierto os digo, que no se levantó entre los que nacen de mujeres otro mayor que Juan el Bautista; mas el que es muy más pequeño en el reino de los cielos, mayor es que él."}, {"numero": 12, "texto": "Desde los días de Juan el Bautista hasta ahora, al reino de los cielos se hace fuerza, y los valientes lo arrebatan."}, {"numero": 13, "texto": "Porque todos los profetas y la ley hasta Juan profetizaron."}, {"numero": 14, "texto": "Y si queréis recibir, él es aquel Elías que había de venir."}, {"numero": 15, "texto": "El que tiene oídos para oir, oiga."}, {"numero": 16, "texto": "Mas ¿á quién compararé esta generación? Es semejante á los muchachos que se sientan en las plazas, y dan voces á sus compañeros,"}, {"numero": 17, "texto": "Y dicen: Os tañimos flauta, y no bailasteis; os endechamos, y no lamentasteis."}, {"numero": 18, "texto": "Porque vino Juan, que ni comía ni bebía, y dicen: Demonio tiene."}, {"numero": 19, "texto": "Vino el Hijo del hombre, que come y bebe, y dicen: He aquí un hombre comilón, y bebedor de vino, amigo de publicanos y de pecadores. Mas la sabiduría es justificada por sus hijos."}, {"numero": 20, "texto": "Entonces comenzó á reconvenir á las ciudades en las cuales habían sido hechas muy muchas de sus maravillas, porque no se habían arrepentido, diciendo:"}, {"numero": 21, "texto": "¡Ay de ti, Corazín! ¡Ay de ti, Bethsaida! porque si en Tiro y en Sidón fueran hechas las maravillas que han sido hechas en vosotras, en otro tiempo se hubieran arrepentido en saco y en ceniza."}, {"numero": 22, "texto": "Por tanto os digo, que á Tiro y á Sidón será más tolerable el castigo en el día del juicio, que á vosotras."}, {"numero": 23, "texto": "Y tú, Capernaum, que eres levantada hasta el cielo, hasta los infiernos serás abajada; porque si en los de Sodoma fueran hechas las maravillas que han sido hechas en ti, hubieran quedado hasta el día de hoy."}, {"numero": 24, "texto": "Por tanto os digo, que á la tierra de los de Sodoma será más tolerable el castigo en el día del juicio, que á ti."}, {"numero": 25, "texto": "En aquel tiempo, respondiendo Jesús, dijo: Te alabo, Padre, Señor del cielo y de la tierra, que hayas escondido estas cosas de los sabios y de los entendidos, y las hayas revelado á los niños."}, {"numero": 26, "texto": "Así, Padre, pues que así agradó en tus ojos."}, {"numero": 27, "texto": "Todas las cosas me son entregadas de mi Padre: y nadie conoció al Hijo, sino el Padre; ni al Padre conoció alguno, sino el Hijo, y aquel á quien el Hijo lo quisiere revelar."}, {"numero": 28, "texto": "Venid á mí todos los que estáis trabajados y cargados, que yo os haré descansar."}, {"numero": 29, "texto": "Llevad mi yugo sobre vosotros, y aprended de mí, que soy manso y humilde de corazón; y hallaréis descanso para vuestras almas."}, {"numero": 30, "texto": "Porque mi yugo es fácil, y ligera mi carga."}]'::jsonb, 'Reina-Valera 1909')
